--
-- Name: _aj_regresar_a_bodega(public.entregas, uuid, uuid, numeric, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aj_regresar_a_bodega(v_ent public.entregas, p_producto uuid, p_lote uuid, p_qty numeric, p_truck uuid, p_bodega uuid, p_uid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rest numeric := p_qty;
  v_take numeric;
  c record;
  s record;
  v_desc_surtido boolean;
BEGIN
  FOR c IN
    SELECT id, cantidad, notas FROM public.movimientos_inventario
     WHERE referencia_id = v_ent.id AND referencia_tipo = 'entrega_cargado' AND tipo = 'entrada'
       AND producto_id = p_producto AND almacen_destino_id = p_truck AND cantidad > 0
     ORDER BY created_at DESC FOR UPDATE
  LOOP
    EXIT WHEN v_rest <= 0.000001;
    v_take := LEAST(c.cantidad, v_rest);
    v_desc_surtido := COALESCE(c.notas,'') ILIKE '%ya descontado%';
    UPDATE public.stock_almacen SET cantidad = cantidad - v_take, updated_at = now()
     WHERE almacen_id = p_truck AND producto_id = p_producto;
    IF c.cantidad - v_take <= 0.000001 THEN DELETE FROM public.movimientos_inventario WHERE id = c.id;
    ELSE UPDATE public.movimientos_inventario SET cantidad = cantidad - v_take WHERE id = c.id; END IF;
    IF p_lote IS NOT NULL THEN
      UPDATE public.movimientos_inventario SET cantidad = cantidad - v_take
       WHERE id = (SELECT id FROM public.movimientos_inventario
                    WHERE referencia_id = v_ent.id AND referencia_tipo = 'entrega_cargado_lote' AND producto_id = p_producto
                      AND lote_id = p_lote AND cantidad >= v_take ORDER BY created_at DESC LIMIT 1);
      IF FOUND THEN PERFORM public._aplica_stock_lote(v_ent.empresa_id, p_truck, p_producto, p_lote, -v_take); END IF;
      DELETE FROM public.movimientos_inventario
       WHERE referencia_id = v_ent.id AND referencia_tipo = 'entrega_cargado_lote' AND producto_id = p_producto AND cantidad <= 0.000001;
    END IF;
    IF v_desc_surtido THEN
      FOR s IN
        SELECT id, cantidad, lote_id, almacen_origen_id FROM public.movimientos_inventario
         WHERE referencia_id = v_ent.id AND referencia_tipo = 'entrega' AND tipo = 'salida' AND producto_id = p_producto
           AND cantidad > 0 AND (p_lote IS NULL OR lote_id IS NOT DISTINCT FROM p_lote)
         ORDER BY created_at DESC FOR UPDATE
      LOOP
        EXIT WHEN v_take <= 0.000001;
        UPDATE public.stock_almacen SET cantidad = cantidad + LEAST(s.cantidad, v_take), updated_at = now()
         WHERE almacen_id = s.almacen_origen_id AND producto_id = p_producto;
        IF s.lote_id IS NOT NULL THEN
          PERFORM public._aplica_stock_lote(v_ent.empresa_id, s.almacen_origen_id, p_producto, s.lote_id, LEAST(s.cantidad, v_take));
        END IF;
        IF s.cantidad - LEAST(s.cantidad, v_take) <= 0.000001 THEN DELETE FROM public.movimientos_inventario WHERE id = s.id;
        ELSE UPDATE public.movimientos_inventario SET cantidad = cantidad - LEAST(s.cantidad, v_take) WHERE id = s.id; END IF;
        v_rest := v_rest - LEAST(s.cantidad, v_take);
        v_take := v_take - LEAST(s.cantidad, v_take);
      END LOOP;
    ELSE
      UPDATE public.stock_almacen SET cantidad = cantidad + v_take, updated_at = now()
       WHERE almacen_id = p_bodega AND producto_id = p_producto;
      IF NOT FOUND THEN
        INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad) VALUES (v_ent.empresa_id, p_bodega, p_producto, v_take);
      END IF;
      IF p_lote IS NOT NULL THEN PERFORM public._aplica_stock_lote(v_ent.empresa_id, p_bodega, p_producto, p_lote, v_take); END IF;
      v_rest := v_rest - v_take;
    END IF;
  END LOOP;

  IF v_rest > 0.000001 THEN
    UPDATE public.stock_almacen SET cantidad = cantidad - v_rest, updated_at = now()
     WHERE almacen_id = p_truck AND producto_id = p_producto;
    UPDATE public.stock_almacen SET cantidad = cantidad + v_rest, updated_at = now()
     WHERE almacen_id = p_bodega AND producto_id = p_producto;
    IF NOT FOUND THEN
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad) VALUES (v_ent.empresa_id, p_bodega, p_producto, v_rest);
    END IF;
    INSERT INTO public.movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id,
           lote_id, referencia_tipo, referencia_id, user_id, notas, fecha)
    VALUES (v_ent.empresa_id, 'transferencia', p_producto, v_rest, p_truck, p_bodega, p_lote,
           'entrega_ajuste_bodega', v_ent.id, p_uid, 'Ajuste de entrega: sobrante a bodega (folio ' || COALESCE(v_ent.folio,'—') || ')', CURRENT_DATE);
  END IF;
END;
$$;


--
-- Name: _aplica_stock_lote(uuid, uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aplica_stock_lote(p_empresa uuid, p_almacen uuid, p_producto uuid, p_lote uuid, p_delta numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_lote IS NULL OR p_almacen IS NULL OR COALESCE(p_delta,0) = 0 THEN RETURN; END IF;
  INSERT INTO public.stock_lotes (empresa_id, almacen_id, producto_id, lote_id, cantidad)
  VALUES (p_empresa, p_almacen, p_producto, p_lote, p_delta)
  ON CONFLICT (almacen_id, lote_id)
    DO UPDATE SET cantidad = public.stock_lotes.cantidad + EXCLUDED.cantidad, updated_at = now();
END; $$;


--
-- Name: _aplicar_delta_compra_edicion(uuid, uuid, uuid, uuid, numeric, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._aplicar_delta_compra_edicion(p_empresa_id uuid, p_compra_id uuid, p_producto_id uuid, p_almacen_id uuid, p_delta numeric, p_user_id uuid, p_folio text, p_nota text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stock numeric;
  v_pendiente numeric;
  v_tomar numeric;
  v_stock_lote numeric;
  v_lote record;
  v_epsilon constant numeric := 0.0001;
BEGIN
  IF p_almacen_id IS NULL THEN
    RAISE EXCEPTION 'La compra no tiene almacén destino';
  END IF;
  IF COALESCE(p_delta, 0) = 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
  VALUES (p_empresa_id, p_almacen_id, p_producto_id, 0)
  ON CONFLICT (almacen_id, producto_id) DO NOTHING;

  SELECT cantidad
    INTO v_stock
  FROM public.stock_almacen
  WHERE almacen_id = p_almacen_id
    AND producto_id = p_producto_id
  FOR UPDATE;

  IF p_delta < 0 AND COALESCE(v_stock, 0) + p_delta < -v_epsilon THEN
    RAISE EXCEPTION
      'No se puede reducir o eliminar este renglón: el almacén tiene % pieza(s) y se necesitan revertir %. Parte de esa mercancía ya fue utilizada o vendida.',
      COALESCE(v_stock, 0), ABS(p_delta);
  END IF;

  UPDATE public.stock_almacen
     SET cantidad = cantidad + p_delta,
         updated_at = now()
   WHERE almacen_id = p_almacen_id
     AND producto_id = p_producto_id;

  IF p_delta > 0 THEN
    INSERT INTO public.movimientos_inventario (
      empresa_id, tipo, producto_id, cantidad, almacen_destino_id,
      referencia_tipo, referencia_id, user_id, fecha, notas
    ) VALUES (
      p_empresa_id, 'entrada', p_producto_id, p_delta, p_almacen_id,
      'compra', p_compra_id, p_user_id, current_date,
      concat('Edición compra ', COALESCE(p_folio, p_compra_id::text),
             CASE WHEN p_nota IS NULL THEN '' ELSE ' · ' || p_nota END)
    );
    RETURN;
  END IF;

  v_pendiente := ABS(p_delta);
  FOR v_lote IN
    WITH neto AS (
      SELECT mi.lote_id,
             SUM(
               CASE WHEN mi.almacen_destino_id = p_almacen_id THEN mi.cantidad ELSE 0 END
               - CASE WHEN mi.almacen_origen_id = p_almacen_id THEN mi.cantidad ELSE 0 END
             ) AS piezas,
             MAX(mi.created_at) AS ultimo_movimiento
      FROM public.movimientos_inventario mi
      WHERE mi.empresa_id = p_empresa_id
        AND mi.referencia_tipo = 'compra'
        AND mi.referencia_id = p_compra_id
        AND mi.producto_id = p_producto_id
        AND mi.lote_id IS NOT NULL
      GROUP BY mi.lote_id
    ), asignado AS (
      SELECT cll.lote_id, SUM(cll.piezas) AS piezas
      FROM public.compra_linea_lotes cll
      WHERE cll.empresa_id = p_empresa_id
        AND cll.compra_id = p_compra_id
        AND cll.producto_id = p_producto_id
        AND cll.almacen_id = p_almacen_id
      GROUP BY cll.lote_id
    )
    SELECT n.lote_id,
           GREATEST(0, n.piezas - COALESCE(a.piezas, 0)) AS disponible
    FROM neto n
    LEFT JOIN asignado a ON a.lote_id = n.lote_id
    WHERE n.piezas - COALESCE(a.piezas, 0) > v_epsilon
    ORDER BY n.ultimo_movimiento DESC, n.lote_id
  LOOP
    EXIT WHEN v_pendiente <= v_epsilon;
    v_tomar := LEAST(v_pendiente, v_lote.disponible);

    SELECT cantidad
      INTO v_stock_lote
    FROM public.stock_lotes
    WHERE almacen_id = p_almacen_id
      AND lote_id = v_lote.lote_id
    FOR UPDATE;

    IF COALESCE(v_stock_lote, 0) + v_epsilon < v_tomar THEN
      RAISE EXCEPTION
        'No se puede reducir la compra: el lote relacionado ya no tiene existencias suficientes.';
    END IF;

    INSERT INTO public.movimientos_inventario (
      empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id,
      referencia_tipo, referencia_id, user_id, fecha, notas
    ) VALUES (
      p_empresa_id, 'salida', p_producto_id, v_tomar, p_almacen_id, v_lote.lote_id,
      'compra', p_compra_id, p_user_id, current_date,
      concat('Reversa por edición compra ', COALESCE(p_folio, p_compra_id::text),
             CASE WHEN p_nota IS NULL THEN '' ELSE ' · ' || p_nota END)
    );
    v_pendiente := v_pendiente - v_tomar;
  END LOOP;

  IF v_pendiente > v_epsilon THEN
    INSERT INTO public.movimientos_inventario (
      empresa_id, tipo, producto_id, cantidad, almacen_origen_id,
      referencia_tipo, referencia_id, user_id, fecha, notas
    ) VALUES (
      p_empresa_id, 'salida', p_producto_id, v_pendiente, p_almacen_id,
      'compra', p_compra_id, p_user_id, current_date,
      concat('Reversa por edición compra ', COALESCE(p_folio, p_compra_id::text),
             CASE WHEN p_nota IS NULL THEN '' ELSE ' · ' || p_nota END)
    );
  END IF;
END;
$$;


--
-- Name: _current_user_nombre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._current_user_nombre() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((SELECT nombre FROM public.profiles WHERE user_id = auth.uid() LIMIT 1), 'Sistema');
$$;


--
-- Name: _inotif_cliente_nombre(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._inotif_cliente_nombre(_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT nombre FROM public.clientes WHERE id = _id;
$$;


--
-- Name: _map_entrega_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._map_entrega_status(_s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE _s
    WHEN 'surtido'      THEN 'entrega_surtida'
    WHEN 'asignado'     THEN 'entrega_asignada'
    WHEN 'cargado'      THEN 'entrega_cargada'
    WHEN 'en_ruta'      THEN 'entrega_en_ruta'
    WHEN 'listo'        THEN 'entrega_lista'
    WHEN 'hecho'        THEN 'entrega_hecha'
    WHEN 'cancelado'    THEN 'entrega_cancelada'
    WHEN 'no_entregado' THEN 'entrega_no_entregada'
    ELSE 'entrega_editada'
  END;
$$;


--
-- Name: _mover_stock_entre_almacenes(uuid, uuid, numeric, uuid, uuid, text, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._mover_stock_entre_almacenes(p_empresa_id uuid, p_producto_id uuid, p_cantidad numeric, p_almacen_origen uuid, p_almacen_destino uuid, p_referencia_tipo text, p_referencia_id uuid, p_user_id uuid, p_fecha date, p_notas text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_stock_id uuid;
  v_qty numeric;
  v_allow_neg boolean;
  v_prod_name text;
BEGIN
  IF p_cantidad IS NULL OR p_cantidad <= 0 THEN RETURN; END IF;

  SELECT nombre, vender_sin_stock INTO v_prod_name, v_allow_neg
  FROM productos WHERE id = p_producto_id;

  -- Salida desde origen
  IF p_almacen_origen IS NOT NULL THEN
    SELECT id, cantidad INTO v_stock_id, v_qty
    FROM stock_almacen
    WHERE almacen_id = p_almacen_origen AND producto_id = p_producto_id
    FOR UPDATE;

    IF v_stock_id IS NULL THEN
      IF NOT COALESCE(v_allow_neg, false) THEN
        RAISE EXCEPTION 'Stock insuficiente para "%" en almacén origen (no existe registro)', COALESCE(v_prod_name, p_producto_id::text);
      END IF;
      INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (p_empresa_id, p_almacen_origen, p_producto_id, -p_cantidad);
    ELSE
      IF NOT COALESCE(v_allow_neg, false) AND (v_qty - p_cantidad) < 0 THEN
        RAISE EXCEPTION 'Stock insuficiente para "%" en almacén origen. Disponible: %, requerido: %', COALESCE(v_prod_name, p_producto_id::text), v_qty, p_cantidad;
      END IF;
      UPDATE stock_almacen SET cantidad = v_qty - p_cantidad, updated_at = now() WHERE id = v_stock_id;
    END IF;

    INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
    VALUES (p_empresa_id, 'salida', p_producto_id, p_cantidad, p_almacen_origen, p_almacen_destino, p_referencia_tipo, p_referencia_id, p_user_id, p_fecha, p_notas);
  END IF;

  -- Entrada al destino
  IF p_almacen_destino IS NOT NULL THEN
    SELECT id, cantidad INTO v_stock_id, v_qty
    FROM stock_almacen
    WHERE almacen_id = p_almacen_destino AND producto_id = p_producto_id
    FOR UPDATE;

    IF v_stock_id IS NULL THEN
      INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (p_empresa_id, p_almacen_destino, p_producto_id, p_cantidad);
    ELSE
      UPDATE stock_almacen SET cantidad = v_qty + p_cantidad, updated_at = now() WHERE id = v_stock_id;
    END IF;

    INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
    VALUES (p_empresa_id, 'entrada', p_producto_id, p_cantidad, p_almacen_origen, p_almacen_destino, p_referencia_tipo, p_referencia_id, p_user_id, p_fecha, p_notas);
  END IF;
END;
$$;


--
-- Name: acreditar_timbres_pago(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acreditar_timbres_pago(p_empresa_id uuid, p_cantidad integer, p_user_id uuid, p_notas text, p_referencia text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_saldo_actual integer; v_saldo_nuevo integer;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'No autorizado para abonar timbres' USING ERRCODE = '42501';
  END IF;
  IF p_referencia IS NULL OR btrim(p_referencia) = '' THEN RAISE EXCEPTION 'referencia requerida'; END IF;
  IF p_cantidad IS NULL OR p_cantidad <= 0 THEN RAISE EXCEPTION 'cantidad inválida'; END IF;
  INSERT INTO timbres_saldo (empresa_id, saldo) VALUES (p_empresa_id, 0) ON CONFLICT (empresa_id) DO NOTHING;
  SELECT saldo INTO v_saldo_actual FROM timbres_saldo WHERE empresa_id = p_empresa_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM timbres_movimientos WHERE referencia_externa = p_referencia) THEN RETURN NULL; END IF;
  v_saldo_nuevo := v_saldo_actual + p_cantidad;
  UPDATE timbres_saldo SET saldo = v_saldo_nuevo, updated_at = now() WHERE empresa_id = p_empresa_id;
  INSERT INTO timbres_movimientos (empresa_id, tipo, cantidad, saldo_anterior, saldo_nuevo, user_id, notas, referencia_externa)
  VALUES (p_empresa_id, 'compra', p_cantidad, v_saldo_actual, v_saldo_nuevo, p_user_id, COALESCE(p_notas, 'Compra de timbres'), p_referencia);
  RETURN v_saldo_nuevo;
END; $$;


--
-- Name: actualizar_mi_partner_contacto(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actualizar_mi_partner_contacto(_telefono text DEFAULT NULL::text, _notas text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.partners
  SET
    telefono = NULLIF(trim(_telefono), ''),
    notas = NULLIF(trim(_notas), '')
  WHERE user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Partner no encontrado';
  END IF;
END;
$$;


--
-- Name: add_timbres(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_timbres(p_empresa_id uuid, p_cantidad integer, p_user_id uuid, p_notas text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo_actual integer;
  v_saldo_nuevo integer;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para abonar timbres' USING ERRCODE = '42501';
  END IF;

  INSERT INTO timbres_saldo (empresa_id, saldo)
  VALUES (p_empresa_id, 0)
  ON CONFLICT (empresa_id) DO NOTHING;

  SELECT saldo INTO v_saldo_actual
  FROM timbres_saldo
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  v_saldo_nuevo := v_saldo_actual + p_cantidad;

  UPDATE timbres_saldo
  SET saldo = v_saldo_nuevo, updated_at = now()
  WHERE empresa_id = p_empresa_id;

  INSERT INTO timbres_movimientos (empresa_id, tipo, cantidad, saldo_anterior, saldo_nuevo, user_id, notas)
  VALUES (p_empresa_id, 'compra', p_cantidad, v_saldo_actual, v_saldo_nuevo, p_user_id, COALESCE(p_notas, 'Recarga de timbres'));

  RETURN v_saldo_nuevo;
END;
$$;


--
-- Name: admin_link_team_account(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_link_team_account(p_person_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Acceso denegado'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM auth.users account
    JOIN public.commission_people person
      ON person.id = p_person_id
     AND person.person_type = 'internal'
     AND person.is_active = true
     AND lower(person.email) = lower(account.email)
    WHERE account.id = p_user_id
  ) THEN
    RAISE EXCEPTION
      'La cuenta no existe, está inactiva o su correo no coincide con el integrante'
      USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.platform_team_members tm
  SET
    user_id = p_user_id,
    status = 'active',
    invited_at = COALESCE(tm.invited_at, now()),
    updated_by = auth.uid()
  WHERE tm.person_id = p_person_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'El integrante no existe'
      USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'user_id', p_user_id
  );
END;
$$;


--
-- Name: admin_pay_internal_commissions(uuid, uuid[], text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_pay_internal_commissions(p_person_id uuid, p_entry_ids uuid[], p_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_amount numeric(12,2);
  v_payout_id uuid;
  v_count integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Acceso denegado'
      USING ERRCODE = '42501';
  END IF;

  IF p_entry_ids IS NULL
     OR cardinality(p_entry_ids) = 0 THEN
    RAISE EXCEPTION
      'Selecciona comisiones';
  END IF;

  IF p_reference IS NULL
     OR length(btrim(p_reference)) < 3 THEN
    RAISE EXCEPTION
      'La referencia o comprobante es obligatorio'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.internal_commission_entries ice
  WHERE ice.id = ANY(p_entry_ids)
    AND ice.person_id = p_person_id
  ORDER BY ice.id
  FOR UPDATE;

  SELECT
    COALESCE(sum(ice.commission_amount), 0),
    count(*)::integer
  INTO
    v_amount,
    v_count
  FROM public.internal_commission_entries ice
  WHERE ice.id = ANY(p_entry_ids)
    AND ice.person_id = p_person_id
    AND ice.status = 'approved';

  IF v_count <> cardinality(p_entry_ids)
     OR v_amount <= 0 THEN
    RAISE EXCEPTION
      'Todas las comisiones deben estar aprobadas y pertenecer al integrante';
  END IF;

  INSERT INTO public.internal_commission_payouts(
    person_id,
    amount,
    method,
    reference,
    notes
  )
  VALUES (
    p_person_id,
    v_amount,
    NULLIF(btrim(p_method), ''),
    NULLIF(btrim(p_reference), ''),
    NULLIF(btrim(p_notes), '')
  )
  RETURNING id INTO v_payout_id;

  UPDATE public.internal_commission_entries ice
  SET
    status = 'paid',
    payout_id = v_payout_id,
    paid_at = now()
  WHERE ice.id = ANY(p_entry_ids)
    AND ice.person_id = p_person_id
    AND ice.status = 'approved';

  RETURN jsonb_build_object(
    'ok', true,
    'payout_id', v_payout_id,
    'amount', v_amount,
    'entries', v_count
  );
END;
$$;


--
-- Name: admin_reparar_promociones(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reparar_promociones(_empresa_id uuid DEFAULT NULL::uuid, _desde date DEFAULT NULL::date) RETURNS TABLE(venta_id uuid, folio text, empresa text, total_anterior numeric, descuento numeric, total_nuevo numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  d numeric;
  antes numeric;
BEGIN
  IF COALESCE(auth.jwt() ->> 'email','') <> 'diego.leon@uniline.mx' THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  FOR r IN
    SELECT v.id, v.folio, v.total, e.nombre AS empresa
    FROM public.ventas v
    JOIN public.empresas e ON e.id = v.empresa_id
    WHERE v.status <> 'cancelado'
      AND (_empresa_id IS NULL OR v.empresa_id = _empresa_id)
      AND (_desde IS NULL OR v.fecha >= _desde)
      AND NOT EXISTS (SELECT 1 FROM public.promocion_aplicada pa WHERE pa.venta_id = v.id)
    ORDER BY v.created_at DESC
  LOOP
    antes := r.total;
    d := public.fn_reevaluar_promos_venta(r.id);
    IF COALESCE(d,0) > 0 THEN
      venta_id := r.id; folio := r.folio; empresa := r.empresa;
      total_anterior := antes; descuento := d;
      SELECT v2.total INTO total_nuevo FROM public.ventas v2 WHERE v2.id = r.id;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


