CREATE TABLE public.commission_people (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    person_type text NOT NULL,
    partner_id uuid,
    name text NOT NULL,
    email text,
    phone text,
    manager_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    notes text,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commission_people_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT commission_people_not_own_manager CHECK (((manager_id IS NULL) OR (manager_id <> id))),
    CONSTRAINT commission_people_partner_consistency CHECK ((((person_type = 'partner'::text) AND (partner_id IS NOT NULL)) OR ((person_type = 'internal'::text) AND (partner_id IS NULL)))),
    CONSTRAINT commission_people_person_type_check CHECK ((person_type = ANY (ARRAY['internal'::text, 'partner'::text])))
);
