--
-- Name: admin_save_commission_person(uuid, text, text, text, uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_save_commission_person(p_person_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_manager_id uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true, p_notes text DEFAULT NULL::text, p_change_reason text DEFAULT NULL::text) RETURNS public.commission_people
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_person public.commission_people;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Solo un super administrador puede gestionar el equipo de comisiones';
  END IF;

  PERFORM set_config(
    'app.commission_change_reason',
    COALESCE(btrim(p_change_reason), ''),
    true
  );

  IF p_person_id IS NULL THEN
    IF p_name IS NULL OR length(btrim(p_name)) = 0 THEN
      RAISE EXCEPTION 'El nombre es obligatorio';
    END IF;

    INSERT INTO public.commission_people (
      person_type,
      name,
      email,
      phone,
      manager_id,
      is_active,
      notes
    )
    VALUES (
      'internal',
      btrim(p_name),
      NULLIF(btrim(p_email), ''),
      NULLIF(btrim(p_phone), ''),
      p_manager_id,
      p_is_active,
      NULLIF(btrim(p_notes), '')
    )
    RETURNING * INTO v_person;

  ELSE
    SELECT *
    INTO v_person
    FROM public.commission_people
    WHERE id = p_person_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'La persona no existe';
    END IF;

    IF v_person.person_type = 'partner' THEN
      UPDATE public.commission_people
      SET
        manager_id = p_manager_id,
        notes = NULLIF(btrim(p_notes), '')
      WHERE id = p_person_id
      RETURNING * INTO v_person;

    ELSE
      IF p_name IS NULL OR length(btrim(p_name)) = 0 THEN
        RAISE EXCEPTION 'El nombre es obligatorio';
      END IF;

      IF v_person.is_active = true
        AND p_is_active = false
        AND (
          EXISTS (
            SELECT 1
            FROM public.commission_people
            WHERE manager_id = p_person_id
              AND is_active = true
          )
          OR EXISTS (
            SELECT 1
            FROM public.commission_client_attributions
            WHERE managed_by_id = p_person_id
          )
        )
      THEN
        RAISE EXCEPTION
          'Reasigna primero sus colaboradores y clientes antes de desactivarlo';
      END IF;

      UPDATE public.commission_people
      SET
        name = btrim(p_name),
        email = NULLIF(btrim(p_email), ''),
        phone = NULLIF(btrim(p_phone), ''),
        manager_id = p_manager_id,
        is_active = p_is_active,
        notes = NULLIF(btrim(p_notes), '')
      WHERE id = p_person_id
      RETURNING * INTO v_person;
    END IF;
  END IF;

  RETURN v_person;
END;
$$;


--
-- Name: admin_save_team_member(uuid, text, text, text, text, uuid, text, text, text, text, numeric, integer, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_save_team_member(p_person_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_job_title text DEFAULT NULL::text, p_manager_id uuid DEFAULT NULL::uuid, p_access_level text DEFAULT 'executive'::text, p_access_scope text DEFAULT 'own'::text, p_status text DEFAULT 'invited'::text, p_commission_mode text DEFAULT 'none'::text, p_commission_pct numeric DEFAULT 0, p_commission_payment_limit integer DEFAULT NULL::integer, p_commission_fixed_amount numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_change_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_person_id uuid;
  v_user_id uuid;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Solo un super administrador puede gestionar el equipo'
      USING ERRCODE = '42501';
  END IF;

  IF p_name IS NULL OR length(btrim(p_name)) = 0 THEN
    RAISE EXCEPTION
      'El nombre es obligatorio'
      USING ERRCODE = '22023';
  END IF;

  IF p_email IS NULL OR position('@' IN p_email) = 0 THEN
    RAISE EXCEPTION
      'El correo es obligatorio para dar acceso'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.partners partner
    WHERE lower(partner.email) = lower(btrim(p_email))
  ) THEN
    RAISE EXCEPTION
      'Ese correo pertenece a un Partner externo y no puede reutilizarse como integrante interno'
      USING ERRCODE = '23505';
  END IF;

  IF p_access_level NOT IN ('executive', 'supervisor', 'manager')
     OR p_access_scope NOT IN ('own', 'team', 'all')
     OR p_status NOT IN ('invited', 'active', 'suspended') THEN
    RAISE EXCEPTION
      'Configuración de acceso inválida'
      USING ERRCODE = '22023';
  END IF;

  IF p_commission_mode NOT IN (
    'none',
    'first_payment',
    'first_n_payments',
    'recurring',
    'fixed_activation'
  ) THEN
    RAISE EXCEPTION
      'Plan de comisión inválido'
      USING ERRCODE = '22023';
  END IF;

  IF p_commission_mode IN (
    'first_payment',
    'first_n_payments',
    'recurring'
  )
  AND (
    COALESCE(p_commission_pct, 0) <= 0
    OR p_commission_pct > 100
  ) THEN
    RAISE EXCEPTION
      'El porcentaje debe estar entre 0.01 y 100'
      USING ERRCODE = '22023';
  END IF;

  IF p_commission_mode = 'first_n_payments'
     AND (
       p_commission_payment_limit IS NULL
       OR p_commission_payment_limit NOT BETWEEN 1 AND 60
     ) THEN
    RAISE EXCEPTION
      'Indica entre 1 y 60 pagos comisionables'
      USING ERRCODE = '22023';
  END IF;

  IF p_commission_mode = 'fixed_activation'
     AND COALESCE(p_commission_fixed_amount, 0) <= 0 THEN
    RAISE EXCEPTION
      'El monto fijo debe ser mayor a cero'
      USING ERRCODE = '22023';
  END IF;

  IF p_manager_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.commission_people cp
       WHERE cp.id = p_manager_id
         AND cp.person_type = 'internal'
         AND cp.is_active = true
     ) THEN
    RAISE EXCEPTION
      'El encargado no existe o está inactivo';
  END IF;

  PERFORM set_config(
    'app.commission_change_reason',
    COALESCE(btrim(p_change_reason), ''),
    true
  );

  IF p_person_id IS NULL THEN
    SELECT cp.id
    INTO v_person_id
    FROM public.commission_people cp
    WHERE cp.person_type = 'internal'
      AND lower(cp.email) = lower(btrim(p_email));

    IF v_person_id IS NULL THEN
      INSERT INTO public.commission_people(
        person_type,
        name,
        email,
        phone,
        manager_id,
        is_active,
        notes
      )
      VALUES (
        'internal',
        btrim(p_name),
        lower(btrim(p_email)),
        NULLIF(btrim(p_phone), ''),
        p_manager_id,
        p_status <> 'suspended',
        NULLIF(btrim(p_notes), '')
      )
      RETURNING id INTO v_person_id;
    ELSE
      UPDATE public.commission_people cp
      SET
        name = btrim(p_name),
        phone = NULLIF(btrim(p_phone), ''),
        manager_id = p_manager_id,
        is_active = p_status <> 'suspended',
        notes = NULLIF(btrim(p_notes), '')
      WHERE cp.id = v_person_id;
    END IF;

    SELECT au.id
    INTO v_user_id
    FROM auth.users au
    WHERE lower(au.email) = lower(btrim(p_email))
    ORDER BY au.created_at
    LIMIT 1;

  ELSE
    SELECT tm.user_id
    INTO v_user_id
    FROM public.platform_team_members tm
    WHERE tm.person_id = p_person_id;

    IF v_user_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM auth.users account
         WHERE account.id = v_user_id
           AND lower(account.email) = lower(btrim(p_email))
       ) THEN
      RAISE EXCEPTION
        'La cuenta ya está vinculada; cambia su correo desde autenticación antes de editarlo aquí'
        USING ERRCODE = '22023';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.commission_people cp
      WHERE cp.id = p_person_id
        AND cp.person_type = 'internal'
    ) THEN
      RAISE EXCEPTION
        'El integrante interno no existe'
        USING ERRCODE = 'P0002';
    END IF;

    IF p_change_reason IS NULL
       OR length(btrim(p_change_reason)) < 3 THEN
      RAISE EXCEPTION
        'Indica el motivo del cambio'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.commission_people cp
    SET
      name = btrim(p_name),
      email = lower(btrim(p_email)),
      phone = NULLIF(btrim(p_phone), ''),
      manager_id = p_manager_id,
      is_active = p_status <> 'suspended',
      notes = NULLIF(btrim(p_notes), '')
    WHERE cp.id = p_person_id;

    v_person_id := p_person_id;
  END IF;

  IF v_user_id IS NULL THEN
    SELECT au.id
    INTO v_user_id
    FROM auth.users au
    WHERE lower(au.email) = lower(btrim(p_email))
    ORDER BY au.created_at
    LIMIT 1;
  END IF;

  INSERT INTO public.platform_team_members(
    person_id,
    user_id,
    job_title,
    access_level,
    access_scope,
    status,
    commission_mode,
    commission_pct,
    commission_payment_limit,
    commission_fixed_amount,
    invited_at,
    updated_by
  )
  VALUES (
    v_person_id,
    v_user_id,
    NULLIF(btrim(p_job_title), ''),
    p_access_level,
    p_access_scope,
    CASE
      WHEN v_user_id IS NOT NULL
       AND p_status = 'invited'
      THEN 'active'
      ELSE p_status
    END,
    p_commission_mode,
    COALESCE(p_commission_pct, 0),
    CASE
      WHEN p_commission_mode = 'first_n_payments'
      THEN p_commission_payment_limit
      ELSE NULL
    END,
    CASE
      WHEN p_commission_mode = 'fixed_activation'
      THEN COALESCE(p_commission_fixed_amount, 0)
      ELSE 0
    END,
    CASE
      WHEN p_status = 'invited'
      THEN now()
      ELSE NULL
    END,
    auth.uid()
  )
  ON CONFLICT (person_id)
  DO UPDATE SET
    job_title = EXCLUDED.job_title,
    access_level = EXCLUDED.access_level,
    access_scope = EXCLUDED.access_scope,
    status = EXCLUDED.status,
    commission_mode = EXCLUDED.commission_mode,
    commission_pct = EXCLUDED.commission_pct,
    commission_payment_limit = EXCLUDED.commission_payment_limit,
    commission_fixed_amount = EXCLUDED.commission_fixed_amount,
    invited_at = CASE
      WHEN EXCLUDED.status = 'invited'
      THEN COALESCE(
        platform_team_members.invited_at,
        now()
      )
      ELSE platform_team_members.invited_at
    END,
    updated_by = auth.uid();

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', v_person_id,
    'user_id', v_user_id
  );
END;
$$;


