    notes text,
    recorded_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    commissioned_by_id uuid,
    commission_starts_at timestamp with time zone,
    CONSTRAINT commission_client_attributions_channel_check CHECK ((channel = ANY (ARRAY['partner_link'::text, 'partner_coupon'::text, 'manual'::text, 'whatsapp'::text, 'web'::text, 'referral'::text, 'organic'::text, 'other'::text])))
);
ALTER TABLE ONLY public.commission_client_attributions ALTER COLUMN id SET (pg_attver=168578000);
ALTER TABLE ONLY public.commission_client_attributions ALTER COLUMN empresa_id SET (pg_attver=168578000);
ALTER TABLE ONLY public.commission_client_attributions ALTER COLUMN captured_by_id SET (pg_attver=168578000);
