--
-- Name: admin_set_commission_client_attribution(uuid, uuid, uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_commission_client_attribution(p_empresa_id uuid, p_captured_by_id uuid DEFAULT NULL::uuid, p_managed_by_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'manual'::text, p_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_change_reason text DEFAULT NULL::text) RETURNS public.commission_client_attributions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.commission_client_attributions;
  v_result public.commission_client_attributions;
  v_has_existing boolean;
  v_changed boolean;
  v_capture_changed boolean;
  v_partner_id uuid;
  v_partner_slug text;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Solo un super administrador puede asignar clientes';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.empresas
    WHERE id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'La empresa no existe';
  END IF;

  IF p_channel NOT IN (
    'partner_link',
    'partner_coupon',
    'manual',
    'whatsapp',
    'web',
    'referral',
    'organic',
    'other'
  ) THEN
    RAISE EXCEPTION 'Canal de captación no válido';
  END IF;

  IF p_captured_by_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.commission_people
      WHERE id = p_captured_by_id
    )
  THEN
    RAISE EXCEPTION 'La persona que captó al cliente no existe';
  END IF;

  IF p_managed_by_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.commission_people
      WHERE id = p_managed_by_id
        AND is_active = true
    )
  THEN
    RAISE EXCEPTION
      'El encargado actual no existe o está inactivo';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.commission_client_attributions
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  v_has_existing := FOUND;

  v_capture_changed :=
    NOT v_has_existing
    OR v_existing.captured_by_id IS DISTINCT FROM p_captured_by_id;

  IF v_capture_changed
    AND p_captured_by_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.commission_people
      WHERE id = p_captured_by_id
        AND is_active = true
    )
  THEN
    RAISE EXCEPTION
      'No puedes atribuir un cliente nuevo a una persona inactiva';
  END IF;

  IF v_has_existing THEN
    v_changed :=
      v_existing.captured_by_id IS DISTINCT FROM p_captured_by_id
      OR v_existing.managed_by_id IS DISTINCT FROM p_managed_by_id
      OR v_existing.channel IS DISTINCT FROM p_channel
      OR v_existing.notes IS DISTINCT FROM NULLIF(btrim(p_notes), '')
      OR (
        p_captured_at IS NOT NULL
        AND v_existing.captured_at IS DISTINCT FROM p_captured_at
      );

    IF v_changed
      AND (
        p_change_reason IS NULL
        OR length(btrim(p_change_reason)) = 0
      )
    THEN
      RAISE EXCEPTION
        'Indica el motivo de la reasignación para conservar la auditoría';
    END IF;
  END IF;

  PERFORM set_config(
    'app.commission_change_reason',
    COALESCE(btrim(p_change_reason), ''),
    true
  );

  INSERT INTO public.commission_client_attributions (
    empresa_id,
    captured_by_id,
    managed_by_id,
    channel,
    captured_at,
    notes
  )
  VALUES (
    p_empresa_id,
    p_captured_by_id,
    p_managed_by_id,
    p_channel,
    COALESCE(p_captured_at, now()),
    NULLIF(btrim(p_notes), '')
  )
  ON CONFLICT (empresa_id) DO UPDATE SET
    captured_by_id = EXCLUDED.captured_by_id,
    managed_by_id = EXCLUDED.managed_by_id,
    channel = EXCLUDED.channel,
    captured_at = CASE
      WHEN p_captured_at IS NULL
        THEN public.commission_client_attributions.captured_at
      ELSE EXCLUDED.captured_at
    END,
    notes = EXCLUDED.notes
  RETURNING * INTO v_result;

  IF v_capture_changed THEN
    SELECT
      person.partner_id,
      partner.ref_slug
    INTO
      v_partner_id,
      v_partner_slug
    FROM public.commission_people person
    LEFT JOIN public.partners partner
      ON partner.id = person.partner_id
    WHERE person.id = p_captured_by_id;

    IF v_partner_id IS NOT NULL THEN
      INSERT INTO public.partner_atribuciones (
        empresa_id,
        partner_id,
        ref_slug,
        metodo
      )
      VALUES (
        p_empresa_id,
        v_partner_id,
        v_partner_slug,
        'manual'
      )
      ON CONFLICT (empresa_id) DO UPDATE SET
        partner_id = EXCLUDED.partner_id,
        ref_slug = EXCLUDED.ref_slug,
        metodo = 'manual';
    ELSE
      DELETE FROM public.partner_atribuciones
      WHERE empresa_id = p_empresa_id;
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: admin_set_internal_commission_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_internal_commission_status(p_entry_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Acceso denegado'
      USING ERRCODE = '42501';
  END IF;

  IF p_status NOT IN ('approved', 'void') THEN
    RAISE EXCEPTION
      'Estado no permitido'
      USING ERRCODE = '22023';
  END IF;

  IF p_status = 'void'
     AND (
       p_reason IS NULL
       OR length(btrim(p_reason)) < 3
     ) THEN
    RAISE EXCEPTION
      'Indica el motivo de anulación'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.internal_commission_entries ice
  SET
    status = p_status,
    approved_by = CASE
      WHEN p_status = 'approved'
      THEN auth.uid()
      ELSE ice.approved_by
    END,
    approved_at = CASE
      WHEN p_status = 'approved'
      THEN now()
      ELSE ice.approved_at
    END,
    reversal_reason = CASE
      WHEN p_status = 'void'
      THEN btrim(p_reason)
      ELSE ice.reversal_reason
    END
  WHERE ice.id = p_entry_id
    AND ice.status IN ('pending', 'approved');

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'La comisión ya no puede modificarse';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'entry_id', p_entry_id,
    'status', p_status
  );
END;
$$;


--
-- Name: admin_set_team_company_assignment(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_team_company_assignment(p_empresa_id uuid, p_managed_by_id uuid DEFAULT NULL::uuid, p_commissioned_by_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_has_partner boolean;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Acceso denegado'
      USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL
     OR length(btrim(p_reason)) < 3 THEN
    RAISE EXCEPTION
      'Indica el motivo de la asignación'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.empresas e
    WHERE e.id = p_empresa_id
  ) THEN
    RAISE EXCEPTION
      'Empresa no encontrada'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_managed_by_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.platform_team_members tm
       JOIN public.commission_people cp
         ON cp.id = tm.person_id
       WHERE tm.person_id = p_managed_by_id
         AND tm.status IN ('invited', 'active')
         AND cp.is_active = true
     ) THEN
    RAISE EXCEPTION
      'El responsable no es un integrante activo';
  END IF;

  IF p_commissioned_by_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.platform_team_members tm
       JOIN public.commission_people cp
         ON cp.id = tm.person_id
       WHERE tm.person_id = p_commissioned_by_id
         AND tm.status IN ('invited', 'active')
         AND tm.commission_mode <> 'none'
         AND cp.is_active = true
         AND cp.person_type = 'internal'
     ) THEN
    RAISE EXCEPTION
      'El comisionista no está activo o no tiene plan de comisión';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.partner_atribuciones pa
    WHERE pa.empresa_id = p_empresa_id
  )
  INTO v_has_partner;

  IF v_has_partner
     AND p_commissioned_by_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta empresa pertenece a un partner; no puede recibir simultáneamente comisión interna';
  END IF;

  PERFORM set_config(
    'app.commission_change_reason',
    btrim(p_reason),
    true
  );

  INSERT INTO public.commission_client_attributions(
    empresa_id,
    managed_by_id,
    commissioned_by_id,
    commission_starts_at,
    channel,
    notes
  )
  VALUES (
    p_empresa_id,
    p_managed_by_id,
    p_commissioned_by_id,
    CASE
      WHEN p_commissioned_by_id IS NULL
      THEN NULL
      ELSE now()
    END,
    'manual',
    btrim(p_reason)
  )
  ON CONFLICT (empresa_id)
  DO UPDATE SET
    managed_by_id = EXCLUDED.managed_by_id,
    commissioned_by_id = EXCLUDED.commissioned_by_id,
    commission_starts_at = CASE
      WHEN commission_client_attributions.commissioned_by_id
           IS DISTINCT FROM EXCLUDED.commissioned_by_id
      THEN EXCLUDED.commission_starts_at
      ELSE commission_client_attributions.commission_starts_at
    END,
    notes = EXCLUDED.notes;

  UPDATE public.admin_trial_crm_leads lead
  SET
    assigned_to = p_managed_by_id,
    updated_by = auth.uid()
  WHERE lead.empresa_id = p_empresa_id
    AND lead.assigned_to IS DISTINCT FROM p_managed_by_id;

  RETURN jsonb_build_object(
    'ok', true,
    'empresa_id', p_empresa_id,
    'partner_protected', v_has_partner
  );
END;
$$;


--
-- Name: admin_set_team_permissions(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_team_permissions(p_person_id uuid, p_permissions jsonb, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Solo un super administrador puede cambiar permisos' USING ERRCODE = '42501';
  END IF;
  IF p_permissions IS NULL OR jsonb_typeof(p_permissions) <> 'object' THEN
    RAISE EXCEPTION 'La configuración de permisos es inválida' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'Indica el motivo del cambio de permisos' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.platform_team_members tm
    JOIN public.commission_people cp ON cp.id = tm.person_id
    WHERE tm.person_id = p_person_id AND cp.person_type = 'internal'
  ) THEN
    RAISE EXCEPTION 'El integrante no existe' USING ERRCODE = 'P0002';
  END IF;

  PERFORM set_config('app.commission_change_reason', btrim(p_reason), true);
  UPDATE public.platform_team_members tm
  SET permissions = p_permissions, updated_by = auth.uid()
  WHERE tm.person_id = p_person_id;

  RETURN jsonb_build_object('ok', true, 'person_id', p_person_id, 'permissions', p_permissions);
END;
$$;


--
-- Name: admin_sync_duplicados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_sync_duplicados() RETURNS TABLE(empresa_id uuid, cliente_id uuid, folio text, monto numeric, fecha date, cobro_huerfano uuid, cobro_aplicado uuid, seg_diferencia numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Solo super admin';
  END IF;
  RETURN QUERY
  SELECT o.empresa_id, o.cliente_id, v.folio, o.monto, o.fecha,
         o.id, t.id,
         round(abs(extract(epoch from (o.created_at - t.created_at)))::numeric, 1)
  FROM cobros o
  JOIN LATERAL (
    SELECT c2.id, c2.created_at FROM cobros c2
    JOIN cobro_aplicaciones a2 ON a2.cobro_id = c2.id
    WHERE c2.id <> o.id AND c2.empresa_id = o.empresa_id
      AND c2.cliente_id = o.cliente_id AND c2.monto = o.monto AND c2.fecha = o.fecha
    ORDER BY abs(extract(epoch from (c2.created_at - o.created_at))) ASC
    LIMIT 1
  ) t ON true
  LEFT JOIN cobro_aplicaciones ap ON ap.cobro_id = t.id
  LEFT JOIN ventas v ON v.id = ap.venta_id
  WHERE NOT EXISTS (SELECT 1 FROM cobro_aplicaciones a WHERE a.cobro_id = o.id)
  ORDER BY o.fecha DESC
  LIMIT 200;
END $$;


--
-- Name: admin_sync_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_sync_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cobros_dup int;
  v_cobros_huerfanos int;
  v_aplic_dup int;
  v_ventas_dup int;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Solo super admin';
  END IF;

  -- Cobros huérfanos (sin aplicación) que tienen un gemelo YA aplicado
  -- (mismo cliente/monto/fecha) = duplicado exacto del patrón del bug.
  SELECT count(*) INTO v_cobros_dup
  FROM cobros o
  WHERE NOT EXISTS (SELECT 1 FROM cobro_aplicaciones a WHERE a.cobro_id = o.id)
    AND EXISTS (
      SELECT 1 FROM cobros c2
      JOIN cobro_aplicaciones a2 ON a2.cobro_id = c2.id
      WHERE c2.id <> o.id AND c2.empresa_id = o.empresa_id
        AND c2.cliente_id = o.cliente_id AND c2.monto = o.monto AND c2.fecha = o.fecha
    );

  -- Cobros sin ninguna aplicación (INFORMATIVO: incluye anticipos legítimos).
  SELECT count(*) INTO v_cobros_huerfanos
  FROM cobros o
  WHERE NOT EXISTS (SELECT 1 FROM cobro_aplicaciones a WHERE a.cobro_id = o.id);

  -- Misma aplicación (cobro -> venta) repetida = doble aplicación (bug duro).
  SELECT count(*) INTO v_aplic_dup
  FROM (
    SELECT cobro_id, venta_id FROM cobro_aplicaciones
    GROUP BY cobro_id, venta_id HAVING count(*) > 1
  ) x;

  -- Ventas con mismo cliente/total/fecha repetidas (posible duplicado; INFORMATIVO,
  -- puede haber compras legítimas del mismo monto el mismo día).
  SELECT count(*) INTO v_ventas_dup
  FROM (
    SELECT empresa_id, cliente_id, total, fecha
    FROM ventas WHERE total > 0
    GROUP BY empresa_id, cliente_id, total, fecha HAVING count(*) > 1
  ) y;

  RETURN jsonb_build_object(
    'cobros_duplicados', v_cobros_dup,
    'cobros_huerfanos', v_cobros_huerfanos,
    'aplicaciones_duplicadas', v_aplic_dup,
    'ventas_posibles_dup', v_ventas_dup,
    'generado_en', now()
  );
END $$;


--
-- Name: admin_sync_recientes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_sync_recientes() RETURNS TABLE(id uuid, empresa_id uuid, cliente_id uuid, monto numeric, metodo_pago text, fecha date, created_at timestamp with time zone, aplicado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Solo super admin';
  END IF;
  RETURN QUERY
  SELECT c.id, c.empresa_id, c.cliente_id, c.monto, c.metodo_pago, c.fecha, c.created_at,
         EXISTS (SELECT 1 FROM cobro_aplicaciones a WHERE a.cobro_id = c.id)
  FROM cobros c
  ORDER BY c.created_at DESC
  LIMIT 30;
END $$;


--
-- Name: ajustar_entrega(uuid, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_entrega(p_entrega_id uuid, p_lineas jsonb, p_destino text DEFAULT 'camion'::text, p_version timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid      uuid := auth.uid();
  v_ent      public.entregas%ROWTYPE;
  v_ped      public.ventas%ROWTYPE;
  v_truck    uuid;
  v_bodega   uuid;
  v_line     jsonb;
  v_id       uuid;
  v_keep     uuid[];
  p          record;
  m          record;
  v_lote     record;
  v_diff     numeric;
  v_rest     numeric;
  v_take     numeric;
  v_vl       record;
  v_qty      numeric;
  v_cols     text[];
  v_keys     text;
  v_entregado_total numeric;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sesión requerida' USING ERRCODE = '42501'; END IF;
  IF p_destino NOT IN ('camion','bodega') THEN
    RAISE EXCEPTION 'Destino inválido: camion o bodega' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ent FROM public.entregas WHERE id = p_entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega no encontrada' USING ERRCODE = 'P0002'; END IF;
  IF v_ent.empresa_id IS DISTINCT FROM public.get_my_empresa_id() AND NOT public.is_super_admin(v_uid) THEN
    RAISE EXCEPTION 'Sin acceso a esta entrega' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_super_admin(v_uid)
     AND NOT EXISTS (SELECT 1 FROM public.empresas e WHERE e.id = v_ent.empresa_id AND e.owner_user_id = v_uid)
     AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = v_uid)
     AND NOT EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.role_permisos rp ON rp.role_id = ur.role_id
                     WHERE ur.user_id = v_uid AND rp.modulo = 'logistica.entregas' AND rp.accion = 'editar' AND rp.permitido)
     AND EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.role_permisos rp ON rp.role_id = ur.role_id
                 WHERE ur.user_id = v_uid AND rp.modulo = 'ruta.editar_entrega' AND rp.accion = 'ver' AND NOT rp.permitido)
  THEN
    RAISE EXCEPTION 'No tienes permiso para ajustar entregas' USING ERRCODE = '42501';
  END IF;

  IF v_ent.status::text <> 'hecho' THEN
    RAISE EXCEPTION 'Solo se ajusta una entrega ya entregada (estado actual: %).', v_ent.status::text USING ERRCODE = 'P0001';
  END IF;
  IF p_version IS NOT NULL AND v_ent.updated_at IS DISTINCT FROM p_version THEN
    RAISE EXCEPTION 'La entrega cambió en otro dispositivo. Vuelve a abrirla.' USING ERRCODE = '40001';
  END IF;
  IF p_lineas IS NULL OR jsonb_typeof(p_lineas) <> 'array' THEN
    RAISE EXCEPTION 'Renglones inválidos.' USING ERRCODE = '22023';
  END IF;

  IF v_ent.pedido_id IS NOT NULL THEN
    SELECT * INTO v_ped FROM public.ventas WHERE id = v_ent.pedido_id FOR UPDATE;
    IF v_ped.status::text IN ('cancelado','facturado') OR v_ped.cerrado_at IS NOT NULL
       OR EXISTS (SELECT 1 FROM public.venta_lineas WHERE venta_id = v_ped.id AND (COALESCE(facturado,false) OR factura_cfdi_id IS NOT NULL)) THEN
      RAISE EXCEPTION 'El pedido está facturado, cancelado o cerrado: corrígelo con nota de crédito o reábrelo.' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT almacen_id INTO v_truck FROM public.profiles WHERE id = COALESCE(v_ent.vendedor_ruta_id, v_ent.vendedor_id);
  v_truck := COALESCE(v_truck, v_ent.almacen_id);
  IF v_truck IS NULL THEN RAISE EXCEPTION 'La entrega no tiene almacén de ruta.' USING ERRCODE = 'P0001'; END IF;
  v_bodega := COALESCE(
    (SELECT el.almacen_origen_id FROM public.entrega_lineas el WHERE el.entrega_id = p_entrega_id AND el.almacen_origen_id IS NOT NULL LIMIT 1),
    v_ent.almacen_id);
  IF p_destino = 'bodega' AND (v_bodega IS NULL OR v_bodega = v_truck) THEN
    RAISE EXCEPTION 'No se identificó la bodega de origen de esta entrega.' USING ERRCODE = 'P0001';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _aj_antes (producto_id uuid, cant numeric) ON COMMIT DROP;
  DELETE FROM _aj_antes WHERE true;
  INSERT INTO _aj_antes SELECT producto_id, SUM(COALESCE(cantidad_entregada,0))
    FROM public.entrega_lineas WHERE entrega_id = p_entrega_id AND hecho GROUP BY producto_id;

  SELECT COALESCE(array_agg(NULLIF(x->>'id','')::uuid), '{}') INTO v_keep
  FROM jsonb_array_elements(p_lineas) x WHERE NULLIF(x->>'id','') IS NOT NULL;
  UPDATE public.entrega_lineas SET cantidad_entregada = 0
   WHERE entrega_id = p_entrega_id AND NOT (id = ANY(v_keep)) AND COALESCE(cantidad_entregada,0) <> 0;

  PERFORM set_config('rutapp.ajuste_entrega', 'on', true);
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lineas) LOOP
    v_id := NULLIF(v_line->>'id','')::uuid;
    v_qty := COALESCE((v_line->>'cantidad_entregada')::numeric, 0);
    IF v_qty < 0 THEN RAISE EXCEPTION 'Cantidad negativa.' USING ERRCODE = '22023'; END IF;
    IF v_id IS NOT NULL THEN
      UPDATE public.entrega_lineas
         SET cantidad_entregada = v_qty,
             producto_id = COALESCE(NULLIF(v_line->>'producto_id','')::uuid, producto_id),
             unidad_id = COALESCE(NULLIF(v_line->>'unidad_id','')::uuid, unidad_id),
             hecho = true
       WHERE id = v_id AND entrega_id = p_entrega_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Un renglón no pertenece a esta entrega.' USING ERRCODE = '22023'; END IF;
    ELSE
      IF NULLIF(v_line->>'producto_id','') IS NULL THEN RAISE EXCEPTION 'Renglón sin producto.' USING ERRCODE = '22023'; END IF;
      INSERT INTO public.entrega_lineas (entrega_id, producto_id, unidad_id, cantidad_pedida, cantidad_entregada, hecho, almacen_origen_id)
      VALUES (p_entrega_id, (v_line->>'producto_id')::uuid, NULLIF(v_line->>'unidad_id','')::uuid, 0, v_qty, true, v_bodega);
    END IF;
  END LOOP;
  PERFORM set_config('rutapp.ajuste_entrega', 'off', true);

  FOR p IN
    SELECT COALESCE(n.producto_id, a.producto_id) AS producto_id,
           COALESCE(n.cant, 0) AS nuevo, COALESCE(a.cant, 0) AS antes
    FROM (SELECT producto_id, SUM(COALESCE(cantidad_entregada,0)) AS cant
            FROM public.entrega_lineas WHERE entrega_id = p_entrega_id AND hecho GROUP BY producto_id) n
    FULL JOIN _aj_antes a ON a.producto_id = n.producto_id
  LOOP
    v_diff := ROUND(p.nuevo - p.antes, 6);
    CONTINUE WHEN abs(v_diff) < 0.000001;

    IF v_diff > 0 THEN
      UPDATE public.stock_almacen SET cantidad = cantidad - v_diff, updated_at = now()
       WHERE almacen_id = v_truck AND producto_id = p.producto_id;
      IF NOT FOUND THEN
        INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
        VALUES (v_ent.empresa_id, v_truck, p.producto_id, -v_diff);
      END IF;
      v_rest := v_diff;
      IF EXISTS (SELECT 1 FROM public.productos WHERE id = p.producto_id AND COALESCE(maneja_lote,false)) THEN
        FOR v_lote IN
          SELECT sl.lote_id, sl.cantidad AS existencia FROM public.stock_lotes sl JOIN public.lotes l ON l.id = sl.lote_id
           WHERE sl.almacen_id = v_truck AND sl.producto_id = p.producto_id AND sl.cantidad > 0
           ORDER BY l.fecha_caducidad ASC NULLS LAST, l.created_at ASC FOR UPDATE OF sl
        LOOP
          EXIT WHEN v_rest <= 0.000001;
          v_take := LEAST(v_lote.existencia, v_rest);
          INSERT INTO public.movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, vendedor_destino_id,
                 lote_id, referencia_tipo, referencia_id, user_id, notas, fecha)
          VALUES (v_ent.empresa_id, 'salida', p.producto_id, v_take, v_truck, COALESCE(v_ent.vendedor_ruta_id, v_ent.vendedor_id),
                 v_lote.lote_id, 'entrega_hecho', p_entrega_id, v_uid, 'Ajuste de entrega (folio ' || COALESCE(v_ent.folio,'—') || ')', CURRENT_DATE);
          v_rest := v_rest - v_take;
        END LOOP;
      END IF;
      IF v_rest > 0.000001 THEN
        INSERT INTO public.movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, vendedor_destino_id,
               referencia_tipo, referencia_id, user_id, notas, fecha)
        VALUES (v_ent.empresa_id, 'salida', p.producto_id, v_rest, v_truck, COALESCE(v_ent.vendedor_ruta_id, v_ent.vendedor_id),
               'entrega_hecho', p_entrega_id, v_uid, 'Ajuste de entrega (folio ' || COALESCE(v_ent.folio,'—') || ')', CURRENT_DATE);
      END IF;
    ELSE
      v_rest := -v_diff;
      FOR m IN
        SELECT id, cantidad, lote_id FROM public.movimientos_inventario
         WHERE referencia_id = p_entrega_id AND referencia_tipo = 'entrega_hecho' AND tipo = 'salida'
           AND producto_id = p.producto_id AND almacen_origen_id = v_truck AND cantidad > 0
         ORDER BY created_at DESC FOR UPDATE
      LOOP
        EXIT WHEN v_rest <= 0.000001;
        v_take := LEAST(m.cantidad, v_rest);
        UPDATE public.stock_almacen SET cantidad = cantidad + v_take, updated_at = now()
         WHERE almacen_id = v_truck AND producto_id = p.producto_id;
        IF m.lote_id IS NOT NULL THEN
          PERFORM public._aplica_stock_lote(v_ent.empresa_id, v_truck, p.producto_id, m.lote_id, v_take);
        END IF;
        IF m.cantidad - v_take <= 0.000001 THEN
          DELETE FROM public.movimientos_inventario WHERE id = m.id;
        ELSE
          UPDATE public.movimientos_inventario SET cantidad = cantidad - v_take WHERE id = m.id;
        END IF;
        IF p_destino = 'bodega' THEN
          PERFORM public._aj_regresar_a_bodega(v_ent, p.producto_id, m.lote_id, v_take, v_truck, v_bodega, v_uid);
        END IF;
        v_rest := v_rest - v_take;
      END LOOP;
      IF v_rest > 0.000001 THEN
        RAISE EXCEPTION 'No se encontró lo descontado de la entrega para regresar (faltan %).', v_rest USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF v_ent.pedido_id IS NOT NULL THEN
      SELECT * INTO v_vl FROM public.venta_lineas WHERE venta_id = v_ent.pedido_id AND producto_id = p.producto_id
        ORDER BY created_at LIMIT 1 FOR UPDATE;
      IF v_diff < 0 AND v_vl.id IS NOT NULL THEN
        v_qty := GREATEST(0, COALESCE(v_vl.cantidad,0) + v_diff);
        IF v_qty <= 0.000001 THEN
          IF EXISTS (SELECT 1 FROM public.venta_comisiones c WHERE c.venta_linea_id = v_vl.id AND (c.pagada OR c.pago_comision_id IS NOT NULL)) THEN
            RAISE EXCEPTION 'No se puede quitar del pedido un producto cuya comisión ya se pagó.' USING ERRCODE = 'P0001';
          END IF;
          DELETE FROM public.venta_linea_lotes WHERE venta_linea_id = v_vl.id;
          DELETE FROM public.promocion_aplicada WHERE venta_linea_id = v_vl.id;
          DELETE FROM public.venta_lineas WHERE id = v_vl.id;
        ELSE
          UPDATE public.venta_lineas SET
            cantidad = v_qty,
            subtotal = ROUND(COALESCE(subtotal,0) * v_qty / cantidad, 2),
            iva_monto = ROUND(COALESCE(iva_monto,0) * v_qty / cantidad, 2),
            ieps_monto = ROUND(COALESCE(ieps_monto,0) * v_qty / cantidad, 2),
            total = ROUND(COALESCE(total,0) * v_qty / cantidad, 2)
          WHERE id = v_vl.id;
        END IF;
      ELSIF v_diff > 0 THEN
        SELECT COALESCE(SUM(el.cantidad_entregada),0) INTO v_entregado_total
          FROM public.entrega_lineas el JOIN public.entregas e ON e.id = el.entrega_id
         WHERE e.pedido_id = v_ent.pedido_id AND e.status::text NOT IN ('cancelado','no_entregado')
           AND el.producto_id = p.producto_id;
        IF v_vl.id IS NOT NULL THEN
          IF v_entregado_total > COALESCE(v_vl.cantidad,0) + 0.000001 AND COALESCE(v_vl.cantidad,0) > 0 THEN
            UPDATE public.venta_lineas SET
              subtotal = ROUND(COALESCE(subtotal,0) * v_entregado_total / cantidad, 2),
              iva_monto = ROUND(COALESCE(iva_monto,0) * v_entregado_total / cantidad, 2),
              ieps_monto = ROUND(COALESCE(ieps_monto,0) * v_entregado_total / cantidad, 2),
              total = ROUND(COALESCE(total,0) * v_entregado_total / cantidad, 2),
              cantidad = v_entregado_total
            WHERE id = v_vl.id;
          END IF;
        ELSE
          SELECT x INTO v_line FROM jsonb_array_elements(p_lineas) x
           WHERE (x->>'producto_id')::uuid = p.producto_id AND x ? 'venta_linea' LIMIT 1;
          IF v_line IS NULL THEN
            RAISE EXCEPTION 'Falta el precio del producto nuevo para agregarlo al pedido.' USING ERRCODE = '22023';
          END IF;
          SELECT array_agg(column_name::text) INTO v_cols FROM information_schema.columns
           WHERE table_schema = 'public' AND table_name = 'venta_lineas'
             AND column_name NOT IN ('id','venta_id','empresa_id','created_at','updated_at','facturado','factura_cfdi_id',
                                     'comision_pct','comision_monto','producto_id','cantidad');
          SELECT string_agg(quote_ident(k), ', ') INTO v_keys
            FROM jsonb_object_keys(v_line->'venta_linea') k WHERE k = ANY(v_cols);
          EXECUTE format('INSERT INTO public.venta_lineas (venta_id, producto_id, cantidad%1$s) SELECT $2, $3, $4%2$s FROM jsonb_populate_record(NULL::public.venta_lineas, $1)',
                         CASE WHEN v_keys IS NULL THEN '' ELSE ', ' || v_keys END,
                         CASE WHEN v_keys IS NULL THEN '' ELSE ', ' || v_keys END)
            USING v_line->'venta_linea', v_ent.pedido_id, p.producto_id, v_entregado_total;
        END IF;
      END IF;
    END IF;
  END LOOP;

  SET CONSTRAINTS ALL IMMEDIATE;
  IF v_ent.pedido_id IS NOT NULL THEN
    PERFORM public.fn_recalc_venta_header(v_ent.pedido_id);
  END IF;

  SELECT * INTO v_ent FROM public.entregas WHERE id = p_entrega_id;
  RETURN jsonb_build_object('ok', true, 'updated_at', v_ent.updated_at,
    'pedido_total', (SELECT total FROM public.ventas WHERE id = v_ent.pedido_id),
    'pedido_saldo', (SELECT saldo_pendiente FROM public.ventas WHERE id = v_ent.pedido_id));
END;
$_$;


--
-- Name: ajustar_pedido_por_entregado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_pedido_por_entregado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pedido_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'entrega_lineas' THEN
    SELECT e.pedido_id INTO v_pedido_id FROM public.entregas e WHERE e.id = NEW.entrega_id;
  ELSE
    v_pedido_id := NEW.pedido_id;
  END IF;
  IF v_pedido_id IS NULL THEN RETURN NEW; END IF;
  PERFORM public.fn_recalc_venta_saldo(v_pedido_id);
  RETURN NEW;
END;
$$;


--
-- Name: apartar_cfdi_timbrado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apartar_cfdi_timbrado(p_cfdi_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cfdi record;
  v_ids uuid[];
  r record;
  v_ocupada numeric;
  v_serie text;
  v_folio text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;

  SELECT id, empresa_id, status, facturama_id, serie, folio, sustituye_cfdi_id INTO v_cfdi
  FROM cfdis WHERE id = p_cfdi_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CFDI no encontrado'; END IF;
  IF v_cfdi.facturama_id IS NOT NULL THEN RAISE EXCEPTION 'Esta factura ya está timbrada'; END IF;
  IF v_cfdi.status NOT IN ('borrador', 'error') THEN
    RAISE EXCEPTION 'Esta factura ya se está timbrando o quedó incierta (estado %). Usa Reconciliar.', v_cfdi.status;
  END IF;

  SELECT array_agg(DISTINCT venta_linea_id ORDER BY venta_linea_id) INTO v_ids
  FROM cfdi_lineas WHERE cfdi_id = p_cfdi_id AND venta_linea_id IS NOT NULL;

  IF v_ids IS NOT NULL THEN
    -- Bloqueo en orden fijo: dos timbrados sobre la misma venta se esperan, no se cruzan.
    PERFORM 1 FROM venta_lineas WHERE id = ANY (v_ids) ORDER BY id FOR UPDATE;

    IF (SELECT count(*) FROM venta_lineas vl JOIN ventas v ON v.id = vl.venta_id
        WHERE vl.id = ANY (v_ids) AND v.empresa_id = v_cfdi.empresa_id) <> array_length(v_ids, 1) THEN
      RAISE EXCEPTION 'Alguna línea no pertenece a una venta de esta empresa';
    END IF;

    FOR r IN
      SELECT cl.venta_linea_id, sum(cl.cantidad) AS pedida, max(cl.descripcion) AS descripcion,
             vl.cantidad AS vendida, COALESCE(vl.facturado, false) AS facturado, COALESCE(vl.facturado_global, false) AS fglobal
      FROM cfdi_lineas cl JOIN venta_lineas vl ON vl.id = cl.venta_linea_id
      WHERE cl.cfdi_id = p_cfdi_id
      GROUP BY cl.venta_linea_id, vl.cantidad, vl.facturado, vl.facturado_global
    LOOP
      SELECT COALESCE(sum(x.cantidad), 0) INTO v_ocupada
      FROM cfdi_lineas x JOIN cfdis c ON c.id = x.cfdi_id
      WHERE x.venta_linea_id = r.venta_linea_id AND x.cfdi_id <> p_cfdi_id
        AND public.cfdi_status_ocupa(c.status)
        AND c.id IS DISTINCT FROM v_cfdi.sustituye_cfdi_id;
      -- Marcas anteriores a la Fase 2 sin factura vigente que las explique: la línea cuenta como facturada completa.
      IF (r.facturado OR r.fglobal) AND NOT EXISTS (
        SELECT 1 FROM cfdi_lineas x JOIN cfdis c ON c.id = x.cfdi_id
        WHERE x.venta_linea_id = r.venta_linea_id AND public.cfdi_status_vigente(c.status)
      ) THEN
        v_ocupada := COALESCE(r.vendida, 0);
      END IF;
      IF r.pedida > COALESCE(r.vendida, 0) - v_ocupada + 0.000001 THEN
        RAISE EXCEPTION '"%": solo quedan % por facturar (pides %)', r.descripcion,
          greatest(COALESCE(r.vendida, 0) - v_ocupada, 0), r.pedida;
      END IF;
    END LOOP;

    UPDATE venta_lineas SET factura_cfdi_id = p_cfdi_id WHERE id = ANY (v_ids);
  END IF;

  IF COALESCE(btrim(v_cfdi.folio), '') = '' THEN
    INSERT INTO cfdi_series (empresa_id) VALUES (v_cfdi.empresa_id) ON CONFLICT (empresa_id) DO NOTHING;
    UPDATE cfdi_series SET siguiente_folio = siguiente_folio + 1, updated_at = now()
    WHERE empresa_id = v_cfdi.empresa_id
    RETURNING serie, (siguiente_folio - 1)::text INTO v_serie, v_folio;
  ELSE
    v_serie := COALESCE(NULLIF(btrim(v_cfdi.serie), ''), 'A');
    v_folio := btrim(v_cfdi.folio);
  END IF;

  UPDATE cfdis SET status = 'timbrando', stamping_started_at = now(), error_detalle = NULL,
         serie = v_serie, folio = v_folio, updated_at = now()
  WHERE id = p_cfdi_id;

  RETURN jsonb_build_object('serie', v_serie, 'folio', v_folio);
END;
$$;


--
-- Name: apartar_rep(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apartar_rep(p_empresa_id uuid, p_cobro_id uuid, p_user_id uuid, p_cabecera jsonb, p_documentos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cobro record;
  v_id uuid;
  v_serie text;
  v_folio text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;

  SELECT id, empresa_id, status INTO v_cobro FROM cobros WHERE id = p_cobro_id FOR UPDATE;
  IF NOT FOUND OR v_cobro.empresa_id <> p_empresa_id THEN RAISE EXCEPTION 'Cobro no encontrado'; END IF;
  IF COALESCE(v_cobro.status, 'activo') = 'cancelado' THEN RAISE EXCEPTION 'El cobro está cancelado'; END IF;

  INSERT INTO cfdi_series (empresa_id) VALUES (p_empresa_id) ON CONFLICT (empresa_id) DO NOTHING;
  UPDATE cfdi_series SET siguiente_folio_pago = siguiente_folio_pago + 1, updated_at = now()
  WHERE empresa_id = p_empresa_id
  RETURNING serie_pago, (siguiente_folio_pago - 1)::text INTO v_serie, v_folio;

  BEGIN
    INSERT INTO cfdi_pagos (empresa_id, cobro_id, user_id, status, stamping_started_at, serie, folio,
                            fecha_pago, forma_pago, moneda, tipo_cambio, monto, expedition_place, facturama_ambiente,
                            receiver_rfc, receiver_name, receiver_fiscal_regime, receiver_tax_zip_code)
    VALUES (p_empresa_id, p_cobro_id, p_user_id, 'timbrando', now(), v_serie, v_folio,
            (p_cabecera->>'fecha_pago')::timestamptz, p_cabecera->>'forma_pago', 'MXN', 1,
            (p_cabecera->>'monto')::numeric, p_cabecera->>'expedition_place', COALESCE(p_cabecera->>'facturama_ambiente', 'produccion'),
            p_cabecera->>'receiver_rfc', p_cabecera->>'receiver_name',
            p_cabecera->>'receiver_fiscal_regime', p_cabecera->>'receiver_tax_zip_code')
    RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Este cobro ya tiene un complemento de pago vigente o en proceso';
  END;

  INSERT INTO cfdi_pago_documentos (cfdi_pago_id, empresa_id, cfdi_id, venta_id, cfdi_relacionado_uuid, serie_dr, folio_dr,
                                    moneda_dr, tipo_cambio_dr, num_parcialidad, imp_saldo_ant, imp_pagado,
                                    imp_saldo_insoluto, objeto_imp_dr, metodo_pago_dr, iva_trasladado_dr, impuestos_dr)
  SELECT v_id, p_empresa_id, d.cfdi_id, d.venta_id, d.uuid, d.serie, d.folio, 'MXN', 1, d.num_parcialidad,
         d.imp_saldo_ant, d.imp_pagado, d.imp_saldo_insoluto, d.objeto_imp, 'PPD', d.iva, d.impuestos
  FROM jsonb_to_recordset(p_documentos) AS d(cfdi_id uuid, venta_id uuid, uuid text, serie text, folio text,
       num_parcialidad int, imp_saldo_ant numeric, imp_pagado numeric, imp_saldo_insoluto numeric,
       objeto_imp text, iva numeric, impuestos jsonb);

  RETURN jsonb_build_object('id', v_id, 'serie', v_serie, 'folio', v_folio);
END;
$$;


--
-- Name: aplicar_cobro(uuid, uuid, numeric, text, text, date, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_cobro(p_empresa_id uuid, p_cliente_id uuid, p_monto numeric, p_metodo text, p_referencia text, p_fecha date, p_aplicaciones jsonb, p_notas text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN public.aplicar_cobro(
    p_empresa_id,
    p_cliente_id,
    p_monto,
    p_metodo,
    p_referencia,
    p_fecha,
    p_aplicaciones,
    NULL::uuid,
    NULL::text,
    p_notas,
    p_user_id
  );
END;
$$;


--
-- Name: aplicar_cobro(uuid, uuid, numeric, text, text, date, jsonb, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_cobro(p_empresa_id uuid, p_cliente_id uuid, p_monto numeric, p_metodo text, p_referencia text, p_fecha date, p_aplicaciones jsonb, p_turno_id uuid, p_origen text, p_notas text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cobro_id uuid;
  v_app jsonb;
  v_total_app numeric := 0;
  v_user_id uuid := COALESCE(p_user_id, auth.uid());
  v_origen text := NULLIF(lower(btrim(p_origen)), '');
BEGIN
  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'Monto del cobro debe ser mayor a 0';
  END IF;

  FOR v_app IN
    SELECT * FROM jsonb_array_elements(COALESCE(p_aplicaciones, '[]'::jsonb))
  LOOP
    v_total_app := v_total_app + COALESCE((v_app->>'monto_aplicado')::numeric, 0);
  END LOOP;

  IF v_total_app > p_monto + 0.01 THEN
    RAISE EXCEPTION 'Suma de aplicaciones (%) excede monto del cobro (%)', v_total_app, p_monto;
  END IF;

  IF v_origen = 'pos' THEN
    IF p_turno_id IS NULL THEN
      RAISE EXCEPTION 'Un cobro POS requiere un turno activo';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.caja_turnos t
      WHERE t.id = p_turno_id
        AND t.empresa_id = p_empresa_id
        AND t.cajero_id = v_user_id
        AND t.status = 'abierto'
    ) THEN
      RAISE EXCEPTION 'El turno POS no está abierto o no corresponde a la empresa y cajero';
    END IF;
  ELSIF p_turno_id IS NOT NULL THEN
    RAISE EXCEPTION 'Sólo los cobros con origen POS pueden asociarse a un turno';
  END IF;

  INSERT INTO public.cobros (
    empresa_id,
    cliente_id,
    user_id,
    monto,
    metodo_pago,
    referencia,
    fecha,
    notas,
    status,
    turno_id,
    origen
  ) VALUES (
    p_empresa_id,
    p_cliente_id,
    v_user_id,
    p_monto,
    p_metodo,
    p_referencia,
    p_fecha,
    p_notas,
    'activo',
    p_turno_id,
    v_origen
  )
  RETURNING id INTO v_cobro_id;

  FOR v_app IN
    SELECT * FROM jsonb_array_elements(COALESCE(p_aplicaciones, '[]'::jsonb))
  LOOP
    IF COALESCE((v_app->>'monto_aplicado')::numeric, 0) > 0 THEN
      INSERT INTO public.cobro_aplicaciones (cobro_id, venta_id, monto_aplicado)
      VALUES (
        v_cobro_id,
        (v_app->>'venta_id')::uuid,
        (v_app->>'monto_aplicado')::numeric
      );
    END IF;
  END LOOP;

  RETURN v_cobro_id;
END;
$$;


--
-- Name: aplicar_lote_ajuste_reset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_lote_ajuste_reset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_maneja boolean; v_pending numeric; v_lote RECORD; v_take numeric;
BEGIN
  IF NEW.lote_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.referencia_tipo <> 'ajuste' THEN RETURN NEW; END IF;
  IF NEW.tipo <> 'salida' OR NEW.almacen_origen_id IS NULL THEN RETURN NEW; END IF;
  IF COALESCE(NEW.notas, '') NOT ILIKE 'Reinicio a ceros%' THEN RETURN NEW; END IF;
  SELECT COALESCE(maneja_lote, false) INTO v_maneja FROM public.productos WHERE id = NEW.producto_id;
  IF NOT v_maneja THEN RETURN NEW; END IF;
  v_pending := COALESCE(NEW.cantidad, 0);
  FOR v_lote IN
    SELECT sl.lote_id, sl.cantidad AS existencia
    FROM public.stock_lotes sl JOIN public.lotes l ON l.id = sl.lote_id
    WHERE sl.almacen_id = NEW.almacen_origen_id AND sl.producto_id = NEW.producto_id AND sl.cantidad > 0
    ORDER BY l.fecha_caducidad ASC NULLS LAST, l.created_at ASC FOR UPDATE OF sl
  LOOP
    EXIT WHEN v_pending <= 0;
    v_take := LEAST(v_lote.existencia, v_pending);
    INSERT INTO public.movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
    VALUES (NEW.empresa_id, 'salida', NEW.producto_id, v_take, NEW.almacen_origen_id, v_lote.lote_id,
            'ajuste_lote', NEW.referencia_id, COALESCE(NEW.fecha, CURRENT_DATE), 'Reinicio a ceros lote (FEFO)');
    v_pending := v_pending - v_take;
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: aplicar_lote_carga_entrega(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_lote_carga_entrega() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active text[] := ARRAY['asignado','cargado','en_ruta'];
  v_truck uuid; v_vend uuid; v_mov RECORD; v_bodega uuid;
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.status::text = ANY(v_active)
          OR (OLD.status::text = 'hecho' AND NEW.status::text IN ('borrador','surtido')))
     AND NOT (NEW.status::text = ANY(v_active)) AND NEW.status::text <> 'hecho' THEN
    IF NEW.status::text IN ('cancelado','no_entregado') THEN RETURN NEW; END IF;
    FOR v_mov IN
      SELECT producto_id, lote_id, cantidad, almacen_destino_id AS truck
      FROM public.movimientos_inventario
      WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega_cargado_lote' AND lote_id IS NOT NULL
    LOOP
      SELECT almacen_origen_id INTO v_bodega FROM public.movimientos_inventario
      WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega' AND tipo = 'salida'
        AND producto_id = v_mov.producto_id AND lote_id = v_mov.lote_id AND almacen_origen_id IS NOT NULL LIMIT 1;
      -- El lote sale del camión; en bodega sigue apartado por el surtido (se repone al des-surtir).
      IF v_mov.truck IS NOT NULL THEN
        INSERT INTO public.movimientos_inventario
          (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
        VALUES (NEW.empresa_id, 'salida', v_mov.producto_id, v_mov.cantidad, v_mov.truck, v_mov.lote_id,
                'entrega_cargado_lote_rev', NEW.id, CURRENT_DATE, 'Reversa lote · carga (reasignación) sale del camión');
      END IF;
    END LOOP;
    DELETE FROM public.movimientos_inventario WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega_cargado_lote';
    RETURN NEW;
  END IF;
  IF NOT (NEW.status::text = ANY(v_active)) THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status::text = ANY(v_active) THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega_cargado_lote') THEN RETURN NEW; END IF;
  v_vend := COALESCE(NEW.vendedor_ruta_id, NEW.vendedor_id);
  IF v_vend IS NULL THEN RETURN NEW; END IF;
  SELECT almacen_id INTO v_truck FROM public.profiles WHERE id = v_vend;
  IF v_truck IS NULL THEN RETURN NEW; END IF;
  FOR v_mov IN
    SELECT producto_id, lote_id, SUM(cantidad) AS cantidad FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega' AND tipo = 'salida' AND lote_id IS NOT NULL
    GROUP BY producto_id, lote_id
  LOOP
    INSERT INTO public.movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, vendedor_destino_id, fecha, notas)
    VALUES (NEW.empresa_id, 'entrada', v_mov.producto_id, v_mov.cantidad, v_truck, v_mov.lote_id,
            'entrega_cargado_lote', NEW.id, v_vend, CURRENT_DATE, 'Carga lote a camión');
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: aplicar_lote_descarga(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_lote_descarga() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_camion uuid; v_bodega uuid; v_linea RECORD; v_pending numeric; v_lote RECORD; v_take numeric;
BEGIN
  IF NEW.status <> 'aprobada' THEN RETURN NEW; END IF;
  IF OLD.status = 'aprobada' THEN RETURN NEW; END IF;
  IF NOT COALESCE(NEW.descargo_camion, false) THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario WHERE referencia_id = NEW.id AND referencia_tipo = 'descarga_lote') THEN RETURN NEW; END IF;
  SELECT almacen_id INTO v_camion FROM public.profiles WHERE id = NEW.vendedor_id;
  v_bodega := NEW.almacen_destino_id;
  IF v_camion IS NULL OR v_bodega IS NULL THEN RETURN NEW; END IF;
  FOR v_linea IN SELECT producto_id, COALESCE(cantidad_real, 0) AS cantidad_real FROM public.descarga_ruta_lineas WHERE descarga_id = NEW.id LOOP
    v_pending := v_linea.cantidad_real;
    FOR v_lote IN
      SELECT sl.lote_id, sl.cantidad AS existencia FROM public.stock_lotes sl JOIN public.lotes l ON l.id = sl.lote_id
      WHERE sl.almacen_id = v_camion AND sl.producto_id = v_linea.producto_id AND sl.cantidad > 0
      ORDER BY l.fecha_caducidad ASC NULLS LAST, l.created_at ASC FOR UPDATE OF sl
    LOOP
      EXIT WHEN v_pending <= 0;
      v_take := LEAST(v_lote.existencia, v_pending);
      INSERT INTO public.movimientos_inventario
        (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
      VALUES (NEW.empresa_id, 'traspaso', v_linea.producto_id, v_take, v_camion, v_bodega, v_lote.lote_id, 'descarga_lote', NEW.id, COALESCE(NEW.fecha, CURRENT_DATE), 'Descarga lote · camión→bodega (FEFO)');
      v_pending := v_pending - v_take;
    END LOOP;
    FOR v_lote IN
      SELECT sl.lote_id, sl.cantidad AS existencia FROM public.stock_lotes sl
      WHERE sl.almacen_id = v_camion AND sl.producto_id = v_linea.producto_id AND sl.cantidad > 0 FOR UPDATE OF sl
    LOOP
      INSERT INTO public.movimientos_inventario
        (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
      VALUES (NEW.empresa_id, 'salida', v_linea.producto_id, v_lote.existencia, v_camion, v_lote.lote_id, 'descarga_lote', NEW.id, COALESCE(NEW.fecha, CURRENT_DATE), 'Descarga lote · merma/faltante en camión');
    END LOOP;
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: aplicar_lote_devolucion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_lote_devolucion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_dev RECORD; v_almacen uuid; v_merma uuid; v_maneja boolean; v_lote uuid;
BEGIN
  SELECT COALESCE(maneja_lote, false) INTO v_maneja FROM public.productos WHERE id = NEW.producto_id;
  IF NOT v_maneja THEN RETURN NEW; END IF;
  SELECT id, empresa_id, user_id, vendedor_id INTO v_dev FROM public.devoluciones WHERE id = NEW.devolucion_id;
  IF v_dev.id IS NULL THEN RETURN NEW; END IF;
  SELECT almacen_id INTO v_almacen FROM public.profiles WHERE id = v_dev.user_id;
  IF v_almacen IS NULL AND v_dev.vendedor_id IS NOT NULL THEN
    SELECT almacen_id INTO v_almacen FROM public.profiles WHERE id = v_dev.vendedor_id;
  END IF;
  IF NEW.motivo::text IN ('danado', 'vencido', 'caducado') THEN
    SELECT id INTO v_merma FROM public.almacenes WHERE empresa_id = v_dev.empresa_id AND es_merma = true LIMIT 1;
    IF v_merma IS NOT NULL THEN RETURN NEW; END IF;
  END IF;
  IF v_almacen IS NULL THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario
             WHERE referencia_id = v_dev.id AND referencia_tipo = 'devolucion_lote' AND producto_id = NEW.producto_id) THEN RETURN NEW; END IF;
  SELECT id INTO v_lote FROM public.lotes
  WHERE producto_id = NEW.producto_id AND empresa_id = v_dev.empresa_id AND COALESCE(activo, true) = true
  ORDER BY fecha_caducidad ASC NULLS LAST, created_at ASC LIMIT 1;
  IF v_lote IS NULL THEN RETURN NEW; END IF;
  INSERT INTO public.movimientos_inventario
    (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, user_id, fecha, notas)
  VALUES (v_dev.empresa_id, 'entrada', NEW.producto_id, NEW.cantidad, v_almacen, v_lote,
          'devolucion_lote', v_dev.id, v_dev.user_id, CURRENT_DATE, 'Devolución lote (FEFO-in)');
  RETURN NEW;
END; $$;


--
-- Name: aplicar_lote_venta_inmediata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_lote_venta_inmediata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_venta public.ventas%rowtype; v_maneja boolean; v_almacen uuid; v_pending numeric; v_lote RECORD; v_take numeric;
BEGIN
  IF NEW.lote_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_venta FROM public.ventas WHERE id = NEW.venta_id;
  IF v_venta.id IS NULL THEN RETURN NEW; END IF;
  IF v_venta.tipo <> 'venta_directa' OR COALESCE(v_venta.entrega_inmediata, false) IS NOT TRUE THEN RETURN NEW; END IF;
  SELECT COALESCE(maneja_lote, false) INTO v_maneja FROM public.productos WHERE id = NEW.producto_id;
  IF NOT v_maneja THEN RETURN NEW; END IF;
  v_almacen := COALESCE(v_venta.almacen_id, (SELECT almacen_id FROM public.profiles WHERE id = v_venta.vendedor_id LIMIT 1));
  IF v_almacen IS NULL THEN RETURN NEW; END IF;
  v_pending := COALESCE(NEW.cantidad, 0);
  FOR v_lote IN
    SELECT sl.lote_id, sl.cantidad AS existencia FROM public.stock_lotes sl JOIN public.lotes l ON l.id = sl.lote_id
    WHERE sl.almacen_id = v_almacen AND sl.producto_id = NEW.producto_id AND sl.cantidad > 0
    ORDER BY l.fecha_caducidad ASC NULLS LAST, l.created_at ASC FOR UPDATE OF sl
  LOOP
    EXIT WHEN v_pending <= 0;
    v_take := LEAST(v_lote.existencia, v_pending);
    INSERT INTO public.movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, user_id, fecha, notas)
    VALUES (v_venta.empresa_id, 'salida', NEW.producto_id, v_take, v_almacen, v_lote.lote_id, 'venta_lote', v_venta.id,
            COALESCE(v_venta.vendedor_id, v_venta.cliente_id), COALESCE(v_venta.fecha, CURRENT_DATE), 'Venta lote (FEFO) ' || COALESCE(v_venta.folio, ''));
    v_pending := v_pending - v_take;
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: aplicar_partner_referido(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aplicar_partner_referido(p_empresa_id uuid, p_ref_slug text DEFAULT NULL::text, p_cupon_codigo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_partner public.partners%ROWTYPE;
  v_cupon public.cupones%ROWTYPE;
  v_metodo text;
  v_max numeric;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.partner_atribuciones
    WHERE empresa_id = p_empresa_id
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'ya_atribuida'
    );
  END IF;

  IF NULLIF(trim(p_cupon_codigo), '') IS NOT NULL THEN
    SELECT *
    INTO v_cupon
    FROM public.cupones
    WHERE upper(codigo) = upper(trim(p_cupon_codigo))
      AND activo = true
      AND (
        vigencia_inicio IS NULL
        OR vigencia_inicio <= CURRENT_DATE
      )
      AND (
        vigencia_fin IS NULL
        OR vigencia_fin >= CURRENT_DATE
      )
    LIMIT 1;
  END IF;

  IF NULLIF(trim(p_ref_slug), '') IS NOT NULL THEN
    SELECT *
    INTO v_partner
    FROM public.partners
    WHERE lower(ref_slug) = lower(trim(p_ref_slug))
      AND estado = 'activo'
    LIMIT 1;

    IF FOUND THEN
      v_metodo := 'link';
    END IF;
  END IF;

  IF v_partner.id IS NULL
     AND v_cupon.partner_id IS NOT NULL THEN

    SELECT *
    INTO v_partner
    FROM public.partners
    WHERE id = v_cupon.partner_id
      AND estado = 'activo';

    IF FOUND THEN
      v_metodo := 'cupon';
    END IF;
  END IF;

  IF v_cupon.id IS NOT NULL
     AND v_cupon.partner_id IS NOT NULL THEN

    v_max := public.get_partner_coupon_cap(v_cupon.partner_id);

    IF v_cupon.descuento_pct > v_max THEN
      UPDATE public.cupones
      SET activo = false
      WHERE id = v_cupon.id;

      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'cupon_supera_comision_partner'
      );
    END IF;
  END IF;

  IF v_partner.id IS NULL THEN
    IF v_cupon.id IS NOT NULL THEN
      INSERT INTO public.cupon_usos (
        cupon_id,
        empresa_id,
        meses_restantes
      )
      VALUES (
        v_cupon.id,
        p_empresa_id,
        v_cupon.meses_duracion
      )
      ON CONFLICT DO NOTHING;

      RETURN jsonb_build_object(
        'ok', true,
        'partner', false,
        'cupon_aplicado', true
      );
    END IF;

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'sin_partner'
    );
  END IF;

  IF v_cupon.partner_id IS NOT NULL
     AND v_cupon.partner_id <> v_partner.id THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'cupon_no_pertenece_partner'
    );
  END IF;

  INSERT INTO public.partner_atribuciones (
    empresa_id,
    partner_id,
    cupon_id,
    ref_slug,
    metodo
  )
  VALUES (
    p_empresa_id,
    v_partner.id,
    v_cupon.id,
    p_ref_slug,
    COALESCE(v_metodo, 'manual')
  );

  IF v_cupon.id IS NOT NULL THEN
    INSERT INTO public.cupon_usos (
      cupon_id,
      empresa_id,
      meses_restantes
    )
    VALUES (
      v_cupon.id,
      p_empresa_id,
      v_cupon.meses_duracion
    )
    ON CONFLICT DO NOTHING;

    UPDATE public.cupones
    SET usos_actuales = COALESCE(usos_actuales, 0) + 1
    WHERE id = v_cupon.id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'partner_id', v_partner.id,
    'partner_nombre', v_partner.nombre,
    'cupon_aplicado', v_cupon.id IS NOT NULL
  );
END;
$$;


--
-- Name: apply_carga_kardex(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_carga_kardex(_carga_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c RECORD;
BEGIN
  SELECT id, empresa_id, almacen_id, almacen_destino_id, vendedor_id, fecha
    INTO c
  FROM public.cargas
  WHERE id = _carga_id;

  IF c.id IS NULL THEN RETURN; END IF;
  IF c.almacen_id IS NULL OR c.almacen_destino_id IS NULL THEN RETURN; END IF;

  -- Skip if already recorded
  IF EXISTS (
    SELECT 1 FROM public.movimientos_inventario
    WHERE referencia_tipo = 'carga' AND referencia_id = c.id
  ) THEN
    RETURN;
  END IF;

  -- Salida del almacén origen
  INSERT INTO public.movimientos_inventario
    (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, vendedor_destino_id,
     referencia_tipo, referencia_id, notas, fecha)
  SELECT
    c.empresa_id, 'salida'::tipo_movimiento, cl.producto_id, cl.cantidad_cargada,
    c.almacen_id, c.vendedor_id,
    'carga', c.id,
    'Carga a ruta (asignación de stock)',
    c.fecha
  FROM public.carga_lineas cl
  WHERE cl.carga_id = c.id AND cl.cantidad_cargada > 0;

  -- Entrada al almacén destino (ruta)
  INSERT INTO public.movimientos_inventario
    (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, vendedor_destino_id,
     referencia_tipo, referencia_id, notas, fecha)
  SELECT
    c.empresa_id, 'entrada'::tipo_movimiento, cl.producto_id, cl.cantidad_cargada,
    c.almacen_destino_id, c.vendedor_id,
    'carga', c.id,
    'Carga a ruta (recepción en almacén de ruta)',
    c.fecha
  FROM public.carga_lineas cl
  WHERE cl.carga_id = c.id AND cl.cantidad_cargada > 0;
END;
$$;


--
-- Name: apply_conteo_ajustes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_conteo_ajustes(p_conteo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conteo record;
  v_linea record;
  v_stock_actual numeric;
  v_dif numeric;
  v_aplicados int := 0;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  -- Lock del conteo
  SELECT id, empresa_id, almacen_id, folio, status
  INTO v_conteo
  FROM public.conteos_fisicos
  WHERE id = p_conteo_id
  FOR UPDATE;

  IF v_conteo.id IS NULL THEN
    RAISE EXCEPTION 'Conteo no encontrado';
  END IF;

  -- Validar tenant
  IF v_conteo.empresa_id IS DISTINCT FROM get_my_empresa_id()
     AND NOT is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Sin permisos sobre este conteo';
  END IF;

  -- Procesar cada línea cerrada y no ajustada
  FOR v_linea IN
    SELECT id, producto_id, cantidad_contada
    FROM public.conteo_lineas
    WHERE conteo_id = p_conteo_id
      AND status = 'cerrado'
      AND ajuste_aplicado = false
    ORDER BY created_at
  LOOP
    -- Lock + lectura del stock actual
    SELECT cantidad INTO v_stock_actual
    FROM public.stock_almacen
    WHERE almacen_id = v_conteo.almacen_id
      AND producto_id = v_linea.producto_id
    FOR UPDATE;

    IF v_stock_actual IS NULL THEN
      v_stock_actual := 0;
    END IF;

    v_dif := COALESCE(v_linea.cantidad_contada, 0) - v_stock_actual;

    IF v_dif <> 0 THEN
      -- Aplicar al stock
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (v_conteo.empresa_id, v_conteo.almacen_id, v_linea.producto_id, v_stock_actual + v_dif)
      ON CONFLICT (almacen_id, producto_id) DO UPDATE
        SET cantidad = EXCLUDED.cantidad, updated_at = now();

      -- Registrar movimiento
      INSERT INTO public.movimientos_inventario (
        empresa_id, tipo, producto_id, cantidad,
        almacen_origen_id, almacen_destino_id,
        referencia_tipo, referencia_id, notas, user_id, fecha
      ) VALUES (
        v_conteo.empresa_id,
        CASE WHEN v_dif > 0 THEN 'entrada' ELSE 'salida' END,
        v_linea.producto_id,
        ABS(v_dif),
        CASE WHEN v_dif > 0 THEN NULL ELSE v_conteo.almacen_id END,
        CASE WHEN v_dif > 0 THEN v_conteo.almacen_id ELSE NULL END,
        'conteo_fisico', p_conteo_id,
        'Ajuste por conteo físico ' || v_conteo.folio
          || '. Contado: ' || COALESCE(v_linea.cantidad_contada, 0)
          || ', Sistema: ' || v_stock_actual,
        v_user_id, CURRENT_DATE
      );
    END IF;

    -- Marcar como ajustada (idempotencia)
    UPDATE public.conteo_lineas
    SET ajuste_aplicado = true
    WHERE id = v_linea.id;

    v_aplicados := v_aplicados + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'aplicados', v_aplicados,
    'conteo_id', p_conteo_id
  );
END;
$$;


--
-- Name: apply_delivered_direct_sale_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_delivered_direct_sale_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linea RECORD;
  v_stock_id uuid;
  v_stock_actual numeric := 0;
  v_new_qty numeric;
  v_vender_sin_stock boolean;
  v_prod_name text;
  v_almacen_id uuid;
BEGIN
  IF NEW.tipo = 'saldo_inicial' THEN RETURN NEW; END IF;
  IF NEW.tipo <> 'venta_directa' THEN RETURN NEW; END IF;
  IF COALESCE(NEW.entrega_inmediata, false) IS TRUE THEN RETURN NEW; END IF;
  IF NEW.status <> 'entregado' OR OLD.status = 'entregado' THEN RETURN NEW; END IF;

  -- Resolver almacén: primero el de la venta, si no, el del perfil del vendedor
  v_almacen_id := COALESCE(
    NEW.almacen_id,
    (SELECT almacen_id FROM public.profiles WHERE id = NEW.vendedor_id LIMIT 1)
  );

  IF v_almacen_id IS NULL THEN
    RAISE EXCEPTION 'No se puede entregar la venta % sin almacén asignado. Asigna un almacén al vendedor en su perfil o a la venta.',
      COALESCE(NEW.folio, NEW.id::text);
  END IF;

  FOR v_linea IN
    SELECT producto_id, cantidad FROM public.venta_lineas WHERE venta_id = NEW.id
  LOOP
    SELECT nombre, vender_sin_stock INTO v_prod_name, v_vender_sin_stock
    FROM public.productos WHERE id = v_linea.producto_id;

    SELECT id, cantidad INTO v_stock_id, v_stock_actual
    FROM public.stock_almacen
    WHERE almacen_id = v_almacen_id AND producto_id = v_linea.producto_id FOR UPDATE;

    v_new_qty := COALESCE(v_stock_actual, 0) - COALESCE(v_linea.cantidad, 0);

    IF NOT COALESCE(v_vender_sin_stock, false) AND v_new_qty < 0 THEN
      RAISE EXCEPTION 'Stock insuficiente en almacén para "%". Disponible: %, solicitado: %',
        COALESCE(v_prod_name, v_linea.producto_id::text),
        COALESCE(v_stock_actual, 0), COALESCE(v_linea.cantidad, 0);
    END IF;

    IF v_stock_id IS NOT NULL THEN
      UPDATE public.stock_almacen SET cantidad = v_new_qty, updated_at = now() WHERE id = v_stock_id;
    ELSE
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (NEW.empresa_id, v_almacen_id, v_linea.producto_id, v_new_qty);
    END IF;

    INSERT INTO public.movimientos_inventario
      (id, empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, created_at, notas)
    VALUES
      (gen_random_uuid(), NEW.empresa_id, 'salida', v_linea.producto_id, v_linea.cantidad,
       v_almacen_id, 'venta', NEW.id, COALESCE(NEW.vendedor_id, NEW.cliente_id),
       COALESCE(NEW.fecha, current_date), now(), concat('Venta entregada ', COALESCE(NEW.folio, NEW.id::text)));
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: apply_descarga_ruta_aprobada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_descarga_ruta_aprobada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_camion uuid; v_bodega uuid; v_linea RECORD;
  v_real numeric; v_cam_now numeric; v_dif numeric;
BEGIN
  IF NEW.status <> 'aprobada' THEN RETURN NEW; END IF;
  IF OLD.status = 'aprobada' THEN RETURN NEW; END IF;
  IF NOT COALESCE(NEW.descargo_camion, false) THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario
             WHERE referencia_tipo='descarga' AND referencia_id=NEW.id) THEN RETURN NEW; END IF;
  SELECT almacen_id INTO v_camion FROM public.profiles WHERE id = NEW.vendedor_id;
  v_bodega := NEW.almacen_destino_id;
  IF v_camion IS NULL OR v_bodega IS NULL THEN
    RAISE EXCEPTION 'Descarga %: falta camión o bodega destino (camión=%, bodega=%)', NEW.id, v_camion, v_bodega; END IF;
  IF v_camion = v_bodega THEN
    RAISE EXCEPTION 'Descarga %: la bodega destino no puede ser el mismo almacén del camión', NEW.id; END IF;
  FOR v_linea IN SELECT id, producto_id, cantidad_real FROM public.descarga_ruta_lineas WHERE descarga_id=NEW.id LOOP
    v_real := COALESCE(v_linea.cantidad_real,0);
    SELECT cantidad INTO v_cam_now FROM public.stock_almacen WHERE almacen_id=v_camion AND producto_id=v_linea.producto_id;
    v_cam_now := COALESCE(v_cam_now,0);
    IF v_real > 0 THEN
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (NEW.empresa_id, v_bodega, v_linea.producto_id, v_real)
      ON CONFLICT (almacen_id, producto_id) DO UPDATE SET cantidad=public.stock_almacen.cantidad+EXCLUDED.cantidad, updated_at=now();
      INSERT INTO public.movimientos_inventario (empresa_id,tipo,producto_id,cantidad,almacen_origen_id,almacen_destino_id,referencia_tipo,referencia_id,user_id,fecha,notas)
      VALUES (NEW.empresa_id,'entrada',v_linea.producto_id,v_real,v_camion,v_bodega,'descarga',NEW.id,COALESCE(NEW.aprobado_por,NEW.user_id),COALESCE(NEW.fecha,CURRENT_DATE),'Descarga de ruta: entrada a bodega (descarga '||NEW.id||')');
    END IF;
    IF v_cam_now <> 0 THEN
      UPDATE public.stock_almacen SET cantidad=0, updated_at=now() WHERE almacen_id=v_camion AND producto_id=v_linea.producto_id;
      INSERT INTO public.movimientos_inventario (empresa_id,tipo,producto_id,cantidad,almacen_origen_id,referencia_tipo,referencia_id,user_id,fecha,notas)
      VALUES (NEW.empresa_id,'salida',v_linea.producto_id,v_cam_now,v_camion,'descarga',NEW.id,COALESCE(NEW.aprobado_por,NEW.user_id),COALESCE(NEW.fecha,CURRENT_DATE),'Descarga de ruta: salida de camión (descarga '||NEW.id||')');
    END IF;
    v_dif := v_real - v_cam_now;
    IF v_dif <> 0 THEN
      INSERT INTO public.ajustes_inventario (empresa_id,producto_id,almacen_id,cantidad_anterior,cantidad_nueva,diferencia,motivo,user_id,fecha)
      VALUES (NEW.empresa_id,v_linea.producto_id,v_camion,v_cam_now,v_real,v_dif,'Diferencia en descarga (revisar) — descarga '||NEW.id||' · esperado '||v_cam_now||' · físico '||v_real,COALESCE(NEW.aprobado_por,NEW.user_id),COALESCE(NEW.fecha,CURRENT_DATE));
    END IF;
    UPDATE public.descarga_ruta_lineas SET cantidad_esperada=v_cam_now, diferencia=v_dif WHERE id=v_linea.id;
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: apply_devolucion_linea_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_devolucion_linea_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dev record;
  v_almacen_id uuid;
  v_merma_almacen uuid;
  v_existing int;
  v_legacy int;
BEGIN
  SELECT id, empresa_id, user_id, vendedor_id, almacen_destino_id INTO v_dev
  FROM public.devoluciones WHERE id = NEW.devolucion_id;
  IF v_dev.id IS NULL THEN RETURN NEW; END IF;

  -- Almacén destino automático: el del usuario que registró (fallback al vendedor).
  SELECT almacen_id INTO v_almacen_id FROM public.profiles WHERE id = v_dev.user_id;
  IF v_almacen_id IS NULL AND v_dev.vendedor_id IS NOT NULL THEN
    SELECT almacen_id INTO v_almacen_id FROM public.profiles WHERE id = v_dev.vendedor_id;
  END IF;

  -- Ruteo automático por motivo (producto NO vendible → Almacén Mermas).
  IF NEW.motivo::text IN ('danado', 'vencido', 'caducado') THEN
    SELECT id INTO v_merma_almacen
    FROM public.almacenes
    WHERE empresa_id = v_dev.empresa_id AND es_merma = true
    LIMIT 1;
    IF v_merma_almacen IS NOT NULL THEN
      v_almacen_id := v_merma_almacen;
    END IF;
  END IF;

  -- NUEVO (escritorio): si la devolución trae almacén destino explícito, GANA
  -- sobre el ruteo automático. Retrocompatible: móvil no lo setea → sin cambios.
  IF v_dev.almacen_destino_id IS NOT NULL THEN
    v_almacen_id := v_dev.almacen_destino_id;
    IF v_almacen_id <> COALESCE(v_merma_almacen, '00000000-0000-0000-0000-000000000000'::uuid) THEN
      v_merma_almacen := NULL;
    END IF;
  END IF;

  IF v_almacen_id IS NULL THEN
    RAISE LOG 'apply_devolucion_linea_inventory: no almacen for devolucion %', v_dev.id;
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_existing
  FROM public.movimientos_inventario
  WHERE referencia_tipo = 'devolucion_aplicada' AND referencia_id = v_dev.id AND producto_id = NEW.producto_id
    AND notas LIKE '%[linea:' || NEW.id::text || ']%';
  IF v_existing > 0 THEN RETURN NEW; END IF;

  SELECT COUNT(*) INTO v_legacy
  FROM public.movimientos_inventario
  WHERE referencia_tipo = 'devolucion' AND referencia_id = v_dev.id AND producto_id = NEW.producto_id AND tipo = 'entrada';
  IF v_legacy > 0 THEN
    INSERT INTO public.movimientos_inventario (
      empresa_id, tipo, producto_id, cantidad, almacen_destino_id,
      referencia_tipo, referencia_id, user_id, notas, fecha
    ) VALUES (
      v_dev.empresa_id, 'entrada', NEW.producto_id, 0, v_almacen_id,
      'devolucion_aplicada', v_dev.id, v_dev.user_id, 'Ancla (reingreso previo por app móvil)', CURRENT_DATE
    );
    RETURN NEW;
  END IF;

  -- Reingreso real al almacén elegido (vendible o mermas)
  INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
  VALUES (v_dev.empresa_id, v_almacen_id, NEW.producto_id, NEW.cantidad)
  ON CONFLICT (almacen_id, producto_id)
    DO UPDATE SET cantidad = stock_almacen.cantidad + EXCLUDED.cantidad, updated_at = now();

  INSERT INTO public.movimientos_inventario (
    empresa_id, tipo, producto_id, cantidad, almacen_destino_id,
    referencia_tipo, referencia_id, user_id, notas, fecha
  ) VALUES (
    v_dev.empresa_id, 'entrada', NEW.producto_id, NEW.cantidad, v_almacen_id,
    'devolucion_aplicada', v_dev.id, v_dev.user_id,
    CASE WHEN v_merma_almacen IS NOT NULL THEN 'Devolución a MERMAS (trigger BD)'
         ELSE 'Devolución (trigger BD)' END || ' [linea:' || NEW.id::text || ']',
    CURRENT_DATE
  );

  RETURN NEW;
END;
$$;


--
-- Name: apply_entrega_cargado_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_entrega_cargado_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vendedor_id uuid;
  v_almacen_destino uuid;
  v_linea record;
  v_existing int;
  v_surtir_done boolean;
  v_active_statuses text[] := ARRAY['asignado','cargado','en_ruta'];
BEGIN
  IF TG_OP = 'UPDATE'
     AND (OLD.status::text = ANY(v_active_statuses)
          OR (OLD.status::text = 'hecho' AND NEW.status::text IN ('borrador','surtido')))
     AND NOT (NEW.status::text = ANY(v_active_statuses))
     AND NEW.status::text <> 'hecho' THEN

    -- Cargado con el repartidor + cancelado/no_entregado => se queda en el camión
    IF NEW.status::text IN ('cancelado','no_entregado') THEN
      RETURN NEW;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.movimientos_inventario
      WHERE referencia_id = NEW.id AND notas ILIKE 'Cancelación%'
    ) THEN
      RETURN NEW;
    END IF;
    FOR v_linea IN
      SELECT producto_id, cantidad, almacen_origen_id, almacen_destino_id, notas
      FROM public.movimientos_inventario
      WHERE referencia_id = NEW.id
        AND referencia_tipo IN ('entrega_cargado', 'entrega')
        AND notas ILIKE 'Carga%'
    LOOP
      IF v_linea.almacen_origen_id IS NOT NULL AND v_linea.cantidad > 0
         AND v_linea.notas NOT ILIKE '%anclaje%' AND v_linea.notas NOT ILIKE '%surtir%' THEN
        UPDATE public.stock_almacen
        SET cantidad = cantidad + v_linea.cantidad, updated_at = now()
        WHERE almacen_id = v_linea.almacen_origen_id AND producto_id = v_linea.producto_id;
      END IF;
      IF v_linea.almacen_destino_id IS NOT NULL AND v_linea.cantidad > 0 THEN
        UPDATE public.stock_almacen
        SET cantidad = cantidad - v_linea.cantidad, updated_at = now()
        WHERE almacen_id = v_linea.almacen_destino_id AND producto_id = v_linea.producto_id;
      END IF;
    END LOOP;
    DELETE FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id
      AND referencia_tipo IN ('entrega_cargado', 'entrega')
      AND notas ILIKE 'Carga%';
    RETURN NEW;
  END IF;

  IF NOT (NEW.status::text = ANY(v_active_statuses)) THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status::text = ANY(v_active_statuses) THEN RETURN NEW; END IF;
  SELECT COUNT(*) INTO v_existing
  FROM public.movimientos_inventario
  WHERE referencia_tipo = 'entrega_cargado' AND referencia_id = NEW.id;
  IF v_existing > 0 THEN RETURN NEW; END IF;

  v_vendedor_id := COALESCE(NEW.vendedor_ruta_id, NEW.vendedor_id);
  IF v_vendedor_id IS NULL THEN RETURN NEW; END IF;
  SELECT almacen_id INTO v_almacen_destino FROM public.profiles WHERE id = v_vendedor_id;
  IF v_almacen_destino IS NULL THEN RETURN NEW; END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega' AND tipo = 'salida' AND cantidad > 0
  ) INTO v_surtir_done;

  FOR v_linea IN
    SELECT producto_id, cantidad_entregada, almacen_origen_id
    FROM public.entrega_lineas
    WHERE entrega_id = NEW.id AND hecho = true AND COALESCE(cantidad_entregada, 0) > 0
  LOOP
    IF NOT v_surtir_done AND v_linea.almacen_origen_id IS NOT NULL THEN
      UPDATE public.stock_almacen
      SET cantidad = cantidad - v_linea.cantidad_entregada, updated_at = now()
      WHERE almacen_id = v_linea.almacen_origen_id AND producto_id = v_linea.producto_id;
    END IF;

    INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
    VALUES (NEW.empresa_id, v_almacen_destino, v_linea.producto_id, v_linea.cantidad_entregada)
    ON CONFLICT (almacen_id, producto_id)
      DO UPDATE SET cantidad = stock_almacen.cantidad + EXCLUDED.cantidad, updated_at = now();

    INSERT INTO public.movimientos_inventario (
      empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id,
      vendedor_destino_id, referencia_tipo, referencia_id, notas, fecha
    ) VALUES (
      NEW.empresa_id, 'entrada', v_linea.producto_id, v_linea.cantidad_entregada,
      v_linea.almacen_origen_id, v_almacen_destino, v_vendedor_id, 'entrega_cargado', NEW.id,
      CASE WHEN v_surtir_done THEN 'Carga a camión (origen ya descontado por surtir)'
           ELSE 'Carga a ruta (trigger BD, asignación)' END,
      CURRENT_DATE
    );
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: apply_entrega_hecho_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_entrega_hecho_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vendedor_id uuid; v_almacen_id uuid; v_linea record;
  v_neto numeric; v_pendiente numeric;
  v_maneja_lote boolean;
  v_take numeric; v_lote record; v_left numeric;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'hecho' AND NEW.status IS DISTINCT FROM 'hecho' THEN
    FOR v_linea IN
      SELECT producto_id, cantidad, almacen_origen_id, lote_id FROM public.movimientos_inventario
      WHERE referencia_id = NEW.id AND tipo = 'salida'
        AND (referencia_tipo = 'entrega_hecho' OR (referencia_tipo = 'entrega' AND NEW.status::text = 'borrador'))
    LOOP
      IF v_linea.almacen_origen_id IS NOT NULL AND v_linea.cantidad > 0 THEN
        UPDATE public.stock_almacen SET cantidad = cantidad + v_linea.cantidad, updated_at = now()
        WHERE almacen_id = v_linea.almacen_origen_id AND producto_id = v_linea.producto_id;
        IF v_linea.lote_id IS NOT NULL THEN
          INSERT INTO public.stock_lotes (empresa_id, almacen_id, producto_id, lote_id, cantidad)
          VALUES (NEW.empresa_id, v_linea.almacen_origen_id, v_linea.producto_id, v_linea.lote_id, v_linea.cantidad)
          ON CONFLICT (almacen_id, lote_id)
            DO UPDATE SET cantidad = public.stock_lotes.cantidad + v_linea.cantidad, updated_at = now();
        END IF;
      END IF;
    END LOOP;
    DELETE FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND tipo = 'salida'
        AND (referencia_tipo = 'entrega_hecho' OR (referencia_tipo = 'entrega' AND NEW.status::text = 'borrador'));
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM 'hecho' THEN RETURN NEW; END IF;

  v_vendedor_id := COALESCE(NEW.vendedor_ruta_id, NEW.vendedor_id);
  SELECT almacen_id INTO v_almacen_id FROM public.profiles WHERE id = v_vendedor_id;
  IF v_almacen_id IS NULL THEN v_almacen_id := NEW.almacen_id; END IF;
  IF v_almacen_id IS NULL THEN RETURN NEW; END IF;

  FOR v_linea IN
    SELECT el.id, el.producto_id, el.cantidad_entregada, el.unidad_id, el.lote_id, COALESCE(p.maneja_lote,false) AS maneja_lote
    FROM public.entrega_lineas el
    JOIN public.productos p ON p.id = el.producto_id
    WHERE el.entrega_id = NEW.id AND el.hecho = true AND COALESCE(el.cantidad_entregada, 0) > 0
  LOOP
    SELECT COALESCE(SUM(CASE WHEN tipo='salida' AND almacen_origen_id = v_almacen_id THEN cantidad ELSE 0 END),0)
    INTO v_neto FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega_hecho' AND producto_id = v_linea.producto_id;

    v_pendiente := v_linea.cantidad_entregada - v_neto;

    IF v_pendiente > 0 THEN
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad, updated_at)
      VALUES (NEW.empresa_id, v_almacen_id, v_linea.producto_id, -v_pendiente, now())
      ON CONFLICT (almacen_id, producto_id)
        DO UPDATE SET cantidad = public.stock_almacen.cantidad - v_pendiente, updated_at = now();

      IF v_linea.maneja_lote THEN
        IF v_linea.lote_id IS NOT NULL THEN
          INSERT INTO public.movimientos_inventario (
            empresa_id, tipo, producto_id, cantidad, unidad_id, almacen_origen_id,
            vendedor_destino_id, lote_id, referencia_tipo, referencia_id, notas, fecha
          ) VALUES (
            NEW.empresa_id, 'salida', v_linea.producto_id, v_pendiente, v_linea.unidad_id, v_almacen_id,
            v_vendedor_id, v_linea.lote_id, 'entrega_hecho', NEW.id,
            'Entrega a cliente (folio ' || COALESCE(NEW.folio,'—') || ')', CURRENT_DATE
          );
        ELSE
          v_left := v_pendiente;
          FOR v_lote IN
            SELECT sl.lote_id, sl.cantidad AS existencia
            FROM public.stock_lotes sl
            JOIN public.lotes l ON l.id = sl.lote_id
            WHERE sl.almacen_id = v_almacen_id AND sl.producto_id = v_linea.producto_id AND sl.cantidad > 0
            ORDER BY l.fecha_caducidad ASC NULLS LAST, l.created_at ASC
            FOR UPDATE OF sl
          LOOP
            EXIT WHEN v_left <= 0;
            v_take := LEAST(v_lote.existencia, v_left);
            INSERT INTO public.movimientos_inventario (
              empresa_id, tipo, producto_id, cantidad, unidad_id, almacen_origen_id,
              vendedor_destino_id, lote_id, referencia_tipo, referencia_id, notas, fecha
            ) VALUES (
              NEW.empresa_id, 'salida', v_linea.producto_id, v_take, v_linea.unidad_id, v_almacen_id,
              v_vendedor_id, v_lote.lote_id, 'entrega_hecho', NEW.id,
              'Entrega a cliente (folio ' || COALESCE(NEW.folio,'—') || ')', CURRENT_DATE
            );
            v_left := v_left - v_take;
          END LOOP;

          IF v_left > 0 THEN
            INSERT INTO public.movimientos_inventario (
              empresa_id, tipo, producto_id, cantidad, unidad_id, almacen_origen_id,
              vendedor_destino_id, referencia_tipo, referencia_id, notas, fecha
            ) VALUES (
              NEW.empresa_id, 'salida', v_linea.producto_id, v_left, v_linea.unidad_id, v_almacen_id,
              v_vendedor_id, 'entrega_hecho', NEW.id,
              'Entrega a cliente (folio ' || COALESCE(NEW.folio,'—') || ') — sin lote', CURRENT_DATE
            );
          END IF;
        END IF;
      ELSE
        INSERT INTO public.movimientos_inventario (
          empresa_id, tipo, producto_id, cantidad, unidad_id, almacen_origen_id,
          vendedor_destino_id, referencia_tipo, referencia_id, notas, fecha
        ) VALUES (
          NEW.empresa_id, 'salida', v_linea.producto_id, v_pendiente, v_linea.unidad_id, v_almacen_id,
          v_vendedor_id, 'entrega_hecho', NEW.id,
          'Entrega a cliente (folio ' || COALESCE(NEW.folio,'—') || ')', CURRENT_DATE
        );
      END IF;
    ELSE
      INSERT INTO public.movimientos_inventario (
        empresa_id, tipo, producto_id, cantidad, unidad_id, almacen_origen_id,
        vendedor_destino_id, referencia_tipo, referencia_id, notas, fecha
      )
      SELECT NEW.empresa_id, 'salida', v_linea.producto_id, 0, v_linea.unidad_id, v_almacen_id,
        v_vendedor_id, 'entrega_hecho', NEW.id, 'Anclaje (descuento previo)', CURRENT_DATE
      WHERE NOT EXISTS (
        SELECT 1 FROM public.movimientos_inventario
        WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega_hecho' AND producto_id = v_linea.producto_id
      );
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: apply_immediate_sale_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_immediate_sale_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_venta public.ventas%rowtype; v_stock_id uuid; v_stock_actual numeric := 0;
  v_new_qty numeric; v_vender_sin_stock boolean; v_prod_name text;
  v_almacen_id uuid; v_sin_stock boolean; v_maneja_lote boolean;
begin
  select * into v_venta from public.ventas where id = new.venta_id;
  if v_venta.id is null then return new; end if;
  if v_venta.tipo = 'saldo_inicial' then return new; end if;
  if v_venta.tipo <> 'venta_directa' or coalesce(v_venta.entrega_inmediata, false) is not true then return new; end if;
  select nombre, vender_sin_stock, coalesce(maneja_lote,false)
    into v_prod_name, v_vender_sin_stock, v_maneja_lote
    from productos where id = new.producto_id;
  v_almacen_id := coalesce(v_venta.almacen_id, (select almacen_id from public.profiles where id = v_venta.vendedor_id limit 1));
  if v_almacen_id is null then
    raise exception 'No se puede registrar la venta % sin almacén asignado.', coalesce(v_venta.folio, v_venta.id::text);
  end if;
  select id, cantidad into v_stock_id, v_stock_actual from public.stock_almacen
    where almacen_id = v_almacen_id and producto_id = new.producto_id for update;
  v_new_qty := coalesce(v_stock_actual, 0) - coalesce(new.cantidad, 0);
  v_sin_stock := (not coalesce(v_vender_sin_stock, false)) and v_new_qty < 0;
  if v_stock_id is not null then
    update public.stock_almacen set cantidad = v_new_qty, updated_at = now() where id = v_stock_id;
  else
    insert into public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
    values (v_venta.empresa_id, v_almacen_id, new.producto_id, v_new_qty);
  end if;

  -- Si el producto maneja lote, el movimiento (con lote_id) lo inserta aplicar_lote_venta_inmediata.
  -- Evita duplicar el asiento en el kardex.
  if v_maneja_lote then
    return new;
  end if;

  insert into public.movimientos_inventario
    (id, empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, created_at, notas, lote_id)
  values
    (gen_random_uuid(), v_venta.empresa_id, 'salida', new.producto_id, new.cantidad,
     v_almacen_id, 'venta', v_venta.id, coalesce(v_venta.vendedor_id, v_venta.cliente_id),
     coalesce(v_venta.fecha, current_date), now(),
     concat('Venta POS ', coalesce(v_venta.folio, v_venta.id::text),
            case when v_sin_stock then ' · SIN STOCK SUFICIENTE (revisar)' else '' end),
     new.lote_id);
  return new;
end; $$;


--
-- Name: apply_pedido_entregado_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_pedido_entregado_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_linea record;
  v_stock_id uuid;
  v_stock_actual numeric := 0;
  v_new_qty numeric;
  v_vender_sin_stock boolean;
  v_has_entregas boolean := false;
  v_almacen_id uuid;
begin
  if new.tipo = 'saldo_inicial' then return new; end if;
  if new.tipo <> 'pedido' then return new; end if;
  if new.status <> 'entregado' then return new; end if;
  if old.status = 'entregado' then return new; end if;

  -- Conservar guard original: si hay flujo de entregas, este trigger no debe duplicar
  select exists(
    select 1 from public.entregas e where e.pedido_id = new.id
  ) into v_has_entregas;

  if v_has_entregas then
    return new;
  end if;

  -- Resolver almacén con fallback al perfil del vendedor
  v_almacen_id := coalesce(
    new.almacen_id,
    (select almacen_id from public.profiles where id = new.vendedor_id limit 1)
  );

  if v_almacen_id is null then
    raise exception 'No se puede entregar el pedido % sin almacén asignado. Asigna un almacén al vendedor en su perfil o al pedido.',
      coalesce(new.folio, new.id::text);
  end if;

  for v_linea in
    select vl.producto_id, vl.cantidad from public.venta_lineas vl where vl.venta_id = new.id
  loop
    select vender_sin_stock into v_vender_sin_stock from productos where id = v_linea.producto_id;

    select id, cantidad into v_stock_id, v_stock_actual
    from public.stock_almacen
    where almacen_id = v_almacen_id and producto_id = v_linea.producto_id for update;

    v_new_qty := coalesce(v_stock_actual, 0) - coalesce(v_linea.cantidad, 0);
    if not coalesce(v_vender_sin_stock, false) and v_new_qty < 0 then
      raise exception 'Stock insuficiente en almacén para "%"',
        coalesce((select nombre from productos where id = v_linea.producto_id), '');
    end if;

    if v_stock_id is not null then
      update public.stock_almacen set cantidad = v_new_qty, updated_at = now() where id = v_stock_id;
    else
      insert into public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      values (new.empresa_id, v_almacen_id, v_linea.producto_id, v_new_qty);
    end if;

    insert into public.movimientos_inventario
      (id, empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, created_at, notas)
    values
      (gen_random_uuid(), new.empresa_id, 'salida', v_linea.producto_id, v_linea.cantidad,
       v_almacen_id, 'venta', new.id, coalesce(new.vendedor_id, new.cliente_id),
       coalesce(new.fecha, current_date), now(),
       concat('Pedido entregado ', coalesce(new.folio, new.id::text)));
  end loop;

  return new;
end;
$$;


--
-- Name: aprobar_solicitud_partner(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aprobar_solicitud_partner(_solicitud_id uuid, _slug text, _comision_pct numeric DEFAULT 20) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sol public.partner_solicitudes%ROWTYPE;
  v_partner_id uuid;
  v_user_id uuid;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT *
  INTO v_sol
  FROM public.partner_solicitudes
  WHERE id = _solicitud_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF v_sol.status <> 'pending' THEN
    RAISE EXCEPTION 'Solicitud ya procesada';
  END IF;

  SELECT id
  INTO v_user_id
  FROM auth.users
  WHERE lower(email) = lower(v_sol.email)
  LIMIT 1;

  IF v_user_id IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.profiles
       WHERE user_id = v_user_id
         AND empresa_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION
      'Este correo ya pertenece a una empresa cliente. No puede ser partner.';
  END IF;

  INSERT INTO public.partners (
    nombre,
    email,
    telefono,
    ref_slug,
    comision_pct,
    user_id,
    estado,
    terms_accepted_at,
    terms_version
  )
  VALUES (
    v_sol.nombre,
    v_sol.email,
    v_sol.telefono,
    lower(_slug),
    _comision_pct,
    v_user_id,
    'activo',
    v_sol.terms_accepted_at,
    v_sol.terms_version
  )
  RETURNING id INTO v_partner_id;

  UPDATE public.partner_solicitudes
  SET
    status = 'approved',
    partner_id = v_partner_id,
    processed_at = now(),
    processed_by = auth.uid()
  WHERE id = _solicitud_id;

  RETURN v_partner_id;
END;
$$;


--
-- Name: aprobar_solicitud_traspaso(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aprobar_solicitud_traspaso(p_solicitud_id uuid, p_lineas jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sol public.solicitudes_traspaso%ROWTYPE;
  v_item jsonb;
  v_linea public.solicitud_traspaso_lineas%ROWTYPE;
  v_disp numeric;
  v_nombre text;
  v_total numeric;
BEGIN
  SELECT * INTO v_sol
    FROM public.solicitudes_traspaso
   WHERE id = p_solicitud_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF NOT (
    v_sol.empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF v_sol.status <> 'solicitada' THEN
    RAISE EXCEPTION 'Solo se puede aprobar una solicitud enviada';
  END IF;

  IF v_sol.almacen_origen_id IS NULL
     OR v_sol.almacen_destino_id IS NULL THEN
    RAISE EXCEPTION 'Define el almacén origen y destino';
  END IF;

  IF p_lineas IS NOT NULL THEN
    FOR v_item IN
      SELECT * FROM jsonb_array_elements(p_lineas)
    LOOP
      UPDATE public.solicitud_traspaso_lineas
         SET cantidad_aprobada = GREATEST(
           COALESCE(
             (v_item->>'cantidad_aprobada')::numeric,
             0
           ),
           0
         )
       WHERE id = (v_item->>'linea_id')::uuid
         AND solicitud_id = p_solicitud_id
         AND excluida = false;
    END LOOP;
  END IF;

  FOR v_linea IN
    SELECT *
      FROM public.solicitud_traspaso_lineas
     WHERE solicitud_id = p_solicitud_id
       AND excluida = false
       AND cantidad_aprobada > 0
  LOOP
    v_disp := GREATEST(
      COALESCE(
        public.fn_disponible_almacen(
          v_linea.producto_id,
          v_sol.almacen_origen_id
        ),
        0
      ),
      0
    );

    IF v_linea.cantidad_aprobada > v_disp THEN
      SELECT nombre INTO v_nombre
        FROM public.productos
       WHERE id = v_linea.producto_id;

      RAISE EXCEPTION
        'Existencia disponible insuficiente en origen para "%". Disponible: %, aprobado: %',
        v_nombre,
        v_disp,
        v_linea.cantidad_aprobada;
    END IF;
  END LOOP;

  SELECT COALESCE(SUM(cantidad_aprobada), 0)
    INTO v_total
    FROM public.solicitud_traspaso_lineas
   WHERE solicitud_id = p_solicitud_id
     AND excluida = false;

  IF v_total <= 0 THEN
    RAISE EXCEPTION 'Debes aprobar al menos una cantidad mayor a cero';
  END IF;

  UPDATE public.solicitudes_traspaso
     SET status = 'aprobada',
         aprobado_por = auth.uid(),
         aprobado_at = now()
   WHERE id = p_solicitud_id;

  PERFORM public.fn_log_solicitud_traspaso(
    p_solicitud_id,
    v_sol.empresa_id,
    'aprobada',
    p_lineas
  );
END;
$$;


--
-- Name: archivar_usuario(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archivar_usuario(p_profile_id uuid, p_motivo text DEFAULT NULL::text, p_force boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE

  v_empresa_id uuid;
  v_user_id uuid;

  v_estado text;

  v_archivado_en timestamptz;
  v_archivado_por uuid;
  v_archivado_motivo text;

  v_summary jsonb;

BEGIN

  SELECT
    empresa_id,
    user_id,
    estado,
    archivado_en,
    archivado_por,
    archivado_motivo

  INTO
    v_empresa_id,
    v_user_id,
    v_estado,
    v_archivado_en,
    v_archivado_por,
    v_archivado_motivo

  FROM public.profiles

  WHERE id = p_profile_id

  FOR UPDATE;


  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION
      'Usuario no encontrado';
  END IF;


  IF NOT public.is_empresa_admin(auth.uid(), v_empresa_id) THEN

    RAISE EXCEPTION
      'Acceso denegado: requiere permisos de administrador';

  END IF;


  -- ----------------------------------------------------------
  -- Idempotencia
  -- Si ya está archivado, NO hacemos nada destructivo.
  -- ----------------------------------------------------------

  IF v_estado = 'archivado'
     OR v_archivado_en IS NOT NULL THEN

    RETURN jsonb_build_object(

      'archivado',
      true,

      'already_archived',
      true,

      'profile_id',
      p_profile_id,

      'archivado_en',
      v_archivado_en,

      'archivado_por',
      v_archivado_por,

      'archivado_motivo',
      v_archivado_motivo

    );

  END IF;


  -- ----------------------------------------------------------
  -- No archivar al propietario de la empresa
  -- ----------------------------------------------------------

  IF EXISTS (

    SELECT 1

    FROM public.empresas

    WHERE id = v_empresa_id
      AND owner_user_id = v_user_id

  ) THEN

    RAISE EXCEPTION
      'No se puede archivar al propietario de la empresa';

  END IF;


  -- ----------------------------------------------------------
  -- No autoarchivado
  -- ----------------------------------------------------------

  IF v_user_id = auth.uid() THEN

    RAISE EXCEPTION
      'No puedes archivar tu propio usuario';

  END IF;


  -- ----------------------------------------------------------
  -- Revisar pendientes
  -- ----------------------------------------------------------

  v_summary :=
    public.get_user_archive_summary(p_profile_id);


  IF NOT p_force
     AND NOT (v_summary->>'puede_archivar')::boolean THEN

    RAISE EXCEPTION
      'El usuario tiene pendientes. Reasigna entregas/ventas, cierra rutas y vacía el almacén antes de archivar. Detalle: %',
      v_summary::text;

  END IF;


  -- ----------------------------------------------------------
  -- BAJA LÓGICA
  -- ----------------------------------------------------------

  UPDATE public.profiles

  SET

    estado = 'archivado',

    archivado_en = now(),

    archivado_por = auth.uid(),

    archivado_motivo = p_motivo

  WHERE id = p_profile_id;


  -- MUY IMPORTANTE:
  --
  -- NO SE BORRAN LOS ROLES.
  --
  -- Antes se hacía algo como:
  --
  -- DELETE FROM public.user_roles
  -- WHERE user_id = v_user_id;
  --
  -- ESO YA NO DEBE HACERSE.
  --
  -- Los roles se conservan para poder reactivar después.


  RETURN jsonb_build_object(

    'archivado',
    true,

    'already_archived',
    false,

    'profile_id',
    p_profile_id,

    'user_id',
    v_user_id,

    'empresa_id',
    v_empresa_id,

    'resumen_previo',
    v_summary

  );

END;
$$;


--
-- Name: asignar_lote_masivo(uuid, uuid, text, date, date, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asignar_lote_masivo(p_empresa_id uuid, p_almacen_id uuid, p_codigo text, p_caducidad date, p_fabricacion date, p_costo numeric, p_items jsonb, p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb; v_producto uuid; v_cant numeric; v_lote uuid; v_count int := 0;
BEGIN
  IF p_almacen_id IS NULL THEN RAISE EXCEPTION 'Falta el almacén'; END IF;
  IF p_codigo IS NULL OR btrim(p_codigo) = '' THEN RAISE EXCEPTION 'El código de lote es obligatorio'; END IF;
  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    v_producto := (v_item->>'producto_id')::uuid;
    v_cant := COALESCE((v_item->>'cantidad')::numeric, 0);
    IF v_producto IS NULL THEN CONTINUE; END IF;
    UPDATE productos SET maneja_lote = true WHERE id = v_producto AND empresa_id = p_empresa_id;
    SELECT id INTO v_lote FROM lotes
     WHERE empresa_id = p_empresa_id AND producto_id = v_producto AND codigo = btrim(p_codigo)
       AND COALESCE(fecha_caducidad,'9999-12-31'::date) = COALESCE(p_caducidad,'9999-12-31'::date);
    IF v_lote IS NULL THEN
      INSERT INTO lotes (empresa_id, producto_id, codigo, fecha_caducidad, fecha_fabricacion, costo)
      VALUES (p_empresa_id, v_producto, btrim(p_codigo), p_caducidad, p_fabricacion, p_costo) RETURNING id INTO v_lote;
    ELSE
      UPDATE lotes SET fecha_fabricacion = COALESCE(p_fabricacion, fecha_fabricacion), costo = COALESCE(p_costo, costo) WHERE id = v_lote;
    END IF;
    INSERT INTO stock_lotes (empresa_id, almacen_id, producto_id, lote_id, cantidad)
    VALUES (p_empresa_id, p_almacen_id, v_producto, v_lote, v_cant)
    ON CONFLICT (almacen_id, lote_id) DO UPDATE SET cantidad = EXCLUDED.cantidad, updated_at = now();
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END; $$;


--
-- Name: asignar_publico_general_a_venta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asignar_publico_general_a_venta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente_id uuid;
BEGIN
  IF NEW.cliente_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.clientes (
    empresa_id,
    nombre,
    status,
    credito,
    es_publico_general
  ) VALUES (
    NEW.empresa_id,
    'Público general',
    'activo',
    false,
    true
  )
  ON CONFLICT (empresa_id) WHERE es_publico_general
  DO UPDATE SET status = 'activo'
  RETURNING id INTO v_cliente_id;

  NEW.cliente_id := v_cliente_id;
  RETURN NEW;
END;
$$;


--
-- Name: audit_commission_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_commission_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entity_type text;
  v_entity_id uuid;
  v_action text;
  v_previous jsonb;
  v_new jsonb;
  v_reason text;
BEGIN
  v_entity_type := CASE TG_TABLE_NAME
    WHEN 'commission_people' THEN 'person'
    ELSE 'client_attribution'
  END;

  v_action := CASE TG_OP
    WHEN 'INSERT' THEN 'created'
    WHEN 'UPDATE' THEN 'updated'
    ELSE 'deleted'
  END;

  v_previous := CASE
    WHEN TG_OP = 'INSERT' THEN NULL
    ELSE to_jsonb(OLD)
  END;

  v_new := CASE
    WHEN TG_OP = 'DELETE' THEN NULL
    ELSE to_jsonb(NEW)
  END;

  v_entity_id := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.id
    ELSE NEW.id
  END;

  v_reason := NULLIF(
    current_setting('app.commission_change_reason', true),
    ''
  );

  INSERT INTO public.commission_audit_log (
    entity_type,
    entity_id,
    action,
    previous_data,
    new_data,
    reason,
    changed_by
  )
  VALUES (
    v_entity_type,
    v_entity_id,
    v_action,
    v_previous,
    v_new,
    v_reason,
    auth.uid()
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


