-- Name: auto_entregas_en_ruta_on_sesion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_entregas_en_ruta_on_sesion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'en_ruta' THEN
    UPDATE public.entregas
    SET status = 'en_ruta'
    WHERE empresa_id = NEW.empresa_id
      AND vendedor_id = NEW.vendedor_id
      AND fecha = NEW.fecha
      AND status = 'cargado';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: auto_folio_compra(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_folio_compra() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('folio:COM'), hashtext(NEW.empresa_id::text));
  SELECT 'COM-' || public.folio_lpad((COALESCE(MAX(CASE WHEN folio ~ '^COM-[0-9]+$' THEN CAST(SUBSTRING(folio FROM 5) AS INT) ELSE 0 END),0)+1)::TEXT,4,'0')
  INTO NEW.folio FROM public.compras WHERE empresa_id = NEW.empresa_id;
  RETURN NEW;
END; $_$;


