--
-- Name: auto_folio_venta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_folio_venta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF NEW.tipo = 'saldo_inicial' THEN
    PERFORM pg_advisory_xact_lock(hashtext('folio:SAL'), hashtext(NEW.empresa_id::text));
    SELECT 'SAL-' || public.folio_num(COALESCE(MAX(CASE WHEN folio ~ '^SAL-[0-9]+$' THEN CAST(SUBSTRING(folio FROM 5) AS BIGINT) ELSE 0 END), 0) + 1)
    INTO NEW.folio FROM public.ventas WHERE empresa_id = NEW.empresa_id;
  ELSE
    NEW.folio := next_folio(CASE WHEN NEW.tipo = 'pedido' THEN 'PED' ELSE 'VTA' END, NEW.empresa_id);
  END IF;
  RETURN NEW;
END;
$_$;


