--
-- Name: auto_venta_entregado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_venta_entregado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pedido_id uuid;
  v_total_entregas int;
  v_entregas_hecho int;
BEGIN
  v_pedido_id := NEW.pedido_id;
  IF v_pedido_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.status <> 'hecho' THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'hecho')
  INTO v_total_entregas, v_entregas_hecho
  FROM public.entregas
  WHERE pedido_id = v_pedido_id AND status <> 'cancelado';

  IF v_total_entregas > 0 AND v_total_entregas = v_entregas_hecho THEN
    UPDATE public.ventas SET status = 'entregado'
    WHERE id = v_pedido_id AND status = 'confirmado';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: auto_venta_facturado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_venta_facturado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta_id uuid;
  v_total_lineas int;
  v_lineas_facturadas int;
BEGIN
  v_venta_id := NEW.venta_id;
  IF v_venta_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.facturado IS NOT TRUE THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE facturado = true)
  INTO v_total_lineas, v_lineas_facturadas
  FROM public.venta_lineas
  WHERE venta_id = v_venta_id;

  IF v_total_lineas > 0 AND v_total_lineas = v_lineas_facturadas THEN
    UPDATE public.ventas SET status = 'facturado'
    WHERE id = v_venta_id AND status IN ('confirmado', 'entregado');
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: bloquea_entrega_linea_pedido_cerrado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bloquea_entrega_linea_pedido_cerrado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pedido uuid;
BEGIN
  SELECT e.pedido_id INTO v_pedido FROM public.entregas e WHERE e.id = NEW.entrega_id;
  IF v_pedido IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.ventas WHERE id = v_pedido AND cerrado_at IS NOT NULL) THEN
    RAISE EXCEPTION 'El pedido está cerrado parcial. Reábrelo para cambiar lo entregado.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bloquea_entrega_pedido_cerrado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bloquea_entrega_pedido_cerrado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.pedido_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.ventas WHERE id = NEW.pedido_id AND cerrado_at IS NOT NULL) THEN
    RAISE EXCEPTION 'El pedido está cerrado parcial. Reábrelo para crear o cambiar entregas.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: bloquear_cancelar_pedido_con_entregas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bloquear_cancelar_pedido_con_entregas() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_entregas text;
BEGIN
  IF NEW.status::text NOT IN ('cancelado','borrador') THEN RETURN NEW; END IF;
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  SELECT string_agg(folio, ', ' ORDER BY folio) INTO v_entregas
  FROM public.entregas WHERE pedido_id = NEW.id AND status::text <> 'cancelado';
  IF v_entregas IS NOT NULL THEN
    RAISE EXCEPTION 'Este pedido tiene entregas activas (%). Cancela o reversa primero sus entregas antes de % la venta.',
      v_entregas, CASE WHEN NEW.status::text = 'cancelado' THEN 'cancelar' ELSE 'regresar a borrador' END
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: calc_audit_stock_teorico(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calc_audit_stock_teorico(p_linea_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_producto_id uuid;
  v_almacen_id uuid;
  v_apertura timestamptz;
  v_cantidad_esperada numeric;
  v_net_movements numeric;
BEGIN
  SELECT al.producto_id, al.cantidad_esperada, a.almacen_id, a.created_at
  INTO v_producto_id, v_cantidad_esperada, v_almacen_id, v_apertura
  FROM auditoria_lineas al
  JOIN auditorias a ON a.id = al.auditoria_id
  WHERE al.id = p_linea_id;

  IF v_producto_id IS NULL OR v_almacen_id IS NULL THEN
    RETURN v_cantidad_esperada;
  END IF;

  -- entrada: stock arrives at almacen_destino_id → positive
  -- salida: stock leaves from almacen_origen_id → negative  
  -- transferencia: arrives at destino (+), leaves from origen (-)
  SELECT COALESCE(SUM(
    CASE 
      WHEN tipo = 'entrada' AND almacen_destino_id = v_almacen_id THEN cantidad
      WHEN tipo = 'entrada' AND almacen_origen_id = v_almacen_id THEN cantidad
      WHEN tipo = 'salida' AND almacen_origen_id = v_almacen_id THEN -cantidad
      WHEN tipo = 'salida' AND almacen_destino_id = v_almacen_id THEN -cantidad
      WHEN tipo = 'transferencia' AND almacen_destino_id = v_almacen_id THEN cantidad
      WHEN tipo = 'transferencia' AND almacen_origen_id = v_almacen_id THEN -cantidad
      ELSE 0
    END
  ), 0)
  INTO v_net_movements
  FROM movimientos_inventario
  WHERE producto_id = v_producto_id
    AND created_at > v_apertura
    AND (almacen_origen_id = v_almacen_id OR almacen_destino_id = v_almacen_id)
    AND (referencia_tipo IS NULL OR referencia_tipo != 'auditoria');

  RETURN v_cantidad_esperada + v_net_movements;
END;
$$;


--
-- Name: calcular_comision_volumen(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_comision_volumen(p_vendedor_id uuid, p_desde date, p_hasta date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid;
  v_esquema RECORD;
  v_total_ventas numeric := 0;
  v_num_ventas integer := 0;
  v_comision numeric := 0;
  v_tier jsonb;
  v_pct numeric;
  v_meta numeric;
  v_bono numeric;
  v_bono_pct numeric;
  v_ventas_ids uuid[];
  v_caller_empresa uuid;
  v_desde_efectivo date;
BEGIN
  SELECT empresa_id INTO v_caller_empresa FROM public.profiles WHERE user_id = auth.uid();
  SELECT empresa_id INTO v_empresa FROM public.profiles WHERE id = p_vendedor_id;
  IF v_caller_empresa IS NULL OR v_empresa IS NULL OR v_caller_empresa <> v_empresa THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT ce.* INTO v_esquema
  FROM public.profiles p
  JOIN public.comision_esquemas ce ON ce.id = p.comision_esquema_id
  WHERE p.id = p_vendedor_id AND ce.activo = true;

  IF v_esquema IS NULL THEN
    RETURN jsonb_build_object('error','sin_esquema');
  END IF;

  v_desde_efectivo := GREATEST(p_desde, COALESCE(v_esquema.vigente_desde, p_desde));

  IF v_esquema.base = 'cobradas' THEN
    SELECT COALESCE(SUM(v.total),0), COUNT(*), COALESCE(array_agg(v.id),'{}'::uuid[])
      INTO v_total_ventas, v_num_ventas, v_ventas_ids
    FROM public.ventas v
    WHERE v.empresa_id = v_empresa
      AND v.vendedor_id = p_vendedor_id
      AND v.fecha BETWEEN v_desde_efectivo AND p_hasta
      AND v.status <> 'cancelado'
      AND COALESCE(v.es_saldo_inicial,false) = false
      AND COALESCE(v.saldo_pendiente, 0) <= 0.01
      AND v.comision_volumen_pago_id IS NULL;
  ELSE
    SELECT COALESCE(SUM(v.total),0), COUNT(*), COALESCE(array_agg(v.id),'{}'::uuid[])
      INTO v_total_ventas, v_num_ventas, v_ventas_ids
    FROM public.ventas v
    WHERE v.empresa_id = v_empresa
      AND v.vendedor_id = p_vendedor_id
      AND v.fecha BETWEEN v_desde_efectivo AND p_hasta
      AND v.status <> 'cancelado'
      AND COALESCE(v.es_saldo_inicial,false) = false
      AND v.comision_volumen_pago_id IS NULL;
  END IF;

  IF v_esquema.tipo = 'volumen_pct' THEN
    v_pct := COALESCE((v_esquema.config->>'pct')::numeric, 0);
    v_comision := ROUND(v_total_ventas * v_pct / 100, 2);
  ELSIF v_esquema.tipo = 'volumen_tiers' THEN
    v_pct := 0;
    FOR v_tier IN SELECT * FROM jsonb_array_elements(COALESCE(v_esquema.config->'tiers','[]'::jsonb)) LOOP
      IF v_total_ventas >= COALESCE((v_tier->>'desde')::numeric, 0)
         AND (v_tier->>'hasta' IS NULL OR v_total_ventas <= (v_tier->>'hasta')::numeric) THEN
        v_pct := COALESCE((v_tier->>'pct')::numeric, 0);
        EXIT;
      END IF;
    END LOOP;
    v_comision := ROUND(v_total_ventas * v_pct / 100, 2);
  ELSIF v_esquema.tipo = 'bono_meta' THEN
    v_meta := COALESCE((v_esquema.config->>'meta')::numeric, 0);
    v_bono := COALESCE((v_esquema.config->>'bono')::numeric, 0);
    v_bono_pct := COALESCE((v_esquema.config->>'bono_pct')::numeric, 0);
    IF v_total_ventas >= v_meta AND v_meta > 0 THEN
      v_comision := ROUND(v_bono + (v_total_ventas * v_bono_pct / 100), 2);
    ELSE
      v_comision := 0;
    END IF;
  ELSIF v_esquema.tipo = 'lista_precios' THEN
    SELECT COALESCE(SUM(vc.comision_monto),0)
      INTO v_comision
    FROM public.venta_comisiones vc
    WHERE vc.empresa_id = v_empresa
      AND vc.vendedor_id = p_vendedor_id
      AND vc.venta_id = ANY(v_ventas_ids);
    v_comision := ROUND(COALESCE(v_comision,0) * (1 + COALESCE((v_esquema.config->>'ajuste_pct')::numeric,0)/100), 2);
    v_pct := CASE WHEN v_total_ventas > 0 THEN ROUND(v_comision * 100 / v_total_ventas, 2) ELSE 0 END;
  END IF;

  RETURN jsonb_build_object(
    'esquema_id', v_esquema.id,
    'esquema_nombre', v_esquema.nombre,
    'tipo', v_esquema.tipo,
    'periodo', v_esquema.periodo,
    'base', v_esquema.base,
    'vigente_desde', v_esquema.vigente_desde,
    'desde_efectivo', v_desde_efectivo,
    'total_ventas', v_total_ventas,
    'num_ventas', v_num_ventas,
    'comision', v_comision,
    'pct_aplicado', v_pct,
    'meta_alcanzada', CASE WHEN v_esquema.tipo='bono_meta' THEN (v_total_ventas >= COALESCE((v_esquema.config->>'meta')::numeric,0)) ELSE null END,
    'ventas_ids', to_jsonb(v_ventas_ids)
  );
END;
$$;


--
-- Name: cancelar_compra_segura(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_compra_segura(p_compra_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_compra public.compras%ROWTYPE;
  v_actor uuid := auth.uid();

  v_producto record;
  v_lote record;

  v_stock numeric;
  v_stock_lote numeric;
  v_ledger_neto numeric;
  v_lote_total numeric;
  v_sin_lote numeric;

  v_productos integer := 0;
  v_piezas numeric := 0;
  v_pagos_eliminados integer := 0;

  v_epsilon constant numeric := 0.0001;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION
      'Debes iniciar sesión para cancelar la compra';
  END IF;

  /*
   * Bloquea la compra.
   * Dos cancelaciones concurrentes no pueden ejecutarse al mismo tiempo.
   */
  SELECT *
  INTO v_compra
  FROM public.compras
  WHERE id = p_compra_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Compra no encontrada';
  END IF;

  IF NOT (
    v_compra.empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(v_actor)
  ) THEN
    RAISE EXCEPTION
      'No tienes permiso para cancelar esta compra';
  END IF;

  /*
   * Idempotencia:
   * si ya fue cancelada, no mueve nuevamente el inventario.
   */
  IF v_compra.status = 'cancelada' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'ya_cancelada', true,
      'compra_id', v_compra.id,
      'folio', v_compra.folio,
      'productos_revertidos', 0,
      'piezas_revertidas', 0,
      'pagos_eliminados', 0
    );
  END IF;

  IF v_compra.status = 'borrador' THEN
    RAISE EXCEPTION
      'Una compra en borrador debe eliminarse, no cancelarse';
  END IF;

  IF v_compra.almacen_id IS NULL THEN
    RAISE EXCEPTION
      'La compra no tiene almacén destino';
  END IF;

  /*
   * Bloquea líneas y pagos para que nadie pueda recibir mercancía
   * o registrar pagos mientras se está cancelando.
   */
  PERFORM 1
  FROM public.compra_lineas
  WHERE compra_id = v_compra.id
  ORDER BY id
  FOR UPDATE;

  PERFORM 1
  FROM public.pago_compras
  WHERE compra_id = v_compra.id
  ORDER BY id
  FOR UPDATE;


  /*
   * PRIMERA PASADA:
   * valida absolutamente todo antes de cambiar inventario.
   */
  FOR v_producto IN
    SELECT
      cl.producto_id,
      SUM(
        GREATEST(0, COALESCE(cl.cantidad_recibida, 0))
      ) AS recibido
    FROM public.compra_lineas cl
    WHERE cl.compra_id = v_compra.id
    GROUP BY cl.producto_id
    HAVING SUM(
      GREATEST(0, COALESCE(cl.cantidad_recibida, 0))
    ) > v_epsilon
    ORDER BY cl.producto_id
  LOOP
    /*
     * Bloquear stock general del producto.
     */
    SELECT sa.cantidad
    INTO v_stock
    FROM public.stock_almacen sa
    WHERE sa.empresa_id = v_compra.empresa_id
      AND sa.almacen_id = v_compra.almacen_id
      AND sa.producto_id = v_producto.producto_id
    FOR UPDATE;

    IF NOT FOUND
       OR COALESCE(v_stock, 0) + v_epsilon < v_producto.recibido
    THEN
      RAISE EXCEPTION
        'No se puede cancelar: el producto % tiene % pieza(s) disponibles y deben revertirse %. Parte de la mercancía ya fue utilizada o vendida.',
        COALESCE(
          (
            SELECT p.nombre
            FROM public.productos p
            WHERE p.id = v_producto.producto_id
          ),
          v_producto.producto_id::text
        ),
        COALESCE(v_stock, 0),
        v_producto.recibido;
    END IF;

    /*
     * El kardex neto de la compra debe coincidir con la cantidad
     * recibida registrada en las líneas.
     */
    SELECT COALESCE(
      SUM(
        CASE
          WHEN mi.tipo = 'entrada'
           AND mi.almacen_destino_id = v_compra.almacen_id
            THEN mi.cantidad

          WHEN mi.tipo = 'salida'
           AND mi.almacen_origen_id = v_compra.almacen_id
            THEN -mi.cantidad

          ELSE 0
        END
      ),
      0
    )
    INTO v_ledger_neto
    FROM public.movimientos_inventario mi
    WHERE mi.empresa_id = v_compra.empresa_id
      AND mi.referencia_id = v_compra.id
      AND mi.referencia_tipo = 'compra'
      AND mi.producto_id = v_producto.producto_id;

    IF ABS(v_ledger_neto - v_producto.recibido) > v_epsilon THEN
      RAISE EXCEPTION
        'No se puede cancelar porque el kardex previo de % no coincide con la recepción: kardex %, recibido %. Requiere auditoría antes de cancelar.',
        COALESCE(
          (
            SELECT p.nombre
            FROM public.productos p
            WHERE p.id = v_producto.producto_id
          ),
          v_producto.producto_id::text
        ),
        v_ledger_neto,
        v_producto.recibido;
    END IF;

    /*
     * Detectar lotes con saldo negativo.
     */
    IF EXISTS (
      SELECT 1
      FROM (
        SELECT
          mi.lote_id,
          SUM(
            CASE

              WHEN mi.tipo = 'entrada'
               AND mi.almacen_destino_id = v_compra.almacen_id
                THEN mi.cantidad

              WHEN mi.tipo = 'salida'
               AND mi.almacen_origen_id = v_compra.almacen_id
                THEN -mi.cantidad

              ELSE 0
            END
          ) AS neto
        FROM public.movimientos_inventario mi
        WHERE mi.empresa_id = v_compra.empresa_id
          AND mi.referencia_id = v_compra.id
          AND mi.referencia_tipo = 'compra'
          AND mi.producto_id = v_producto.producto_id
          AND mi.lote_id IS NOT NULL
        GROUP BY mi.lote_id
      ) lotes
      WHERE lotes.neto < -v_epsilon
    ) THEN
      RAISE EXCEPTION
        'La compra tiene un lote con saldo negativo y requiere auditoría';
    END IF;

    /*
     * Total actualmente recibido mediante lotes.
     */
    SELECT COALESCE(SUM(lotes.neto), 0)
    INTO v_lote_total
    FROM (
      SELECT
        mi.lote_id,
        SUM(
          CASE
            WHEN mi.tipo = 'entrada'
             AND mi.almacen_destino_id = v_compra.almacen_id
              THEN mi.cantidad

            WHEN mi.tipo = 'salida'
             AND mi.almacen_origen_id = v_compra.almacen_id
              THEN -mi.cantidad

            ELSE 0
          END
        ) AS neto
      FROM public.movimientos_inventario mi
      WHERE mi.empresa_id = v_compra.empresa_id
        AND mi.referencia_id = v_compra.id
        AND mi.referencia_tipo = 'compra'
        AND mi.producto_id = v_producto.producto_id
        AND mi.lote_id IS NOT NULL
      GROUP BY mi.lote_id
    ) lotes
    WHERE lotes.neto > v_epsilon;

    IF v_lote_total > v_producto.recibido + v_epsilon THEN
      RAISE EXCEPTION
        'El desglose por lote supera la recepción del producto y requiere auditoría';
    END IF;

    /*
     * Validar la existencia real de cada lote.
     */
    FOR v_lote IN
      SELECT
        mi.lote_id,
        SUM(
          CASE
            WHEN mi.tipo = 'entrada'
             AND mi.almacen_destino_id = v_compra.almacen_id
              THEN mi.cantidad

            WHEN mi.tipo = 'salida'
             AND mi.almacen_origen_id = v_compra.almacen_id
              THEN -mi.cantidad

            ELSE 0
          END
        ) AS neto
      FROM public.movimientos_inventario mi
      WHERE mi.empresa_id = v_compra.empresa_id
        AND mi.referencia_id = v_compra.id
        AND mi.referencia_tipo = 'compra'
        AND mi.producto_id = v_producto.producto_id
        AND mi.lote_id IS NOT NULL
      GROUP BY mi.lote_id
      HAVING SUM(
        CASE
          WHEN mi.tipo = 'entrada'
           AND mi.almacen_destino_id = v_compra.almacen_id
            THEN mi.cantidad

          WHEN mi.tipo = 'salida'
           AND mi.almacen_origen_id = v_compra.almacen_id
            THEN -mi.cantidad

          ELSE 0
        END
      ) > v_epsilon
      ORDER BY mi.lote_id
    LOOP
      SELECT sl.cantidad
      INTO v_stock_lote
      FROM public.stock_lotes sl
      WHERE sl.empresa_id = v_compra.empresa_id
        AND sl.almacen_id = v_compra.almacen_id
        AND sl.producto_id = v_producto.producto_id
        AND sl.lote_id = v_lote.lote_id
      FOR UPDATE;

      IF NOT FOUND
         OR COALESCE(v_stock_lote, 0) + v_epsilon < v_lote.neto
      THEN
        RAISE EXCEPTION
          'No se puede cancelar: un lote relacionado ya no tiene existencias suficientes';
      END IF;
    END LOOP;
  END LOOP;


  /*
   * SEGUNDA PASADA:
   * todo está validado y bloqueado. Ahora sí se aplica la cancelación.
   */
  FOR v_producto IN
    SELECT
      cl.producto_id,
      SUM(
        GREATEST(0, COALESCE(cl.cantidad_recibida, 0))
      ) AS recibido
    FROM public.compra_lineas cl
    WHERE cl.compra_id = v_compra.id
    GROUP BY cl.producto_id
    HAVING SUM(
      GREATEST(0, COALESCE(cl.cantidad_recibida, 0))
    ) > v_epsilon
    ORDER BY cl.producto_id
  LOOP
    /*
     * Descontar una sola vez del stock general.
     */
    UPDATE public.stock_almacen
    SET
      cantidad = cantidad - v_producto.recibido,
      updated_at = now()
    WHERE empresa_id = v_compra.empresa_id
      AND almacen_id = v_compra.almacen_id
      AND producto_id = v_producto.producto_id;

    /*
     * Crear un solo movimiento por lote.
     */
    v_lote_total := 0;

    FOR v_lote IN
      SELECT
        mi.lote_id,
        SUM(
          CASE
            WHEN mi.tipo = 'entrada'
             AND mi.almacen_destino_id = v_compra.almacen_id
              THEN mi.cantidad

            WHEN mi.tipo = 'salida'
             AND mi.almacen_origen_id = v_compra.almacen_id
              THEN -mi.cantidad

            ELSE 0
          END
        ) AS neto
      FROM public.movimientos_inventario mi
      WHERE mi.empresa_id = v_compra.empresa_id
        AND mi.referencia_id = v_compra.id
        AND mi.referencia_tipo = 'compra'
        AND mi.producto_id = v_producto.producto_id
        AND mi.lote_id IS NOT NULL
      GROUP BY mi.lote_id
      HAVING SUM(
        CASE
          WHEN mi.tipo = 'entrada'
           AND mi.almacen_destino_id = v_compra.almacen_id
            THEN mi.cantidad

          WHEN mi.tipo = 'salida'
           AND mi.almacen_origen_id = v_compra.almacen_id
            THEN -mi.cantidad

          ELSE 0
        END
      ) > v_epsilon
      ORDER BY mi.lote_id
    LOOP
      INSERT INTO public.movimientos_inventario (
        empresa_id,
        tipo,
        producto_id,
        cantidad,
        almacen_origen_id,
        lote_id,
        referencia_tipo,
        referencia_id,
        user_id,
        fecha,
        notas
      )
      VALUES (
        v_compra.empresa_id,
        'salida',
        v_producto.producto_id,
        v_lote.neto,
        v_compra.almacen_id,
        v_lote.lote_id,
        'compra',
        v_compra.id,
        v_actor,
        current_date,
        concat(
          'Cancelación atómica compra ',
          COALESCE(v_compra.folio, v_compra.id::text)
        )
      );

      v_lote_total := v_lote_total + v_lote.neto;
    END LOOP;

    /*
     * Cantidad recibida sin lote.
     */
    v_sin_lote := v_producto.recibido - v_lote_total;

    IF v_sin_lote > v_epsilon THEN
      INSERT INTO public.movimientos_inventario (
        empresa_id,
        tipo,
        producto_id,
        cantidad,
        almacen_origen_id,
        referencia_tipo,
        referencia_id,
        user_id,
        fecha,
        notas
      )
      VALUES (
        v_compra.empresa_id,
        'salida',
        v_producto.producto_id,
        v_sin_lote,
        v_compra.almacen_id,
        'compra',
        v_compra.id,
        v_actor,
        current_date,
        concat(
          'Cancelación atómica compra ',
          COALESCE(v_compra.folio, v_compra.id::text)
        )
      );
    END IF;

    v_productos := v_productos + 1;
    v_piezas := v_piezas + v_producto.recibido;
  END LOOP;

  /*
   * Pagos y estado forman parte de la misma transacción.
   */
  DELETE FROM public.pago_compras
  WHERE compra_id = v_compra.id;

  GET DIAGNOSTICS v_pagos_eliminados = ROW_COUNT;

  UPDATE public.compras
  SET
    status = 'cancelada',
    saldo_pendiente = 0
  WHERE id = v_compra.id;

  RETURN jsonb_build_object(
    'ok', true,
    'ya_cancelada', false,
    'compra_id', v_compra.id,
    'folio', v_compra.folio,
    'productos_revertidos', v_productos,
    'piezas_revertidas', v_piezas,
    'pagos_eliminados', v_pagos_eliminados
  );
END;
$$;


--
-- Name: cancelar_entregas_bulk(uuid[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entregas_bulk(p_entrega_ids uuid[], p_motivo text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid := get_my_empresa_id();
  v_entrega RECORD;
  v_canceladas int := 0;
  v_omitidas int := 0;
BEGIN
  IF p_entrega_ids IS NULL OR array_length(p_entrega_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No hay entregas seleccionadas';
  END IF;
  FOR v_entrega IN
    SELECT e.id, e.status FROM entregas e
    WHERE e.id = ANY(p_entrega_ids) AND (e.empresa_id = v_empresa OR is_super_admin(auth.uid()))
    FOR UPDATE OF e
  LOOP
    IF v_entrega.status::text IN ('hecho','cancelado') THEN
      v_omitidas := v_omitidas + 1; CONTINUE;
    END IF;
    UPDATE entregas SET status = 'cancelado',
      motivo_no_entrega = COALESCE(p_motivo, motivo_no_entrega)
    WHERE id = v_entrega.id;
    v_canceladas := v_canceladas + 1;
  END LOOP;
  RETURN jsonb_build_object('canceladas', v_canceladas, 'con_devolucion_stock', 0, 'omitidas', v_omitidas);
END;
$$;


--
-- Name: cancelar_merma(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_merma(_merma_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _empresa_id uuid := public.get_my_empresa_id();
  _user_id uuid := auth.uid();
  _m record; _almacen_mermas uuid; _l record; _ll record;
BEGIN
  SELECT * INTO _m FROM public.mermas WHERE id = _merma_id AND (empresa_id = _empresa_id OR public.is_super_admin(_user_id));
  IF NOT FOUND THEN RAISE EXCEPTION 'Merma no encontrada'; END IF;
  IF _m.cancelada THEN RAISE EXCEPTION 'Merma ya cancelada'; END IF;
  _almacen_mermas := public.ensure_almacen_mermas(_m.empresa_id);
  FOR _l IN SELECT * FROM public.merma_lineas WHERE merma_id = _merma_id LOOP
    UPDATE public.stock_almacen SET cantidad = cantidad + _l.cantidad, updated_at = now()
     WHERE empresa_id = _m.empresa_id AND almacen_id = _m.almacen_origen_id AND producto_id = _l.producto_id;
    IF NOT FOUND THEN
      INSERT INTO public.stock_almacen(empresa_id, almacen_id, producto_id, cantidad)
      VALUES (_m.empresa_id, _m.almacen_origen_id, _l.producto_id, _l.cantidad);
    END IF;
    UPDATE public.stock_almacen SET cantidad = cantidad - _l.cantidad, updated_at = now()
     WHERE empresa_id = _m.empresa_id AND almacen_id = _almacen_mermas AND producto_id = _l.producto_id;

    INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, notas, user_id, fecha)
    VALUES (_m.empresa_id, 'entrada', _l.producto_id, _l.cantidad, _m.almacen_origen_id, 'merma_cancelacion', _m.id, _m.folio || ' (CANCELADA)', _user_id, CURRENT_DATE);

    INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, notas, user_id, fecha)
    VALUES (_m.empresa_id, 'salida', _l.producto_id, _l.cantidad, _almacen_mermas, 'merma_cancelacion', _m.id, _m.folio || ' (CANCELADA)', _user_id, CURRENT_DATE);

    FOR _ll IN SELECT * FROM public.merma_linea_lotes WHERE merma_linea_id = _l.id LOOP
      -- El stock por lote lo aplica el trigger trg_sync_stock_lote a partir de estos movimientos
      INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
      VALUES (_m.empresa_id, 'entrada', _ll.producto_id, _ll.cantidad, _m.almacen_origen_id, _ll.lote_id, 'merma_cancelacion_lote', _m.id, _m.folio || ' (CANCELADA)', _user_id, CURRENT_DATE);
      INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
      VALUES (_m.empresa_id, 'salida', _ll.producto_id, _ll.cantidad, _almacen_mermas, _ll.lote_id, 'merma_cancelacion_lote', _m.id, _m.folio || ' (CANCELADA)', _user_id, CURRENT_DATE);
    END LOOP;
  END LOOP;
  UPDATE public.mermas SET cancelada = true, cancelada_at = now(), cancelada_por = _user_id WHERE id = _merma_id;
END; $$;


--
-- Name: cancelar_solicitud_traspaso(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_solicitud_traspaso(p_solicitud_id uuid, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sol public.solicitudes_traspaso%ROWTYPE;
BEGIN
  SELECT * INTO v_sol FROM public.solicitudes_traspaso WHERE id = p_solicitud_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF;
  IF NOT (v_sol.empresa_id = public.get_my_empresa_id() OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF v_sol.status IN ('surtida','cancelada') THEN RAISE EXCEPTION 'Esta solicitud no se puede cancelar'; END IF;
  UPDATE public.solicitudes_traspaso SET status = 'cancelada' WHERE id = p_solicitud_id;
  PERFORM public.fn_log_solicitud_traspaso(p_solicitud_id, v_sol.empresa_id, 'cancelada', jsonb_build_object('motivo', p_motivo));
END; $$;


--
-- Name: cancelar_traspaso(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_traspaso(p_traspaso_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_traspaso traspasos%ROWTYPE;
  v_linea RECORD;
  v_today date := CURRENT_DATE;
  v_sa_id uuid;
  v_sa_qty numeric;
  v_new_qty numeric;
  v_prod_name text;
  v_allow_negative boolean;
  v_vendedor_almacen_id uuid;
BEGIN
  SELECT * INTO v_traspaso FROM traspasos WHERE id = p_traspaso_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Traspaso no encontrado'; END IF;
  IF v_traspaso.status = 'cancelado' THEN RAISE EXCEPTION 'Este traspaso ya está cancelado'; END IF;

  IF v_traspaso.status = 'confirmado' THEN
    FOR v_linea IN SELECT * FROM traspaso_lineas WHERE traspaso_id = p_traspaso_id LOOP
      SELECT nombre, vender_sin_stock INTO v_prod_name, v_allow_negative FROM productos WHERE id = v_linea.producto_id;

      -- === RETURN TO ORIGIN ===
      IF v_traspaso.almacen_origen_id IS NOT NULL THEN
        SELECT id, cantidad INTO v_sa_id, v_sa_qty
        FROM stock_almacen WHERE almacen_id = v_traspaso.almacen_origen_id AND producto_id = v_linea.producto_id FOR UPDATE;

        IF v_sa_id IS NOT NULL THEN
          UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty, 0) + v_linea.cantidad, updated_at = now() WHERE id = v_sa_id;
        ELSE
          INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad) VALUES (v_traspaso.empresa_id, v_traspaso.almacen_origen_id, v_linea.producto_id, v_linea.cantidad);
        END IF;

        INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
        VALUES (v_traspaso.empresa_id, 'entrada', v_linea.producto_id, v_linea.cantidad, v_traspaso.almacen_origen_id, 'traspaso', p_traspaso_id, p_user_id, v_today, 'Cancelación traspaso ' || COALESCE(v_traspaso.folio, ''));
      END IF;

      IF v_traspaso.vendedor_origen_id IS NOT NULL THEN
        SELECT almacen_id INTO v_vendedor_almacen_id FROM profiles WHERE id = v_traspaso.vendedor_origen_id;
        IF v_vendedor_almacen_id IS NOT NULL THEN
          SELECT id, cantidad INTO v_sa_id, v_sa_qty
          FROM stock_almacen WHERE almacen_id = v_vendedor_almacen_id AND producto_id = v_linea.producto_id FOR UPDATE;

          IF v_sa_id IS NOT NULL THEN
            UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty, 0) + v_linea.cantidad, updated_at = now() WHERE id = v_sa_id;
          ELSE
            INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad) VALUES (v_traspaso.empresa_id, v_vendedor_almacen_id, v_linea.producto_id, v_linea.cantidad);
          END IF;

          INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
          VALUES (v_traspaso.empresa_id, 'entrada', v_linea.producto_id, v_linea.cantidad, v_vendedor_almacen_id, 'traspaso', p_traspaso_id, p_user_id, v_today, 'Cancelación traspaso ' || COALESCE(v_traspaso.folio, '') || ' (devuelto a ruta)');
        END IF;
      END IF;

      -- === DEDUCT FROM DESTINATION ===
      IF v_traspaso.almacen_destino_id IS NOT NULL THEN
        SELECT id, cantidad INTO v_sa_id, v_sa_qty
        FROM stock_almacen WHERE almacen_id = v_traspaso.almacen_destino_id AND producto_id = v_linea.producto_id FOR UPDATE;

        IF v_sa_id IS NOT NULL THEN
          v_new_qty := COALESCE(v_sa_qty, 0) - v_linea.cantidad;
          IF NOT COALESCE(v_allow_negative, false) AND v_new_qty < 0 THEN
            RAISE EXCEPTION 'Stock insuficiente en destino para cancelar "%". Disponible: %, solicitado: %', v_prod_name, COALESCE(v_sa_qty, 0), v_linea.cantidad;
          END IF;
          UPDATE stock_almacen SET cantidad = v_new_qty, updated_at = now() WHERE id = v_sa_id;
        END IF;

        INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas)
        VALUES (v_traspaso.empresa_id, 'salida', v_linea.producto_id, v_linea.cantidad, v_traspaso.almacen_destino_id, 'traspaso', p_traspaso_id, p_user_id, v_today, 'Cancelación traspaso ' || COALESCE(v_traspaso.folio, ''));
      END IF;

      IF v_traspaso.vendedor_destino_id IS NOT NULL THEN
        SELECT almacen_id INTO v_vendedor_almacen_id FROM profiles WHERE id = v_traspaso.vendedor_destino_id;
        IF v_vendedor_almacen_id IS NOT NULL THEN
          SELECT id, cantidad INTO v_sa_id, v_sa_qty
          FROM stock_almacen WHERE almacen_id = v_vendedor_almacen_id AND producto_id = v_linea.producto_id FOR UPDATE;

          IF v_sa_id IS NOT NULL THEN
            v_new_qty := COALESCE(v_sa_qty, 0) - v_linea.cantidad;
            IF NOT COALESCE(v_allow_negative, false) AND v_new_qty < 0 THEN
              RAISE EXCEPTION 'Stock insuficiente en ruta destino para cancelar "%". Disponible: %, solicitado: %', v_prod_name, COALESCE(v_sa_qty, 0), v_linea.cantidad;
            END IF;
            UPDATE stock_almacen SET cantidad = v_new_qty, updated_at = now() WHERE id = v_sa_id;
          END IF;

          INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas)
          VALUES (v_traspaso.empresa_id, 'salida', v_linea.producto_id, v_linea.cantidad, v_vendedor_almacen_id, 'traspaso', p_traspaso_id, p_user_id, v_today, 'Cancelación traspaso ' || COALESCE(v_traspaso.folio, '') || ' (retirado de ruta)');
        END IF;
      END IF;

    END LOOP;
  END IF;

  UPDATE traspasos SET status = 'cancelado' WHERE id = p_traspaso_id;
END;
$$;


--
-- Name: cerrar_pedido_parcial(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cerrar_pedido_parcial(p_venta_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta      public.ventas%ROWTYPE;
  v_orig_base  numeric;
  v_deliv_base numeric;
  v_cobrable   numeric;
  v_cobros     numeric;
  v_saldo      numeric;
  v_snapshot   jsonb;
BEGIN
  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pedido no encontrado'; END IF;

  IF v_venta.tipo::text <> 'pedido' THEN
    RAISE EXCEPTION 'Solo se pueden cerrar pedidos'; END IF;
  IF v_venta.politica_cobro IS DISTINCT FROM 'entregado' THEN
    RAISE EXCEPTION 'Solo aplica a pedidos con política de cobro por entregado'; END IF;
  IF v_venta.cerrado_at IS NOT NULL THEN
    RAISE EXCEPTION 'El pedido ya está cerrado'; END IF;
  IF v_venta.status::text IN ('cancelado','facturado') THEN
    RAISE EXCEPTION 'No se puede cerrar un pedido cancelado o facturado'; END IF;
  IF COALESCE(v_venta.es_saldo_inicial,false) THEN
    RAISE EXCEPTION 'No aplica a saldos iniciales'; END IF;

  SELECT COALESCE(SUM(base), 0), COALESCE(SUM(base * ratio), 0)
    INTO v_orig_base, v_deliv_base
  FROM (
    SELECT
      (COALESCE(vl.subtotal,0) + COALESCE(vl.iva_monto,0) + COALESCE(vl.ieps_monto,0)) AS base,
      CASE WHEN vl.cantidad > 0
           THEN LEAST(COALESCE(ent.entregado, 0), vl.cantidad) / vl.cantidad
           ELSE 0 END AS ratio
    FROM public.venta_lineas vl
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(el.cantidad_entregada), 0) AS entregado
      FROM public.entrega_lineas el
      JOIN public.entregas e ON e.id = el.entrega_id
      WHERE e.pedido_id = p_venta_id
        AND e.status::text NOT IN ('cancelado','no_entregado')
        AND el.producto_id = vl.producto_id
    ) ent ON true
    WHERE vl.venta_id = p_venta_id
  ) q;

  IF COALESCE(v_deliv_base, 0) <= 0 THEN
    RAISE EXCEPTION 'No hay nada entregado: cancela el pedido en vez de cerrarlo';
  END IF;

  v_cobrable := CASE WHEN COALESCE(v_orig_base,0) > 0
                     THEN ROUND(COALESCE(v_venta.total,0) * (v_deliv_base / v_orig_base), 2)
                     ELSE 0 END;

  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_cobros
  FROM public.cobro_aplicaciones ca
  JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = p_venta_id AND COALESCE(c.status,'activo') <> 'cancelado';

  v_saldo := GREATEST(0, v_cobrable - v_cobros);

  v_snapshot := jsonb_build_object(
    'pedido_total',    COALESCE(v_venta.total,0),
    'total_efectivo',  v_cobrable,
    'cobros',          v_cobros,
    'saldo',           v_saldo,
    'base_original',   v_orig_base,
    'base_entregada',  v_deliv_base,
    'lineas', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'linea_id',    vl.id,
               'producto_id', vl.producto_id,
               'pedido',      vl.cantidad,
               'entregado',   COALESCE((
                  SELECT SUM(el.cantidad_entregada)
                  FROM public.entrega_lineas el JOIN public.entregas e ON e.id = el.entrega_id
                  WHERE e.pedido_id = p_venta_id
                    AND e.status::text NOT IN ('cancelado','no_entregado')
                    AND el.producto_id = vl.producto_id), 0),
               'subtotal_orig', vl.subtotal,
               'iva_orig',      vl.iva_monto,
               'ieps_orig',     vl.ieps_monto,
               'total_orig',    vl.total
             )), '[]'::jsonb)
      FROM public.venta_lineas vl WHERE vl.venta_id = p_venta_id
    )
  );

  -- UPDATE sin LATERAL: el ratio se calcula inline usando vl (target) y ent (FROM).
  UPDATE public.venta_lineas vl
  SET
    cantidad   = LEAST(COALESCE(ent.entregado, 0), vl.cantidad),
    subtotal   = ROUND(COALESCE(vl.subtotal,0)
                       * CASE WHEN vl.cantidad > 0
                              THEN LEAST(COALESCE(ent.entregado,0), vl.cantidad) / vl.cantidad
                              ELSE 0 END, 2),
    iva_monto  = ROUND(COALESCE(vl.iva_monto,0)
                       * CASE WHEN vl.cantidad > 0
                              THEN LEAST(COALESCE(ent.entregado,0), vl.cantidad) / vl.cantidad
                              ELSE 0 END, 2),
    ieps_monto = ROUND(COALESCE(vl.ieps_monto,0)
                       * CASE WHEN vl.cantidad > 0
                              THEN LEAST(COALESCE(ent.entregado,0), vl.cantidad) / vl.cantidad
                              ELSE 0 END, 2),
    total      = ROUND(COALESCE(vl.total,0)
                       * CASE WHEN vl.cantidad > 0
                              THEN LEAST(COALESCE(ent.entregado,0), vl.cantidad) / vl.cantidad
                              ELSE 0 END, 2)
  FROM (
    SELECT vl2.id AS linea_id,
           COALESCE((SELECT SUM(el.cantidad_entregada)
                       FROM public.entrega_lineas el
                       JOIN public.entregas e ON e.id = el.entrega_id
                      WHERE e.pedido_id = p_venta_id
                        AND e.status::text NOT IN ('cancelado','no_entregado')
                        AND el.producto_id = vl2.producto_id), 0) AS entregado
    FROM public.venta_lineas vl2
    WHERE vl2.venta_id = p_venta_id
  ) ent
  WHERE vl.id = ent.linea_id AND vl.venta_id = p_venta_id;

  UPDATE public.ventas
  SET cerrado_at       = now(),
      cerrado_por      = COALESCE(p_user_id, auth.uid()),
      total_efectivo   = v_cobrable,
      cerrado_snapshot = v_snapshot
  WHERE id = p_venta_id;

  PERFORM public.fn_recalc_venta_saldo(p_venta_id);
END;
$$;


--
-- Name: cerrar_solicitud_traspaso(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cerrar_solicitud_traspaso(p_solicitud_id uuid, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sol public.solicitudes_traspaso%ROWTYPE;
BEGIN
  SELECT * INTO v_sol FROM public.solicitudes_traspaso WHERE id = p_solicitud_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF;
  IF NOT (v_sol.empresa_id = public.get_my_empresa_id() OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF v_sol.status NOT IN ('aprobada','parcialmente_surtida') THEN
    RAISE EXCEPTION 'Solo se puede cerrar una solicitud publicada o parcialmente surtida';
  END IF;
  UPDATE public.solicitudes_traspaso
     SET status = 'cerrada', cerrado_at = now(), cerrado_por = auth.uid(), motivo_cierre = p_motivo
   WHERE id = p_solicitud_id;
  PERFORM public.fn_log_solicitud_traspaso(p_solicitud_id, v_sol.empresa_id, 'cerrada',
    jsonb_build_object('motivo', p_motivo));
END; $$;


