--
-- Name: check_stock_lote_paridad(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_stock_lote_paridad(p_empresa_id uuid DEFAULT NULL::uuid) RETURNS TABLE(empresa_id uuid, almacen_id uuid, almacen_nombre text, producto_id uuid, codigo text, nombre text, stock_general numeric, suma_lotes numeric, diferencia numeric, caso text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    sa.empresa_id,
    sa.almacen_id,
    a.nombre AS almacen_nombre,
    sa.producto_id,
    p.codigo,
    p.nombre,
    sa.cantidad AS stock_general,
    COALESCE(sl.suma_lotes, 0) AS suma_lotes,
    sa.cantidad - COALESCE(sl.suma_lotes, 0) AS diferencia,
    CASE WHEN COALESCE(sl.suma_lotes, 0) = 0 AND sa.cantidad <> 0 THEN 'con_lote_sin_lotes' ELSE 'descuadre_real' END AS caso
  FROM public.stock_almacen sa
  JOIN public.productos p ON p.id = sa.producto_id AND COALESCE(p.maneja_lote, false) = true
  LEFT JOIN public.almacenes a ON a.id = sa.almacen_id
  LEFT JOIN (SELECT almacen_id, producto_id, SUM(cantidad) AS suma_lotes FROM public.stock_lotes GROUP BY almacen_id, producto_id) sl
    ON sl.almacen_id = sa.almacen_id AND sl.producto_id = sa.producto_id
  WHERE (p_empresa_id IS NULL OR sa.empresa_id = p_empresa_id)
    AND NOT COALESCE(a.es_merma, false)
    AND sa.cantidad <> COALESCE(sl.suma_lotes, 0)
  ORDER BY caso, p.codigo;
$$;


