--
-- Name: cleanup_venta_inventory_on_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_venta_inventory_on_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  m RECORD;
  v_stock_id uuid; v_stock_actual numeric;
BEGIN
  -- Recorre todos los movimientos ligados a la venta (venta, venta_lote, cancelacion_venta, reverso_borrador)
  -- y revierte su efecto en stock_almacen y stock_lotes, luego los elimina.
  FOR m IN
    SELECT * FROM public.movimientos_inventario
    WHERE referencia_id = OLD.id
      AND referencia_tipo IN ('venta','venta_lote','cancelacion_venta','reverso_borrador')
  LOOP
    -- Revertir stock_almacen
    IF m.almacen_origen_id IS NOT NULL THEN
      SELECT id, cantidad INTO v_stock_id, v_stock_actual
        FROM public.stock_almacen
        WHERE almacen_id = m.almacen_origen_id AND producto_id = m.producto_id
        FOR UPDATE;
      IF v_stock_id IS NOT NULL THEN
        UPDATE public.stock_almacen
           SET cantidad = COALESCE(v_stock_actual,0) + COALESCE(m.cantidad,0), updated_at = now()
         WHERE id = v_stock_id;
      END IF;
    END IF;
    IF m.almacen_destino_id IS NOT NULL THEN
      SELECT id, cantidad INTO v_stock_id, v_stock_actual
        FROM public.stock_almacen
        WHERE almacen_id = m.almacen_destino_id AND producto_id = m.producto_id
        FOR UPDATE;
      IF v_stock_id IS NOT NULL THEN
        UPDATE public.stock_almacen
           SET cantidad = COALESCE(v_stock_actual,0) - COALESCE(m.cantidad,0), updated_at = now()
         WHERE id = v_stock_id;
      END IF;
    END IF;
    -- Revertir stock_lotes
    IF m.lote_id IS NOT NULL THEN
      IF m.almacen_origen_id IS NOT NULL THEN
        PERFORM public._aplica_stock_lote(m.empresa_id, m.almacen_origen_id, m.producto_id, m.lote_id, COALESCE(m.cantidad,0));
      END IF;
      IF m.almacen_destino_id IS NOT NULL THEN
        PERFORM public._aplica_stock_lote(m.empresa_id, m.almacen_destino_id, m.producto_id, m.lote_id, -COALESCE(m.cantidad,0));
      END IF;
    END IF;
  END LOOP;

  DELETE FROM public.movimientos_inventario
   WHERE referencia_id = OLD.id
     AND referencia_tipo IN ('venta','venta_lote','cancelacion_venta','reverso_borrador');

  -- Limpia stock apartado ligado a la venta si existe
  DELETE FROM public.stock_apartado WHERE venta_id = OLD.id;

  RETURN OLD;
END; $$;


--
-- Name: close_audit_line(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_audit_line(p_linea_id uuid, p_cerrada boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_auditoria_id uuid;
  v_producto_id uuid;
  v_cantidad_esperada numeric;
  v_total_scans numeric;
BEGIN
  SELECT auditoria_id, producto_id, cantidad_esperada
  INTO v_auditoria_id, v_producto_id, v_cantidad_esperada
  FROM auditoria_lineas WHERE id = p_linea_id;

  IF NOT FOUND THEN RAISE EXCEPTION 'Line not found'; END IF;

  -- Sum scans
  SELECT COALESCE(SUM(cantidad), 0) INTO v_total_scans
  FROM auditoria_escaneos WHERE linea_id = p_linea_id;

  IF p_cerrada THEN
    -- Try to recalculate expected via teorico engine
    BEGIN
      PERFORM calc_audit_stock_teorico(v_auditoria_id);
    EXCEPTION WHEN OTHERS THEN
      NULL; -- ignore if function doesn't exist
    END;

    -- Re-read cantidad_esperada after recalc
    SELECT cantidad_esperada INTO v_cantidad_esperada
    FROM auditoria_lineas WHERE id = p_linea_id;

    UPDATE auditoria_lineas SET
      cerrada = true,
      cerrada_at = now(),
      cantidad_real = v_total_scans,
      diferencia = v_total_scans - v_cantidad_esperada
    WHERE id = p_linea_id;
  ELSE
    UPDATE auditoria_lineas SET
      cerrada = false,
      cerrada_at = NULL
    WHERE id = p_linea_id;
  END IF;
END;
$$;


--
-- Name: close_full_audit(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_full_audit(p_auditoria_id uuid, p_cerrada_por text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linea RECORD;
  v_teorico numeric;
BEGIN
  -- Recalculate theoretical stock for all unclosed lines
  FOR v_linea IN 
    SELECT id, COALESCE(cantidad_real, 0) as contado 
    FROM auditoria_lineas 
    WHERE auditoria_id = p_auditoria_id AND cerrada = false
  LOOP
    v_teorico := calc_audit_stock_teorico(v_linea.id);
    UPDATE auditoria_lineas 
    SET cerrada = true,
        cantidad_esperada = v_teorico,
        diferencia = v_linea.contado - v_teorico
    WHERE id = v_linea.id;
  END LOOP;
  
  -- Close the audit
  UPDATE auditorias SET status = 'cerrada', cerrada_por = p_cerrada_por, cerrada_at = now() WHERE id = p_auditoria_id;
END;
$$;


--
-- Name: cobro_tiene_rep_vigente(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cobro_tiene_rep_vigente(p_cobro_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM cfdi_pagos WHERE cobro_id = p_cobro_id AND public.cfdi_status_ocupa(status))
$$;


--
-- Name: confirm_timbre_reserve(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_timbre_reserve(p_reservation_id uuid, p_cfdi_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existed boolean;
BEGIN
  UPDATE timbres_movimientos
  SET tipo = 'uso',
      referencia_id = p_cfdi_id,
      notas = 'Timbre usado para CFDI (confirmado)'
  WHERE id = p_reservation_id
    AND tipo = 'reserva'
  RETURNING true INTO v_existed;

  RETURN COALESCE(v_existed, false);
END;
$$;


--
-- Name: confirmar_traspaso(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmar_traspaso(p_traspaso_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_traspaso public.traspasos%ROWTYPE;
  v_linea RECORD;
  v_asignacion RECORD;
  v_origen_id uuid;
  v_destino_id uuid;
  v_stock_id uuid;
  v_stock numeric;
  v_dest_stock_id uuid;
  v_total_lotes numeric;
  v_prod_name text;
  v_allow_negative boolean;
  v_maneja_lote boolean;
  v_folio text;
BEGIN
  SELECT * INTO v_traspaso
  FROM public.traspasos
  WHERE id = p_traspaso_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Traspaso no encontrado'; END IF;
  IF v_traspaso.status <> 'borrador' THEN RAISE EXCEPTION 'Solo se puede confirmar un traspaso en borrador'; END IF;
  IF NOT (v_traspaso.empresa_id = public.get_my_empresa_id() OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'No autorizado para confirmar este traspaso';
  END IF;

  v_origen_id := v_traspaso.almacen_origen_id;
  v_destino_id := v_traspaso.almacen_destino_id;

  IF v_traspaso.vendedor_origen_id IS NOT NULL THEN
    SELECT almacen_id INTO v_origen_id FROM public.profiles WHERE id = v_traspaso.vendedor_origen_id;
  END IF;
  IF v_traspaso.vendedor_destino_id IS NOT NULL THEN
    SELECT almacen_id INTO v_destino_id FROM public.profiles WHERE id = v_traspaso.vendedor_destino_id;
  END IF;

  IF v_origen_id IS NULL OR v_destino_id IS NULL THEN RAISE EXCEPTION 'El origen o destino no tiene almacén asignado'; END IF;
  IF v_origen_id = v_destino_id THEN RAISE EXCEPTION 'El origen y destino deben ser diferentes'; END IF;
  v_folio := COALESCE(v_traspaso.folio, '');

  FOR v_linea IN
    SELECT * FROM public.traspaso_lineas WHERE traspaso_id = p_traspaso_id ORDER BY id
  LOOP
    SELECT nombre, COALESCE(vender_sin_stock, false), COALESCE(maneja_lote, false)
    INTO v_prod_name, v_allow_negative, v_maneja_lote
    FROM public.productos
    WHERE id = v_linea.producto_id AND empresa_id = v_traspaso.empresa_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Producto inválido en el traspaso'; END IF;

    v_stock_id := NULL;
    v_stock := 0;
    SELECT id, cantidad INTO v_stock_id, v_stock
    FROM public.stock_almacen
    WHERE empresa_id = v_traspaso.empresa_id AND almacen_id = v_origen_id AND producto_id = v_linea.producto_id
    FOR UPDATE;

    IF NOT v_allow_negative AND COALESCE(v_stock, 0) < v_linea.cantidad THEN
      RAISE EXCEPTION 'Stock insuficiente en origen para "%". Disponible: %, solicitado: %', v_prod_name, COALESCE(v_stock, 0), v_linea.cantidad;
    END IF;

    IF v_maneja_lote THEN
      SELECT COALESCE(SUM(cantidad), 0) INTO v_total_lotes
      FROM public.traspaso_linea_lotes
      WHERE traspaso_linea_id = v_linea.id;
      IF v_total_lotes <> v_linea.cantidad THEN
        RAISE EXCEPTION 'Asigna lotes por el total de "%". Requerido: %, asignado: %', v_prod_name, v_linea.cantidad, v_total_lotes;
      END IF;

      FOR v_asignacion IN
        SELECT tll.lote_id, tll.cantidad, COALESCE(sl.cantidad, 0) AS disponible
        FROM public.traspaso_linea_lotes tll
        JOIN public.lotes l ON l.id = tll.lote_id
        LEFT JOIN public.stock_lotes sl
          ON sl.empresa_id = tll.empresa_id AND sl.almacen_id = v_origen_id
         AND sl.producto_id = tll.producto_id AND sl.lote_id = tll.lote_id
        WHERE tll.traspaso_linea_id = v_linea.id
          AND tll.empresa_id = v_traspaso.empresa_id
          AND l.producto_id = v_linea.producto_id
        ORDER BY tll.id
        FOR UPDATE OF sl
      LOOP
        IF v_asignacion.disponible < v_asignacion.cantidad THEN
          RAISE EXCEPTION 'Stock insuficiente en el lote de "%". Disponible: %, solicitado: %', v_prod_name, v_asignacion.disponible, v_asignacion.cantidad;
        END IF;
        INSERT INTO public.movimientos_inventario
          (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id, lote_id, referencia_tipo, referencia_id, user_id, fecha, notas)
        VALUES
          (v_traspaso.empresa_id, 'transferencia'::public.tipo_movimiento, v_linea.producto_id, v_asignacion.cantidad,
           v_origen_id, v_destino_id, v_asignacion.lote_id, 'traspaso', p_traspaso_id,
           COALESCE(auth.uid(), p_user_id), CURRENT_DATE, 'Traspaso ' || v_folio);
      END LOOP;
    ELSE
      INSERT INTO public.movimientos_inventario
        (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas)
      VALUES
        (v_traspaso.empresa_id, 'salida', v_linea.producto_id, v_linea.cantidad,
         v_origen_id, 'traspaso', p_traspaso_id, COALESCE(auth.uid(), p_user_id), CURRENT_DATE, 'Traspaso ' || v_folio);
      INSERT INTO public.movimientos_inventario
        (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
      VALUES
        (v_traspaso.empresa_id, 'entrada', v_linea.producto_id, v_linea.cantidad,
         v_destino_id, 'traspaso', p_traspaso_id, COALESCE(auth.uid(), p_user_id), CURRENT_DATE, 'Traspaso ' || v_folio);
    END IF;

    IF v_stock_id IS NULL THEN
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (v_traspaso.empresa_id, v_origen_id, v_linea.producto_id, -v_linea.cantidad);
    ELSE
      UPDATE public.stock_almacen SET cantidad = COALESCE(cantidad, 0) - v_linea.cantidad, updated_at = now() WHERE id = v_stock_id;
    END IF;

    v_dest_stock_id := NULL;
    SELECT id INTO v_dest_stock_id
    FROM public.stock_almacen
    WHERE empresa_id = v_traspaso.empresa_id AND almacen_id = v_destino_id AND producto_id = v_linea.producto_id
    FOR UPDATE;
    IF v_dest_stock_id IS NULL THEN
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (v_traspaso.empresa_id, v_destino_id, v_linea.producto_id, v_linea.cantidad);
    ELSE
      UPDATE public.stock_almacen SET cantidad = COALESCE(cantidad, 0) + v_linea.cantidad, updated_at = now() WHERE id = v_dest_stock_id;
    END IF;
  END LOOP;

  UPDATE public.traspasos SET status = 'confirmado' WHERE id = p_traspaso_id;
END;
$$;


--
-- Name: count_active_users(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_active_users(p_empresa_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$

  SELECT COUNT(*)::int

  FROM public.profiles

  WHERE empresa_id = p_empresa_id

    AND estado = 'activo'

    AND archivado_en IS NULL;

$$;


--
-- Name: crear_mi_cupon_partner_v2(text, text, numeric, boolean, uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crear_mi_cupon_partner_v2(p_codigo text, p_nombre text, p_porcentaje numeric, p_un_uso_por_empresa boolean DEFAULT true, p_plan_id uuid DEFAULT NULL::uuid, p_vigencia_tipo text DEFAULT 'siempre'::text, p_vigente_desde date DEFAULT NULL::date, p_vigente_hasta date DEFAULT NULL::date) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_ctx record;
  v_programa json;
  v_cupon_id uuid;
  v_codigo text;
  v_desde timestamptz;
  v_hasta timestamptz;
  v_plan_nombre text;
begin
  select * into v_ctx
  from public.contexto_partner();

  if v_ctx.partner_id is null or v_ctx.estado <> 'activo' then
    raise exception 'Sesion de partner invalida';
  end if;

  v_codigo := upper(trim(coalesce(p_codigo, '')));

  if length(v_codigo) < 3 or length(v_codigo) > 50 then
    raise exception 'El codigo debe tener entre 3 y 50 caracteres';
  end if;

  if v_codigo !~ '^[A-Z0-9_-]+$' then
    raise exception
      'El codigo solo puede usar letras, numeros, guion y guion bajo';
  end if;

  if nullif(trim(coalesce(p_nombre, '')), '') is null then
    raise exception 'El nombre del cupon es obligatorio';
  end if;

  if exists (
    select 1
    from public.cupones c
    where upper(c.codigo) = v_codigo
  ) then
    raise exception 'Ese codigo de cupon ya existe';
  end if;

  if exists (
    select 1
    from public._partner_codigos_reservados r
    where upper(r.codigo) = v_codigo
  ) then
    raise exception 'Ese codigo esta reservado y no puede usarse';
  end if;

  v_programa := public.resolver_programa_partner(v_ctx.partner_id);

  if p_porcentaje <= 0
     or p_porcentaje >
        (v_programa->>'cupon_max_porcentaje')::numeric
  then
    raise exception
      'El descuento debe ser mayor a 0 y no superar % %%',
      v_programa->>'cupon_max_porcentaje';
  end if;

  if p_plan_id is not null then
    select p.nombre
    into v_plan_nombre
    from public.planes_servicios p
    where p.id = p_plan_id
      and p.activo = true
      and p.tipo = 'plan';

    if v_plan_nombre is null then
      raise exception
        'El plan seleccionado no existe o no esta disponible';
    end if;
  end if;

  if p_vigencia_tipo not in ('siempre', 'periodo') then
    raise exception 'Tipo de vigencia invalido';
  end if;

  if p_vigencia_tipo = 'siempre' then
    v_desde := now();
    v_hasta := null;
  else
    if p_vigente_desde is null
       or p_vigente_hasta is null
    then
      raise exception
        'Indica fecha inicial y fecha final para la vigencia';
    end if;

    if p_vigente_hasta < p_vigente_desde then
      raise exception
        'La fecha final no puede ser anterior a la fecha inicial';
    end if;

    v_desde :=
      (
        p_vigente_desde::timestamp
        at time zone 'America/Mexico_City'
      );

    v_hasta :=
      (
        (
          (p_vigente_hasta + 1)::timestamp
          at time zone 'America/Mexico_City'
        )
        - interval '1 microsecond'
      );
  end if;

  insert into public.cupones (
    codigo,
    nombre,
    descripcion,
    tipo_beneficio,
    valor,
    moneda,
    vigente_desde,
    vigente_hasta,
    usos_maximos,
    un_uso_por_empresa,
    aplica_a,
    planes_aplicables,
    combinable,
    activo,
    created_by
  )
  values (
    v_codigo,
    trim(p_nombre),
    'Cupon creado por Partner',
    'porcentaje_descuento',
    p_porcentaje,
    null,
    v_desde,
    v_hasta,
    null,
    coalesce(p_un_uso_por_empresa, true),

    case
      when p_plan_id is null
        then 'todos'
      else 'planes_seleccionados'
    end,

    case
      when p_plan_id is null
        then null
      else array[p_plan_id]::uuid[]
    end,

    false,
    true,
    auth.uid()
  )
  returning id into v_cupon_id;

  insert into public.partner_cupones (
    partner_id,
    cupon_id
  )
  values (
    v_ctx.partner_id,
    v_cupon_id
  );

  return json_build_object(
    'id', v_cupon_id,
    'codigo', v_codigo,
    'porcentaje', p_porcentaje,
    'un_uso_por_empresa',
      coalesce(p_un_uso_por_empresa, true),
    'plan_id', p_plan_id,
    'plan_nombre', v_plan_nombre,
    'vigencia_tipo', p_vigencia_tipo,
    'vigente_desde', v_desde,
    'vigente_hasta', v_hasta
  );
end;
$_$;


--
-- Name: dashboard_costo_ventas(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_costo_ventas(p_empresa_id uuid, p_from date, p_to date, p_vendedor_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_costo numeric;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR p_empresa_id = public.get_my_empresa_id()) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  SELECT COALESCE(SUM(vl.cantidad * COALESCE(pr.costo, 0)), 0)
    INTO v_costo
  FROM public.venta_lineas vl
  JOIN public.ventas v ON v.id = vl.venta_id
  LEFT JOIN public.productos pr
    ON pr.id = vl.producto_id
   AND pr.empresa_id = p_empresa_id
   AND pr.status = 'activo'
  WHERE v.empresa_id = p_empresa_id
    AND v.es_saldo_inicial = false
    AND v.fecha >= p_from
    AND v.fecha <= p_to
    AND v.status <> 'cancelado'
    AND (p_vendedor_id IS NULL OR v.vendedor_id = p_vendedor_id);

  RETURN COALESCE(v_costo, 0);
END;
$$;


--
-- Name: dashboard_evolucion_mensual(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_evolucion_mensual(p_empresa_id uuid, p_from date, p_to date) RETURNS TABLE(tipo text, entidad_id uuid, nombre text, mes text, total numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH l AS (
    SELECT vl.producto_id, v.cliente_id, v.vendedor_id, to_char(v.fecha, 'YYYY-MM') AS mes, COALESCE(vl.total, 0) AS total
    FROM public.venta_lineas vl JOIN public.ventas v ON v.id = vl.venta_id
    WHERE vl.empresa_id = p_empresa_id AND v.empresa_id = p_empresa_id
      AND v.fecha >= p_from AND v.fecha <= p_to AND v.status::text <> 'cancelado')
  SELECT 'producto', l.producto_id, p.nombre, l.mes, SUM(l.total) FROM l LEFT JOIN public.productos p ON p.id = l.producto_id WHERE l.producto_id IS NOT NULL GROUP BY l.producto_id, p.nombre, l.mes
  UNION ALL SELECT 'cliente', l.cliente_id, c.nombre, l.mes, SUM(l.total) FROM l LEFT JOIN public.clientes c ON c.id = l.cliente_id WHERE l.cliente_id IS NOT NULL GROUP BY l.cliente_id, c.nombre, l.mes
  UNION ALL SELECT 'vendedor', l.vendedor_id, pr.nombre, l.mes, SUM(l.total) FROM l LEFT JOIN public.profiles pr ON pr.id = l.vendedor_id WHERE l.vendedor_id IS NOT NULL GROUP BY l.vendedor_id, pr.nombre, l.mes;
$$;


--
-- Name: dashboard_top_productos(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_top_productos(p_empresa_id uuid, p_from date, p_to date) RETURNS TABLE(id uuid, nombre text, codigo text, qty numeric, total numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT vl.producto_id, p.nombre::text, p.codigo::text,
         SUM(COALESCE(vl.cantidad, 0))::numeric, SUM(COALESCE(vl.total, 0))::numeric
  FROM public.venta_lineas vl
  JOIN public.ventas v ON v.id = vl.venta_id
  LEFT JOIN public.productos p ON p.id = vl.producto_id
  WHERE vl.empresa_id = p_empresa_id AND v.empresa_id = p_empresa_id
    AND v.fecha >= p_from AND v.fecha <= p_to
    AND v.status::text <> 'cancelado'
    AND vl.producto_id IS NOT NULL
  GROUP BY vl.producto_id, p.nombre, p.codigo
  ORDER BY 5 DESC;
$$;


--
-- Name: dashboard_ultima_compra_clientes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_ultima_compra_clientes(p_empresa_id uuid) RETURNS TABLE(cliente_id uuid, fecha date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT v.cliente_id, MAX(v.fecha)
  FROM public.ventas v
  WHERE v.empresa_id = p_empresa_id
    AND v.cliente_id IS NOT NULL
    AND v.status::text <> 'cancelado'
  GROUP BY v.cliente_id;
$$;


--
-- Name: deduct_timbre(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduct_timbre(p_empresa_id uuid, p_cfdi_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo_actual integer;
BEGIN
  -- Lock row for update
  SELECT saldo INTO v_saldo_actual
  FROM timbres_saldo
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  IF v_saldo_actual IS NULL OR v_saldo_actual < 1 THEN
    RETURN false;
  END IF;

  -- Deduct
  UPDATE timbres_saldo
  SET saldo = saldo - 1, updated_at = now()
  WHERE empresa_id = p_empresa_id;

  -- Log movement
  INSERT INTO timbres_movimientos (empresa_id, tipo, cantidad, saldo_anterior, saldo_nuevo, referencia_id, user_id, notas)
  VALUES (p_empresa_id, 'uso', -1, v_saldo_actual, v_saldo_actual - 1, p_cfdi_id, p_user_id, 'Timbre usado para CFDI');

  RETURN true;
END;
$$;


--
-- Name: delete_empresa_cascade(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_empresa_cascade(p_empresa_id uuid, p_deleted_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_owner_email text;
  v_owner_phone text;
  v_empresa_nombre text;
  v_user_ids uuid[];
BEGIN
  -- Get empresa info
  SELECT nombre INTO v_empresa_nombre FROM empresas WHERE id = p_empresa_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Empresa no encontrada'; END IF;

  -- Get all user_ids for this empresa
  SELECT array_agg(user_id) INTO v_user_ids FROM profiles WHERE empresa_id = p_empresa_id;

  -- Get owner info for blacklist
  SELECT u.email, u.phone INTO v_owner_email, v_owner_phone
  FROM auth.users u
  JOIN empresas e ON e.owner_user_id = u.id
  WHERE e.id = p_empresa_id;

  -- Add to blacklist
  IF v_owner_email IS NOT NULL THEN
    INSERT INTO trial_blacklist (email, telefono, empresa_nombre, bloqueado_por)
    VALUES (v_owner_email, v_owner_phone, v_empresa_nombre, p_deleted_by);
  END IF;

  -- Also blacklist all other users of this empresa
  INSERT INTO trial_blacklist (email, empresa_nombre, bloqueado_por)
  SELECT u.email, v_empresa_nombre, p_deleted_by
  FROM auth.users u
  JOIN profiles p ON p.user_id = u.id
  WHERE p.empresa_id = p_empresa_id
    AND u.id IS DISTINCT FROM (SELECT owner_user_id FROM empresas WHERE id = p_empresa_id)
    AND u.email IS NOT NULL;

  -- Delete all related data (order matters for FK constraints)
  DELETE FROM auditoria_escaneos WHERE auditoria_id IN (SELECT id FROM auditorias WHERE empresa_id = p_empresa_id);
  DELETE FROM auditoria_entradas WHERE auditoria_linea_id IN (SELECT id FROM auditoria_lineas WHERE auditoria_id IN (SELECT id FROM auditorias WHERE empresa_id = p_empresa_id));
  DELETE FROM auditoria_lineas WHERE auditoria_id IN (SELECT id FROM auditorias WHERE empresa_id = p_empresa_id);
  DELETE FROM auditorias WHERE empresa_id = p_empresa_id;

  DELETE FROM conteo_entradas WHERE conteo_linea_id IN (SELECT id FROM conteo_lineas WHERE conteo_id IN (SELECT id FROM conteos_fisicos WHERE empresa_id = p_empresa_id));
  DELETE FROM conteo_lineas WHERE conteo_id IN (SELECT id FROM conteos_fisicos WHERE empresa_id = p_empresa_id);
  DELETE FROM conteos_fisicos WHERE empresa_id = p_empresa_id;

  DELETE FROM cfdi_lineas WHERE cfdi_id IN (SELECT id FROM cfdis WHERE empresa_id = p_empresa_id);
  DELETE FROM cfdis WHERE empresa_id = p_empresa_id;

  DELETE FROM entrega_lineas WHERE entrega_id IN (SELECT id FROM entregas WHERE empresa_id = p_empresa_id);
  DELETE FROM entregas WHERE empresa_id = p_empresa_id;

  DELETE FROM descarga_ruta_lineas WHERE descarga_id IN (SELECT id FROM descarga_ruta WHERE empresa_id = p_empresa_id);
  DELETE FROM descarga_ruta WHERE empresa_id = p_empresa_id;

  DELETE FROM cobro_aplicaciones WHERE cobro_id IN (SELECT id FROM cobros WHERE empresa_id = p_empresa_id);
  DELETE FROM cobros WHERE empresa_id = p_empresa_id;

  DELETE FROM venta_lineas WHERE venta_id IN (SELECT id FROM ventas WHERE empresa_id = p_empresa_id);
  DELETE FROM carga_pedidos WHERE carga_id IN (SELECT id FROM cargas WHERE empresa_id = p_empresa_id);
  DELETE FROM ventas WHERE empresa_id = p_empresa_id;

  DELETE FROM devoluciones WHERE empresa_id = p_empresa_id;

  DELETE FROM carga_lineas WHERE carga_id IN (SELECT id FROM cargas WHERE empresa_id = p_empresa_id);
  DELETE FROM cargas WHERE empresa_id = p_empresa_id;

  DELETE FROM compra_lineas WHERE compra_id IN (SELECT id FROM compras WHERE empresa_id = p_empresa_id);
  DELETE FROM compras WHERE empresa_id = p_empresa_id;

  DELETE FROM traspaso_lineas WHERE traspaso_id IN (SELECT id FROM traspasos WHERE empresa_id = p_empresa_id);
  DELETE FROM traspasos WHERE empresa_id = p_empresa_id;

  DELETE FROM movimientos_inventario WHERE empresa_id = p_empresa_id;
  DELETE FROM stock_almacen WHERE empresa_id = p_empresa_id;
  DELETE FROM ajustes_inventario WHERE empresa_id = p_empresa_id;

  DELETE FROM cliente_pedido_sugerido WHERE cliente_id IN (SELECT id FROM clientes WHERE empresa_id = p_empresa_id);
  DELETE FROM visitas WHERE empresa_id = p_empresa_id;
  DELETE FROM clientes WHERE empresa_id = p_empresa_id;

  DELETE FROM producto_proveedores WHERE producto_id IN (SELECT id FROM productos WHERE empresa_id = p_empresa_id);
  DELETE FROM producto_precios WHERE producto_id IN (SELECT id FROM productos WHERE empresa_id = p_empresa_id);
  DELETE FROM productos WHERE empresa_id = p_empresa_id;

  DELETE FROM proveedores WHERE empresa_id = p_empresa_id;
  DELETE FROM clasificaciones WHERE empresa_id = p_empresa_id;
  DELETE FROM marcas WHERE empresa_id = p_empresa_id;
  DELETE FROM unidades WHERE empresa_id = p_empresa_id;
  DELETE FROM tasas_iva WHERE empresa_id = p_empresa_id;
  DELETE FROM tasas_ieps WHERE empresa_id = p_empresa_id;
  DELETE FROM tarifa_lineas WHERE tarifa_id IN (SELECT id FROM tarifas WHERE empresa_id = p_empresa_id);
  DELETE FROM tarifas WHERE empresa_id = p_empresa_id;
  DELETE FROM lista_precios WHERE empresa_id = p_empresa_id;
  DELETE FROM listas WHERE empresa_id = p_empresa_id;
  DELETE FROM zonas WHERE empresa_id = p_empresa_id;
  DELETE FROM cobradores WHERE empresa_id = p_empresa_id;
  DELETE FROM vendedores WHERE empresa_id = p_empresa_id;
  DELETE FROM almacenes WHERE empresa_id = p_empresa_id;
  DELETE FROM gastos WHERE empresa_id = p_empresa_id;
  DELETE FROM promociones WHERE empresa_id = p_empresa_id;

  DELETE FROM timbres_movimientos WHERE empresa_id = p_empresa_id;
  DELETE FROM timbres_saldo WHERE empresa_id = p_empresa_id;
  DELETE FROM facturas WHERE empresa_id = p_empresa_id;
  DELETE FROM emisor_fiscal WHERE empresa_id = p_empresa_id;

  DELETE FROM cancellation_requests WHERE empresa_id = p_empresa_id;
  DELETE FROM subscriptions WHERE empresa_id = p_empresa_id;

  DELETE FROM role_permisos WHERE role_id IN (SELECT id FROM roles WHERE empresa_id = p_empresa_id);
  DELETE FROM user_roles WHERE role_id IN (SELECT id FROM roles WHERE empresa_id = p_empresa_id);
  DELETE FROM roles WHERE empresa_id = p_empresa_id;

  -- Delete profiles
  DELETE FROM profiles WHERE empresa_id = p_empresa_id;

  -- Delete empresa
  DELETE FROM empresas WHERE id = p_empresa_id;

  -- Delete auth users (last, after all FK references are gone)
  IF v_user_ids IS NOT NULL THEN
    FOR i IN 1..array_length(v_user_ids, 1) LOOP
      -- Only delete if user has no other empresa profile
      IF NOT EXISTS (SELECT 1 FROM profiles WHERE user_id = v_user_ids[i]) THEN
        DELETE FROM auth.users WHERE id = v_user_ids[i];
      END IF;
    END LOOP;
  END IF;
END;
$$;


--
-- Name: delete_empresas_bulk(uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_empresas_bulk(p_empresa_ids uuid[], p_deleted_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_ok int := 0;
  v_err int := 0;
  v_errors jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de super administrador';
  END IF;

  FOREACH v_id IN ARRAY p_empresa_ids LOOP
    BEGIN
      PERFORM public.delete_empresa_cascade(v_id, p_deleted_by);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1;
      v_errors := v_errors || jsonb_build_object('empresa_id', v_id, 'error', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object('eliminadas', v_ok, 'fallidas', v_err, 'errores', v_errors);
END;
$$;


--
-- Name: desactivar_cupones_partner_fuera_limite(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desactivar_cupones_partner_fuera_limite(_partner_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.cupones
  SET activo = false
  WHERE partner_id = _partner_id
    AND activo = true
    AND descuento_pct > public.get_partner_coupon_cap(_partner_id);

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN v_count;
END;
$$;


--
-- Name: editar_venta(uuid, jsonb, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.editar_venta(p_venta_id uuid, p_lineas jsonb, p_version timestamp with time zone DEFAULT NULL::timestamp with time zone, p_header jsonb DEFAULT NULL::jsonb, p_promos jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid     uuid := auth.uid();
  v_venta   public.ventas%ROWTYPE;
  v_cols    text[];
  v_pcols   text[];
  v_hcols   text[] := ARRAY['notas','descuento_extra','descuento_extra_tipo'];
  v_keep    uuid[];
  v_line    jsonb;
  v_id      uuid;
  v_keys    text;
  v_old     record;
  v_pagado  numeric;
  v_conlote uuid[] := '{}';
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sesión requerida' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venta no encontrada' USING ERRCODE = 'P0002';
  END IF;

  IF v_venta.empresa_id IS DISTINCT FROM public.get_my_empresa_id() AND NOT public.is_super_admin(v_uid) THEN
    RAISE EXCEPTION 'Sin acceso a esta venta' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_super_admin(v_uid)
     AND NOT EXISTS (SELECT 1 FROM public.empresas e WHERE e.id = v_venta.empresa_id AND e.owner_user_id = v_uid)
     AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = v_uid)
     AND NOT EXISTS (
       SELECT 1 FROM public.user_roles ur
       JOIN public.role_permisos rp ON rp.role_id = ur.role_id
       WHERE ur.user_id = v_uid AND rp.modulo = 'ventas' AND rp.accion = 'editar' AND rp.permitido)
  THEN
    RAISE EXCEPTION 'No tienes permiso para editar ventas' USING ERRCODE = '42501';
  END IF;

  IF v_venta.status::text IN ('cancelado','facturado') THEN
    RAISE EXCEPTION 'No se puede editar una venta %.',
      CASE v_venta.status::text WHEN 'cancelado' THEN 'cancelada' ELSE 'facturada' END USING ERRCODE = 'P0001';
  END IF;
  IF v_venta.cerrado_at IS NOT NULL THEN
    RAISE EXCEPTION 'No se puede editar un pedido cerrado como parcial.' USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.venta_lineas
             WHERE venta_id = p_venta_id AND (COALESCE(facturado,false) OR factura_cfdi_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'La venta tiene productos facturados: corrígela con nota de crédito.' USING ERRCODE = 'P0001';
  END IF;
  IF v_venta.tipo::text = 'pedido' AND EXISTS (SELECT 1 FROM public.entregas WHERE pedido_id = p_venta_id) THEN
    RAISE EXCEPTION 'El pedido ya tiene entregas: corrígelo desde la entrega.' USING ERRCODE = 'P0001';
  END IF;
  IF p_version IS NOT NULL AND v_venta.updated_at IS DISTINCT FROM p_version THEN
    RAISE EXCEPTION 'La venta cambió en otro dispositivo. Vuelve a abrirla para editarla.' USING ERRCODE = '40001';
  END IF;
  IF p_lineas IS NULL OR jsonb_typeof(p_lineas) <> 'array' OR jsonb_array_length(p_lineas) = 0 THEN
    RAISE EXCEPTION 'La venta debe tener al menos un producto.' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(column_name::text) INTO v_cols
  FROM information_schema.columns
  WHERE table_schema = 'public' AND table_name = 'venta_lineas'
    AND column_name NOT IN ('id','venta_id','empresa_id','created_at','updated_at',
                            'facturado','factura_cfdi_id','comision_pct','comision_monto');

  SELECT COALESCE(array_agg(NULLIF(x->>'id','')::uuid), '{}') INTO v_keep
  FROM jsonb_array_elements(p_lineas) x WHERE NULLIF(x->>'id','') IS NOT NULL;

  FOR v_old IN SELECT id FROM public.venta_lineas WHERE venta_id = p_venta_id AND NOT (id = ANY(v_keep)) LOOP
    IF EXISTS (SELECT 1 FROM public.venta_comisiones c
               WHERE c.venta_linea_id = v_old.id AND (c.pagada OR c.pago_comision_id IS NOT NULL)) THEN
      RAISE EXCEPTION 'No se puede quitar un producto cuya comisión ya se pagó.' USING ERRCODE = 'P0001';
    END IF;
    DELETE FROM public.venta_linea_lotes WHERE venta_linea_id = v_old.id;
    DELETE FROM public.promocion_aplicada WHERE venta_linea_id = v_old.id;
    DELETE FROM public.venta_lineas WHERE id = v_old.id;
  END LOOP;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lineas) LOOP
    v_id := NULLIF(v_line->>'id','')::uuid;
    SELECT string_agg(quote_ident(k), ', ') INTO v_keys
    FROM jsonb_object_keys(v_line) k WHERE k = ANY(v_cols);

    IF v_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.venta_lineas WHERE id = v_id) THEN
      IF NOT EXISTS (SELECT 1 FROM public.venta_lineas WHERE id = v_id AND venta_id = p_venta_id) THEN
        RAISE EXCEPTION 'Un renglón no pertenece a esta venta.' USING ERRCODE = '22023';
      END IF;
      IF v_keys IS NOT NULL THEN
        EXECUTE format('UPDATE public.venta_lineas t SET (%1$s) = (SELECT %1$s FROM jsonb_populate_record(NULL::public.venta_lineas, $1)) WHERE t.id = $2', v_keys)
          USING v_line, v_id;
      END IF;
    ELSE
      IF v_keys IS NULL OR NOT (v_line ? 'producto_id') THEN
        RAISE EXCEPTION 'Renglón nuevo sin producto.' USING ERRCODE = '22023';
      END IF;
      v_id := COALESCE(v_id, gen_random_uuid());
      EXECUTE format('INSERT INTO public.venta_lineas (id, venta_id, %1$s) SELECT $2, $3, %1$s FROM jsonb_populate_record(NULL::public.venta_lineas, $1)', v_keys)
        USING v_line, v_id, p_venta_id;
    END IF;

    IF v_line ? 'lotes' THEN
      v_conlote := v_conlote || v_id;
      DELETE FROM public.venta_linea_lotes WHERE venta_linea_id = v_id;
      INSERT INTO public.venta_linea_lotes (empresa_id, venta_id, venta_linea_id, producto_id, lote_id, almacen_id, cantidad, user_id)
      SELECT v_venta.empresa_id, p_venta_id, v_id, vl.producto_id, (lt->>'lote_id')::uuid,
             COALESCE(vl.almacen_id, v_venta.almacen_id), (lt->>'cantidad')::numeric, v_uid
      FROM jsonb_array_elements(COALESCE(v_line->'lotes','[]'::jsonb)) lt
      JOIN public.venta_lineas vl ON vl.id = v_id
      WHERE NULLIF(lt->>'lote_id','') IS NOT NULL AND COALESCE((lt->>'cantidad')::numeric, 0) > 0;
    END IF;
  END LOOP;

  FOR v_old IN
    SELECT vl.id, vl.cantidad, SUM(d.cantidad) AS repartido
    FROM public.venta_lineas vl JOIN public.venta_linea_lotes d ON d.venta_linea_id = vl.id
    WHERE vl.venta_id = p_venta_id
    GROUP BY vl.id, vl.cantidad
    HAVING abs(COALESCE(vl.cantidad,0) - SUM(d.cantidad)) > 0.000001
  LOOP
    IF v_old.id = ANY(v_conlote) THEN
      RAISE EXCEPTION 'El reparto por lotes (%) no cuadra con la cantidad del producto (%).', v_old.repartido, v_old.cantidad USING ERRCODE = '22023';
    END IF;
    DELETE FROM public.venta_linea_lotes WHERE venta_linea_id = v_old.id;
  END LOOP;

  SELECT string_agg(quote_ident(k), ', ') INTO v_keys
  FROM jsonb_object_keys(COALESCE(p_header,'{}'::jsonb)) k WHERE k = ANY(v_hcols);
  IF v_keys IS NOT NULL THEN
    EXECUTE format('UPDATE public.ventas t SET (%1$s) = (SELECT %1$s FROM jsonb_populate_record(NULL::public.ventas, $1)) WHERE t.id = $2', v_keys)
      USING p_header, p_venta_id;
  END IF;

  IF p_promos IS NOT NULL THEN
    SELECT array_agg(column_name::text) INTO v_pcols
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'promocion_aplicada'
      AND column_name NOT IN ('id','venta_id','created_at');
    DELETE FROM public.promocion_aplicada WHERE venta_id = p_venta_id;
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_promos) LOOP
      SELECT string_agg(quote_ident(k), ', ') INTO v_keys
      FROM jsonb_object_keys(v_line) k WHERE k = ANY(v_pcols);
      IF v_keys IS NOT NULL THEN
        EXECUTE format('INSERT INTO public.promocion_aplicada (venta_id, %1$s) SELECT $2, %1$s FROM jsonb_populate_record(NULL::public.promocion_aplicada, $1)', v_keys)
          USING v_line, p_venta_id;
      END IF;
    END LOOP;
  END IF;

  SET CONSTRAINTS ALL IMMEDIATE;

  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id;
  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_pagado
  FROM public.cobro_aplicaciones ca JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = p_venta_id AND COALESCE(c.status,'activo') <> 'cancelado';
  IF v_pagado > COALESCE(v_venta.total, 0) + 0.009 THEN
    RAISE EXCEPTION 'El nuevo total (%) queda abajo de lo ya pagado (%). Primero ajusta el pago.',
      round(COALESCE(v_venta.total,0), 2), round(v_pagado, 2) USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'total', v_venta.total,
    'saldo_pendiente', v_venta.saldo_pendiente,
    'updated_at', v_venta.updated_at
  );
END;
$_$;


--
-- Name: enforce_single_lista_principal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_lista_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.es_principal = true THEN
    UPDATE public.lista_precios
       SET es_principal = false
     WHERE empresa_id = NEW.empresa_id
       AND id <> NEW.id
       AND es_principal = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ensure_almacen_mermas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_almacen_mermas(_empresa_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _id uuid;
BEGIN
  SELECT id INTO _id FROM public.almacenes WHERE empresa_id = _empresa_id AND es_merma = true LIMIT 1;
  IF _id IS NULL THEN
    INSERT INTO public.almacenes(empresa_id, nombre, tipo, es_merma, activo)
    VALUES (_empresa_id, 'Mermas', 'almacen', true, true) RETURNING id INTO _id;
  END IF;
  RETURN _id;
END; $$;


--
-- Name: ensure_cliente_publico_general(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_cliente_publico_general(p_empresa_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente_id uuid;
BEGIN
  IF p_empresa_id IS NULL THEN
    RAISE EXCEPTION 'La empresa es obligatoria';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role'
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para administrar Público general en esta empresa';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('publico-general:' || p_empresa_id::text, 0));

  INSERT INTO public.clientes (
    empresa_id,
    nombre,
    status,
    credito,
    es_publico_general
  ) VALUES (
    p_empresa_id,
    'Público general',
    'activo',
    false,
    true
  )
  ON CONFLICT (empresa_id) WHERE es_publico_general
  DO UPDATE SET
    nombre = 'Público general',
    status = 'activo'
  RETURNING id INTO v_cliente_id;

  RETURN v_cliente_id;
END;
$$;


--
-- Name: ensure_empresa_admin_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_empresa_admin_role(p_empresa_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role_id uuid;
  v_owner uuid;
  v_modulo text;
  v_accion text;
  v_modulos text[] := ARRAY[
    'dashboard','supervisor',
    'ventas','ventas.cobranza','ventas.promociones','pos',
    'clientes',
    'logistica.dashboard','logistica.pedidos','logistica.entregas','logistica.descargas','logistica.monitor','logistica.rutas','logistica.mapa_clientes','logistica.mapa_ventas',
    'catalogo.productos','catalogo.tarifas','catalogo.clasificaciones','catalogo.marcas','catalogo.proveedores','catalogo.unidades','catalogo.tasas_iva','catalogo.tasas_ieps',
    'almacen.inventario','almacen.traspasos','almacen.ajustes','almacen.auditorias','almacen.compras','almacen.lotes','almacen.almacenes',
    'finanzas.por_cobrar','finanzas.por_pagar','finanzas.gastos','finanzas.comisiones',
    'reportes.generales','reportes.entregas',
    'facturacion.cfdi','facturacion.catalogos',
    'configuracion.general','configuracion.usuarios','configuracion.whatsapp','configuracion.suscripcion'
  ];
  v_acciones text[] := ARRAY['ver','crear','editar','eliminar'];
BEGIN
  SELECT id INTO v_role_id FROM public.roles
  WHERE empresa_id = p_empresa_id AND nombre = 'Administrador' LIMIT 1;

  IF v_role_id IS NULL THEN
    INSERT INTO public.roles (empresa_id, nombre, descripcion, es_sistema, acceso_ruta_movil)
    VALUES (p_empresa_id, 'Administrador', 'Acceso total al sistema', true, true)
    RETURNING id INTO v_role_id;

    FOREACH v_modulo IN ARRAY v_modulos LOOP
      FOREACH v_accion IN ARRAY v_acciones LOOP
        INSERT INTO public.role_permisos (role_id, modulo, accion, permitido)
        VALUES (v_role_id, v_modulo, v_accion, true)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END LOOP;
  END IF;

  SELECT owner_user_id INTO v_owner FROM public.empresas WHERE id = p_empresa_id;
  IF v_owner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_owner) THEN
    INSERT INTO public.user_roles (user_id, role_id) VALUES (v_owner, v_role_id)
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN v_role_id;
END;
$$;


--
-- Name: ensure_entrega_completion_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_entrega_completion_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'hecho'::public.status_entrega THEN
    IF TG_OP = 'INSERT' AND NEW.fecha_entrega IS NULL THEN
      NEW.fecha_entrega := now();
    ELSIF TG_OP = 'UPDATE'
      AND OLD.status IS DISTINCT FROM 'hecho'::public.status_entrega
      AND (NEW.fecha_entrega IS NULL OR NEW.fecha_entrega IS NOT DISTINCT FROM OLD.fecha_entrega)
    THEN
      NEW.fecha_entrega := now();
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: ensure_lista_precios_principal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_lista_precios_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ya_existe_principal boolean;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.lista_precios WHERE tarifa_id = NEW.id) THEN
    SELECT EXISTS(
      SELECT 1 FROM public.lista_precios
      WHERE empresa_id = NEW.empresa_id AND es_principal = true
    ) INTO v_ya_existe_principal;

    INSERT INTO public.lista_precios (tarifa_id, empresa_id, nombre, es_principal, activa)
    VALUES (NEW.id, NEW.empresa_id, NEW.nombre, NOT v_ya_existe_principal, true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enviar_solicitud_traspaso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enviar_solicitud_traspaso(p_solicitud_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sol public.solicitudes_traspaso%ROWTYPE;
  v_lineas int;
BEGIN
  SELECT * INTO v_sol
    FROM public.solicitudes_traspaso
   WHERE id = p_solicitud_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF NOT (
    v_sol.empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF v_sol.status <> 'borrador' THEN
    RAISE EXCEPTION 'Solo se puede enviar una solicitud en borrador';
  END IF;

  SELECT COUNT(*) INTO v_lineas
    FROM public.solicitud_traspaso_lineas
   WHERE solicitud_id = p_solicitud_id
     AND excluida = false
     AND cantidad_solicitada > 0;

  IF v_lineas = 0 THEN
    RAISE EXCEPTION 'Agrega al menos un producto con cantidad mayor a cero';
  END IF;

  IF v_sol.almacen_destino_id IS NULL
     OR v_sol.almacen_origen_id IS NULL THEN
    RAISE EXCEPTION 'Define el almacén origen y destino';
  END IF;

  -- Única precarga automática.
  UPDATE public.solicitud_traspaso_lineas
     SET cantidad_aprobada = cantidad_solicitada
   WHERE solicitud_id = p_solicitud_id
     AND excluida = false;

  UPDATE public.solicitudes_traspaso
     SET status = 'solicitada',
         enviado_at = now()
   WHERE id = p_solicitud_id;

  PERFORM public.fn_log_solicitud_traspaso(
    p_solicitud_id,
    v_sol.empresa_id,
    'enviada',
    NULL
  );
END;
$$;


--
-- Name: fill_venta_linea_desglose(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_venta_linea_desglose() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cant numeric := COALESCE(NEW.cantidad, 0);
  v_sub  numeric := COALESCE(NEW.subtotal, 0);
  v_iva  numeric := COALESCE(NEW.iva_monto, 0);
  v_ieps numeric := COALESCE(NEW.ieps_monto, 0);
  v_lista numeric;
  v_desc_man numeric;
BEGIN
  -- Solo completa campos informativos vacíos. Nunca toca dinero, totales ni saldos.
  IF NEW.precio_lista_unitario IS NULL THEN
    NEW.precio_lista_unitario := COALESCE(NEW.precio_unitario_sin_redondeo, NEW.precio_unitario);
  END IF;
  v_lista := COALESCE(NEW.precio_lista_unitario, NEW.precio_unitario, 0);

  IF NEW.descuento_promocion_monto IS NULL THEN
    NEW.descuento_promocion_monto := 0;
  END IF;

  IF NEW.importe_bruto IS NULL THEN
    NEW.importe_bruto := ROUND(v_lista * v_cant, 2);
  END IF;

  IF NEW.descuento_manual_monto IS NULL THEN
    v_desc_man := GREATEST(
      ROUND(COALESCE(NEW.importe_bruto, 0) - v_sub - COALESCE(NEW.descuento_promocion_monto, 0), 2),
      0
    );
    NEW.descuento_manual_monto := v_desc_man;
  END IF;

  IF NEW.base_descuento_manual IS NULL THEN
    NEW.base_descuento_manual := ROUND(COALESCE(NEW.importe_bruto, 0) - COALESCE(NEW.descuento_promocion_monto, 0), 2);
  END IF;

  IF NEW.descuento_total_monto IS NULL THEN
    NEW.descuento_total_monto := ROUND(COALESCE(NEW.descuento_promocion_monto, 0) + COALESCE(NEW.descuento_manual_monto, 0), 2);
  END IF;

  IF NEW.base_ieps IS NULL THEN
    NEW.base_ieps := v_sub;
  END IF;

  IF NEW.base_iva IS NULL THEN
    NEW.base_iva := ROUND(v_sub + v_ieps, 2);
  END IF;

  IF NEW.impuestos_totales IS NULL THEN
    NEW.impuestos_totales := ROUND(v_iva + v_ieps, 2);
  END IF;

  IF NEW.descuento_manual IS NULL THEN
    NEW.descuento_manual := COALESCE(NEW.descuento_manual_monto, 0) > 0;
  END IF;

  IF NEW.cantidad_bonificada IS NULL THEN
    NEW.cantidad_bonificada := 0;
  END IF;

  IF NEW.es_bonificacion IS NULL THEN
    NEW.es_bonificacion := (v_sub = 0 AND v_cant > 0);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_admin_crm_call_pitch_catalog_get(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_crm_call_pitch_catalog_get() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_value jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.super_admins sa
    where sa.user_id = auth.uid()
  ) then
    raise exception 'Super admin required';
  end if;

  select config
    into v_value
  from public.internal_crm_call_pitch_config
  where id = 'default';

  return coalesce(v_value, '{}'::jsonb);
end;
$$;


--
-- Name: fn_admin_crm_call_pitch_catalog_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_crm_call_pitch_catalog_save(p_catalog jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_saved jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.super_admins sa
    where sa.user_id = auth.uid()
  ) then
    raise exception 'Super admin required';
  end if;

  if p_catalog is null
     or jsonb_typeof(p_catalog) <> 'object'
     or jsonb_typeof(p_catalog -> 'pitches') <> 'array'
     or jsonb_array_length(p_catalog -> 'pitches') = 0
  then
    raise exception 'Invalid pitch catalog';
  end if;

  if coalesce(p_catalog ->> 'active_pitch_id', '') = '' then
    raise exception 'Active pitch required';
  end if;

  insert into public.internal_crm_call_pitch_config (
    id,
    config,
    updated_at,
    updated_by
  )
  values (
    'default',
    p_catalog,
    now(),
    auth.uid()
  )
  on conflict (id) do update
    set config = excluded.config,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by
  returning config into v_saved;

  return v_saved;
end;
$$;


--
-- Name: fn_admin_crm_call_pitch_save(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_crm_call_pitch_save(p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current jsonb;
  v_active text;
  v_new_pitches jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.super_admins sa
    where sa.user_id = auth.uid()
  ) then
    raise exception 'Super admin required';
  end if;

  if p_config is null
     or jsonb_typeof(p_config) <> 'object'
     or jsonb_typeof(p_config -> 'steps') <> 'array'
     or jsonb_array_length(p_config -> 'steps') = 0
  then
    raise exception 'Invalid pitch configuration';
  end if;

  select config
    into v_current
  from public.internal_crm_call_pitch_config
  where id = 'default';

  if jsonb_typeof(v_current -> 'pitches') = 'array' then

    v_active := v_current ->> 'active_pitch_id';

    select jsonb_agg(
      case
        when item ->> 'id' = v_active
          then jsonb_set(item, '{config}', p_config, true)
        else item
      end
    )
    into v_new_pitches
    from jsonb_array_elements(v_current -> 'pitches') item;

    v_current := jsonb_set(
      v_current,
      '{pitches}',
      coalesce(v_new_pitches, '[]'::jsonb),
      true
    );

    update public.internal_crm_call_pitch_config
    set
      config = v_current,
      updated_at = now(),
      updated_by = auth.uid()
    where id = 'default';

  else

    update public.internal_crm_call_pitch_config
    set
      config = p_config,
      updated_at = now(),
      updated_by = auth.uid()
    where id = 'default';

  end if;

  return p_config;
end;
$$;


--
-- Name: FUNCTION fn_admin_crm_call_pitch_save(p_config jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_admin_crm_call_pitch_save(p_config jsonb) IS 'Guarda la configuración del pitch; solo puede ejecutarla un super admin.';


--
-- Name: fn_admin_team_workspace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_team_workspace() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION
      'Acceso denegado'
      USING ERRCODE = '42501';
  END IF;

  WITH latest_subscription AS MATERIALIZED (
    SELECT DISTINCT ON (s.empresa_id)
      s.empresa_id,
      s.status,
      s.stripe_subscription_id
    FROM public.subscriptions s
    ORDER BY
      s.empresa_id,
      s.updated_at DESC,
      s.created_at DESC
  ),
  member_rows AS MATERIALIZED (
    SELECT
      cp.id,
      cp.name,
      cp.email,
      cp.phone,
      cp.manager_id,
      cp.is_active,
      cp.notes,
      tm.user_id,
      tm.job_title,
      tm.access_level,
      tm.access_scope,
      tm.status,
      tm.commission_mode,
      tm.commission_pct,
      tm.commission_payment_limit,
      tm.commission_fixed_amount,
      tm.permissions,
      tm.invited_at,
      tm.last_access_at,
      manager.name AS manager_name,
      (
        SELECT count(*)
        FROM public.commission_people report
        WHERE report.manager_id = cp.id
          AND report.is_active = true
      ) AS reports_count,
      (
        SELECT count(*)
        FROM public.admin_trial_crm_leads lead
        WHERE lead.assigned_to = cp.id
          AND lead.stage NOT IN (
            'no_interesado',
            'descartado',
            'convertido'
          )
      ) AS crm_leads,
      (
        SELECT count(*)
        FROM public.commission_client_attributions cca
        WHERE cca.managed_by_id = cp.id
      ) AS managed_companies,
      (
        SELECT count(*)
        FROM public.commission_client_attributions cca
        WHERE cca.commissioned_by_id = cp.id
      ) AS commissioned_companies,
      (
        SELECT count(*)
        FROM public.admin_trial_crm_activities act
        WHERE act.created_by = tm.user_id
          AND act.created_at >= now() - interval '30 days'
      ) AS activities_30d,
      COALESCE((
        SELECT sum(ice.commission_amount)
        FROM public.internal_commission_entries ice
        WHERE ice.person_id = cp.id
          AND ice.status IN ('pending', 'approved')
      ), 0) AS commission_pending,
      COALESCE((
        SELECT sum(ice.commission_amount)
        FROM public.internal_commission_entries ice
        WHERE ice.person_id = cp.id
          AND ice.status = 'paid'
      ), 0) AS commission_paid
    FROM public.commission_people cp
    JOIN public.platform_team_members tm
      ON tm.person_id = cp.id
    LEFT JOIN public.commission_people manager
      ON manager.id = cp.manager_id
    WHERE cp.person_type = 'internal'
  ),
  company_rows AS MATERIALIZED (
    SELECT
      e.id,
      e.nombre,
      e.licencia,
      e.email,
      e.telefono,
      e.created_at,
      cca.captured_by_id,
      cca.managed_by_id,
      cca.commissioned_by_id,
      cca.commission_starts_at,
      captured.name AS captured_by_name,
      managed.name AS managed_by_name,
      commissioned.name AS commissioned_by_name,
      (pa.id IS NOT NULL) AS has_partner,
      ls.status AS subscription_status,
      ls.stripe_subscription_id,
      COALESCE((
        SELECT sum(f.total)
        FROM public.facturas f
        WHERE f.empresa_id = e.id
          AND f.estado = 'pagada'
      ), 0) AS paid_total
    FROM public.empresas e
    LEFT JOIN public.commission_client_attributions cca
      ON cca.empresa_id = e.id
    LEFT JOIN public.commission_people captured
      ON captured.id = cca.captured_by_id
    LEFT JOIN public.commission_people managed
      ON managed.id = cca.managed_by_id
    LEFT JOIN public.commission_people commissioned
      ON commissioned.id = cca.commissioned_by_id
    LEFT JOIN public.partner_atribuciones pa
      ON pa.empresa_id = e.id
    LEFT JOIN latest_subscription ls
      ON ls.empresa_id = e.id
    WHERE COALESCE(e.is_partner_sandbox, false) = false
  )

  SELECT jsonb_build_object(
    'generated_at', now(),
    'metrics', jsonb_build_object(
      'active_members', (
        SELECT count(*)
        FROM member_rows
        WHERE status = 'active'
          AND is_active = true
      ),
      'invited_members', (
        SELECT count(*)
        FROM member_rows
        WHERE status = 'invited'
      ),
      'crm_leads', (
        SELECT COALESCE(sum(crm_leads), 0)
        FROM member_rows
      ),
      'managed_companies', (
        SELECT count(*)
        FROM company_rows
        WHERE managed_by_id IS NOT NULL
      ),
      'unassigned_companies', (
        SELECT count(*)
        FROM company_rows
        WHERE managed_by_id IS NULL
      ),
      'commission_pending', (
        SELECT COALESCE(sum(commission_amount), 0)
        FROM public.internal_commission_entries
        WHERE status IN ('pending', 'approved')
      ),
      'commission_paid', (
        SELECT COALESCE(sum(commission_amount), 0)
        FROM public.internal_commission_entries
        WHERE status = 'paid'
      )
    ),
    'members',
    COALESCE((
      SELECT jsonb_agg(
        to_jsonb(m)
        ORDER BY m.is_active DESC, m.name
      )
      FROM member_rows m
    ), '[]'::jsonb),
    'companies',
    COALESCE((
      SELECT jsonb_agg(
        to_jsonb(c)
        ORDER BY c.nombre
      )
      FROM company_rows c
    ), '[]'::jsonb),
    'commissions',
    COALESCE((
      SELECT jsonb_agg(
        to_jsonb(x)
        ORDER BY x.created_at DESC
      )
      FROM (
        SELECT
          ice.*,
          cp.name AS person_name,
          e.nombre AS empresa_nombre
        FROM public.internal_commission_entries ice
        JOIN public.commission_people cp
          ON cp.id = ice.person_id
        JOIN public.empresas e
          ON e.id = ice.empresa_id
        ORDER BY ice.created_at DESC
        LIMIT 1000
      ) x
    ), '[]'::jsonb),
    'activities',
    COALESCE((
      SELECT jsonb_agg(
        to_jsonb(x)
        ORDER BY x.created_at DESC
      )
      FROM (
        SELECT
          a.id,
          a.empresa_id,
          e.nombre AS empresa_nombre,
          a.activity_type,
          a.outcome,
          a.note,
          a.new_stage,
          a.created_at,
          cp.id AS person_id,
          cp.name AS person_name
        FROM public.admin_trial_crm_activities a
        JOIN public.empresas e
          ON e.id = a.empresa_id
        LEFT JOIN public.platform_team_members tm
          ON tm.user_id = a.created_by
        LEFT JOIN public.commission_people cp
          ON cp.id = tm.person_id
        WHERE tm.person_id IS NOT NULL
        ORDER BY a.created_at DESC
        LIMIT 500
      ) x
    ), '[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_admin_trial_crm_create_offer(uuid, numeric, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_create_offer(p_empresa_id uuid, p_discount_pct numeric DEFAULT 20, p_months integer DEFAULT 2, p_valid_days integer DEFAULT 7, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_company public.empresas%ROWTYPE;
  v_coupon_id uuid;
  v_code text;
  v_previous_coupon uuid;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF p_discount_pct < 1 OR p_discount_pct > 50 THEN
    RAISE EXCEPTION 'El descuento de recuperación debe estar entre 1 y 50%%';
  END IF;
  IF p_months < 1 OR p_months > 12 OR p_valid_days < 1 OR p_valid_days > 90 THEN
    RAISE EXCEPTION 'Duración de oferta inválida';
  END IF;

  SELECT * INTO v_company FROM public.empresas WHERE id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Empresa no encontrada'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.ventas v WHERE v.empresa_id = p_empresa_id
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('borrador', 'cancelado')
  ) THEN
    RAISE EXCEPTION 'La empresa ya tiene ventas operativas; no corresponde una oferta de recuperación';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.facturas f
    WHERE f.empresa_id = p_empresa_id
      AND lower(COALESCE(f.estado, '')) = 'pagada'
  ) THEN
    RAISE EXCEPTION 'La empresa ya tiene facturas pagadas; no corresponde una oferta de recuperación';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.subscriptions s
    WHERE s.empresa_id = p_empresa_id
      AND (
        NULLIF(btrim(s.stripe_subscription_id), '') IS NOT NULL
        OR s.status::text IN ('active', 'past_due', 'pendiente_pago')
      )
  ) THEN
    RAISE EXCEPTION 'La empresa ya tiene una suscripción Stripe activa o pendiente';
  END IF;

  SELECT coupon_id INTO v_previous_coupon
  FROM public.admin_trial_crm_leads WHERE empresa_id = p_empresa_id FOR UPDATE;
  IF v_previous_coupon IS NOT NULL THEN
    UPDATE public.cupones SET activo = false WHERE id = v_previous_coupon;
  END IF;

  v_code := 'REC-' || upper(COALESCE(NULLIF(v_company.licencia, ''), substr(replace(v_company.id::text, '-', ''), 1, 8)))
    || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  INSERT INTO public.cupones (
    codigo, descripcion, descuento_pct, planes_aplicables, uso_maximo,
    uso_por_empresa, usos_actuales, meses_duracion, acumulable, activo,
    vigencia_inicio, vigencia_fin
  ) VALUES (
    v_code,
    'Oferta CRM para recuperar a ' || v_company.nombre || COALESCE(' · ' || NULLIF(btrim(p_note), ''), ''),
    p_discount_pct, '{}'::text[], 1, 1, 1, p_months, false, true,
    current_date, current_date + p_valid_days
  ) RETURNING id INTO v_coupon_id;

  INSERT INTO public.cupon_usos (cupon_id, empresa_id, meses_restantes)
  VALUES (v_coupon_id, p_empresa_id, p_months);

  INSERT INTO public.admin_trial_crm_leads (
    empresa_id, stage, coupon_id, coupon_assigned_at, notes, created_by, updated_by
  ) VALUES (
    p_empresa_id, 'interesado', v_coupon_id, now(), NULLIF(btrim(p_note), ''), auth.uid(), auth.uid()
  )
  ON CONFLICT (empresa_id) DO UPDATE SET
    stage = CASE WHEN admin_trial_crm_leads.stage IN ('sin_contactar', 'por_contactar', 'contactado', 'no_localizado') THEN 'interesado' ELSE admin_trial_crm_leads.stage END,
    coupon_id = EXCLUDED.coupon_id,
    coupon_assigned_at = now(),
    notes = COALESCE(EXCLUDED.notes, admin_trial_crm_leads.notes),
    updated_by = auth.uid();

  INSERT INTO public.admin_trial_crm_activities (
    empresa_id, activity_type, outcome, note, new_stage, created_by
  ) VALUES (
    p_empresa_id, 'coupon', v_code,
    format('Oferta de %s%% por %s mes(es), vigente %s días. %s', p_discount_pct, p_months, p_valid_days, COALESCE(p_note, '')),
    'interesado', auth.uid()
  );

  RETURN jsonb_build_object(
    'ok', true, 'coupon_id', v_coupon_id, 'code', v_code,
    'discount_pct', p_discount_pct, 'months', p_months,
    'expires_at', current_date + p_valid_days
  );
END;
$$;


--
-- Name: fn_admin_trial_crm_delete_candidate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_delete_candidate(p_empresa_id uuid, p_confirmation text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_company public.empresas%ROWTYPE;
  v_lead public.admin_trial_crm_leads%ROWTYPE;
  v_age integer;
  v_expected text;
  v_snapshot jsonb;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'Describe el motivo de eliminación con al menos 10 caracteres';
  END IF;

  SELECT * INTO v_company FROM public.empresas WHERE id = p_empresa_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Empresa no encontrada'; END IF;
  SELECT * INTO v_lead FROM public.admin_trial_crm_leads WHERE empresa_id = p_empresa_id FOR UPDATE;

  v_expected := 'ELIMINAR ' || COALESCE(NULLIF(v_company.licencia, ''), v_company.nombre);
  IF p_confirmation IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Confirmación incorrecta. Escribe exactamente: %', v_expected;
  END IF;
  IF v_lead.stage IS NULL OR v_lead.stage NOT IN ('no_interesado', 'descartado') THEN
    RAISE EXCEPTION 'Primero marca el prospecto como No interesado o Descartado';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ventas v WHERE v.empresa_id = p_empresa_id
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('borrador', 'cancelado')
  ) THEN
    RAISE EXCEPTION 'Bloqueado: la empresa ya tiene ventas operativas';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.facturas f WHERE f.empresa_id = p_empresa_id
      AND lower(COALESCE(f.estado, '')) = 'pagada'
  ) THEN
    RAISE EXCEPTION 'Bloqueado: la empresa tiene facturas pagadas';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.subscriptions s WHERE s.empresa_id = p_empresa_id
      AND (s.stripe_subscription_id IS NOT NULL OR s.status IN ('active', 'past_due', 'pendiente_pago'))
  ) THEN
    RAISE EXCEPTION 'Bloqueado: cancela o concilia primero la suscripción activa';
  END IF;

  v_age := GREATEST(0, EXTRACT(DAY FROM now() - v_company.created_at)::integer);
  v_snapshot := jsonb_build_object(
    'empresa', to_jsonb(v_company),
    'lead', to_jsonb(v_lead),
    'counts', jsonb_build_object(
      'ventas', (SELECT COUNT(*) FROM public.ventas WHERE empresa_id = p_empresa_id),
      'productos', (SELECT COUNT(*) FROM public.productos WHERE empresa_id = p_empresa_id),
      'clientes', (SELECT COUNT(*) FROM public.clientes WHERE empresa_id = p_empresa_id),
      'usuarios', (SELECT COUNT(*) FROM public.profiles WHERE empresa_id = p_empresa_id)
    )
  );

  INSERT INTO public.admin_trial_crm_deletions (
    empresa_id, empresa_nombre, licencia, email, telefono, age_days,
    reason, snapshot, deleted_by
  ) VALUES (
    v_company.id, v_company.nombre, v_company.licencia, v_company.email,
    v_company.telefono, v_age, btrim(p_reason), v_snapshot, auth.uid()
  );

  -- La función existente elimina datos y usuarios dentro de la misma transacción.
  -- Si cualquier FK actual impide la depuración, todo se revierte y no queda una
  -- empresa parcialmente eliminada.
  PERFORM public.delete_empresa_cascade(p_empresa_id, auth.uid());

  RETURN jsonb_build_object('ok', true, 'empresa_id', p_empresa_id, 'nombre', v_company.nombre);
END;
$$;


--
-- Name: fn_admin_trial_crm_detect_conversion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_detect_conversion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_updated uuid;
BEGIN
  IF COALESCE(NEW.es_saldo_inicial, false) OR NEW.status::text IN ('borrador', 'cancelado') THEN
    RETURN NEW;
  END IF;

  UPDATE public.admin_trial_crm_leads
  SET stage = 'convertido', converted_at = COALESCE(converted_at, now()), updated_at = now()
  WHERE empresa_id = NEW.empresa_id AND stage <> 'convertido'
  RETURNING empresa_id INTO v_updated;

  IF v_updated IS NOT NULL THEN
    INSERT INTO public.admin_trial_crm_activities (
      empresa_id, activity_type, outcome, note, previous_stage, new_stage
    ) VALUES (
      NEW.empresa_id, 'system', 'primera_venta',
      'Conversión detectada automáticamente por venta ' || COALESCE(NEW.folio, NEW.id::text),
      NULL, 'convertido'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_admin_trial_crm_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_history(p_empresa_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', a.id, 'activity_type', a.activity_type, 'outcome', a.outcome,
    'note', a.note, 'previous_stage', a.previous_stage, 'new_stage', a.new_stage,
    'created_at', a.created_at, 'created_by', a.created_by
  ) ORDER BY a.created_at DESC), '[]'::jsonb)
  INTO v_result
  FROM public.admin_trial_crm_activities a WHERE a.empresa_id = p_empresa_id;
  RETURN v_result;
END;
$$;


--
-- Name: fn_admin_trial_crm_log_contact(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_log_contact(p_empresa_id uuid, p_channel text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_previous_stage text;
  v_new_stage text;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF p_channel NOT IN ('call', 'whatsapp', 'email') THEN
    RAISE EXCEPTION 'Canal de contacto inválido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.empresas WHERE id = p_empresa_id) THEN
    RAISE EXCEPTION 'Empresa no encontrada' USING ERRCODE = 'P0002';
  END IF;

  SELECT stage INTO v_previous_stage
  FROM public.admin_trial_crm_leads
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  v_new_stage := CASE
    WHEN COALESCE(v_previous_stage, 'sin_contactar') = 'sin_contactar' THEN 'por_contactar'
    ELSE COALESCE(v_previous_stage, 'por_contactar')
  END;

  INSERT INTO public.admin_trial_crm_leads (
    empresa_id, stage, last_contact_at, contact_attempts, created_by, updated_by
  ) VALUES (
    p_empresa_id, v_new_stage, now(), 1, auth.uid(), auth.uid()
  )
  ON CONFLICT (empresa_id) DO UPDATE SET
    stage = CASE
      WHEN admin_trial_crm_leads.stage = 'sin_contactar' THEN 'por_contactar'
      ELSE admin_trial_crm_leads.stage
    END,
    last_contact_at = now(),
    contact_attempts = admin_trial_crm_leads.contact_attempts + 1,
    updated_by = auth.uid();

  INSERT INTO public.admin_trial_crm_activities (
    empresa_id, activity_type, outcome, previous_stage, new_stage, created_by
  ) VALUES (
    p_empresa_id, p_channel, 'Contacto iniciado desde CRM',
    COALESCE(v_previous_stage, 'sin_contactar'), v_new_stage, auth.uid()
  );

  RETURN jsonb_build_object('ok', true, 'empresa_id', p_empresa_id, 'channel', p_channel);
END;
$$;


--
-- Name: fn_admin_trial_crm_mark_lost(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_mark_lost(p_empresa_id uuid, p_reason text, p_outcome text DEFAULT 'No interesado'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_previous_stage text;
  v_coupon_id uuid;
  v_reason text := NULLIF(btrim(p_reason), '');
  v_outcome text := COALESCE(NULLIF(btrim(p_outcome), ''), 'No interesado');
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF v_reason IS NULL OR length(v_reason) < 5 THEN
    RAISE EXCEPTION 'Escribe un motivo de al menos 5 caracteres' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.empresas WHERE id = p_empresa_id) THEN
    RAISE EXCEPTION 'Empresa no encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('borrador', 'cancelado')
  ) THEN
    RAISE EXCEPTION 'La empresa ya tiene ventas operativas y no pertenece a recuperación';
  END IF;

  SELECT stage, coupon_id INTO v_previous_stage, v_coupon_id
  FROM public.admin_trial_crm_leads
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  INSERT INTO public.admin_trial_crm_leads (
    empresa_id, stage, next_follow_up_at, notes, lost_at, lost_by,
    lost_reason, created_by, updated_by
  ) VALUES (
    p_empresa_id, 'no_interesado', NULL, v_reason, now(), auth.uid(),
    v_reason, auth.uid(), auth.uid()
  )
  ON CONFLICT (empresa_id) DO UPDATE SET
    stage = 'no_interesado',
    next_follow_up_at = NULL,
    notes = v_reason,
    lost_at = now(),
    lost_by = auth.uid(),
    lost_reason = v_reason,
    updated_by = auth.uid();

  IF v_coupon_id IS NOT NULL THEN
    UPDATE public.cupones SET activo = false WHERE id = v_coupon_id;
  END IF;

  INSERT INTO public.admin_trial_crm_activities (
    empresa_id, activity_type, outcome, note, previous_stage, new_stage, created_by
  ) VALUES (
    p_empresa_id, 'stage', v_outcome, v_reason,
    COALESCE(v_previous_stage, 'sin_contactar'), 'no_interesado', auth.uid()
  );

  RETURN jsonb_build_object(
    'ok', true,
    'empresa_id', p_empresa_id,
    'stage', 'no_interesado',
    'lost_at', now(),
    'coupon_revoked', v_coupon_id IS NOT NULL
  );
END;
$$;


--
-- Name: fn_admin_trial_crm_restore_lost(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_restore_lost(p_empresa_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_previous_stage text;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  SELECT stage INTO v_previous_stage
  FROM public.admin_trial_crm_leads
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Prospecto no encontrado' USING ERRCODE = 'P0002';
  END IF;
  IF v_previous_stage NOT IN ('no_interesado', 'descartado') THEN
    RAISE EXCEPTION 'El prospecto no está en Perdidos' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('borrador', 'cancelado')
  ) THEN
    RAISE EXCEPTION 'La empresa ya tiene ventas operativas y no debe volver a recuperación';
  END IF;

  UPDATE public.admin_trial_crm_leads SET
    stage = 'por_contactar',
    next_follow_up_at = now(),
    lost_at = NULL,
    lost_by = NULL,
    lost_reason = NULL,
    notes = COALESCE(NULLIF(btrim(p_note), ''), notes),
    updated_by = auth.uid()
  WHERE empresa_id = p_empresa_id;

  INSERT INTO public.admin_trial_crm_activities (
    empresa_id, activity_type, outcome, note, previous_stage, new_stage, created_by
  ) VALUES (
    p_empresa_id, 'stage', 'Reactivado en CRM', NULLIF(btrim(p_note), ''),
    v_previous_stage, 'por_contactar', auth.uid()
  );

  RETURN jsonb_build_object('ok', true, 'empresa_id', p_empresa_id, 'stage', 'por_contactar');
END;
$$;


--
-- Name: fn_admin_trial_crm_save(uuid, text, uuid, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_save(p_empresa_id uuid, p_stage text, p_assigned_to uuid DEFAULT NULL::uuid, p_next_follow_up_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text, p_activity_type text DEFAULT 'note'::text, p_outcome text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_previous_stage text;
  v_is_contact boolean := p_activity_type IN ('call', 'whatsapp', 'email');
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF p_stage NOT IN ('sin_contactar', 'por_contactar', 'contactado', 'interesado', 'seguimiento', 'no_localizado', 'no_interesado', 'descartado', 'convertido') THEN
    RAISE EXCEPTION 'Etapa comercial inválida' USING ERRCODE = '22023';
  END IF;
  IF p_activity_type NOT IN ('note', 'call', 'whatsapp', 'email', 'stage', 'assignment', 'system') THEN
    RAISE EXCEPTION 'Tipo de actividad inválido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.empresas WHERE id = p_empresa_id) THEN
    RAISE EXCEPTION 'Empresa no encontrada' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ventas v WHERE v.empresa_id = p_empresa_id
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('borrador', 'cancelado')
  ) AND p_stage <> 'convertido' THEN
    RAISE EXCEPTION 'La empresa ya tiene ventas operativas y no pertenece a recuperación';
  END IF;
  IF p_assigned_to IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.commission_people WHERE id = p_assigned_to AND is_active = true AND person_type = 'internal'
  ) THEN
    RAISE EXCEPTION 'Responsable interno inválido';
  END IF;

  SELECT stage INTO v_previous_stage
  FROM public.admin_trial_crm_leads WHERE empresa_id = p_empresa_id FOR UPDATE;

  INSERT INTO public.admin_trial_crm_leads (
    empresa_id, stage, assigned_to, next_follow_up_at, last_contact_at,
    contact_attempts, notes, converted_at, created_by, updated_by
  ) VALUES (
    p_empresa_id, p_stage, p_assigned_to, p_next_follow_up_at,
    CASE WHEN v_is_contact THEN now() ELSE NULL END,
    CASE WHEN v_is_contact THEN 1 ELSE 0 END,
    NULLIF(btrim(p_note), ''),
    CASE WHEN p_stage = 'convertido' THEN now() ELSE NULL END,
    auth.uid(), auth.uid()
  )
  ON CONFLICT (empresa_id) DO UPDATE SET
    stage = EXCLUDED.stage,
    assigned_to = EXCLUDED.assigned_to,
    next_follow_up_at = EXCLUDED.next_follow_up_at,
    last_contact_at = CASE WHEN v_is_contact THEN now() ELSE admin_trial_crm_leads.last_contact_at END,
    contact_attempts = admin_trial_crm_leads.contact_attempts + CASE WHEN v_is_contact THEN 1 ELSE 0 END,
    notes = CASE WHEN NULLIF(btrim(p_note), '') IS NULL THEN admin_trial_crm_leads.notes ELSE NULLIF(btrim(p_note), '') END,
    converted_at = CASE WHEN EXCLUDED.stage = 'convertido' THEN COALESCE(admin_trial_crm_leads.converted_at, now()) ELSE admin_trial_crm_leads.converted_at END,
    updated_by = auth.uid();

  INSERT INTO public.admin_trial_crm_activities (
    empresa_id, activity_type, outcome, note, previous_stage, new_stage, created_by
  ) VALUES (
    p_empresa_id, p_activity_type, NULLIF(btrim(p_outcome), ''), NULLIF(btrim(p_note), ''),
    v_previous_stage, p_stage, auth.uid()
  );

  RETURN jsonb_build_object('ok', true, 'empresa_id', p_empresa_id, 'stage', p_stage);
END;
$$;


--
-- Name: fn_admin_trial_crm_snapshot(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_snapshot(p_min_age_days integer DEFAULT 0, p_max_age_days integer DEFAULT 3650) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_min_age integer := GREATEST(0, COALESCE(p_min_age_days, 0));
  v_max_age integer := LEAST(36500, GREATEST(v_min_age, COALESCE(p_max_age_days, 3650)));
  v_result jsonb;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  WITH sale_stats AS MATERIALIZED (
    SELECT
      v.empresa_id,
      COUNT(*)::integer AS all_sales,
      COUNT(*) FILTER (
        WHERE COALESCE(v.es_saldo_inicial, false) = false
          AND v.status::text NOT IN ('borrador', 'cancelado')
      )::integer AS valid_sales,
      COUNT(*) FILTER (WHERE v.status::text = 'borrador')::integer AS draft_sales,
      MAX(v.created_at) AS last_sale_record_at
    FROM public.ventas v
    GROUP BY v.empresa_id
  ),
  product_stats AS MATERIALIZED (
    SELECT p.empresa_id, COUNT(*)::integer AS products,
      COUNT(*) FILTER (WHERE p.status::text = 'activo')::integer AS active_products,
      MAX(p.created_at) AS last_product_at
    FROM public.productos p GROUP BY p.empresa_id
  ),
  client_stats AS MATERIALIZED (
    SELECT c.empresa_id, COUNT(*)::integer AS clients, MAX(c.created_at) AS last_client_at
    FROM public.clientes c GROUP BY c.empresa_id
  ),
  profile_stats AS MATERIALIZED (
    SELECT p.empresa_id, COUNT(*)::integer AS users,
      MAX(u.last_sign_in_at) AS last_sign_in_at,
      MIN(u.email) FILTER (WHERE p.user_id = e.owner_user_id) AS owner_email
    FROM public.profiles p
    JOIN public.empresas e ON e.id = p.empresa_id
    LEFT JOIN auth.users u ON u.id = p.user_id
    GROUP BY p.empresa_id
  ),
  invoice_stats AS MATERIALIZED (
    SELECT f.empresa_id,
      COUNT(*)::integer AS invoices,
      COUNT(*) FILTER (WHERE lower(COALESCE(f.estado, '')) = 'pagada')::integer AS paid_invoices,
      COALESCE(SUM(f.total) FILTER (WHERE lower(COALESCE(f.estado, '')) = 'pagada'), 0)::numeric AS paid_total,
      MAX(f.fecha_pago) FILTER (WHERE lower(COALESCE(f.estado, '')) = 'pagada') AS last_payment_at
    FROM public.facturas f
    GROUP BY f.empresa_id
  ),
  latest_subscription AS MATERIALIZED (
    SELECT DISTINCT ON (s.empresa_id)
      s.empresa_id, s.id, s.status, s.trial_ends_at, s.current_period_end,
      s.fecha_vencimiento, s.stripe_customer_id, s.stripe_subscription_id,
      s.es_manual, s.acceso_bloqueado
    FROM public.subscriptions s
    ORDER BY s.empresa_id, s.updated_at DESC, s.created_at DESC
  ),
  last_activity AS MATERIALIZED (
    SELECT DISTINCT ON (a.empresa_id)
      a.empresa_id, a.activity_type, a.outcome, a.note, a.created_at
    FROM public.admin_trial_crm_activities a
    ORDER BY a.empresa_id, a.created_at DESC
  ),
  base AS MATERIALIZED (
    SELECT
      e.id AS empresa_id,
      e.nombre,
      e.licencia,
      COALESCE(NULLIF(e.email, ''), prs.owner_email) AS email,
      e.telefono,
      e.created_at,
      GREATEST(0, EXTRACT(DAY FROM now() - e.created_at)::integer) AS age_days,
      e.onboarding_completado,
      COALESCE(ss.all_sales, 0) AS all_sales,
      COALESCE(ss.valid_sales, 0) AS valid_sales,
      COALESCE(ss.draft_sales, 0) AS draft_sales,
      ss.last_sale_record_at,
      COALESCE(ps.products, 0) AS products,
      COALESCE(ps.active_products, 0) AS active_products,
      ps.last_product_at,
      COALESCE(cs.clients, 0) AS clients,
      cs.last_client_at,
      COALESCE(prs.users, 0) AS users,
      prs.last_sign_in_at,
      CASE WHEN prs.last_sign_in_at IS NULL THEN NULL
        ELSE GREATEST(0, EXTRACT(DAY FROM now() - prs.last_sign_in_at)::integer) END AS days_since_login,
      COALESCE(inv.invoices, 0) AS invoices,
      COALESCE(inv.paid_invoices, 0) AS paid_invoices,
      COALESCE(inv.paid_total, 0) AS paid_total,
      inv.last_payment_at,
      sub.id AS subscription_id,
      COALESCE(sub.status, 'sin_suscripcion') AS subscription_status,
      sub.trial_ends_at,
      sub.current_period_end,
      sub.fecha_vencimiento,
      sub.stripe_customer_id,
      sub.stripe_subscription_id,
      COALESCE(sub.es_manual, false) AS manual_subscription,
      COALESCE(sub.acceso_bloqueado, false) AS access_blocked,
      COALESCE(lead.stage, 'sin_contactar') AS crm_stage,
      lead.assigned_to,
      person.name AS assigned_name,
      lead.next_follow_up_at,
      lead.last_contact_at,
      COALESCE(lead.contact_attempts, 0) AS contact_attempts,
      lead.notes,
      lead.coupon_id,
      coupon.codigo AS coupon_code,
      coupon.descuento_pct AS coupon_discount_pct,
      coupon.meses_duracion AS coupon_months,
      coupon.vigencia_fin AS coupon_expires_at,
      (
        COALESCE(coupon.activo, false)
        AND (coupon.vigencia_inicio IS NULL OR coupon.vigencia_inicio <= current_date)
        AND (coupon.vigencia_fin IS NULL OR coupon.vigencia_fin >= current_date)
      ) AS coupon_active,
      la.activity_type AS last_activity_type,
      la.outcome AS last_activity_outcome,
      la.note AS last_activity_note,
      la.created_at AS last_activity_at,
      CASE
        WHEN COALESCE(ps.products, 0) > 0 AND COALESCE(cs.clients, 0) > 0 AND COALESCE(ss.draft_sales, 0) > 0 THEN 'casi_listo'
        WHEN COALESCE(ps.products, 0) > 0 OR COALESCE(cs.clients, 0) > 0 OR COALESCE(ss.draft_sales, 0) > 0 THEN 'exploro'
        ELSE 'sin_configurar'
      END AS setup_level,
      LEAST(100,
        (CASE WHEN prs.last_sign_in_at IS NOT NULL THEN 15 ELSE 0 END) +
        (CASE WHEN COALESCE(e.onboarding_completado, false) THEN 20 ELSE 0 END) +
        (CASE WHEN COALESCE(ps.products, 0) > 0 THEN 25 ELSE 0 END) +
        (CASE WHEN COALESCE(cs.clients, 0) > 0 THEN 20 ELSE 0 END) +
        (CASE WHEN COALESCE(ss.draft_sales, 0) > 0 THEN 20 ELSE 0 END)
      )::integer AS activation_score,
      (
        COALESCE(inv.paid_invoices, 0) = 0
        AND sub.stripe_subscription_id IS NULL
        AND COALESCE(sub.status, 'sin_suscripcion') NOT IN ('active', 'past_due', 'pendiente_pago')
      ) AS deletion_eligible
    FROM public.empresas e
    LEFT JOIN sale_stats ss ON ss.empresa_id = e.id
    LEFT JOIN product_stats ps ON ps.empresa_id = e.id
    LEFT JOIN client_stats cs ON cs.empresa_id = e.id
    LEFT JOIN profile_stats prs ON prs.empresa_id = e.id
    LEFT JOIN invoice_stats inv ON inv.empresa_id = e.id
    LEFT JOIN latest_subscription sub ON sub.empresa_id = e.id
    LEFT JOIN public.admin_trial_crm_leads lead ON lead.empresa_id = e.id
    LEFT JOIN public.commission_people person ON person.id = lead.assigned_to
    LEFT JOIN public.cupones coupon ON coupon.id = lead.coupon_id
    LEFT JOIN last_activity la ON la.empresa_id = e.id
    WHERE COALESCE(e.is_partner_sandbox, false) = false
      AND COALESCE(ss.valid_sales, 0) = 0
      AND GREATEST(0, EXTRACT(DAY FROM now() - e.created_at)::integer) BETWEEN v_min_age AND v_max_age
  ),
  monthly AS MATERIALIZED (
    SELECT generate_series(
      date_trunc('month', current_date)::date - interval '11 months',
      date_trunc('month', current_date)::date,
      interval '1 month'
    )::date AS month
  ),
  monthly_counts AS MATERIALIZED (
    SELECT date_trunc('month', b.created_at)::date AS month, COUNT(*)::integer AS signups
    FROM base b GROUP BY 1
  )
  SELECT jsonb_build_object(
    'generated_at', now(),
    'metrics', jsonb_build_object(
      'total', (SELECT COUNT(*) FROM base),
      'uncontacted', (SELECT COUNT(*) FROM base WHERE crm_stage = 'sin_contactar'),
      'overdue_followups', (SELECT COUNT(*) FROM base WHERE next_follow_up_at < now() AND crm_stage NOT IN ('no_interesado', 'descartado', 'convertido')),
      'registered_7d', (SELECT COUNT(*) FROM base WHERE created_at >= now() - interval '7 days'),
      'registered_30d', (SELECT COUNT(*) FROM base WHERE created_at >= now() - interval '30 days'),
      'with_setup', (SELECT COUNT(*) FROM base WHERE activation_score > 0),
      'almost_ready', (SELECT COUNT(*) FROM base WHERE setup_level = 'casi_listo'),
      'expired_trial', (SELECT COUNT(*) FROM base WHERE trial_ends_at < now()),
      'offers_active', (SELECT COUNT(*) FROM base WHERE coupon_active = true),
      'deletion_eligible', (SELECT COUNT(*) FROM base WHERE deletion_eligible = true)
    ),
    'stages', COALESCE((
      SELECT jsonb_object_agg(x.crm_stage, x.total)
      FROM (SELECT crm_stage, COUNT(*)::integer AS total FROM base GROUP BY crm_stage) x
    ), '{}'::jsonb),
    'monthly_signups', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'month', m.month, 'signups', COALESCE(mc.signups, 0)
      ) ORDER BY m.month)
      FROM monthly m LEFT JOIN monthly_counts mc ON mc.month = m.month
    ), '[]'::jsonb),
    'assignees', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name) ORDER BY p.name)
      FROM public.commission_people p
      WHERE p.is_active = true AND p.person_type = 'internal'
    ), '[]'::jsonb),
    'leads', COALESCE((
      SELECT jsonb_agg(to_jsonb(b) ORDER BY
        CASE WHEN b.next_follow_up_at < now() THEN 0 ELSE 1 END,
        CASE b.setup_level WHEN 'casi_listo' THEN 0 WHEN 'exploro' THEN 1 ELSE 2 END,
        b.created_at DESC
      ) FROM base b
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_admin_trial_crm_workspace(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_admin_trial_crm_workspace(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_days integer := LEAST(365, GREATEST(7, COALESCE(p_days, 30)));
  v_snapshot jsonb;
  v_leads jsonb;
  v_operations jsonb;
BEGIN
  IF NOT (public.is_super_admin(auth.uid()) OR COALESCE(current_setting('app.crm_internal_team', true), '') = 'on') THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  v_snapshot := public.fn_admin_trial_crm_snapshot(0, 36500);

  SELECT COALESCE(jsonb_agg(
    item || jsonb_build_object(
      'lost_at', lead.lost_at,
      'lost_by', lead.lost_by,
      'lost_reason', lead.lost_reason,
      'lost_by_name', COALESCE(
        lost_profile.nombre,
        lost_user.raw_user_meta_data ->> 'full_name',
        lost_user.raw_user_meta_data ->> 'name',
        lost_user.email
      )
    ) ORDER BY ordinality
  ), '[]'::jsonb)
  INTO v_leads
  FROM jsonb_array_elements(COALESCE(v_snapshot -> 'leads', '[]'::jsonb))
    WITH ORDINALITY AS source(item, ordinality)
  LEFT JOIN public.admin_trial_crm_leads lead
    ON lead.empresa_id = (source.item ->> 'empresa_id')::uuid
  LEFT JOIN public.profiles lost_profile ON lost_profile.user_id = lead.lost_by
  LEFT JOIN auth.users lost_user ON lost_user.id = lead.lost_by;

  WITH activity AS MATERIALIZED (
    SELECT
      a.id,
      a.empresa_id,
      a.activity_type,
      a.outcome,
      a.note,
      a.previous_stage,
      a.new_stage,
      a.created_by,
      a.created_at,
      (a.created_at AT TIME ZONE 'America/Mexico_City')::date AS local_day,
      e.nombre AS empresa_nombre,
      COALESCE(
        profile.nombre,
        app_user.raw_user_meta_data ->> 'full_name',
        app_user.raw_user_meta_data ->> 'name',
        app_user.email,
        CASE WHEN a.created_by IS NULL THEN 'Sistema' ELSE 'Usuario sin nombre' END
      ) AS actor_name
    FROM public.admin_trial_crm_activities a
    JOIN public.empresas e ON e.id = a.empresa_id
    LEFT JOIN public.profiles profile ON profile.user_id = a.created_by
    LEFT JOIN auth.users app_user ON app_user.id = a.created_by
    WHERE a.created_at >= now() - make_interval(days => v_days)
  ),
  calendar AS MATERIALIZED (
    SELECT generate_series(
      (now() AT TIME ZONE 'America/Mexico_City')::date - (v_days - 1),
      (now() AT TIME ZONE 'America/Mexico_City')::date,
      interval '1 day'
    )::date AS day
  ),
  daily AS MATERIALIZED (
    SELECT
      a.local_day AS day,
      COUNT(*)::integer AS activities,
      COUNT(*) FILTER (WHERE a.activity_type IN ('call', 'whatsapp', 'email'))::integer AS contacts,
      COUNT(*) FILTER (WHERE a.activity_type = 'call')::integer AS calls,
      COUNT(*) FILTER (WHERE a.activity_type = 'whatsapp')::integer AS whatsapp,
      COUNT(*) FILTER (WHERE a.activity_type = 'email')::integer AS emails,
      COUNT(*) FILTER (WHERE a.activity_type = 'coupon')::integer AS offers,
      COUNT(*) FILTER (WHERE a.new_stage IN ('no_interesado', 'descartado'))::integer AS lost
    FROM activity a
    GROUP BY a.local_day
  ),
  team AS MATERIALIZED (
    SELECT
      a.created_by AS user_id,
      a.actor_name AS name,
      COUNT(*)::integer AS activities,
      COUNT(DISTINCT a.empresa_id)::integer AS leads_touched,
      COUNT(*) FILTER (WHERE a.activity_type IN ('call', 'whatsapp', 'email'))::integer AS contacts,
      COUNT(*) FILTER (WHERE a.activity_type = 'call')::integer AS calls,
      COUNT(*) FILTER (WHERE a.activity_type = 'whatsapp')::integer AS whatsapp,
      COUNT(*) FILTER (WHERE a.activity_type = 'email')::integer AS emails,
      COUNT(*) FILTER (WHERE a.activity_type = 'note')::integer AS notes,
      COUNT(*) FILTER (WHERE a.activity_type = 'coupon')::integer AS offers,
      COUNT(*) FILTER (WHERE a.new_stage = 'interesado')::integer AS interested,
      COUNT(*) FILTER (WHERE a.new_stage IN ('no_interesado', 'descartado'))::integer AS lost,
      MAX(a.created_at) AS last_activity_at
    FROM activity a
    GROUP BY a.created_by, a.actor_name
  )
  SELECT jsonb_build_object(
    'days', v_days,
    'metrics', jsonb_build_object(
      'activities', (SELECT COUNT(*) FROM activity),
      'contacts', (SELECT COUNT(*) FROM activity WHERE activity_type IN ('call', 'whatsapp', 'email')),
      'calls', (SELECT COUNT(*) FROM activity WHERE activity_type = 'call'),
      'whatsapp', (SELECT COUNT(*) FROM activity WHERE activity_type = 'whatsapp'),
      'emails', (SELECT COUNT(*) FROM activity WHERE activity_type = 'email'),
      'notes', (SELECT COUNT(*) FROM activity WHERE activity_type = 'note'),
      'offers', (SELECT COUNT(*) FROM activity WHERE activity_type = 'coupon'),
      'leads_touched', (SELECT COUNT(DISTINCT empresa_id) FROM activity),
      'staff_active', (SELECT COUNT(DISTINCT created_by) FROM activity WHERE created_by IS NOT NULL),
      'interested', (SELECT COUNT(*) FROM activity WHERE new_stage = 'interesado'),
      'lost', (SELECT COUNT(*) FROM activity WHERE new_stage IN ('no_interesado', 'descartado'))
    ),
    'daily', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'day', c.day,
        'activities', COALESCE(d.activities, 0),
        'contacts', COALESCE(d.contacts, 0),
        'calls', COALESCE(d.calls, 0),
        'whatsapp', COALESCE(d.whatsapp, 0),
        'emails', COALESCE(d.emails, 0),
        'offers', COALESCE(d.offers, 0),
        'lost', COALESCE(d.lost, 0)
      ) ORDER BY c.day)
      FROM calendar c LEFT JOIN daily d ON d.day = c.day
    ), '[]'::jsonb),
    'team', COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.contacts DESC, t.activities DESC) FROM team t), '[]'::jsonb),
    'recent', COALESCE((
      SELECT jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC)
      FROM (
        SELECT id, empresa_id, empresa_nombre, activity_type, outcome, note,
          previous_stage, new_stage, created_by, actor_name, created_at
        FROM activity ORDER BY created_at DESC LIMIT 200
      ) r
    ), '[]'::jsonb)
  ) INTO v_operations;

  RETURN v_snapshot || jsonb_build_object(
    'leads', v_leads,
    'operations', v_operations
  );
END;
$$;


--
-- Name: fn_bloquea_borrado_con_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_bloquea_borrado_con_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc  uuid;
  v_prod uuid;
BEGIN
  -- Procesos del servidor (limpieza de cuentas) quedan exentos.
  IF COALESCE(auth.role(), '') = 'service_role' THEN RETURN OLD; END IF;
  v_doc := (to_jsonb(OLD) ->> TG_ARGV[0])::uuid;
  IF TG_NARGS > 1 THEN v_prod := (to_jsonb(OLD) ->> TG_ARGV[1])::uuid; END IF;
  IF v_doc IS NOT NULL AND public.fn_doc_mueve_stock(v_doc, v_prod) THEN
    RAISE EXCEPTION 'No se puede borrar: ya movió inventario. Cancélalo en lugar de borrarlo.'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: fn_compra_linea_lote_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_compra_linea_lote_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec record;
  v_delta numeric;
  v_linea record;
  v_total numeric;
  v_loteado numeric;
  v_sa_id uuid; v_sa_qty numeric;
  v_pendiente numeric;
  v_folio text;
BEGIN
  IF TG_OP = 'INSERT' THEN v_rec := NEW; v_delta := NEW.piezas;
  ELSE v_rec := OLD; v_delta := -OLD.piezas;
  END IF;

  SELECT cl.*, (cl.cantidad * COALESCE(NULLIF(cl.factor_conversion,0),1)) AS total_piezas
    INTO v_linea
  FROM compra_lineas cl WHERE cl.id = v_rec.compra_linea_id FOR UPDATE;

  IF v_linea IS NULL THEN RETURN v_rec; END IF;

  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM lotes l WHERE l.id = NEW.lote_id AND l.producto_id = v_linea.producto_id) THEN
      RAISE EXCEPTION 'El lote no corresponde al producto de la línea';
    END IF;
    v_total := v_linea.total_piezas;
    v_loteado := COALESCE(v_linea.piezas_loteadas, 0);
    IF v_loteado + NEW.piezas > v_total + 0.0001 THEN
      RAISE EXCEPTION 'No puedes lotear más piezas de las compradas (pendiente: %)', GREATEST(0, v_total - v_loteado);
    END IF;
  END IF;

  IF v_rec.almacen_id IS NOT NULL THEN
    SELECT id, cantidad INTO v_sa_id, v_sa_qty
    FROM stock_almacen WHERE almacen_id = v_rec.almacen_id AND producto_id = v_linea.producto_id FOR UPDATE;
    IF v_sa_id IS NOT NULL THEN
      UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty,0) + v_delta, updated_at = now() WHERE id = v_sa_id;
    ELSIF v_delta > 0 THEN
      INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (v_rec.empresa_id, v_rec.almacen_id, v_linea.producto_id, v_delta);
    END IF;
    -- NOTA: el stock por lote lo aplica trg_sync_stock_lote al insertar el movimiento.
  END IF;

  SELECT folio INTO v_folio FROM compras WHERE id = v_rec.compra_id;

  INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad,
    almacen_destino_id, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas, lote_id)
  VALUES (v_rec.empresa_id,
    (CASE WHEN v_delta > 0 THEN 'entrada' ELSE 'salida' END)::tipo_movimiento,
    v_linea.producto_id, ABS(v_delta),
    CASE WHEN v_delta > 0 THEN v_rec.almacen_id ELSE NULL END,
    CASE WHEN v_delta < 0 THEN v_rec.almacen_id ELSE NULL END,
    'compra', v_rec.compra_id, v_rec.user_id, current_date,
    concat('Compra ', COALESCE(v_folio, v_rec.compra_id::text),
           CASE WHEN v_delta > 0 THEN ' loteo/recepción' ELSE ' reversa de loteo' END),
    v_rec.lote_id);

  UPDATE compra_lineas
     SET piezas_loteadas = GREATEST(0, COALESCE(piezas_loteadas,0) + v_delta),
         cantidad_recibida = GREATEST(0, COALESCE(cantidad_recibida,0) + v_delta)
   WHERE id = v_rec.compra_linea_id;

  SELECT COALESCE(SUM(GREATEST(0, cantidad * COALESCE(NULLIF(factor_conversion,0),1) - COALESCE(cantidad_recibida,0))), 0)
    INTO v_pendiente
  FROM compra_lineas WHERE compra_id = v_rec.compra_id;

  IF v_pendiente = 0 THEN
    UPDATE compras SET status = 'recibida'
     WHERE id = v_rec.compra_id AND status NOT IN ('recibida','pagada','cancelada');
  END IF;

  RETURN v_rec;
END;
$$;


--
-- Name: fn_crm_call_pitch_get(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_crm_call_pitch_get() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_value jsonb;
  v_active text;
  v_pitch jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select config
    into v_value
  from public.internal_crm_call_pitch_config
  where id = 'default';

  v_value := coalesce(v_value, '{}'::jsonb);

  if jsonb_typeof(v_value -> 'pitches') = 'array' then
    v_active := coalesce(v_value ->> 'active_pitch_id', '');

    select item -> 'config'
      into v_pitch
    from jsonb_array_elements(v_value -> 'pitches') item
    where item ->> 'id' = v_active
    limit 1;

    if v_pitch is null then
      select item -> 'config'
        into v_pitch
      from jsonb_array_elements(v_value -> 'pitches') item
      limit 1;
    end if;

    return coalesce(v_pitch, '{}'::jsonb);
  end if;

  return v_value;
end;
$$;


--
-- Name: FUNCTION fn_crm_call_pitch_get(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_crm_call_pitch_get() IS 'Devuelve la configuración vigente del pitch de llamada para usuarios autenticados.';


--
-- Name: fn_crm_cancellation_insight(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_crm_cancellation_insight(p_empresa_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_allowed boolean := false;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  v_allowed := public.is_super_admin(auth.uid());

  IF NOT v_allowed THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.platform_team_members tm
      WHERE tm.user_id = auth.uid()
        AND tm.status = 'active'
        AND COALESCE((tm.permissions ->> 'crm')::boolean, false) = true
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Sin permiso para consultar CRM';
  END IF;

  SELECT jsonb_build_object(
    'empresa_id', p_empresa_id,
    'total_requests', count(*),
    'has_cancelled', COALESCE(bool_or(cr.cancelled), false),

    'latest', (
      SELECT jsonb_build_object(
        'id', latest.id,
        'reason', latest.reason,
        'reason_detail', latest.reason_detail,
        'offered_discount', latest.offered_discount,
        'discount_accepted', latest.discount_accepted,
        'cancelled', latest.cancelled,
        'created_at', latest.created_at
      )
      FROM public.cancellation_requests latest
      WHERE latest.empresa_id = p_empresa_id
      ORDER BY latest.created_at DESC, latest.id DESC
      LIMIT 1
    ),

    'latest_cancelled', (
      SELECT jsonb_build_object(
        'id', cancelled_row.id,
        'reason', cancelled_row.reason,
        'reason_detail', cancelled_row.reason_detail,
        'offered_discount', cancelled_row.offered_discount,
        'discount_accepted', cancelled_row.discount_accepted,
        'cancelled', cancelled_row.cancelled,
        'created_at', cancelled_row.created_at
      )
      FROM public.cancellation_requests cancelled_row
      WHERE cancelled_row.empresa_id = p_empresa_id
        AND cancelled_row.cancelled = true
      ORDER BY cancelled_row.created_at DESC, cancelled_row.id DESC
      LIMIT 1
    )
  )
  INTO v_result
  FROM public.cancellation_requests cr
  WHERE cr.empresa_id = p_empresa_id;

  RETURN COALESCE(
    v_result,
    jsonb_build_object(
      'empresa_id', p_empresa_id,
      'total_requests', 0,
      'has_cancelled', false,
      'latest', null,
      'latest_cancelled', null
    )
  );
END;
$$;


--
-- Name: fn_crm_cancellations_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_crm_cancellations_list() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_allowed boolean := false;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'No autenticado';
  END IF;

  v_allowed := public.is_super_admin(auth.uid());

  IF NOT v_allowed THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.platform_team_members tm
      WHERE tm.user_id = auth.uid()
        AND tm.status = 'active'
        AND COALESCE((tm.permissions ->> 'crm')::boolean, false) = true
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Sin permiso para consultar CRM';
  END IF;

  SELECT COALESCE(
    jsonb_agg(row_data ORDER BY cancelled_at DESC),
    '[]'::jsonb
  )
  INTO v_result
  FROM (
    SELECT
      jsonb_build_object(
        'empresa_id', e.id,
        'empresa_nombre', e.nombre,
        'licencia', e.licencia,
        'email', e.email,
        'telefono', e.telefono,
        'reason', cr.reason,
        'reason_detail', cr.reason_detail,
        'offered_discount', cr.offered_discount,
        'discount_accepted', cr.discount_accepted,
        'cancelled', cr.cancelled,
        'cancelled_at', cr.created_at,
        'request_id', cr.id
      ) AS row_data,
      cr.created_at AS cancelled_at
    FROM public.cancellation_requests cr
    JOIN public.empresas e
      ON e.id = cr.empresa_id
    WHERE cr.cancelled = true
  ) q;

  RETURN v_result;
END;
$$;


--
-- Name: fn_customer_intelligence_detail(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_customer_intelligence_detail(p_empresa_id uuid, p_cliente_id uuid, p_months integer DEFAULT 12, p_window_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_months integer := LEAST(36, GREATEST(3, COALESCE(p_months, 12)));
  v_window_days integer := LEAST(180, GREATEST(7, COALESCE(p_window_days, 30)));
  v_current_from date := current_date - (v_window_days - 1);
  v_previous_from date := current_date - (v_window_days * 2 - 1);
  v_history_from date := (date_trunc('month', current_date) - ((v_months - 1) || ' months')::interval)::date;
  v_result jsonb;
BEGIN
  IF p_empresa_id IS NULL OR p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'Empresa y cliente son obligatorios' USING ERRCODE = '22004';
  END IF;

  IF p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para consultar esta empresa'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.clientes c WHERE c.id = p_cliente_id AND c.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'El cliente no pertenece a la empresa' USING ERRCODE = '22023';
  END IF;

  WITH client_sales AS MATERIALIZED (
    SELECT v.id, v.folio, v.fecha, v.tipo::text AS type, v.status::text AS status,
      COALESCE(v.total_efectivo, v.total, 0)::numeric AS total
    FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND v.cliente_id = p_cliente_id
      AND v.fecha <= current_date
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('cancelado', 'borrador')
  ),
  months AS MATERIALIZED (
    SELECT generate_series(
      date_trunc('month', current_date)::date - ((v_months - 1) || ' months')::interval,
      date_trunc('month', current_date)::date,
      interval '1 month'
    )::date AS period
  ),
  month_sales AS MATERIALIZED (
    SELECT date_trunc('month', cs.fecha::timestamp)::date AS period,
      COUNT(*)::integer AS orders, COALESCE(SUM(cs.total), 0)::numeric AS total
    FROM client_sales cs
    WHERE cs.fecha >= v_history_from
    GROUP BY 1
  ),
  weeks AS MATERIALIZED (
    SELECT generate_series(
      date_trunc('week', current_date)::date - interval '15 weeks',
      date_trunc('week', current_date)::date,
      interval '1 week'
    )::date AS period
  ),
  week_sales AS MATERIALIZED (
    SELECT date_trunc('week', cs.fecha::timestamp)::date AS period,
      COUNT(*)::integer AS orders, COALESCE(SUM(cs.total), 0)::numeric AS total
    FROM client_sales cs
    WHERE cs.fecha >= date_trunc('week', current_date)::date - interval '15 weeks'
    GROUP BY 1
  ),
  product_sales AS MATERIALIZED (
    SELECT
      vl.producto_id,
      COALESCE(SUM(vl.cantidad), 0)::numeric AS history_qty,
      COALESCE(SUM(vl.total), 0)::numeric AS history_total,
      COALESCE(SUM(vl.cantidad) FILTER (WHERE cs.fecha >= v_current_from), 0)::numeric AS recent_qty,
      COALESCE(SUM(vl.total) FILTER (WHERE cs.fecha >= v_current_from), 0)::numeric AS recent_total,
      COALESCE(SUM(vl.cantidad) FILTER (WHERE cs.fecha >= v_previous_from AND cs.fecha < v_current_from), 0)::numeric AS previous_qty,
      COALESCE(SUM(vl.total) FILTER (WHERE cs.fecha >= v_previous_from AND cs.fecha < v_current_from), 0)::numeric AS previous_total,
      MAX(cs.fecha) AS last_purchase
    FROM client_sales cs
    JOIN public.venta_lineas vl ON vl.venta_id = cs.id
    WHERE cs.fecha >= v_history_from
      AND vl.producto_id IS NOT NULL
    GROUP BY vl.producto_id
  ),
  product_detail AS MATERIALIZED (
    SELECT
      ps.producto_id AS id,
      p.codigo,
      p.nombre,
      COALESCE(u.abreviatura, u.nombre, 'uds') AS unit,
      ps.history_qty,
      ps.history_total,
      ps.recent_qty,
      ps.recent_total,
      ps.previous_qty,
      ps.previous_total,
      ps.last_purchase,
      CASE
        WHEN ps.previous_qty > 0 THEN ROUND(((ps.recent_qty - ps.previous_qty) / ps.previous_qty) * 100, 1)
        WHEN ps.recent_qty > 0 THEN 100
        ELSE NULL
      END AS qty_change_pct,
      CASE
        WHEN ps.previous_total > 0 THEN ROUND(((ps.recent_total - ps.previous_total) / ps.previous_total) * 100, 1)
        WHEN ps.recent_total > 0 THEN 100
        ELSE NULL
      END AS total_change_pct,
      CASE
        WHEN ps.recent_qty = 0 AND ps.previous_qty > 0 THEN 'detenido'
        WHEN ps.previous_qty > 0 AND ps.recent_qty < ps.previous_qty * 0.85 THEN 'bajando'
        WHEN ps.previous_qty > 0 AND ps.recent_qty > ps.previous_qty * 1.15 THEN 'creciendo'
        ELSE 'estable'
      END AS trend
    FROM product_sales ps
    JOIN public.productos p ON p.id = ps.producto_id AND p.empresa_id = p_empresa_id
    LEFT JOIN public.unidades u ON u.id = p.unidad_venta_id
  ),
  client_summary AS MATERIALIZED (
    SELECT
      COUNT(*)::integer AS orders,
      COALESCE(SUM(total), 0)::numeric AS lifetime_total,
      MIN(fecha) AS first_purchase,
      MAX(fecha) AS last_purchase,
      COALESCE(SUM(total) FILTER (WHERE fecha >= v_current_from), 0)::numeric AS recent_total,
      COALESCE(SUM(total) FILTER (WHERE fecha >= v_previous_from AND fecha < v_current_from), 0)::numeric AS previous_total
    FROM client_sales
  )
  SELECT jsonb_build_object(
    'generated_at', now(),
    'window_days', v_window_days,
    'client', (
      SELECT jsonb_build_object(
        'id', c.id,
        'codigo', c.codigo,
        'nombre', c.nombre,
        'status', c.status,
        'signup_date', COALESCE(c.fecha_alta, c.created_at::date),
        'seller_name', COALESCE(pr.nombre, 'Sin vendedor'),
        'zone_name', COALESCE(z.nombre, 'Sin zona'),
        'first_purchase', cs.first_purchase,
        'last_purchase', cs.last_purchase,
        'orders', cs.orders,
        'lifetime_total', cs.lifetime_total,
        'avg_ticket', CASE WHEN cs.orders > 0 THEN ROUND(cs.lifetime_total / cs.orders, 2) ELSE 0 END,
        'recent_total', cs.recent_total,
        'previous_total', cs.previous_total,
        'change_pct', CASE
          WHEN cs.previous_total > 0 THEN ROUND(((cs.recent_total - cs.previous_total) / cs.previous_total) * 100, 1)
          WHEN cs.recent_total > 0 THEN 100 ELSE NULL END
      )
      FROM public.clientes c
      CROSS JOIN client_summary cs
      LEFT JOIN public.profiles pr ON pr.id = c.vendedor_id
      LEFT JOIN public.zonas z ON z.id = c.zona_id
      WHERE c.id = p_cliente_id AND c.empresa_id = p_empresa_id
    ),
    'monthly', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'period', m.period,
        'orders', COALESCE(ms.orders, 0),
        'total', COALESCE(ms.total, 0)
      ) ORDER BY m.period)
      FROM months m LEFT JOIN month_sales ms ON ms.period = m.period
    ), '[]'::jsonb),
    'weekly', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'period', w.period,
        'orders', COALESCE(ws.orders, 0),
        'total', COALESCE(ws.total, 0)
      ) ORDER BY w.period)
      FROM weeks w LEFT JOIN week_sales ws ON ws.period = w.period
    ), '[]'::jsonb),
    'products', COALESCE((
      SELECT jsonb_agg(to_jsonb(pd) ORDER BY
        CASE pd.trend WHEN 'detenido' THEN 1 WHEN 'bajando' THEN 2 WHEN 'creciendo' THEN 3 ELSE 4 END,
        pd.previous_total DESC,
        pd.nombre
      ) FROM product_detail pd
    ), '[]'::jsonb),
    'recent_purchases', COALESCE((
      SELECT jsonb_agg(to_jsonb(r) ORDER BY r.fecha DESC, r.id DESC)
      FROM (
        SELECT cs.id, cs.folio, cs.fecha, cs.type, cs.status, cs.total
        FROM client_sales cs ORDER BY cs.fecha DESC, cs.id DESC LIMIT 25
      ) r
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_customer_intelligence_detail(p_empresa_id uuid, p_cliente_id uuid, p_months integer, p_window_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_customer_intelligence_detail(p_empresa_id uuid, p_cliente_id uuid, p_months integer, p_window_days integer) IS 'Historia mensual, semanal y por producto de un cliente.';


--
-- Name: fn_customer_intelligence_product_dimensions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_customer_intelligence_product_dimensions(p_empresa_id uuid, p_cliente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF p_empresa_id IS NULL OR p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'Empresa y cliente son obligatorios' USING ERRCODE = '22004';
  END IF;

  IF p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para consultar esta empresa'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.clientes c
    WHERE c.id = p_cliente_id
      AND c.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'El cliente no pertenece a la empresa' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', dimensions.id,
    'category_name', dimensions.category_name,
    'brand_name', dimensions.brand_name
  ) ORDER BY dimensions.id), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT DISTINCT
      p.id,
      COALESCE(cl.nombre, 'Sin categoría') AS category_name,
      COALESCE(m.nombre, 'Sin marca') AS brand_name
    FROM public.ventas v
    JOIN public.venta_lineas vl ON vl.venta_id = v.id
    JOIN public.productos p
      ON p.id = vl.producto_id
     AND p.empresa_id = p_empresa_id
    LEFT JOIN public.clasificaciones cl ON cl.id = p.clasificacion_id
    LEFT JOIN public.marcas m ON m.id = p.marca_id
    WHERE v.empresa_id = p_empresa_id
      AND v.cliente_id = p_cliente_id
      AND v.fecha <= current_date
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('cancelado', 'borrador')
      AND vl.producto_id IS NOT NULL
  ) dimensions;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_customer_intelligence_product_dimensions(p_empresa_id uuid, p_cliente_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_customer_intelligence_product_dimensions(p_empresa_id uuid, p_cliente_id uuid) IS 'Categoría y marca de los productos comprados por un cliente; no recalcula importes ni cantidades.';


--
-- Name: fn_customer_intelligence_snapshot(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_customer_intelligence_snapshot(p_empresa_id uuid, p_window_days integer DEFAULT 30, p_inactive_days integer DEFAULT 45) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_window_days integer := LEAST(180, GREATEST(7, COALESCE(p_window_days, 30)));
  v_inactive_days integer := LEAST(365, GREATEST(15, COALESCE(p_inactive_days, 45)));
  v_current_from date := current_date - (v_window_days - 1);
  v_previous_from date := current_date - (v_window_days * 2 - 1);
  v_result jsonb;
BEGIN
  IF p_empresa_id IS NULL THEN
    RAISE EXCEPTION 'p_empresa_id es obligatorio' USING ERRCODE = '22004';
  END IF;

  IF p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para consultar esta empresa'
      USING ERRCODE = '42501';
  END IF;

  WITH eligible_sales AS MATERIALIZED (
    SELECT v.id, v.cliente_id, v.fecha, COALESCE(v.total_efectivo, v.total, 0)::numeric AS total
    FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND v.cliente_id IS NOT NULL
      AND v.fecha <= current_date
      AND COALESCE(v.es_saldo_inicial, false) = false
      AND v.status::text NOT IN ('cancelado', 'borrador')
  ),
  sale_days AS MATERIALIZED (
    SELECT DISTINCT es.cliente_id, es.fecha
    FROM eligible_sales es
  ),
  sale_gaps AS MATERIALIZED (
    SELECT
      sd.cliente_id,
      sd.fecha - LAG(sd.fecha) OVER (PARTITION BY sd.cliente_id ORDER BY sd.fecha) AS gap_days
    FROM sale_days sd
  ),
  gap_stats AS MATERIALIZED (
    SELECT sg.cliente_id, ROUND(AVG(sg.gap_days) FILTER (WHERE sg.gap_days > 0), 1) AS avg_gap_days
    FROM sale_gaps sg
    GROUP BY sg.cliente_id
  ),
  sales_stats AS MATERIALIZED (
    SELECT
      es.cliente_id,
      MIN(es.fecha) AS first_purchase,
      MAX(es.fecha) AS last_purchase,
      COUNT(*)::integer AS lifetime_orders,
      COALESCE(SUM(es.total), 0)::numeric AS lifetime_total,
      COUNT(DISTINCT date_trunc('month', es.fecha::timestamp))::integer AS active_months,
      COUNT(*) FILTER (WHERE es.fecha >= v_current_from)::integer AS recent_orders,
      COALESCE(SUM(es.total) FILTER (WHERE es.fecha >= v_current_from), 0)::numeric AS recent_total,
      COUNT(*) FILTER (WHERE es.fecha >= v_previous_from AND es.fecha < v_current_from)::integer AS previous_orders,
      COALESCE(SUM(es.total) FILTER (WHERE es.fecha >= v_previous_from AND es.fecha < v_current_from), 0)::numeric AS previous_total,
      MAX(es.fecha) FILTER (WHERE es.fecha < v_current_from) AS purchase_before_window
    FROM eligible_sales es
    GROUP BY es.cliente_id
  ),
  client_base AS MATERIALIZED (
    SELECT
      c.id,
      c.codigo,
      c.nombre,
      c.status,
      COALESCE(c.fecha_alta, c.created_at::date) AS signup_date,
      c.vendedor_id,
      COALESCE(pr.nombre, 'Sin vendedor') AS seller_name,
      c.zona_id,
      COALESCE(z.nombre, 'Sin zona') AS zone_name,
      ss.first_purchase,
      ss.last_purchase,
      COALESCE(ss.lifetime_orders, 0) AS lifetime_orders,
      COALESCE(ss.lifetime_total, 0) AS lifetime_total,
      COALESCE(ss.active_months, 0) AS active_months,
      COALESCE(ss.recent_orders, 0) AS recent_orders,
      COALESCE(ss.recent_total, 0) AS recent_total,
      COALESCE(ss.previous_orders, 0) AS previous_orders,
      COALESCE(ss.previous_total, 0) AS previous_total,
      ss.purchase_before_window,
      gs.avg_gap_days,
      CASE WHEN ss.last_purchase IS NULL THEN NULL ELSE current_date - ss.last_purchase END AS days_since_purchase,
      CASE
        WHEN COALESCE(ss.lifetime_orders, 0) = 0 THEN 0
        ELSE ROUND(ss.lifetime_total / ss.lifetime_orders, 2)
      END AS avg_ticket,
      CASE
        WHEN COALESCE(ss.previous_total, 0) > 0
          THEN ROUND(((COALESCE(ss.recent_total, 0) - ss.previous_total) / ss.previous_total) * 100, 1)
        WHEN COALESCE(ss.recent_total, 0) > 0 THEN 100
        ELSE NULL
      END AS change_pct,
      CASE
        WHEN ss.last_purchase IS NULL THEN NULL
        ELSE ss.last_purchase + GREATEST(7, CEIL(COALESCE(gs.avg_gap_days, v_inactive_days))::integer)
      END AS expected_next_purchase
    FROM public.clientes c
    LEFT JOIN sales_stats ss ON ss.cliente_id = c.id
    LEFT JOIN gap_stats gs ON gs.cliente_id = c.id
    LEFT JOIN public.profiles pr ON pr.id = c.vendedor_id
    LEFT JOIN public.zonas z ON z.id = c.zona_id
    WHERE c.empresa_id = p_empresa_id
  ),
  classified AS MATERIALIZED (
    SELECT
      cb.*,
      CASE
        WHEN cb.lifetime_orders = 0 THEN 'sin_compras'
        WHEN cb.first_purchase >= v_current_from THEN 'nuevo'
        WHEN cb.recent_orders > 0
             AND cb.previous_orders = 0
             AND cb.purchase_before_window < v_previous_from THEN 'recuperado'
        WHEN cb.days_since_purchase > v_inactive_days * 2 THEN 'perdido'
        WHEN cb.days_since_purchase > v_inactive_days THEN 'inactivo'
        WHEN cb.expected_next_purchase IS NOT NULL
             AND current_date > cb.expected_next_purchase + GREATEST(3, CEIL(COALESCE(cb.avg_gap_days, 7) * 0.5)::integer)
          THEN 'en_riesgo'
        WHEN cb.previous_total > 0 AND cb.recent_total < cb.previous_total * 0.85 THEN 'bajando'
        WHEN cb.previous_total > 0 AND cb.recent_total > cb.previous_total * 1.15 THEN 'creciendo'
        ELSE 'estable'
      END AS segment,
      CASE
        WHEN cb.expected_next_purchase IS NULL THEN NULL
        ELSE current_date - cb.expected_next_purchase
      END AS days_overdue
    FROM client_base cb
  ),
  segment_stats AS MATERIALIZED (
    SELECT
      c.segment,
      COUNT(*)::integer AS clients,
      COALESCE(SUM(c.recent_total), 0)::numeric AS recent_total,
      COALESCE(SUM(c.previous_total), 0)::numeric AS previous_total,
      COALESCE(SUM(c.lifetime_total), 0)::numeric AS lifetime_total
    FROM classified c
    GROUP BY c.segment
  ),
  portfolio_months AS MATERIALIZED (
    SELECT generate_series(
      date_trunc('month', current_date)::date - interval '11 months',
      date_trunc('month', current_date)::date,
      interval '1 month'
    )::date AS month
  ),
  portfolio_sales AS MATERIALIZED (
    SELECT
      date_trunc('month', es.fecha::timestamp)::date AS month,
      COUNT(*)::integer AS orders,
      COUNT(DISTINCT es.cliente_id)::integer AS buyers,
      COALESCE(SUM(es.total), 0)::numeric AS total
    FROM eligible_sales es
    WHERE es.fecha >= date_trunc('month', current_date)::date - interval '11 months'
    GROUP BY 1
  )
  SELECT jsonb_build_object(
    'generated_at', now(),
    'window_days', v_window_days,
    'inactive_days', v_inactive_days,
    'metrics', jsonb_build_object(
      'clients_total', (SELECT COUNT(*) FROM classified),
      'active_clients', (SELECT COUNT(*) FROM classified WHERE status = 'activo'),
      'buyers_lifetime', (SELECT COUNT(*) FROM classified WHERE lifetime_orders > 0),
      'buyers_recent', (SELECT COUNT(*) FROM classified WHERE recent_orders > 0),
      'new_signups', (SELECT COUNT(*) FROM classified WHERE signup_date >= v_current_from),
      'retained_buyers', (SELECT COUNT(*) FROM classified WHERE recent_orders > 0 AND previous_orders > 0),
      'previous_buyers', (SELECT COUNT(*) FROM classified WHERE previous_orders > 0),
      'retention_pct', COALESCE((
        SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE recent_orders > 0 AND previous_orders > 0)
          / NULLIF(COUNT(*) FILTER (WHERE previous_orders > 0), 0), 1)
        FROM classified
      ), 0),
      'recent_revenue', (SELECT COALESCE(SUM(recent_total), 0) FROM classified),
      'previous_revenue', (SELECT COALESCE(SUM(previous_total), 0) FROM classified),
      'revenue_at_risk', (SELECT COALESCE(SUM(previous_total), 0) FROM classified WHERE segment IN ('bajando', 'en_riesgo', 'inactivo', 'perdido')),
      'avg_ticket_recent', COALESCE((
        SELECT ROUND(SUM(recent_total) / NULLIF(SUM(recent_orders), 0), 2) FROM classified
      ), 0)
    ),
    'segments', COALESCE((
      SELECT jsonb_object_agg(ss.segment, jsonb_build_object(
        'clients', ss.clients,
        'recent_total', ss.recent_total,
        'previous_total', ss.previous_total,
        'lifetime_total', ss.lifetime_total
      )) FROM segment_stats ss
    ), '{}'::jsonb),
    'monthly_portfolio', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'month', pm.month,
        'orders', COALESCE(ps.orders, 0),
        'buyers', COALESCE(ps.buyers, 0),
        'total', COALESCE(ps.total, 0)
      ) ORDER BY pm.month)
      FROM portfolio_months pm
      LEFT JOIN portfolio_sales ps ON ps.month = pm.month
    ), '[]'::jsonb),
    'clients', COALESCE((
      SELECT jsonb_agg(to_jsonb(c) ORDER BY
        CASE c.segment
          WHEN 'en_riesgo' THEN 1 WHEN 'bajando' THEN 2 WHEN 'inactivo' THEN 3
          WHEN 'perdido' THEN 4 WHEN 'recuperado' THEN 5 WHEN 'creciendo' THEN 6
          WHEN 'nuevo' THEN 7 WHEN 'estable' THEN 8 ELSE 9
        END,
        c.previous_total DESC,
        c.nombre
      ) FROM classified c
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_customer_intelligence_snapshot(p_empresa_id uuid, p_window_days integer, p_inactive_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_customer_intelligence_snapshot(p_empresa_id uuid, p_window_days integer, p_inactive_days integer) IS 'Radar agregado y segmentación de comportamiento de clientes por empresa.';


--
-- Name: fn_disponible_almacen(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_disponible_almacen(p_producto_id uuid, p_almacen_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((SELECT cantidad FROM public.stock_almacen
                    WHERE producto_id = p_producto_id AND almacen_id = p_almacen_id LIMIT 1), 0)
       - COALESCE((SELECT SUM(cantidad) FROM public.stock_apartado
                    WHERE producto_id = p_producto_id AND almacen_id = p_almacen_id), 0)
$$;


--
-- Name: fn_disponible_lotes(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_disponible_lotes(p_almacen_id uuid, p_producto_id uuid, p_excluir_venta_id uuid DEFAULT NULL::uuid) RETURNS TABLE(lote_id uuid, codigo text, fecha_caducidad date, cantidad numeric, apartado numeric, disponible numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH emp AS (SELECT public.get_my_empresa_id() AS id)
  SELECT sl.lote_id,
         l.codigo,
         l.fecha_caducidad,
         sl.cantidad,
         COALESCE(ap.apartado, 0) AS apartado,
         sl.cantidad - COALESCE(ap.apartado, 0) AS disponible
    FROM public.stock_lotes sl
    JOIN public.lotes l ON l.id = sl.lote_id
    JOIN emp ON emp.id = sl.empresa_id
    LEFT JOIN LATERAL (
      SELECT SUM(sa.cantidad) AS apartado
        FROM public.stock_apartado sa
       WHERE sa.empresa_id = sl.empresa_id
         AND sa.almacen_id = sl.almacen_id
         AND sa.producto_id = sl.producto_id
         AND sa.lote_id = sl.lote_id
         AND (p_excluir_venta_id IS NULL OR sa.venta_id <> p_excluir_venta_id)
    ) ap ON TRUE
   WHERE sl.almacen_id = p_almacen_id
     AND sl.producto_id = p_producto_id
     AND l.activo IS DISTINCT FROM false
     AND sl.cantidad > 0
   ORDER BY COALESCE(l.fecha_caducidad, DATE '9999-12-31'), l.codigo;
$$;


--
-- Name: fn_doc_mueve_stock(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_doc_mueve_stock(p_doc uuid, p_producto uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM (
      SELECT m.producto_id, x.almacen_id, SUM(x.delta) AS neto
      FROM public.movimientos_inventario m
      CROSS JOIN LATERAL (VALUES
        (CASE WHEN m.tipo::text IN ('entrada','transferencia') THEN m.almacen_destino_id END,
         COALESCE(m.cantidad, 0)),
        (CASE WHEN m.tipo::text IN ('salida','transferencia')
                OR (m.tipo::text = 'entrada' AND COALESCE(m.notas, '') NOT ILIKE '%ya descontado%')
              THEN m.almacen_origen_id END,
         -COALESCE(m.cantidad, 0))
      ) AS x(almacen_id, delta)
      WHERE m.referencia_id = p_doc
        AND (p_producto IS NULL OR m.producto_id = p_producto)
        AND x.almacen_id IS NOT NULL
      GROUP BY m.producto_id, x.almacen_id
    ) n
    WHERE abs(n.neto) > 0.000001
  );
$$;


--
-- Name: fn_factor_neto_compra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_factor_neto_compra(p_compra_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN COALESCE(c.descuento_total, 0) = 0
     AND COALESCE(c.ajuste_total, 0) = 0 THEN 1::numeric
    WHEN COALESCE(t.total_lineas, 0) <= 0 THEN 1::numeric
    ELSE GREATEST(COALESCE(c.total, 0), 0) / t.total_lineas
  END
  FROM public.compras c
  LEFT JOIN LATERAL (
    SELECT COALESCE(SUM(cl.total), 0) AS total_lineas
    FROM public.compra_lineas cl
    WHERE cl.compra_id = c.id
  ) t ON true
  WHERE c.id = p_compra_id;
$$;


--
-- Name: fn_fill_venta_linea_almacen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_fill_venta_linea_almacen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.almacen_id IS NULL THEN
    SELECT v.almacen_id INTO NEW.almacen_id
    FROM public.ventas v
    WHERE v.id = NEW.venta_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_fill_venta_linea_comision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_fill_venta_linea_comision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid; v_tarifa uuid; v_cliente uuid; v_pct numeric;
BEGIN
  v_pct := NEW.comision_pct;

  -- Solo resolver desde la lista de precios si la línea viene sin porcentaje
  IF v_pct IS NULL THEN
    SELECT v.empresa_id, v.tarifa_id, v.cliente_id INTO v_empresa, v_tarifa, v_cliente
    FROM ventas v WHERE v.id = NEW.venta_id;
    v_pct := public.resolver_comision_pct_linea(v_empresa, v_tarifa, v_cliente, NEW.producto_id);
  END IF;

  NEW.comision_pct := v_pct;
  NEW.comision_monto := CASE WHEN v_pct IS NULL THEN NULL
    ELSE ROUND(COALESCE(NEW.subtotal, 0) * v_pct / 100.0, 2) END;
  RETURN NEW;
END; $$;


--
-- Name: fn_guard_empresa_facturama(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_guard_empresa_facturama() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (NEW.facturama_ambiente IS DISTINCT FROM OLD.facturama_ambiente
      OR NEW.csd_no_certificado IS DISTINCT FROM OLD.csd_no_certificado
      OR NEW.csd_vence IS DISTINCT FROM OLD.csd_vence)
     AND COALESCE(auth.role(), '') <> 'service_role'
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'El ambiente de facturación y el CSD se cambian desde Facturación › Configuración.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_inventory_intelligence_snapshot(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_inventory_intelligence_snapshot(p_empresa_id uuid, p_window_days integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_days integer := LEAST(365, GREATEST(1, COALESCE(p_window_days, 60)));
  v_since date := current_date - v_days;
  v_history_since date := current_date - 365;
  v_bucket text := CASE WHEN v_days > 90 THEN 'week' ELSE 'day' END;
  v_result jsonb;
BEGIN
  IF p_empresa_id IS NULL THEN
    RAISE EXCEPTION 'p_empresa_id es obligatorio' USING ERRCODE = '22004';
  END IF;

  IF p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado para consultar esta empresa' USING ERRCODE = '42501';
  END IF;

  WITH sales_by_product AS MATERIALIZED (
    SELECT
      vl.producto_id,
      COALESCE(SUM(vl.cantidad) FILTER (WHERE v.fecha >= v_since), 0) AS sold_units,
      COALESCE(SUM(COALESCE(vl.total, 0)) FILTER (WHERE v.fecha >= v_since), 0) AS revenue,
      MAX(v.fecha) AS last_sale_at
    FROM public.venta_lineas vl
    JOIN public.ventas v ON v.id = vl.venta_id AND v.empresa_id = p_empresa_id
    WHERE vl.empresa_id = p_empresa_id
      AND vl.producto_id IS NOT NULL
      AND v.status::text <> 'cancelado'
      AND v.fecha >= v_history_since
    GROUP BY vl.producto_id
  ),
  last_inbound AS MATERIALIZED (
    SELECT producto_id, MAX(fecha) AS last_inbound_at
    FROM public.movimientos_inventario
    WHERE empresa_id = p_empresa_id
      AND producto_id IS NOT NULL
      AND tipo::text = 'entrada'
      AND fecha >= v_history_since
    GROUP BY producto_id
  ),
  movement_trend AS MATERIALIZED (
    SELECT date_trunc(v_bucket, fecha::timestamp)::date AS fecha,
           tipo::text AS tipo,
           SUM(ABS(cantidad)) AS cantidad
    FROM public.movimientos_inventario
    WHERE empresa_id = p_empresa_id AND fecha >= v_since
    GROUP BY 1, 2
  ),
  recent_movements AS MATERIALIZED (
    SELECT id, fecha, created_at, tipo::text AS tipo, cantidad, producto_id, lote_id,
           referencia_tipo, referencia_id, almacen_origen_id, almacen_destino_id, notas
    FROM public.movimientos_inventario
    WHERE empresa_id = p_empresa_id AND fecha >= v_since
    ORDER BY created_at DESC
    LIMIT 500
  ),
  movement_totals AS MATERIALIZED (
    SELECT tipo::text AS tipo, COUNT(*) AS cantidad
    FROM public.movimientos_inventario
    WHERE empresa_id = p_empresa_id AND fecha >= v_since
    GROUP BY tipo
  ),
  active_lot_stock AS MATERIALIZED (
    SELECT sl.lote_id, sl.producto_id, sl.almacen_id, sl.cantidad,
           l.codigo, l.fecha_caducidad, l.fecha_fabricacion, l.costo, l.created_at
    FROM public.stock_lotes sl
    JOIN public.lotes l ON l.id = sl.lote_id AND l.empresa_id = p_empresa_id AND l.activo = true
    WHERE sl.empresa_id = p_empresa_id AND sl.cantidad > 0
  )
  SELECT jsonb_build_object(
    'window_days', v_days,
    'sales_by_product', COALESCE((SELECT jsonb_agg(to_jsonb(s)) FROM sales_by_product s), '[]'::jsonb),
    'last_inbound', COALESCE((SELECT jsonb_agg(to_jsonb(i)) FROM last_inbound i), '[]'::jsonb),
    'movement_trend', COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.fecha) FROM movement_trend t), '[]'::jsonb),
    'recent_movements', COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at DESC) FROM recent_movements m), '[]'::jsonb),
    'movement_count', COALESCE((SELECT SUM(mt.cantidad) FROM movement_totals mt), 0),
    'movement_type_counts', COALESCE((SELECT jsonb_object_agg(mt.tipo, mt.cantidad) FROM movement_totals mt WHERE mt.tipo IS NOT NULL), '{}'::jsonb),
    'lot_stock', COALESCE((SELECT jsonb_agg(to_jsonb(ls)) FROM active_lot_stock ls), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION fn_inventory_intelligence_snapshot(p_empresa_id uuid, p_window_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_inventory_intelligence_snapshot(p_empresa_id uuid, p_window_days integer) IS 'Snapshot agregado y de solo lectura para Inteligencia de Inventario.';


--
-- Name: fn_inventory_kardex_at_date(uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_inventory_kardex_at_date(p_empresa_id uuid, p_producto_id uuid, p_almacen_id uuid, p_fecha_desde date, p_fecha_hasta date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_tz text;
  v_start timestamptz;
  v_end timestamptz;
  v_today date;
  v_current numeric := 0;
  v_opening numeric := 0;
  v_final numeric := 0;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    p_empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No tienes permiso para consultar esta empresa' USING ERRCODE = '42501';
  END IF;

  IF p_producto_id IS NULL OR p_almacen_id IS NULL
     OR p_fecha_desde IS NULL OR p_fecha_hasta IS NULL THEN
    RAISE EXCEPTION 'Producto, ubicación y fechas son obligatorios' USING ERRCODE = '22004';
  END IF;

  IF p_fecha_desde > p_fecha_hasta THEN
    RAISE EXCEPTION 'La fecha inicial no puede ser posterior a la final' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(NULLIF(e.zona_horaria, ''), 'America/Mexico_City')
    INTO v_tz
  FROM public.empresas e
  WHERE e.id = p_empresa_id;

  IF v_tz IS NULL THEN
    RAISE EXCEPTION 'Empresa no encontrada' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.productos p
    WHERE p.id = p_producto_id AND p.empresa_id = p_empresa_id
  ) OR NOT EXISTS (
    SELECT 1 FROM public.almacenes a
    WHERE a.id = p_almacen_id AND a.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'Producto o ubicación no pertenece a la empresa' USING ERRCODE = '42501';
  END IF;

  v_today := (now() AT TIME ZONE v_tz)::date;
  IF p_fecha_hasta > v_today THEN
    RAISE EXCEPTION 'No se puede consultar una fecha futura' USING ERRCODE = '22023';
  END IF;

  v_start := (p_fecha_desde::timestamp AT TIME ZONE v_tz);
  v_end := ((p_fecha_hasta + 1)::timestamp AT TIME ZONE v_tz);

  SELECT COALESCE(s.cantidad, 0)::numeric
    INTO v_current
  FROM public.stock_almacen s
  WHERE s.empresa_id = p_empresa_id
    AND s.producto_id = p_producto_id
    AND s.almacen_id = p_almacen_id;
  v_current := COALESCE(v_current, 0);

  WITH later AS (
    SELECT m.created_at,
      (CASE WHEN m.almacen_destino_id = p_almacen_id THEN COALESCE(m.cantidad, 0) ELSE 0 END
       - CASE WHEN m.almacen_origen_id = p_almacen_id THEN COALESCE(m.cantidad, 0) ELSE 0 END)::numeric AS delta
    FROM public.movimientos_inventario m
    WHERE m.empresa_id = p_empresa_id
      AND m.producto_id = p_producto_id
      AND (m.almacen_origen_id = p_almacen_id OR m.almacen_destino_id = p_almacen_id)
  )
  SELECT
    v_current - COALESCE(SUM(delta) FILTER (WHERE created_at >= v_start), 0),
    v_current - COALESCE(SUM(delta) FILTER (WHERE created_at >= v_end), 0)
  INTO v_opening, v_final
  FROM later;

  WITH movements AS MATERIALIZED (
    SELECT
      m.id,
      m.fecha,
      m.created_at,
      m.tipo::text AS tipo,
      m.referencia_tipo,
      m.referencia_id,
      m.notas,
      m.user_id,
      m.lote_id,
      m.almacen_origen_id,
      ao.nombre AS origen,
      m.almacen_destino_id,
      ad.nombre AS destino,
      COALESCE(m.cantidad, 0)::numeric AS cantidad,
      (CASE WHEN m.almacen_destino_id = p_almacen_id THEN COALESCE(m.cantidad, 0) ELSE 0 END
       - CASE WHEN m.almacen_origen_id = p_almacen_id THEN COALESCE(m.cantidad, 0) ELSE 0 END)::numeric AS delta
    FROM public.movimientos_inventario m
    LEFT JOIN public.almacenes ao ON ao.id = m.almacen_origen_id
    LEFT JOIN public.almacenes ad ON ad.id = m.almacen_destino_id
    WHERE m.empresa_id = p_empresa_id
      AND m.producto_id = p_producto_id
      AND (m.almacen_origen_id = p_almacen_id OR m.almacen_destino_id = p_almacen_id)
      AND m.created_at >= v_start
      AND m.created_at < v_end
  ),
  running AS MATERIALIZED (
    SELECT m.*,
      (v_opening + SUM(m.delta) OVER (
        ORDER BY m.created_at, m.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
      ))::numeric AS balance
    FROM movements m
  )
  SELECT jsonb_build_object(
    'generated_at', now(),
    'timezone', v_tz,
    'from_date', p_fecha_desde,
    'to_date', p_fecha_hasta,
    'cutoff_at', v_end,
    'producto', (SELECT jsonb_build_object('id', p.id, 'codigo', p.codigo, 'nombre', p.nombre)
                 FROM public.productos p WHERE p.id = p_producto_id),
    'ubicacion', (SELECT jsonb_build_object('id', a.id, 'nombre', a.nombre, 'tipo', a.tipo, 'activa', a.activo)
                  FROM public.almacenes a WHERE a.id = p_almacen_id),
    'metrics', jsonb_build_object(
      'opening_stock', v_opening,
      'final_stock', v_final,
      'current_stock', v_current,
      'entries', COALESCE((SELECT SUM(r.delta) FROM running r WHERE r.delta > 0), 0),
      'exits', ABS(COALESCE((SELECT SUM(r.delta) FROM running r WHERE r.delta < 0), 0)),
      'movements', (SELECT COUNT(*) FROM running),
      'reconciled', ABS(v_opening + COALESCE((SELECT SUM(r.delta) FROM running r), 0) - v_final) < 0.0001
    ),
    'rows', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id,
        'fecha_documento', r.fecha,
        'registrado_at', r.created_at,
        'tipo', r.tipo,
        'referencia_tipo', r.referencia_tipo,
        'referencia_id', r.referencia_id,
        'notas', r.notas,
        'user_id', r.user_id,
        'lote_id', r.lote_id,
        'almacen_origen_id', r.almacen_origen_id,
        'origen', r.origen,
        'almacen_destino_id', r.almacen_destino_id,
        'destino', r.destino,
        'cantidad', r.cantidad,
        'delta', r.delta,
        'saldo', r.balance
      ) ORDER BY r.created_at, r.id)
      FROM running r
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_inventory_stock_at_date(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_inventory_stock_at_date(p_empresa_id uuid, p_fecha date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_tz text;
  v_cutoff timestamptz;
  v_today date;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    p_empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No tienes permiso para consultar esta empresa' USING ERRCODE = '42501';
  END IF;

  IF p_fecha IS NULL THEN
    RAISE EXCEPTION 'La fecha de corte es obligatoria' USING ERRCODE = '22004';
  END IF;

  SELECT COALESCE(NULLIF(e.zona_horaria, ''), 'America/Mexico_City')
    INTO v_tz
  FROM public.empresas e
  WHERE e.id = p_empresa_id;

  IF v_tz IS NULL THEN
    RAISE EXCEPTION 'Empresa no encontrada' USING ERRCODE = 'P0002';
  END IF;

  v_today := (now() AT TIME ZONE v_tz)::date;
  IF p_fecha > v_today THEN
    RAISE EXCEPTION 'No se puede consultar una fecha futura' USING ERRCODE = '22023';
  END IF;

  -- Instante UTC que corresponde al inicio del día siguiente en la empresa.
  v_cutoff := ((p_fecha + 1)::timestamp AT TIME ZONE v_tz);

  WITH post_base AS MATERIALIZED (
    SELECT
      m.producto_id,
      m.almacen_origen_id,
      m.almacen_destino_id,
      COALESCE(m.cantidad, 0)::numeric AS cantidad
    FROM public.movimientos_inventario m
    WHERE m.empresa_id = p_empresa_id
      AND m.created_at >= v_cutoff
      AND m.producto_id IS NOT NULL
      AND (m.almacen_origen_id IS NOT NULL OR m.almacen_destino_id IS NOT NULL)
  ),
  post_delta AS MATERIALIZED (
    SELECT d.producto_id, d.almacen_id,
           SUM(d.delta)::numeric AS delta,
           COUNT(*)::integer AS movements_after_cutoff
    FROM (
      SELECT producto_id, almacen_destino_id AS almacen_id, cantidad AS delta
      FROM post_base WHERE almacen_destino_id IS NOT NULL
      UNION ALL
      SELECT producto_id, almacen_origen_id AS almacen_id, -cantidad AS delta
      FROM post_base WHERE almacen_origen_id IS NOT NULL
    ) d
    GROUP BY d.producto_id, d.almacen_id
  ),
  live AS MATERIALIZED (
    SELECT s.producto_id, s.almacen_id,
           COALESCE(s.cantidad, 0)::numeric AS current_quantity
    FROM public.stock_almacen s
    WHERE s.empresa_id = p_empresa_id
  ),
  keys AS MATERIALIZED (
    SELECT producto_id, almacen_id FROM live
    UNION
    SELECT producto_id, almacen_id FROM post_delta
  ),
  rows AS MATERIALIZED (
    SELECT
      k.producto_id,
      p.codigo AS product_code,
      p.nombre AS product_name,
      p.status::text AS product_status,
      p.clasificacion_id AS category_id,
      c.nombre AS category_name,
      p.marca_id AS brand_id,
      b.nombre AS brand_name,
      p.proveedor_preferido_id AS supplier_id,
      pr.nombre AS supplier_name,
      u.abreviatura AS unit_name,
      COALESCE(p.costo, 0)::numeric AS current_unit_cost,
      k.almacen_id AS location_id,
      a.nombre AS location_name,
      COALESCE(NULLIF(a.tipo, ''), 'almacen') AS location_type,
      COALESCE(a.activo, false) AS location_active,
      (COALESCE(l.current_quantity, 0) - COALESCE(pd.delta, 0))::numeric AS quantity,
      COALESCE(l.current_quantity, 0)::numeric AS current_quantity,
      COALESCE(pd.delta, 0)::numeric AS change_since_cutoff,
      COALESCE(pd.movements_after_cutoff, 0)::integer AS movements_after_cutoff
    FROM keys k
    JOIN public.productos p
      ON p.id = k.producto_id AND p.empresa_id = p_empresa_id
    JOIN public.almacenes a
      ON a.id = k.almacen_id AND a.empresa_id = p_empresa_id
    LEFT JOIN live l
      ON l.producto_id = k.producto_id AND l.almacen_id = k.almacen_id
    LEFT JOIN post_delta pd
      ON pd.producto_id = k.producto_id AND pd.almacen_id = k.almacen_id
    LEFT JOIN public.clasificaciones c ON c.id = p.clasificacion_id
    LEFT JOIN public.marcas b ON b.id = p.marca_id
    LEFT JOIN public.proveedores pr ON pr.id = p.proveedor_preferido_id
    LEFT JOIN public.unidades u ON u.id = p.unidad_venta_id
    WHERE COALESCE(l.current_quantity, 0) <> 0
       OR COALESCE(pd.delta, 0) <> 0
  )
  SELECT jsonb_build_object(
    'generated_at', now(),
    'cutoff_date', p_fecha,
    'cutoff_at', v_cutoff,
    'timezone', v_tz,
    'method', 'current_stock_minus_later_movements',
    'ledger_started_at', (
      SELECT MIN(m.created_at) FROM public.movimientos_inventario m
      WHERE m.empresa_id = p_empresa_id
    ),
    'metrics', jsonb_build_object(
      'units', COALESCE((SELECT SUM(r.quantity) FROM rows r), 0),
      'products', (SELECT COUNT(DISTINCT r.producto_id) FROM rows r WHERE r.quantity <> 0),
      'locations', (SELECT COUNT(DISTINCT r.location_id) FROM rows r WHERE r.quantity <> 0),
      'warehouse_units', COALESCE((SELECT SUM(r.quantity) FROM rows r WHERE r.location_type <> 'ruta'), 0),
      'route_units', COALESCE((SELECT SUM(r.quantity) FROM rows r WHERE r.location_type = 'ruta'), 0),
      'estimated_value_at_current_cost', COALESCE((SELECT SUM(r.quantity * r.current_unit_cost) FROM rows r), 0),
      'movements_reversed', COALESCE((SELECT SUM(r.movements_after_cutoff) FROM rows r), 0)
    ),
    'rows', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'producto_id', r.producto_id,
        'codigo', r.product_code,
        'producto', r.product_name,
        'producto_status', r.product_status,
        'categoria_id', r.category_id,
        'categoria', r.category_name,
        'marca_id', r.brand_id,
        'marca', r.brand_name,
        'proveedor_id', r.supplier_id,
        'proveedor', r.supplier_name,
        'unidad', r.unit_name,
        'costo_actual', r.current_unit_cost,
        'almacen_id', r.location_id,
        'almacen', r.location_name,
        'ubicacion_tipo', r.location_type,
        'ubicacion_activa', r.location_active,
        'cantidad', r.quantity,
        'cantidad_actual', r.current_quantity,
        'diferencia_actual', r.current_quantity - r.quantity,
        'movimientos_posteriores', r.movements_after_cutoff
      ) ORDER BY r.product_name, r.location_type, r.location_name)
      FROM rows r
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_log_solicitud_traspaso(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_log_solicitud_traspaso(p_solicitud_id uuid, p_empresa_id uuid, p_accion text, p_detalle jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_nombre text;
BEGIN
  SELECT nombre INTO v_nombre FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;
  INSERT INTO public.solicitud_traspaso_historial (empresa_id, solicitud_id, accion, user_id, user_nombre, detalle)
  VALUES (p_empresa_id, p_solicitud_id, p_accion, auth.uid(), v_nombre, p_detalle);
END; $$;


--
-- Name: fn_logistica_concentrado_pedidos_v3(uuid, date, date, text, text[], text, uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_concentrado_pedidos_v3(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_field text DEFAULT 'fecha'::text, p_statuses text[] DEFAULT NULL::text[], p_tipo text DEFAULT 'pedido'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_page_size integer := CASE WHEN COALESCE(p_page_size, 50) <= 0 THEN NULL ELSE LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 500) END;
  v_offset integer := CASE WHEN COALESCE(p_page_size, 50) <= 0 THEN 0 ELSE GREATEST(COALESCE(p_offset, 0), 0) END;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH filtered_ventas AS MATERIALIZED (
    SELECT
      v.id,
      v.folio,
      v.fecha,
      v.fecha_entrega,
      v.status::text AS status,
      v.tipo::text AS tipo,
      v.total,
      v.cliente_id,
      v.vendedor_id,
      c.nombre AS cliente_nombre,
      pv.nombre AS vendedor_nombre
    FROM public.ventas v
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    LEFT JOIN public.profiles pv ON pv.id = v.vendedor_id
    WHERE v.empresa_id = p_empresa_id
      AND (COALESCE(cardinality(p_statuses), 0) = 0 OR v.status::text = ANY(p_statuses))
      AND (COALESCE(p_tipo, 'todos') = 'todos' OR v.tipo::text = p_tipo)
      AND (p_vendedor_ids IS NULL OR cardinality(p_vendedor_ids) = 0 OR v.vendedor_id = ANY(p_vendedor_ids))
      AND (
        COALESCE(p_fecha_field, 'fecha') <> 'fecha_entrega'
        OR ((p_fecha_desde IS NULL OR v.fecha_entrega >= p_fecha_desde) AND (p_fecha_hasta IS NULL OR v.fecha_entrega <= p_fecha_hasta))
      )
      AND (
        COALESCE(p_fecha_field, 'fecha') = 'fecha_entrega'
        OR ((p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde) AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta))
      )
  ),
  page_ventas AS MATERIALIZED (
    SELECT *
    FROM filtered_ventas
    ORDER BY fecha_entrega ASC NULLS LAST, public.folio_orden(folio) ASC NULLS LAST, folio ASC NULLS LAST, id
    LIMIT v_page_size OFFSET v_offset
  ),
  venta_producto AS MATERIALIZED (
    SELECT vl.venta_id, vl.producto_id, SUM(COALESCE(vl.cantidad, 0))::numeric AS requerido
    FROM public.venta_lineas vl
    INNER JOIN page_ventas pv ON pv.id = vl.venta_id
    GROUP BY vl.venta_id, vl.producto_id
  ),
  entrega_producto AS MATERIALIZED (
    SELECT e.pedido_id AS venta_id, el.producto_id, SUM(COALESCE(el.cantidad_entregada, 0))::numeric AS surtido
    FROM public.entregas e
    INNER JOIN page_ventas pv ON pv.id = e.pedido_id
    INNER JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.status::text IN ('surtido', 'cargado', 'hecho')
    GROUP BY e.pedido_id, el.producto_id
  ),
  pedido_agg AS MATERIALIZED (
    SELECT
      pv.id,
      COALESCE(SUM(vp.requerido), 0)::numeric AS requerido,
      COALESCE(SUM(COALESCE(ep.surtido, 0)), 0)::numeric AS surtido,
      COALESCE(SUM(GREATEST(0::numeric, vp.requerido - COALESCE(ep.surtido, 0))), 0)::numeric AS pendiente
    FROM page_ventas pv
    LEFT JOIN venta_producto vp ON vp.venta_id = pv.id
    LEFT JOIN entrega_producto ep ON ep.venta_id = vp.venta_id AND ep.producto_id IS NOT DISTINCT FROM vp.producto_id
    GROUP BY pv.id
  ),
  pedidos_json AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', pv.id,
      'folio', pv.folio,
      'fecha_entrega', pv.fecha_entrega,
      'status', pv.status,
      'tipo', pv.tipo,
      'cliente', COALESCE(pv.cliente_nombre, '—'),
      'vendedor_id', pv.vendedor_id,
      'vendedor', COALESCE(pv.vendedor_nombre, '—'),
      'total', COALESCE(pv.total, 0),
      'requerido', pa.requerido,
      'entregado', pa.surtido,
      'pendiente', pa.pendiente,
      'surtido_status', CASE
        WHEN pa.requerido = 0 THEN 'sin_lineas'
        WHEN pa.surtido <= 0 THEN 'pendiente'
        WHEN pa.pendiente <= 0 THEN 'surtido'
        ELSE 'parcial'
      END
    ) ORDER BY pv.fecha_entrega ASC NULLS LAST, public.folio_orden(pv.folio) ASC NULLS LAST, pv.folio ASC NULLS LAST, pv.id), '[]'::jsonb) AS rows
    FROM page_ventas pv
    INNER JOIN pedido_agg pa ON pa.id = pv.id
  )
  SELECT jsonb_build_object(
    'pedidos', pj.rows,
    'pedidos_count', (SELECT COUNT(*) FROM filtered_ventas),
    'page_size', COALESCE(v_page_size, -1),
    'offset', v_offset
  ) INTO v_result
  FROM pedidos_json pj;

  RETURN COALESCE(v_result, jsonb_build_object('pedidos', '[]'::jsonb, 'pedidos_count', 0, 'page_size', COALESCE(v_page_size, -1), 'offset', v_offset));
END;
$$;


--
-- Name: FUNCTION fn_logistica_concentrado_pedidos_v3(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_field text, p_statuses text[], p_tipo text, p_vendedor_ids uuid[], p_page_size integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_concentrado_pedidos_v3(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_field text, p_statuses text[], p_tipo text, p_vendedor_ids uuid[], p_page_size integer, p_offset integer) IS 'Vista Por pedido del Concentrado: pagina ventas primero y calcula lineas solamente para la pagina visible; 0 = Todo.';


--
-- Name: fn_logistica_concentrado_surtido_v2(uuid, date, date, text, text[], text, uuid[], uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_concentrado_surtido_v2(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_field text DEFAULT 'fecha'::text, p_statuses text[] DEFAULT NULL::text[], p_tipo text DEFAULT 'pedido'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_almacen_ids uuid[] DEFAULT NULL::uuid[], p_pedido_page_size integer DEFAULT 50, p_pedido_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_page_size integer := LEAST(GREATEST(COALESCE(p_pedido_page_size, 50), 1), 100);
  v_offset integer := GREATEST(COALESCE(p_pedido_offset, 0), 0);
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH filtered_ventas AS MATERIALIZED (
    SELECT
      v.id,
      v.folio,
      v.fecha,
      v.fecha_entrega,
      v.status::text AS status,
      v.tipo::text AS tipo,
      v.total,
      v.cliente_id,
      v.vendedor_id,
      c.nombre AS cliente_nombre,
      pv.nombre AS vendedor_nombre
    FROM public.ventas v
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    LEFT JOIN public.profiles pv ON pv.id = v.vendedor_id
    WHERE v.empresa_id = p_empresa_id
      AND (
        COALESCE(cardinality(p_statuses), 0) = 0
        OR v.status::text = ANY(p_statuses)
      )
      AND (
        COALESCE(p_tipo, 'todos') = 'todos'
        OR v.tipo::text = p_tipo
      )
      AND (
        p_vendedor_ids IS NULL
        OR cardinality(p_vendedor_ids) = 0
        OR v.vendedor_id = ANY(p_vendedor_ids)
      )
      AND (
        COALESCE(p_fecha_field, 'fecha') <> 'fecha_entrega'
        OR (
          (p_fecha_desde IS NULL OR v.fecha_entrega >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR v.fecha_entrega <= p_fecha_hasta)
        )
      )
      AND (
        COALESCE(p_fecha_field, 'fecha') = 'fecha_entrega'
        OR (
          (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
        )
      )
  ),
  venta_producto AS MATERIALIZED (
    SELECT vl.venta_id, vl.producto_id,
      SUM(COALESCE(vl.cantidad,0))::numeric AS requerido
    FROM public.venta_lineas vl
    INNER JOIN filtered_ventas fv ON fv.id = vl.venta_id
    GROUP BY vl.venta_id, vl.producto_id
  ),
  entrega_producto AS MATERIALIZED (
    SELECT e.pedido_id AS venta_id, el.producto_id,
      SUM(COALESCE(el.cantidad_entregada,0))::numeric AS surtido
    FROM public.entregas e
    INNER JOIN filtered_ventas fv ON fv.id = e.pedido_id
    INNER JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.status::text IN ('surtido','cargado','hecho')
    GROUP BY e.pedido_id, el.producto_id
  ),
  line_calc AS MATERIALIZED (
    SELECT vp.venta_id, vp.producto_id, vp.requerido,
      COALESCE(ep.surtido,0)::numeric AS surtido,
      GREATEST(0::numeric, vp.requerido - COALESCE(ep.surtido,0))::numeric AS pendiente
    FROM venta_producto vp
    LEFT JOIN entrega_producto ep
      ON ep.venta_id = vp.venta_id
     AND ep.producto_id IS NOT DISTINCT FROM vp.producto_id
  ),
  pedido_agg AS MATERIALIZED (
    SELECT fv.id,
      COALESCE(SUM(lc.requerido),0)::numeric AS requerido,
      COALESCE(SUM(lc.surtido),0)::numeric AS surtido,
      COALESCE(SUM(lc.pendiente),0)::numeric AS pendiente
    FROM filtered_ventas fv
    LEFT JOIN line_calc lc ON lc.venta_id = fv.id
    GROUP BY fv.id
  ),
  producto_agg AS MATERIALIZED (
    SELECT lc.producto_id,
      SUM(lc.requerido)::numeric AS requerido,
      SUM(lc.surtido)::numeric AS surtido,
      SUM(lc.pendiente)::numeric AS pendiente
    FROM line_calc lc
    GROUP BY lc.producto_id
  ),
  stock_sel AS MATERIALIZED (
    SELECT sa.producto_id, SUM(COALESCE(sa.cantidad,0))::numeric AS stock
    FROM public.stock_almacen sa
    WHERE sa.empresa_id = p_empresa_id
      AND p_almacen_ids IS NOT NULL
      AND cardinality(p_almacen_ids) > 0
      AND sa.almacen_id = ANY(p_almacen_ids)
    GROUP BY sa.producto_id
  ),
  producto_final AS MATERIALIZED (
    SELECT
      pa.producto_id,
      COALESCE(p.codigo,'—') AS codigo,
      COALESCE(p.nombre,'—') AS nombre,
      pa.requerido,
      pa.surtido AS entregado,
      pa.pendiente,
      CASE
        WHEN p_almacen_ids IS NULL OR cardinality(p_almacen_ids) = 0
          THEN COALESCE(p.cantidad,0)::numeric
        ELSE COALESCE(ss.stock,0)::numeric
      END AS stock,
      GREATEST(0::numeric, pa.pendiente - CASE
        WHEN p_almacen_ids IS NULL OR cardinality(p_almacen_ids) = 0
          THEN COALESCE(p.cantidad,0)::numeric
        ELSE COALESCE(ss.stock,0)::numeric
      END)::numeric AS faltante,
      COALESCE(p.costo,0)::numeric AS costo,
      p.proveedor_preferido_id
    FROM producto_agg pa
    LEFT JOIN public.productos p ON p.id = pa.producto_id
    LEFT JOIN stock_sel ss ON ss.producto_id = pa.producto_id
  ),
  producto_stats AS (
    SELECT
      COUNT(*)::bigint AS productos,
      COUNT(*) FILTER (WHERE faltante > 0)::bigint AS con_faltante,
      COALESCE(SUM(faltante * costo) FILTER (WHERE faltante > 0),0)::numeric AS costo_faltante
    FROM producto_final
  ),
  productos_json AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'producto_id', pf.producto_id,
      'codigo', pf.codigo,
      'nombre', pf.nombre,
      'requerido', pf.requerido,
      'entregado', pf.entregado,
      'pendiente', pf.pendiente,
      'stock', pf.stock,
      'faltante', pf.faltante,
      'costo', pf.costo,
      'proveedor_preferido_id', pf.proveedor_preferido_id
    ) ORDER BY pf.faltante DESC, pf.nombre ASC), '[]'::jsonb) AS rows
    FROM producto_final pf
  ),
  pedido_page AS MATERIALIZED (
    SELECT fv.*, pa.requerido, pa.surtido, pa.pendiente
    FROM filtered_ventas fv
    INNER JOIN pedido_agg pa ON pa.id = fv.id
    ORDER BY fv.fecha_entrega ASC NULLS LAST, public.folio_orden(fv.folio) ASC NULLS LAST, fv.folio ASC NULLS LAST, fv.id
    LIMIT v_page_size OFFSET v_offset
  ),
  pedidos_json AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', pp.id,
      'folio', pp.folio,
      'fecha_entrega', pp.fecha_entrega,
      'status', pp.status,
      'tipo', pp.tipo,
      'cliente', COALESCE(pp.cliente_nombre,'—'),
      'vendedor_id', pp.vendedor_id,
      'vendedor', COALESCE(pp.vendedor_nombre,'—'),
      'total', COALESCE(pp.total,0),
      'requerido', pp.requerido,
      'entregado', pp.surtido,
      'pendiente', pp.pendiente,
      'surtido_status', CASE
        WHEN pp.requerido = 0 THEN 'sin_lineas'
        WHEN pp.surtido <= 0 THEN 'pendiente'
        WHEN pp.pendiente <= 0 THEN 'surtido'
        ELSE 'parcial'
      END
    ) ORDER BY pp.fecha_entrega ASC NULLS LAST, public.folio_orden(pp.folio) ASC NULLS LAST, pp.folio ASC NULLS LAST, pp.id), '[]'::jsonb) AS rows
    FROM pedido_page pp
  )
  SELECT jsonb_build_object(
    'rows', pr.rows,
    'pedidos', pe.rows,
    'pedidos_count', (SELECT COUNT(*) FROM filtered_ventas),
    'pedido_page_size', v_page_size,
    'pedido_offset', v_offset,
    'productos_count', ps.productos,
    'con_faltante', ps.con_faltante,
    'costo_faltante', ps.costo_faltante
  ) INTO v_result
  FROM productos_json pr CROSS JOIN pedidos_json pe CROSS JOIN producto_stats ps;

  RETURN COALESCE(v_result, jsonb_build_object(
    'rows','[]'::jsonb,'pedidos','[]'::jsonb,'pedidos_count',0,
    'pedido_page_size',v_page_size,'pedido_offset',v_offset,
    'productos_count',0,'con_faltante',0,'costo_faltante',0
  ));
END;
$$;


--
-- Name: FUNCTION fn_logistica_concentrado_surtido_v2(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_field text, p_statuses text[], p_tipo text, p_vendedor_ids uuid[], p_almacen_ids uuid[], p_pedido_page_size integer, p_pedido_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_concentrado_surtido_v2(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_field text, p_statuses text[], p_tipo text, p_vendedor_ids uuid[], p_almacen_ids uuid[], p_pedido_page_size integer, p_pedido_offset integer) IS 'Concentrado a surtir agregado en PostgreSQL: productos resumidos + pedidos paginados, con validación tenant fail-closed.';


--
-- Name: fn_logistica_entregas_workspace_v2(uuid, text, uuid, text, text, text, date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_entregas_workspace_v2(p_empresa_id uuid, p_search text DEFAULT NULL::text, p_vendedor_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'todos'::text, p_ruta text DEFAULT 'todos'::text, p_fecha_tipo text DEFAULT 'programada'::text, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_page_size integer := CASE
    WHEN COALESCE(p_page_size, 50) <= 0 THEN NULL
    ELSE LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 500)
  END;
  v_offset integer := CASE
    WHEN COALESCE(p_page_size, 50) <= 0 THEN 0
    ELSE GREATEST(COALESCE(p_offset, 0), 0)
  END;
  v_result jsonb;
  v_search text := NULLIF(BTRIM(p_search), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH candidate_ids AS MATERIALIZED (
    -- Fecha programada de entrega: entregas.fecha.
    SELECT e.id
    FROM public.entregas e
    WHERE COALESCE(p_fecha_tipo, 'programada') = 'programada'
      AND e.empresa_id = p_empresa_id
      AND (p_fecha_desde IS NULL OR e.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR e.fecha < (p_fecha_hasta + 1))

    UNION ALL

    -- Fecha real: entregas.fecha_entrega.
    SELECT e.id
    FROM public.entregas e
    WHERE p_fecha_tipo = 'real'
      AND e.empresa_id = p_empresa_id
      AND (p_fecha_desde IS NULL OR e.fecha_entrega >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR e.fecha_entrega < (p_fecha_hasta + 1))

    UNION ALL

    -- Fecha de creación: half-open interval para conservar el índice de created_at.
    SELECT e.id
    FROM public.entregas e
    WHERE p_fecha_tipo = 'creacion'
      AND e.empresa_id = p_empresa_id
      AND (p_fecha_desde IS NULL OR e.created_at >= p_fecha_desde::timestamptz)
      AND (p_fecha_hasta IS NULL OR e.created_at < (p_fecha_hasta + 1)::timestamptz)

    UNION ALL

    -- Compatibilidad: fecha de levantamiento del pedido asociado.
    SELECT e.id
    FROM public.entregas e
    INNER JOIN public.ventas v ON v.id = e.pedido_id
    WHERE p_fecha_tipo = 'levantamiento'
      AND e.empresa_id = p_empresa_id
      AND (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR v.fecha < (p_fecha_hasta + 1))
  ),
  base AS MATERIALIZED (
    SELECT
      e.id,
      e.folio,
      e.fecha,
      e.fecha_entrega,
      e.status::text AS status,
      e.notas,
      e.pedido_id,
      e.vendedor_id,
      e.cliente_id,
      e.almacen_id,
      e.vendedor_ruta_id,
      e.fecha_asignacion,
      e.fecha_carga,
      e.validado_at,
      e.created_at,
      v.folio AS pedido_folio,
      v.fecha AS pedido_fecha
    FROM candidate_ids ci
    INNER JOIN public.entregas e ON e.id = ci.id
    LEFT JOIN public.ventas v ON v.id = e.pedido_id
    WHERE
      (p_vendedor_id IS NULL OR e.vendedor_id = p_vendedor_id)
      AND (
        COALESCE(p_ruta, 'todos') = 'todos'
        OR (p_ruta = 'sin_ruta' AND e.vendedor_ruta_id IS NULL)
        OR (p_ruta <> 'sin_ruta' AND e.vendedor_ruta_id::text = p_ruta)
      )
      AND (
        v_search IS NULL
        OR COALESCE(e.folio, '') ILIKE '%' || v_search || '%'
        OR COALESCE(v.folio, '') ILIKE '%' || v_search || '%'
        OR EXISTS (
          SELECT 1
          FROM public.clientes cs
          WHERE cs.id = e.cliente_id
            AND COALESCE(cs.nombre, '') ILIKE '%' || v_search || '%'
        )
        OR EXISTS (
          SELECT 1
          FROM public.profiles ps
          WHERE ps.id IN (e.vendedor_id, e.vendedor_ruta_id)
            AND COALESCE(ps.nombre, '') ILIKE '%' || v_search || '%'
        )
        OR EXISTS (
          SELECT 1
          FROM public.entrega_lineas els
          INNER JOIN public.productos prs ON prs.id = els.producto_id
          WHERE els.entrega_id = e.id
            AND (
              COALESCE(prs.codigo, '') ILIKE '%' || v_search || '%'
              OR COALESCE(prs.nombre, '') ILIKE '%' || v_search || '%'
            )
        )
      )
  ),
  status_counts AS (
    SELECT
      COUNT(*)::bigint AS total,
      COUNT(*) FILTER (WHERE status = 'borrador')::bigint AS borrador,
      COUNT(*) FILTER (WHERE status = 'surtido')::bigint AS surtido,
      COUNT(*) FILTER (WHERE status = 'asignado')::bigint AS asignado,
      COUNT(*) FILTER (WHERE status = 'cargado')::bigint AS cargado,
      COUNT(*) FILTER (WHERE status = 'en_ruta')::bigint AS en_ruta,
      COUNT(*) FILTER (WHERE status = 'listo')::bigint AS listo,
      COUNT(*) FILTER (WHERE status = 'hecho')::bigint AS hecho,
      COUNT(*) FILTER (WHERE status = 'no_entregado')::bigint AS no_entregado,
      COUNT(*) FILTER (WHERE status = 'cancelado')::bigint AS cancelado
    FROM base
  ),
  status_filtered AS MATERIALIZED (
    SELECT *
    FROM base
    WHERE COALESCE(p_status, 'todos') = 'todos'
       OR status = p_status
  ),
  page_ids AS MATERIALIZED (
    SELECT id, created_at
    FROM status_filtered
    ORDER BY created_at DESC, id DESC
    LIMIT v_page_size
    OFFSET v_offset
  ),
  details AS MATERIALIZED (
    SELECT
      b.*,
      c.nombre AS cliente_nombre,
      vend.nombre AS vendedor_nombre,
      vend.telefono AS vendedor_telefono,
      vend.almacen_id AS vendedor_almacen_destino_id,
      vend_a.nombre AS vendedor_almacen_destino_nombre,
      a.nombre AS almacen_nombre,
      vr.nombre AS vendedor_ruta_nombre,
      vr.telefono AS vendedor_ruta_telefono,
      vr.almacen_id AS vendedor_ruta_almacen_destino_id,
      vra.nombre AS vendedor_ruta_almacen_destino_nombre
    FROM page_ids p
    INNER JOIN base b ON b.id = p.id
    LEFT JOIN public.clientes c ON c.id = b.cliente_id
    LEFT JOIN public.profiles vend ON vend.id = b.vendedor_id
    LEFT JOIN public.almacenes vend_a ON vend_a.id = vend.almacen_id
    LEFT JOIN public.almacenes a ON a.id = b.almacen_id
    LEFT JOIN public.profiles vr ON vr.id = b.vendedor_ruta_id
    LEFT JOIN public.almacenes vra ON vra.id = vr.almacen_id
  ),
  rows_json AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', d.id,
          'folio', d.folio,
          'fecha', d.fecha,
          'fecha_entrega', d.fecha_entrega,
          'status', d.status,
          'notas', d.notas,
          'pedido_id', d.pedido_id,
          'vendedor_id', d.vendedor_id,
          'cliente_id', d.cliente_id,
          'almacen_id', d.almacen_id,
          'vendedor_ruta_id', d.vendedor_ruta_id,
          'fecha_asignacion', d.fecha_asignacion,
          'fecha_carga', d.fecha_carga,
          'validado_at', d.validado_at,
          'created_at', d.created_at,
          'pedido_folio', d.pedido_folio,
          'pedido_fecha', d.pedido_fecha,
          'cliente_nombre', d.cliente_nombre,
          'vendedor_nombre', d.vendedor_nombre,
          'vendedor_telefono', d.vendedor_telefono,
          'vendedor_almacen_destino_id', d.vendedor_almacen_destino_id,
          'vendedor_almacen_destino_nombre', d.vendedor_almacen_destino_nombre,
          'almacen_nombre', d.almacen_nombre,
          'vendedor_ruta_nombre', d.vendedor_ruta_nombre,
          'vendedor_ruta_telefono', d.vendedor_ruta_telefono,
          'vendedor_ruta_almacen_destino_id', d.vendedor_ruta_almacen_destino_id,
          'vendedor_ruta_almacen_destino_nombre', d.vendedor_ruta_almacen_destino_nombre
        )
        ORDER BY d.created_at DESC, d.id DESC
      ),
      '[]'::jsonb
    ) AS rows
    FROM details d
  )
  SELECT jsonb_build_object(
    'rows', r.rows,
    'total_count', (SELECT COUNT(*) FROM status_filtered),
    'page_size', COALESCE(v_page_size, -1),
    'offset', v_offset,
    'counts', jsonb_build_object(
      'total', sc.total,
      'borrador', sc.borrador,
      'surtido', sc.surtido,
      'asignado', sc.asignado,
      'cargado', sc.cargado,
      'en_ruta', sc.en_ruta,
      'listo', sc.listo,
      'hecho', sc.hecho,
      'no_entregado', sc.no_entregado,
      'cancelado', sc.cancelado
    )
  )
  INTO v_result
  FROM rows_json r
  CROSS JOIN status_counts sc;

  RETURN COALESCE(
    v_result,
    jsonb_build_object(
      'rows', '[]'::jsonb,
      'total_count', 0,
      'page_size', COALESCE(v_page_size, -1),
      'offset', v_offset,
      'counts', jsonb_build_object(
        'total', 0,
        'borrador', 0,
        'surtido', 0,
        'asignado', 0,
        'cargado', 0,
        'en_ruta', 0,
        'listo', 0,
        'hecho', 0,
        'no_entregado', 0,
        'cancelado', 0
      )
    )
  );
END;
$$;


--
-- Name: FUNCTION fn_logistica_entregas_workspace_v2(p_empresa_id uuid, p_search text, p_vendedor_id uuid, p_status text, p_ruta text, p_fecha_tipo text, p_fecha_desde date, p_fecha_hasta date, p_page_size integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_entregas_workspace_v2(p_empresa_id uuid, p_search text, p_vendedor_id uuid, p_status text, p_ruta text, p_fecha_tipo text, p_fecha_desde date, p_fecha_hasta date, p_page_size integer, p_offset integer) IS 'Entregas paginadas: filtro centralizado por fecha programada, real, creación o levantamiento; búsqueda server-side y aislamiento tenant fail-closed.';


--
-- Name: fn_logistica_pedido_detalle_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_pedido_detalle_v4(p_pedido_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_empresa_id uuid;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT v.empresa_id
  INTO v_empresa_id
  FROM public.ventas v
  WHERE v.id = p_pedido_id
    AND v.tipo = 'pedido';

  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'pedido not found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND v_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH entrega_producto AS MATERIALIZED (
    SELECT
      el.producto_id,
      SUM(CASE WHEN e.status::text = 'borrador' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS generada,
      SUM(CASE WHEN e.status::text IN ('surtido','asignado','cargado','en_ruta','hecho') THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS surtida,
      SUM(CASE WHEN e.status::text = 'hecho' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS entregada
    FROM public.entregas e
    INNER JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.pedido_id = p_pedido_id
      AND e.status::text <> 'cancelado'
    GROUP BY el.producto_id
  ),
  lineas AS MATERIALIZED (
    SELECT
      vl.id,
      vl.producto_id,
      vl.unidad_id,
      vl.lote_id,
      COALESCE(pr.codigo, '') AS codigo,
      COALESCE(pr.nombre, vl.descripcion, '') AS producto,
      u.abreviatura AS unidad,
      COALESCE(vl.cantidad, 0)::numeric AS cantidad,
      COALESCE(ep.generada, 0)::numeric AS generado,
      COALESCE(ep.surtida, 0)::numeric AS surtido,
      COALESCE(ep.entregada, 0)::numeric AS entregado,
      GREATEST(0::numeric, COALESCE(vl.cantidad, 0) - COALESCE(ep.surtida, 0) - COALESCE(ep.generada, 0))::numeric AS pendiente,
      COALESCE(vl.precio_unitario, 0)::numeric AS precio,
      (COALESCE(vl.cantidad, 0) * COALESCE(vl.precio_unitario, 0))::numeric AS subtotal,
      vl.created_at
    FROM public.venta_lineas vl
    LEFT JOIN public.productos pr ON pr.id = vl.producto_id
    LEFT JOIN public.unidades u ON u.id = vl.unidad_id
    LEFT JOIN entrega_producto ep ON ep.producto_id IS NOT DISTINCT FROM vl.producto_id
    WHERE vl.venta_id = p_pedido_id
  ),
  header AS (
    SELECT
      c.direccion AS cliente_direccion,
      c.telefono AS cliente_telefono,
      v.notas
    FROM public.ventas v
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    WHERE v.id = p_pedido_id
  ),
  rows_json AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', l.id,
      'producto_id', l.producto_id,
      'unidad_id', l.unidad_id,
      'lote_id', l.lote_id,
      'codigo', l.codigo,
      'producto', l.producto,
      'unidad', l.unidad,
      'cantidad', l.cantidad,
      'generado', l.generado,
      'surtido', l.surtido,
      'entregado', l.entregado,
      'pendiente', l.pendiente,
      'precio', l.precio,
      'subtotal', l.subtotal
    ) ORDER BY l.created_at ASC, l.id), '[]'::jsonb) AS rows
    FROM lineas l
  )
  SELECT jsonb_build_object(
    'rows', r.rows,
    'cliente_direccion', h.cliente_direccion,
    'cliente_telefono', h.cliente_telefono,
    'notas', h.notas,
    'db_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  )
  INTO v_result
  FROM rows_json r
  CROSS JOIN header h;

  RETURN COALESCE(v_result, jsonb_build_object('rows','[]'::jsonb,'cliente_direccion',NULL,'cliente_telefono',NULL,'notas',NULL,'db_ms',0));
END;
$$;


--
-- Name: FUNCTION fn_logistica_pedido_detalle_v4(p_pedido_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_pedido_detalle_v4(p_pedido_id uuid) IS 'Detalle lazy de un solo pedido. Consulta únicamente sus venta_lineas y entregas relacionadas.';


--
-- Name: fn_logistica_pedidos_counts_v4(uuid, date, date, text, uuid[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_pedidos_counts_v4(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_tipo text DEFAULT 'levantamiento'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_search text DEFAULT NULL::text, p_tab text DEFAULT 'pendientes'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH filtered AS MATERIALIZED (
    SELECT
      v.id,
      r.bucket,
      r.total_pendiente,
      r.total_valor_pendiente
    FROM public.ventas v
    INNER JOIN public.logistica_pedido_resumen r ON r.pedido_id = v.id
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    LEFT JOIN public.profiles vend ON vend.id = v.vendedor_id
    LEFT JOIN public.profiles rep ON rep.id = r.vendedor_ruta_id
    WHERE v.empresa_id = p_empresa_id
      AND v.tipo = 'pedido'
      AND (
        p_vendedor_ids IS NULL
        OR cardinality(p_vendedor_ids) = 0
        OR v.vendedor_id = ANY(p_vendedor_ids)
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
        OR (
          (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
        )
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'
        OR (
          (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
        )
      )
      AND (
        NULLIF(BTRIM(p_search), '') IS NULL
        OR COALESCE(v.folio, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(c.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(vend.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(rep.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR EXISTS (
          SELECT 1
          FROM public.venta_lineas vl
          INNER JOIN public.productos pr ON pr.id = vl.producto_id
          WHERE vl.venta_id = v.id
            AND (
              COALESCE(pr.codigo, '') ILIKE '%' || BTRIM(p_search) || '%'
              OR COALESCE(pr.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
            )
        )
      )
  ),
  stats AS (
    SELECT
      COUNT(*) FILTER (WHERE bucket = 'pendientes')::bigint AS pendientes,
      COUNT(*) FILTER (WHERE bucket = 'generadas')::bigint AS generadas,
      COUNT(*) FILTER (WHERE bucket = 'surtidos')::bigint AS surtidos,
      COUNT(*) FILTER (WHERE bucket = 'en_ruta')::bigint AS en_ruta,
      COUNT(*) FILTER (WHERE bucket = 'entregados')::bigint AS entregados,
      COUNT(*) FILTER (WHERE bucket = 'cerrados')::bigint AS cerrados,
      COUNT(*)::bigint AS todos,
      COUNT(*) FILTER (
        WHERE COALESCE(p_tab, 'pendientes') = 'todos'
           OR bucket = COALESCE(p_tab, 'pendientes')
      )::bigint AS selected_count,
      COALESCE(SUM(total_pendiente) FILTER (
        WHERE COALESCE(p_tab, 'pendientes') = 'todos'
           OR bucket = COALESCE(p_tab, 'pendientes')
      ), 0)::numeric AS selected_total_pendiente,
      COALESCE(SUM(total_valor_pendiente) FILTER (
        WHERE COALESCE(p_tab, 'pendientes') = 'todos'
           OR bucket = COALESCE(p_tab, 'pendientes')
      ), 0)::numeric AS selected_total_valor_pendiente
    FROM filtered
  )
  SELECT jsonb_build_object(
    'counts', jsonb_build_object(
      'pendientes', pendientes,
      'generadas', generadas,
      'surtidos', surtidos,
      'en_ruta', en_ruta,
      'entregados', entregados,
      'cerrados', cerrados,
      'todos', todos
    ),
    'selected_count', selected_count,
    'selected_total_pendiente', selected_total_pendiente,
    'selected_total_valor_pendiente', selected_total_valor_pendiente,
    'db_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  )
  INTO v_result
  FROM stats;

  RETURN COALESCE(v_result, jsonb_build_object(
    'counts', jsonb_build_object('pendientes',0,'generadas',0,'surtidos',0,'en_ruta',0,'entregados',0,'cerrados',0,'todos',0),
    'selected_count',0,'selected_total_pendiente',0,'selected_total_valor_pendiente',0,'db_ms',0
  ));
END;
$$;


--
-- Name: FUNCTION fn_logistica_pedidos_counts_v4(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text, p_tab text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_pedidos_counts_v4(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text, p_tab text) IS 'Contadores/totales de Pedidos Operación sobre resumen persistente; no recorre partidas para progreso.';


--
-- Name: fn_logistica_pedidos_page_v4(uuid, date, date, text, uuid[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_pedidos_page_v4(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_tipo text DEFAULT 'levantamiento'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_search text DEFAULT NULL::text, p_tab text DEFAULT 'pendientes'::text, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_page_size integer := CASE
    WHEN COALESCE(p_page_size, 50) <= 0 THEN NULL
    ELSE LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 500)
  END;
  v_offset integer := CASE
    WHEN COALESCE(p_page_size, 50) <= 0 THEN 0
    ELSE GREATEST(COALESCE(p_offset, 0), 0)
  END;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH page_rows AS MATERIALIZED (
    SELECT
      v.id,
      v.folio,
      v.cliente_id,
      c.nombre AS cliente_nombre,
      v.vendedor_id,
      vend.nombre AS vendedor_nombre,
      v.status::text AS status,
      v.fecha AS fecha,
      COALESCE(v.total, 0)::numeric AS total,
      v.cerrado_at,
      r.total_demanda,
      r.total_generada,
      r.total_surtido,
      r.total_entregado,
      r.total_pendiente,
      r.total_valor_pendiente,
      r.lineas_pendientes,
      r.fully_generada,
      r.fully_surtido,
      r.fully_delivered,
      r.en_ruta,
      r.estado_odoo,
      r.bucket,
      r.fecha_programada,
      r.fecha_entrega_real,
      r.vendedor_ruta_id,
      rep.nombre AS vendedor_ruta_nombre,
      CASE
        WHEN COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
          THEN COALESCE(r.fecha_programada, v.fecha_entrega, v.fecha)
        ELSE v.fecha
      END AS sort_date,
      v.created_at
    FROM public.ventas v
    INNER JOIN public.logistica_pedido_resumen r ON r.pedido_id = v.id
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    LEFT JOIN public.profiles vend ON vend.id = v.vendedor_id
    LEFT JOIN public.profiles rep ON rep.id = r.vendedor_ruta_id
    WHERE v.empresa_id = p_empresa_id
      AND v.tipo = 'pedido'
      AND (
        COALESCE(p_tab, 'pendientes') = 'todos'
        OR r.bucket = COALESCE(p_tab, 'pendientes')
      )
      AND (
        p_vendedor_ids IS NULL
        OR cardinality(p_vendedor_ids) = 0
        OR v.vendedor_id = ANY(p_vendedor_ids)
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
        OR (
          (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
        )
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'
        OR (
          (p_fecha_desde IS NULL OR r.fecha_programada >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR r.fecha_programada <= p_fecha_hasta)
        )
      )
      AND (
        NULLIF(BTRIM(p_search), '') IS NULL
        OR COALESCE(v.folio, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(c.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(vend.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(rep.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR EXISTS (
          SELECT 1
          FROM public.venta_lineas vl
          INNER JOIN public.productos pr ON pr.id = vl.producto_id
          WHERE vl.venta_id = v.id
            AND (
              COALESCE(pr.codigo, '') ILIKE '%' || BTRIM(p_search) || '%'
              OR COALESCE(pr.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
            )
        )
      )
    ORDER BY sort_date DESC NULLS LAST, v.created_at DESC, v.id DESC
    LIMIT v_page_size
    OFFSET v_offset
  ),
  rows_json AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'folio', p.folio,
        'cliente_id', p.cliente_id,
        'cliente_nombre', p.cliente_nombre,
        'vendedor_id', p.vendedor_id,
        'vendedor_nombre', p.vendedor_nombre,
        'status', p.status,
        'fecha', p.fecha,
        'total', p.total,
        'cerrado_at', p.cerrado_at,
        'total_demanda', p.total_demanda,
        'total_generada', p.total_generada,
        'total_surtido', p.total_surtido,
        'total_entregado', p.total_entregado,
        'total_pendiente', p.total_pendiente,
        'total_valor_pendiente', p.total_valor_pendiente,
        'lineas_pendientes', p.lineas_pendientes,
        'fully_generada', p.fully_generada,
        'fully_surtido', p.fully_surtido,
        'fully_delivered', p.fully_delivered,
        'en_ruta', p.en_ruta,
        'estado_odoo', p.estado_odoo,
        'fecha_programada', p.fecha_programada,
        'fecha_entrega_real', p.fecha_entrega_real,
        'vendedor_ruta_id', p.vendedor_ruta_id,
        'vendedor_ruta_nombre', p.vendedor_ruta_nombre,
        'pct_generada', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_generada / p.total_demanda) * 100)::int ELSE 0 END,
        'pct_surtido', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_surtido / p.total_demanda) * 100)::int ELSE 0 END,
        'pct_entregado', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_entregado / p.total_demanda) * 100)::int ELSE 0 END
      ) ORDER BY p.sort_date DESC NULLS LAST, p.created_at DESC, p.id DESC
    ), '[]'::jsonb) AS rows
    FROM page_rows p
  )
  SELECT jsonb_build_object(
    'rows', rows,
    'row_count', jsonb_array_length(rows),
    'page_size', COALESCE(v_page_size, -1),
    'offset', v_offset,
    'db_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  )
  INTO v_result
  FROM rows_json;

  RETURN COALESCE(v_result, jsonb_build_object('rows','[]'::jsonb,'row_count',0,'page_size',COALESCE(v_page_size,-1),'offset',v_offset,'db_ms',0));
END;
$$;


--
-- Name: FUNCTION fn_logistica_pedidos_page_v4(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text, p_tab text, p_page_size integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_pedidos_page_v4(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text, p_tab text, p_page_size integer, p_offset integer) IS 'Página ligera de Pedidos Operación. Filtra/busca en servidor y lee progreso desde logistica_pedido_resumen.';


--
-- Name: fn_logistica_pedidos_workspace(uuid, date, date, text, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_pedidos_workspace(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_tipo text DEFAULT 'levantamiento'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_search text DEFAULT NULL::text) RETURNS TABLE(id uuid, folio text, cliente_id uuid, cliente_nombre text, cliente_direccion text, cliente_telefono text, vendedor_id uuid, vendedor_nombre text, status text, fecha text, fecha_programada text, fecha_entrega_real text, total numeric, cerrado_at text, notas text, total_demanda numeric, total_generada numeric, total_surtido numeric, total_entregado numeric, total_pendiente numeric, total_valor_pendiente numeric, lineas_pendientes bigint, fully_generada boolean, fully_surtido boolean, fully_delivered boolean, en_ruta boolean, estado_odoo text, pct_generada integer, pct_surtido integer, pct_entregado integer, vendedor_ruta_id uuid, sort_date date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$

WITH base AS (

  SELECT
    v.id,
    v.folio,
    v.cliente_id,
    c.nombre AS cliente_nombre,
    c.direccion AS cliente_direccion,
    c.telefono AS cliente_telefono,
    v.vendedor_id,
    vp.nombre AS vendedor_nombre,
    v.status::text AS status,
    v.fecha::date AS fecha,
    v.fecha_entrega::date AS fecha_entrega_original,
    COALESCE(v.total, 0)::numeric AS total,
    v.cerrado_at,
    v.notas,
    v.created_at

  FROM public.ventas v

  LEFT JOIN public.clientes c
    ON c.id = v.cliente_id

  LEFT JOIN public.profiles vp
    ON vp.id = v.vendedor_id

  WHERE v.empresa_id = p_empresa_id

    AND v.tipo::text = 'pedido'

    AND v.status::text IN (
      'borrador',
      'confirmado',
      'entregado'
    )

    AND (
      p_vendedor_ids IS NULL
      OR cardinality(p_vendedor_ids) = 0
      OR v.vendedor_id = ANY(p_vendedor_ids)
    )

    AND (
      NULLIF(BTRIM(p_search), '') IS NULL
      OR COALESCE(v.folio, '') ILIKE '%' || BTRIM(p_search) || '%'
      OR COALESCE(c.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
    )

    -- Si se filtra por fecha de levantamiento,
    -- recorta pedidos ANTES de procesar entregas o líneas.
    AND (
      COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
      OR (
        (p_fecha_desde IS NULL OR v.fecha::date >= p_fecha_desde)
        AND
        (p_fecha_hasta IS NULL OR v.fecha::date <= p_fecha_hasta)
      )
    )

    -- Para fecha programada, reducir primero los posibles pedidos.
    -- Después se hace la validación exacta usando la última
    -- fecha programada de entrega activa.
    AND (
      COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'

      OR (
        p_fecha_desde IS NULL
        AND p_fecha_hasta IS NULL
      )

      OR (

        (
          v.fecha_entrega IS NOT NULL
          AND (
            p_fecha_desde IS NULL
            OR v.fecha_entrega::date >= p_fecha_desde
          )
          AND (
            p_fecha_hasta IS NULL
            OR v.fecha_entrega::date <= p_fecha_hasta
          )
        )

        OR EXISTS (
          SELECT 1
          FROM public.entregas ex
          WHERE ex.pedido_id = v.id
            AND ex.status::text <> 'cancelado'
            AND (
              p_fecha_desde IS NULL
              OR ex.fecha::date >= p_fecha_desde
            )
            AND (
              p_fecha_hasta IS NULL
              OR ex.fecha::date <= p_fecha_hasta
            )
        )

      )
    )
),


-- ============================================
-- INFORMACIÓN GENERAL DE LAS ENTREGAS
-- ============================================

entrega_meta AS (

  SELECT
    e.pedido_id,

    MAX(e.fecha::date)
      FILTER (
        WHERE e.status::text <> 'cancelado'
      ) AS fecha_programada_actual,

    MAX(e.fecha_entrega::date)
      FILTER (
        WHERE e.status::text = 'hecho'
      ) AS fecha_entrega_real,

    BOOL_OR(
      e.status::text IN (
        'asignado',
        'cargado',
        'en_ruta'
      )
    ) AS tiene_en_ruta,

    (
      ARRAY_AGG(
        e.vendedor_ruta_id
        ORDER BY
          e.fecha DESC NULLS LAST,
          e.created_at DESC
      )
      FILTER (
        WHERE e.status::text <> 'cancelado'
          AND e.vendedor_ruta_id IS NOT NULL
      )
    )[1] AS vendedor_ruta_id

  FROM public.entregas e

  INNER JOIN base b
    ON b.id = e.pedido_id

  GROUP BY e.pedido_id
),


-- ============================================
-- APLICAR FILTRO FINAL DE FECHA
-- ============================================

filtered AS (

  SELECT
    b.*,

    COALESCE(
      em.fecha_programada_actual,
      b.fecha_entrega_original
    ) AS fecha_programada,

    em.fecha_entrega_real,

    COALESCE(
      em.tiene_en_ruta,
      false
    ) AS tiene_en_ruta,

    em.vendedor_ruta_id

  FROM base b

  LEFT JOIN entrega_meta em
    ON em.pedido_id = b.id

  WHERE

    (
      COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'

      AND (
        p_fecha_desde IS NULL
        OR COALESCE(
          em.fecha_programada_actual,
          b.fecha_entrega_original
        ) >= p_fecha_desde
      )

      AND (
        p_fecha_hasta IS NULL
        OR COALESCE(
          em.fecha_programada_actual,
          b.fecha_entrega_original
        ) <= p_fecha_hasta
      )
    )

    OR

    (
      COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'

      AND (
        p_fecha_desde IS NULL
        OR b.fecha >= p_fecha_desde
      )

      AND (
        p_fecha_hasta IS NULL
        OR b.fecha <= p_fecha_hasta
      )
    )
),


-- ============================================
-- CANTIDADES ORIGINALES DE CADA PEDIDO
-- ============================================

venta_producto AS (

  SELECT
    vl.venta_id,
    vl.producto_id,

    SUM(
      COALESCE(vl.cantidad, 0)
    )::numeric AS cantidad,

    SUM(
      COALESCE(vl.cantidad, 0)
      *
      COALESCE(vl.precio_unitario, 0)
    )::numeric AS valor

  FROM public.venta_lineas vl

  INNER JOIN filtered f
    ON f.id = vl.venta_id

  GROUP BY
    vl.venta_id,
    vl.producto_id
),


-- ============================================
-- CANTIDADES GENERADAS / SURTIDAS / ENTREGADAS
-- ============================================

entrega_producto AS (

  SELECT
    e.pedido_id,
    el.producto_id,

    SUM(
      CASE
        WHEN e.status::text = 'borrador'
        THEN COALESCE(el.cantidad_entregada, 0)
        ELSE 0
      END
    )::numeric AS generada,

    SUM(
      CASE
        WHEN e.status::text IN (
          'surtido',
          'asignado',
          'cargado',
          'en_ruta',
          'hecho'
        )
        THEN COALESCE(el.cantidad_entregada, 0)
        ELSE 0
      END
    )::numeric AS surtida,

    SUM(
      CASE
        WHEN e.status::text = 'hecho'
        THEN COALESCE(el.cantidad_entregada, 0)
        ELSE 0
      END
    )::numeric AS entregada

  FROM public.entregas e

  INNER JOIN filtered f
    ON f.id = e.pedido_id

  INNER JOIN public.entrega_lineas el
    ON el.entrega_id = e.id

  WHERE e.status::text <> 'cancelado'

  GROUP BY
    e.pedido_id,
    el.producto_id
),


-- ============================================
-- CALCULAR PENDIENTES POR PRODUCTO
-- ============================================

line_calc AS (

  SELECT
    vp.venta_id,
    vp.producto_id,
    vp.cantidad,
    vp.valor,

    COALESCE(
      ep.generada,
      0
    )::numeric AS generada,

    COALESCE(
      ep.surtida,
      0
    )::numeric AS surtida,

    COALESCE(
      ep.entregada,
      0
    )::numeric AS entregada,

    GREATEST(
      0::numeric,
      vp.cantidad
        - COALESCE(ep.surtida, 0)
        - COALESCE(ep.generada, 0)
    )::numeric AS pendiente,

    CASE

      WHEN vp.cantidad > 0 THEN

        GREATEST(
          0::numeric,
          vp.cantidad
            - COALESCE(ep.surtida, 0)
            - COALESCE(ep.generada, 0)
        )
        *
        (
          vp.valor / vp.cantidad
        )

      ELSE 0::numeric

    END AS valor_pendiente

  FROM venta_producto vp

  LEFT JOIN entrega_producto ep
    ON ep.pedido_id = vp.venta_id
   AND ep.producto_id IS NOT DISTINCT FROM vp.producto_id
),


-- ============================================
-- RESUMEN POR PEDIDO
-- ============================================

agg AS (

  SELECT
    f.id,

    COALESCE(
      SUM(lc.cantidad),
      0
    )::numeric AS total_demanda,

    COALESCE(
      SUM(lc.generada),
      0
    )::numeric AS total_generada,

    COALESCE(
      SUM(lc.surtida),
      0
    )::numeric AS total_surtido,

    COALESCE(
      SUM(lc.entregada),
      0
    )::numeric AS total_entregado,

    COALESCE(
      SUM(lc.pendiente),
      0
    )::numeric AS total_pendiente,

    COALESCE(
      SUM(lc.valor_pendiente),
      0
    )::numeric AS total_valor_pendiente,

    COUNT(*)
      FILTER (
        WHERE lc.pendiente > 0
      )::bigint AS lineas_pendientes

  FROM filtered f

  LEFT JOIN line_calc lc
    ON lc.venta_id = f.id

  GROUP BY f.id
),


-- ============================================
-- ESTADOS CALCULADOS
-- ============================================

calc AS (

  SELECT
    f.*,

    a.total_demanda,
    a.total_generada,
    a.total_surtido,
    a.total_entregado,
    a.total_pendiente,
    a.total_valor_pendiente,
    a.lineas_pendientes,

    (
      a.total_demanda > 0
      AND a.total_entregado >= a.total_demanda
    ) AS fully_delivered,

    (
      a.total_demanda > 0
      AND a.total_surtido >= a.total_demanda
    ) AS fully_surtido,

    (
      NOT (
        a.total_demanda > 0
        AND a.total_surtido >= a.total_demanda
      )

      AND a.total_demanda > 0

      AND (
        a.total_generada
        + a.total_surtido
      ) >= a.total_demanda

    ) AS fully_generada

  FROM filtered f

  INNER JOIN agg a
    ON a.id = f.id
),


final_calc AS (

  SELECT
    c.*,

    (
      NOT c.fully_delivered
      AND c.tiene_en_ruta
    ) AS en_ruta,

    CASE

      WHEN c.fully_delivered
        THEN 'entregado'

      WHEN (
        NOT c.fully_delivered
        AND c.tiene_en_ruta
      )
        THEN 'en_ruta'

      WHEN c.fully_surtido
        THEN 'surtido_completo'

      WHEN c.total_surtido > 0
        THEN 'surtido_parcial'

      WHEN (
        c.total_generada > 0
        AND c.fully_generada
      )
        THEN 'pendiente_surtir'

      WHEN c.total_generada > 0
        THEN 'en_surtido'

      ELSE NULL

    END AS estado_odoo

  FROM calc c
)


-- ============================================
-- RESULTADO FINAL
-- ============================================

SELECT
  f.id,
  f.folio,
  f.cliente_id,
  f.cliente_nombre,
  f.cliente_direccion,
  f.cliente_telefono,
  f.vendedor_id,
  f.vendedor_nombre,
  f.status,

  f.fecha::text AS fecha,

  f.fecha_programada::text
    AS fecha_programada,

  f.fecha_entrega_real::text
    AS fecha_entrega_real,

  f.total,

  f.cerrado_at::text
    AS cerrado_at,

  f.notas,

  f.total_demanda,
  f.total_generada,
  f.total_surtido,
  f.total_entregado,
  f.total_pendiente,
  f.total_valor_pendiente,
  f.lineas_pendientes,

  f.fully_generada,
  f.fully_surtido,
  f.fully_delivered,
  f.en_ruta,

  f.estado_odoo,

  CASE
    WHEN f.total_demanda > 0
    THEN ROUND(
      (
        f.total_generada
        / f.total_demanda
      ) * 100
    )::int
    ELSE 0
  END AS pct_generada,

  CASE
    WHEN f.total_demanda > 0
    THEN ROUND(
      (
        f.total_surtido
        / f.total_demanda
      ) * 100
    )::int
    ELSE 0
  END AS pct_surtido,

  CASE
    WHEN f.total_demanda > 0
    THEN ROUND(
      (
        f.total_entregado
        / f.total_demanda
      ) * 100
    )::int
    ELSE 0
  END AS pct_entregado,

  f.vendedor_ruta_id,

  CASE

    WHEN COALESCE(
      p_fecha_tipo,
      'levantamiento'
    ) = 'programada'

    THEN COALESCE(
      f.fecha_programada,
      f.fecha
    )

    ELSE f.fecha

  END AS sort_date

FROM final_calc f

ORDER BY
  sort_date DESC,
  f.created_at DESC;

$$;


--
-- Name: FUNCTION fn_logistica_pedidos_workspace(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_logistica_pedidos_workspace(p_empresa_id uuid, p_fecha_desde date, p_fecha_hasta date, p_fecha_tipo text, p_vendedor_ids uuid[], p_search text) IS 'Resumen operativo de pedidos para Logística. Filtra primero y evita enviar líneas/entregas completas en la carga inicial.';


--
-- Name: fn_logistica_pedidos_workspace_v2(uuid, date, date, text, uuid[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_logistica_pedidos_workspace_v2(p_empresa_id uuid, p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_fecha_tipo text DEFAULT 'levantamiento'::text, p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_search text DEFAULT NULL::text, p_tab text DEFAULT 'pendientes'::text, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_page_size integer := CASE WHEN COALESCE(p_page_size, 50) <= 0 THEN NULL ELSE LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 500) END;
  v_offset integer := CASE WHEN COALESCE(p_page_size, 50) <= 0 THEN 0 ELSE GREATEST(COALESCE(p_offset, 0), 0) END;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '42501';
  END IF;

  -- Fail closed: un usuario normal sólo puede consultar exactamente su empresa.
  -- Super admin conserva acceso multiempresa. SECURITY DEFINER evita reevaluar
  -- las políticas RLS correlacionadas en venta_lineas/entrega_lineas por cada fila.
  IF COALESCE(public.is_super_admin(auth.uid()), false) = false
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id() THEN
    RAISE EXCEPTION 'empresa access denied' USING ERRCODE = '42501';
  END IF;

  WITH base AS MATERIALIZED (
    SELECT
      v.id,
      v.folio,
      v.cliente_id,
      c.nombre AS cliente_nombre,
      c.direccion AS cliente_direccion,
      c.telefono AS cliente_telefono,
      v.vendedor_id,
      vp.nombre AS vendedor_nombre,
      v.status::text AS status,
      v.fecha AS fecha,
      v.fecha_entrega AS fecha_entrega_original,
      COALESCE(v.total, 0)::numeric AS total,
      v.cerrado_at,
      v.notas,
      v.created_at
    FROM public.ventas v
    LEFT JOIN public.clientes c ON c.id = v.cliente_id
    LEFT JOIN public.profiles vp ON vp.id = v.vendedor_id
    WHERE v.empresa_id = p_empresa_id
      AND v.tipo = 'pedido'
      AND (
        p_vendedor_ids IS NULL
        OR cardinality(p_vendedor_ids) = 0
        OR v.vendedor_id = ANY(p_vendedor_ids)
      )
      AND (
        NULLIF(BTRIM(p_search), '') IS NULL
        OR COALESCE(v.folio, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(c.nombre, '') ILIKE '%' || BTRIM(p_search) || '%'
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
        OR (
          (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
          AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
        )
      )
      AND (
        COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'
        OR (p_fecha_desde IS NULL AND p_fecha_hasta IS NULL)
        OR (
          (
            v.fecha_entrega IS NOT NULL
            AND (p_fecha_desde IS NULL OR v.fecha_entrega >= p_fecha_desde)
            AND (p_fecha_hasta IS NULL OR v.fecha_entrega <= p_fecha_hasta)
          )
          OR EXISTS (
            SELECT 1
            FROM public.entregas ex
            WHERE ex.pedido_id = v.id
              AND ex.status::text <> 'cancelado'
              AND (p_fecha_desde IS NULL OR ex.fecha >= p_fecha_desde)
              AND (p_fecha_hasta IS NULL OR ex.fecha <= p_fecha_hasta)
          )
        )
      )
  ),
  entrega_meta AS MATERIALIZED (
    SELECT
      e.pedido_id,
      MAX(e.fecha) FILTER (WHERE e.status::text <> 'cancelado') AS fecha_programada_actual,
      MAX(e.fecha_entrega) FILTER (WHERE e.status::text = 'hecho') AS fecha_entrega_real,
      BOOL_OR(e.status::text IN ('asignado', 'cargado', 'en_ruta')) AS tiene_en_ruta,
      (
        ARRAY_AGG(
          e.vendedor_ruta_id
          ORDER BY e.fecha DESC NULLS LAST, e.created_at DESC
        ) FILTER (
          WHERE e.status::text <> 'cancelado'
            AND e.vendedor_ruta_id IS NOT NULL
        )
      )[1] AS vendedor_ruta_id
    FROM public.entregas e
    INNER JOIN base b ON b.id = e.pedido_id
    GROUP BY e.pedido_id
  ),
  filtered AS MATERIALIZED (
    SELECT
      b.*,
      COALESCE(em.fecha_programada_actual, b.fecha_entrega_original) AS fecha_programada,
      em.fecha_entrega_real,
      COALESCE(em.tiene_en_ruta, false) AS tiene_en_ruta,
      em.vendedor_ruta_id,
      CASE
        WHEN COALESCE(p_fecha_tipo, 'levantamiento') = 'programada'
          THEN COALESCE(em.fecha_programada_actual, b.fecha_entrega_original, b.fecha)
        ELSE b.fecha
      END AS sort_date
    FROM base b
    LEFT JOIN entrega_meta em ON em.pedido_id = b.id
    WHERE
      COALESCE(p_fecha_tipo, 'levantamiento') <> 'programada'
      OR (
        (p_fecha_desde IS NULL OR COALESCE(em.fecha_programada_actual, b.fecha_entrega_original) >= p_fecha_desde)
        AND (p_fecha_hasta IS NULL OR COALESCE(em.fecha_programada_actual, b.fecha_entrega_original) <= p_fecha_hasta)
      )
  ),
  venta_producto AS MATERIALIZED (
    SELECT
      vl.venta_id,
      vl.producto_id,
      SUM(COALESCE(vl.cantidad, 0))::numeric AS cantidad,
      SUM(COALESCE(vl.cantidad, 0) * COALESCE(vl.precio_unitario, 0))::numeric AS valor
    FROM public.venta_lineas vl
    INNER JOIN filtered f ON f.id = vl.venta_id
    GROUP BY vl.venta_id, vl.producto_id
  ),
  entrega_producto AS MATERIALIZED (
    SELECT
      e.pedido_id,
      el.producto_id,
      SUM(CASE WHEN e.status::text = 'borrador' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS generada,
      SUM(CASE WHEN e.status::text IN ('surtido', 'asignado', 'cargado', 'en_ruta', 'hecho') THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS surtida,
      SUM(CASE WHEN e.status::text = 'hecho' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS entregada
    FROM public.entregas e
    INNER JOIN filtered f ON f.id = e.pedido_id
    INNER JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.status::text <> 'cancelado'
    GROUP BY e.pedido_id, el.producto_id
  ),
  line_calc AS MATERIALIZED (
    SELECT
      vp.venta_id,
      vp.producto_id,
      vp.cantidad,
      COALESCE(ep.generada, 0)::numeric AS generada,
      COALESCE(ep.surtida, 0)::numeric AS surtida,
      COALESCE(ep.entregada, 0)::numeric AS entregada,
      GREATEST(0::numeric, vp.cantidad - COALESCE(ep.surtida, 0) - COALESCE(ep.generada, 0))::numeric AS pendiente,
      CASE
        WHEN vp.cantidad > 0 THEN
          GREATEST(0::numeric, vp.cantidad - COALESCE(ep.surtida, 0) - COALESCE(ep.generada, 0)) * (vp.valor / vp.cantidad)
        ELSE 0::numeric
      END AS valor_pendiente
    FROM venta_producto vp
    LEFT JOIN entrega_producto ep
      ON ep.pedido_id = vp.venta_id
     AND ep.producto_id IS NOT DISTINCT FROM vp.producto_id
  ),
  agg AS MATERIALIZED (
    SELECT
      f.id,
      COALESCE(SUM(lc.cantidad), 0)::numeric AS total_demanda,
      COALESCE(SUM(lc.generada), 0)::numeric AS total_generada,
      COALESCE(SUM(lc.surtida), 0)::numeric AS total_surtido,
      COALESCE(SUM(lc.entregada), 0)::numeric AS total_entregado,
      COALESCE(SUM(lc.pendiente), 0)::numeric AS total_pendiente,
      COALESCE(SUM(lc.valor_pendiente), 0)::numeric AS total_valor_pendiente,
      COUNT(*) FILTER (WHERE lc.pendiente > 0)::bigint AS lineas_pendientes
    FROM filtered f
    LEFT JOIN line_calc lc ON lc.venta_id = f.id
    GROUP BY f.id
  ),
  calc AS MATERIALIZED (
    SELECT
      f.*,
      a.total_demanda,
      a.total_generada,
      a.total_surtido,
      a.total_entregado,
      a.total_pendiente,
      a.total_valor_pendiente,
      a.lineas_pendientes,
      (a.total_demanda > 0 AND a.total_entregado >= a.total_demanda) AS fully_delivered,
      (a.total_demanda > 0 AND a.total_surtido >= a.total_demanda) AS fully_surtido,
      (
        NOT (a.total_demanda > 0 AND a.total_surtido >= a.total_demanda)
        AND a.total_demanda > 0
        AND (a.total_generada + a.total_surtido) >= a.total_demanda
      ) AS fully_generada
    FROM filtered f
    INNER JOIN agg a ON a.id = f.id
  ),
  final_calc AS MATERIALIZED (
    SELECT
      c.*,
      (NOT c.fully_delivered AND c.tiene_en_ruta) AS en_ruta,
      CASE
        WHEN c.fully_delivered THEN 'entregado'
        WHEN (NOT c.fully_delivered AND c.tiene_en_ruta) THEN 'en_ruta'
        WHEN c.fully_surtido THEN 'surtido_completo'
        WHEN c.total_surtido > 0 THEN 'surtido_parcial'
        WHEN c.total_generada > 0 AND c.fully_generada THEN 'pendiente_surtir'
        WHEN c.total_generada > 0 THEN 'en_surtido'
        ELSE NULL
      END AS estado_odoo,
      (
        c.cerrado_at IS NULL
        AND c.status NOT IN ('cancelado', 'facturado')
      ) AS operativo
    FROM calc c
  ),
  stats AS (
    SELECT
      COUNT(*) FILTER (WHERE operativo AND NOT fully_generada AND NOT fully_surtido AND NOT fully_delivered AND NOT en_ruta)::bigint AS pendientes,
      COUNT(*) FILTER (WHERE operativo AND fully_generada AND NOT fully_surtido AND NOT fully_delivered AND NOT en_ruta)::bigint AS generadas,
      COUNT(*) FILTER (WHERE operativo AND fully_surtido AND NOT fully_delivered AND NOT en_ruta)::bigint AS surtidos,
      COUNT(*) FILTER (WHERE operativo AND en_ruta AND NOT fully_delivered)::bigint AS en_ruta,
      COUNT(*) FILTER (WHERE operativo AND fully_delivered)::bigint AS entregados,
      COUNT(*) FILTER (WHERE cerrado_at IS NOT NULL)::bigint AS cerrados,
      COUNT(*)::bigint AS todos
    FROM final_calc
  ),
  tab_filtered AS MATERIALIZED (
    SELECT *
    FROM final_calc
    WHERE CASE COALESCE(p_tab, 'pendientes')
      WHEN 'todos' THEN true
      WHEN 'cerrados' THEN cerrado_at IS NOT NULL
      WHEN 'generadas' THEN operativo AND fully_generada AND NOT fully_surtido AND NOT fully_delivered AND NOT en_ruta
      WHEN 'surtidos' THEN operativo AND fully_surtido AND NOT fully_delivered AND NOT en_ruta
      WHEN 'en_ruta' THEN operativo AND en_ruta AND NOT fully_delivered
      WHEN 'entregados' THEN operativo AND fully_delivered
      ELSE operativo AND NOT fully_generada AND NOT fully_surtido AND NOT fully_delivered AND NOT en_ruta
    END
  ),
  tab_stats AS (
    SELECT
      COUNT(*)::bigint AS total_count,
      COALESCE(SUM(total_pendiente), 0)::numeric AS total_pendiente,
      COALESCE(SUM(total_valor_pendiente), 0)::numeric AS total_valor_pendiente
    FROM tab_filtered
  ),
  paged AS MATERIALIZED (
    SELECT *
    FROM tab_filtered
    ORDER BY sort_date DESC NULLS LAST, created_at DESC, id DESC
    LIMIT v_page_size
    OFFSET v_offset
  ),
  rows_json AS (
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', p.id,
          'folio', p.folio,
          'cliente_id', p.cliente_id,
          'cliente_nombre', p.cliente_nombre,
          'cliente_direccion', p.cliente_direccion,
          'cliente_telefono', p.cliente_telefono,
          'vendedor_id', p.vendedor_id,
          'vendedor_nombre', p.vendedor_nombre,
          'status', p.status,
          'fecha', p.fecha,
          'fecha_programada', p.fecha_programada,
          'fecha_entrega_real', p.fecha_entrega_real,
          'total', p.total,
          'cerrado_at', p.cerrado_at,
          'notas', p.notas,
          'total_demanda', p.total_demanda,
          'total_generada', p.total_generada,
          'total_surtido', p.total_surtido,
          'total_entregado', p.total_entregado,
          'total_pendiente', p.total_pendiente,
          'total_valor_pendiente', p.total_valor_pendiente,
          'lineas_pendientes', p.lineas_pendientes,
          'fully_generada', p.fully_generada,
          'fully_surtido', p.fully_surtido,
          'fully_delivered', p.fully_delivered,
          'en_ruta', p.en_ruta,
          'estado_odoo', p.estado_odoo,
          'pct_generada', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_generada / p.total_demanda) * 100)::int ELSE 0 END,
          'pct_surtido', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_surtido / p.total_demanda) * 100)::int ELSE 0 END,
          'pct_entregado', CASE WHEN p.total_demanda > 0 THEN ROUND((p.total_entregado / p.total_demanda) * 100)::int ELSE 0 END,
          'vendedor_ruta_id', p.vendedor_ruta_id,
          'sort_date', p.sort_date
        )
        ORDER BY p.sort_date DESC NULLS LAST, p.created_at DESC, p.id DESC
      ),
      '[]'::jsonb
    ) AS rows
    FROM paged p
  )
  SELECT jsonb_build_object(
    'rows', r.rows,
    'page_size', v_page_size,
    'offset', v_offset,
    'total_count', ts.total_count,
    'total_pendiente', ts.total_pendiente,
    'total_valor_pendiente', ts.total_valor_pendiente,
    'counts', jsonb_build_object(
      'pendientes', s.pendientes,
      'generadas', s.generadas,
      'surtidos', s.surtidos,
      'en_ruta', s.en_ruta,
      'entregados', s.entregados,
      'cerrados', s.cerrados,
      'todos', s.todos
    )
  )
  INTO v_result
  FROM rows_json r
  CROSS JOIN stats s
  CROSS JOIN tab_stats ts;

  RETURN COALESCE(
    v_result,
    jsonb_build_object(
      'rows', '[]'::jsonb,
      'page_size', v_page_size,
      'offset', v_offset,
      'total_count', 0,
      'total_pendiente', 0,
      'total_valor_pendiente', 0,
      'counts', jsonb_build_object(
        'pendientes', 0,
        'generadas', 0,
        'surtidos', 0,
        'en_ruta', 0,
        'entregados', 0,
        'cerrados', 0,
        'todos', 0
      )
    )
  );
END;
$$;


