--
-- Name: fn_my_team_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_my_team_access() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'has_access', true,
    'person_id', tm.person_id,
    'name', cp.name,
    'job_title', tm.job_title,
    'access_level', tm.access_level,
    'access_scope', tm.access_scope,
    'status', tm.status,
    'permissions', tm.permissions
  )
  INTO v_result
  FROM public.platform_team_members tm
  JOIN public.commission_people cp
    ON cp.id = tm.person_id
  WHERE tm.user_id = auth.uid()
    AND tm.status IN ('invited', 'active')
    AND cp.is_active = true
    AND cp.person_type = 'internal';

  RETURN COALESCE(
    v_result,
    jsonb_build_object('has_access', false)
  );
END;
$$;


--
-- Name: fn_netear_linea_promo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_netear_linea_promo(_linea_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  l record;
  d numeric;
  faltante numeric;
  factor numeric;
  n_iva numeric; n_ieps numeric; n_total numeric; n_sub numeric;
BEGIN
  SELECT * INTO l FROM public.venta_lineas WHERE id = _linea_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(SUM(descuento_aplicado),0) INTO d
  FROM public.promocion_aplicada WHERE venta_linea_id = _linea_id;

  faltante := ROUND(d - COALESCE(l.descuento_promocion_monto,0), 2);
  IF faltante <= 0.009 THEN RETURN; END IF;
  IF COALESCE(l.total,0) <= 0 OR faltante > l.total THEN RETURN; END IF;

  factor := (l.total - faltante) / l.total;
  n_iva  := ROUND(COALESCE(l.iva_monto,0)  * factor, 2);
  n_ieps := ROUND(COALESCE(l.ieps_monto,0) * factor, 2);
  n_total := ROUND(l.total - faltante, 2);
  n_sub := ROUND(n_total - n_iva - n_ieps, 2);

  UPDATE public.venta_lineas SET
    subtotal = n_sub,
    iva_monto = n_iva,
    ieps_monto = n_ieps,
    total = n_total,
    precio_unitario = CASE WHEN COALESCE(l.cantidad,0) > 0 THEN ROUND(n_sub / l.cantidad, 4) ELSE l.precio_unitario END,
    descuento_promocion_monto = ROUND(d, 2),
    descuento_total_monto = ROUND(d + COALESCE(l.descuento_manual_monto,0), 2),
    base_ieps = n_sub,
    base_iva = ROUND(n_sub + n_ieps, 2),
    impuestos_totales = ROUND(n_iva + n_ieps, 2)
  WHERE id = _linea_id;
END;
$$;


--
-- Name: fn_notify_empresa_alta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_notify_empresa_alta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'net', 'extensions'
    AS $$
declare
  v_url text := 'https://hadesai.com.mx/api/public/webhooks/inbound/702bc3ba6ff0f2b4c7a5c9bd4623ac3e3809';
  v_owner_email text;
  v_payload jsonb;
begin
  begin
    select u.email into v_owner_email from auth.users u where u.id = new.owner_user_id;
  exception when others then
    v_owner_email := null;
  end;

  v_payload := jsonb_build_object(
    'event', 'empresa.created',
    'ocurrio_en', now(),
    'empresa', to_jsonb(new) || jsonb_build_object('owner_email', v_owner_email)
  );

  begin
    perform net.http_post(
      url := v_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := v_payload,
      timeout_milliseconds := 5000
    );
  exception when others then
    null;
  end;

  return new;
end;
$$;


