--
-- Name: fn_promo_linea_elegible(public.promociones, public.venta_lineas, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_promo_linea_elegible(p public.promociones, vl public.venta_lineas, _clasificacion_id uuid, _cliente_id uuid, _zona_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(vl.cantidad, 0) > 0
    AND (
      COALESCE(p.alcance_lista, 'todas') <> 'especifica'
      OR (p.lista_precio_id IS NOT NULL
          AND NOT COALESCE(vl.precio_manual, false)
          AND vl.lista_precio_id = p.lista_precio_id)
    )
    AND (
      p.aplica_a = 'todos'
      OR (p.aplica_a = 'producto' AND vl.producto_id = ANY(p.producto_ids))
      OR (p.aplica_a = 'clasificacion' AND _clasificacion_id = ANY(p.clasificacion_ids))
      OR (p.aplica_a = 'cliente' AND _cliente_id = ANY(p.cliente_ids))
      OR (p.aplica_a = 'zona' AND _zona_id = ANY(p.zona_ids))
    );
$$;


--
-- Name: fn_recalc_venta_header(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_recalc_venta_header(p_venta_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta       public.ventas%ROWTYPE;
  v_n           integer;
  v_sub         numeric := 0;
  v_iva         numeric := 0;
  v_ieps        numeric := 0;
  v_tot         numeric := 0;
  v_desc_lin    numeric := 0;
  v_extra       numeric := 0;
  v_promo       numeric := 0;
  v_promo_linea boolean := false;
  v_licencia    text;
  v_new_total   numeric;
  v_new_desc    numeric;
BEGIN
  IF p_venta_id IS NULL THEN RETURN; END IF;

  -- Sin FOR UPDATE: el UPDATE final toma el candado. Evita deadlocks por orden inverso de bloqueo.
  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COUNT(*),
         COALESCE(SUM(COALESCE(vl.subtotal,0)),0),
         COALESCE(SUM(COALESCE(vl.iva_monto,0)),0),
         COALESCE(SUM(COALESCE(vl.ieps_monto,0)),0),
         COALESCE(SUM(COALESCE(vl.total,0)),0),
         COALESCE(SUM(ROUND(COALESCE(vl.subtotal,0) * COALESCE(vl.descuento_pct,0) / 100.0, 2)),0)
    INTO v_n, v_sub, v_iva, v_ieps, v_tot, v_desc_lin
  FROM public.venta_lineas vl
  WHERE vl.venta_id = p_venta_id;

  IF v_n = 0 THEN RETURN; END IF;

  v_extra := CASE
    WHEN COALESCE(v_venta.descuento_extra, 0) <= 0 THEN 0
    WHEN COALESCE(v_venta.descuento_extra_tipo, 'porcentaje') = 'monto'
      THEN LEAST(v_venta.descuento_extra, v_tot)
    ELSE ROUND(v_tot * v_venta.descuento_extra / 100.0, 2)
  END;

  SELECT e.licencia INTO v_licencia FROM public.empresas e WHERE e.id = v_venta.empresa_id;
  SELECT EXISTS (
    SELECT 1 FROM public.feature_flags ff
    WHERE ff.clave = 'promo_descuento_linea'
      AND (ff.alcance = 'todos'
           OR (ff.alcance = 'licencias' AND v_licencia = ANY(COALESCE(ff.licencias, ARRAY[]::text[]))))
  ) INTO v_promo_linea;

  IF NOT v_promo_linea THEN
    SELECT COALESCE(SUM(COALESCE(pa.descuento_aplicado, 0)), 0) INTO v_promo
    FROM public.promocion_aplicada pa
    WHERE pa.venta_id = p_venta_id;
  END IF;

  v_new_total := GREATEST(0, ROUND(v_tot - v_extra - v_promo, 2));
  v_new_desc  := ROUND(v_desc_lin + v_extra + v_promo, 2);

  IF ABS(COALESCE(v_venta.subtotal,0)    - ROUND(v_sub,2))  > 0.005
  OR ABS(COALESCE(v_venta.iva_total,0)   - ROUND(v_iva,2))  > 0.005
  OR ABS(COALESCE(v_venta.ieps_total,0)  - ROUND(v_ieps,2)) > 0.005
  OR ABS(COALESCE(v_venta.total,0)       - v_new_total)     > 0.005
  OR ABS(COALESCE(v_venta.descuento_total,0) - v_new_desc)  > 0.005 THEN
    UPDATE public.ventas
       SET subtotal        = ROUND(v_sub, 2),
           iva_total       = ROUND(v_iva, 2),
           ieps_total      = ROUND(v_ieps, 2),
           descuento_total = v_new_desc,
           total           = v_new_total
     WHERE id = p_venta_id;
  END IF;

  PERFORM public.fn_recalc_venta_saldo(p_venta_id);
END;
$$;


--
-- Name: fn_recalc_venta_saldo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_recalc_venta_saldo(p_venta_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta        public.ventas%ROWTYPE;
  v_cobros       numeric;
  v_cobrable     numeric;
  v_orig_base    numeric;
  v_deliv_base   numeric;
  v_es_entregado boolean;
BEGIN
  IF p_venta_id IS NULL THEN RETURN; END IF;
  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_cobros
  FROM public.cobro_aplicaciones ca
  JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = p_venta_id
    AND COALESCE(c.status, 'activo') <> 'cancelado';

  v_cobrable := public.fn_venta_cobrable(v_venta);

  UPDATE public.ventas
  SET saldo_pendiente = GREATEST(0, v_cobrable - COALESCE(v_cobros, 0))
  WHERE id = p_venta_id;
END;
$$;


--
-- Name: fn_reevaluar_promos_venta(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reevaluar_promos_venta(_venta_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v record;
  p public.promociones;
  l record;
  total_reparado numeric := 0;
  usados uuid[] := '{}';
  regalo_consumido jsonb := '{}'::jsonb;
  fecha_venta date;
  dia_txt text;
  v_zona uuid;
  cant_min numeric;
  cant_gratis numeric;
  disparo numeric;
  ganado numeric;
  regalo_linea record;
  disponibles numeric;
  gratis_real numeric;
  desc_monto numeric;
  unit numeric;
  -- modo acumulado
  cant_grupo numeric;
  g_in numeric;
  g_out numeric;
  consumido numeric;
  avail_in numeric;
  avail_out numeric;
  s int;
  pedido numeric;
  de_fuera numeric;
  del_grupo numeric;
  por_asignar numeric;
  saltar numeric;
  u numeric;
BEGIN
  SELECT * INTO v FROM public.ventas WHERE id = _venta_id;
  IF NOT FOUND OR v.status = 'cancelado' THEN RETURN 0; END IF;

  -- Idempotencia: si la venta ya tiene promociones registradas, no se toca.
  IF EXISTS (SELECT 1 FROM public.promocion_aplicada WHERE venta_id = _venta_id) THEN
    RETURN 0;
  END IF;

  SELECT c.zona_id INTO v_zona FROM public.clientes c WHERE c.id = v.cliente_id;

  fecha_venta := COALESCE(v.fecha, (v.created_at AT TIME ZONE 'America/Mexico_City')::date);
  dia_txt := CASE EXTRACT(dow FROM fecha_venta)::int
    WHEN 0 THEN 'domingo' WHEN 1 THEN 'lunes' WHEN 2 THEN 'martes' WHEN 3 THEN 'miércoles'
    WHEN 4 THEN 'jueves' WHEN 5 THEN 'viernes' ELSE 'sábado' END;

  FOR p IN
    SELECT * FROM public.promociones
    WHERE empresa_id = v.empresa_id AND activa
      AND (vigencia_inicio IS NULL OR vigencia_inicio <= fecha_venta)
      AND (vigencia_fin IS NULL OR vigencia_fin >= fecha_venta)
      AND (COALESCE(array_length(dias_semana,1),0) = 0 OR dia_txt = ANY(dias_semana))
    ORDER BY COALESCE(prioridad,0) DESC
  LOOP
    cant_min := GREATEST(1, COALESCE(p.cantidad_minima,1));
    cant_gratis := GREATEST(1, COALESCE(p.cantidad_gratis,1));

    -- ── Modo acumulado: suma de los SKU participantes ──────────────────────
    IF COALESCE(p.modo_minimo, 'por_sku') = 'acumulado' THEN
      IF p.tipo = 'producto_gratis' THEN
        IF p.producto_gratis_id IS NULL THEN CONTINUE; END IF;

        SELECT COALESCE(SUM(CASE WHEN vl.producto_id = p.producto_gratis_id THEN 0 ELSE vl.cantidad END),0),
               COALESCE(SUM(CASE WHEN vl.producto_id = p.producto_gratis_id THEN vl.cantidad ELSE 0 END),0)
          INTO disparo, g_in
        FROM public.venta_lineas vl
        LEFT JOIN public.productos pr ON pr.id = vl.producto_id
        WHERE vl.venta_id = _venta_id
          AND NOT (vl.producto_id = ANY(usados))
          AND vl.producto_id = ANY(p.participantes_ids)
          AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona);

        SELECT COALESCE(SUM(vl.cantidad),0) - g_in INTO g_out
        FROM public.venta_lineas vl
        WHERE vl.venta_id = _venta_id AND vl.producto_id = p.producto_gratis_id;

        consumido := COALESCE((regalo_consumido ->> p.producto_gratis_id::text)::numeric, 0);
        avail_out := GREATEST(0, g_out - consumido);
        avail_in := GREATEST(0, g_in - GREATEST(0, consumido - g_out));
        cant_grupo := disparo + avail_in;

        gratis_real := 0;
        s := floor(cant_grupo / cant_min)::int;
        WHILE s > 0 LOOP
          pedido := s * cant_gratis;
          de_fuera := LEAST(pedido, avail_out);
          del_grupo := LEAST(pedido - de_fuera, avail_in);
          IF cant_grupo - del_grupo >= s * cant_min THEN
            gratis_real := de_fuera + del_grupo;
            EXIT;
          END IF;
          s := s - 1;
        END LOOP;
        IF gratis_real <= 0 THEN CONTINUE; END IF;

        -- Reparto en los renglones del regalo: primero los de fuera del grupo.
        por_asignar := gratis_real;
        saltar := consumido;
        FOR l IN
          SELECT vl.*, (vl.producto_id = ANY(p.participantes_ids)
                        AND NOT (vl.producto_id = ANY(usados))
                        AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona)) AS en_grupo
          FROM public.venta_lineas vl
          LEFT JOIN public.productos pr ON pr.id = vl.producto_id
          WHERE vl.venta_id = _venta_id AND vl.producto_id = p.producto_gratis_id
            AND COALESCE(vl.cantidad,0) > 0
          ORDER BY en_grupo ASC, vl.created_at
        LOOP
          EXIT WHEN por_asignar <= 0;
          u := GREATEST(0, l.cantidad - saltar);
          saltar := GREATEST(0, saltar - l.cantidad);
          u := LEAST(u, por_asignar);
          IF u <= 0 THEN CONTINUE; END IF;
          unit := l.total / NULLIF(l.cantidad,0);
          desc_monto := LEAST(ROUND(u * unit, 2), l.total);
          IF desc_monto > 0 THEN
            INSERT INTO public.promocion_aplicada (promocion_id, venta_id, venta_linea_id, descuento_aplicado, descripcion, promocion_nombre, tipo, cantidad_gratis)
            VALUES (p.id, _venta_id, l.id, desc_monto, u || '× gratis — ' || p.nombre, p.nombre, p.tipo::text, u);
            total_reparado := total_reparado + desc_monto;
          END IF;
          por_asignar := por_asignar - u;
        END LOOP;

        regalo_consumido := regalo_consumido || jsonb_build_object(
          p.producto_gratis_id::text, consumido + gratis_real);

        IF NOT COALESCE(p.acumulable,false) THEN
          SELECT usados || COALESCE(array_agg(DISTINCT vl.producto_id),'{}') INTO usados
          FROM public.venta_lineas vl
          LEFT JOIN public.productos pr ON pr.id = vl.producto_id
          WHERE vl.venta_id = _venta_id
            AND vl.producto_id = ANY(p.participantes_ids)
            AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona);
        END IF;
        CONTINUE;
      END IF;

      SELECT COALESCE(SUM(vl.cantidad),0) INTO cant_grupo
      FROM public.venta_lineas vl
      LEFT JOIN public.productos pr ON pr.id = vl.producto_id
      WHERE vl.venta_id = _venta_id
        AND NOT (vl.producto_id = ANY(usados))
        AND vl.producto_id = ANY(p.participantes_ids)
        AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona);

      IF cant_grupo <= 0 OR cant_grupo < COALESCE(p.cantidad_minima,0) THEN CONTINUE; END IF;
      IF p.tipo = 'volumen' AND (COALESCE(p.cantidad_minima,0) <= 0 OR COALESCE(p.valor,0) <= 0) THEN CONTINUE; END IF;

      FOR l IN
        SELECT vl.*
        FROM public.venta_lineas vl
        LEFT JOIN public.productos pr ON pr.id = vl.producto_id
        WHERE vl.venta_id = _venta_id
          AND NOT (vl.producto_id = ANY(usados))
          AND vl.producto_id = ANY(p.participantes_ids)
          AND COALESCE(vl.total,0) > 0
          AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona)
      LOOP
        unit := l.total / NULLIF(l.cantidad,0);
        desc_monto := 0;
        IF p.tipo IN ('descuento_porcentaje', 'volumen') THEN
          desc_monto := ROUND(l.total * COALESCE(p.valor,0) / 100.0, 2);
        ELSIF p.tipo = 'descuento_monto' THEN
          desc_monto := ROUND(LEAST(COALESCE(p.valor,0) * l.cantidad, l.total), 2);
        ELSIF p.tipo = 'precio_especial' THEN
          desc_monto := ROUND(GREATEST(0, (unit - COALESCE(p.valor,0)) * l.cantidad), 2);
        END IF;
        IF desc_monto <= 0 THEN CONTINUE; END IF;
        desc_monto := LEAST(desc_monto, l.total);

        INSERT INTO public.promocion_aplicada (promocion_id, venta_id, venta_linea_id, descuento_aplicado, descripcion, promocion_nombre, tipo, cantidad_gratis)
        VALUES (p.id, _venta_id, l.id, desc_monto, p.nombre, p.nombre, p.tipo::text, 0);
        total_reparado := total_reparado + desc_monto;
        IF NOT COALESCE(p.acumulable,false) THEN
          usados := usados || l.producto_id;
        END IF;
      END LOOP;
      CONTINUE;
    END IF;

    -- Producto gratis con regalo DISTINTO: se evalúa global por promoción.
    IF p.tipo = 'producto_gratis' AND p.producto_gratis_id IS NOT NULL THEN
      SELECT COALESCE(SUM(vl.cantidad),0) INTO disparo
      FROM public.venta_lineas vl
      LEFT JOIN public.productos pr ON pr.id = vl.producto_id
      WHERE vl.venta_id = _venta_id
        AND vl.producto_id <> p.producto_gratis_id
        AND NOT (vl.producto_id = ANY(usados))
        AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona);

      ganado := floor(COALESCE(disparo,0) / cant_min) * cant_gratis;
      IF ganado <= 0 THEN CONTINUE; END IF;

      SELECT * INTO regalo_linea FROM public.venta_lineas
      WHERE venta_id = _venta_id AND producto_id = p.producto_gratis_id
      ORDER BY cantidad DESC LIMIT 1;
      IF NOT FOUND OR COALESCE(regalo_linea.cantidad,0) <= 0 THEN CONTINUE; END IF;

      disponibles := regalo_linea.cantidad
        - COALESCE((regalo_consumido ->> p.producto_gratis_id::text)::numeric, 0);
      gratis_real := LEAST(ganado, GREATEST(disponibles, 0));
      IF gratis_real <= 0 THEN CONTINUE; END IF;

      unit := regalo_linea.total / NULLIF(regalo_linea.cantidad,0);
      desc_monto := ROUND(gratis_real * unit, 2);
      IF desc_monto <= 0 THEN CONTINUE; END IF;

      INSERT INTO public.promocion_aplicada (promocion_id, venta_id, venta_linea_id, descuento_aplicado, descripcion, promocion_nombre, tipo, cantidad_gratis)
      VALUES (p.id, _venta_id, regalo_linea.id, desc_monto, gratis_real || '× gratis — ' || p.nombre, p.nombre, p.tipo::text, gratis_real);
      total_reparado := total_reparado + desc_monto;
      regalo_consumido := regalo_consumido || jsonb_build_object(
        p.producto_gratis_id::text,
        COALESCE((regalo_consumido ->> p.producto_gratis_id::text)::numeric,0) + gratis_real);

      IF NOT COALESCE(p.acumulable,false) THEN
        SELECT usados || COALESCE(array_agg(DISTINCT vl.producto_id),'{}') INTO usados
        FROM public.venta_lineas vl
        WHERE vl.venta_id = _venta_id AND vl.producto_id <> p.producto_gratis_id;
      END IF;
      CONTINUE;
    END IF;

    -- Resto de tipos: por línea.
    FOR l IN
      SELECT vl.*, pr.clasificacion_id
      FROM public.venta_lineas vl
      LEFT JOIN public.productos pr ON pr.id = vl.producto_id
      WHERE vl.venta_id = _venta_id
        AND NOT (vl.producto_id = ANY(usados))
        AND COALESCE(vl.cantidad,0) > 0 AND COALESCE(vl.total,0) > 0
        AND public.fn_promo_linea_elegible(p, vl, pr.clasificacion_id, v.cliente_id, v_zona)
    LOOP
      IF l.cantidad < COALESCE(p.cantidad_minima,0) THEN CONTINUE; END IF;
      unit := l.total / NULLIF(l.cantidad,0);
      desc_monto := 0;

      IF p.tipo = 'descuento_porcentaje' THEN
        desc_monto := ROUND(l.total * COALESCE(p.valor,0) / 100.0, 2);
      ELSIF p.tipo = 'descuento_monto' THEN
        desc_monto := ROUND(LEAST(COALESCE(p.valor,0) * l.cantidad, l.total), 2);
      ELSIF p.tipo = 'precio_especial' THEN
        desc_monto := ROUND(GREATEST(0, (unit - COALESCE(p.valor,0)) * l.cantidad), 2);
      ELSIF p.tipo = 'volumen' THEN
        IF COALESCE(p.cantidad_minima,0) <= 0 OR COALESCE(p.valor,0) <= 0 THEN CONTINUE; END IF;
        desc_monto := ROUND(l.total * COALESCE(p.valor,0) / 100.0, 2);
      ELSIF p.tipo = 'producto_gratis' THEN
        ganado := floor(l.cantidad / cant_min) * cant_gratis;
        IF ganado <= 0 THEN CONTINUE; END IF;
        desc_monto := ROUND(ganado * unit, 2);
      END IF;

      IF desc_monto <= 0 THEN CONTINUE; END IF;
      desc_monto := LEAST(desc_monto, l.total);

      INSERT INTO public.promocion_aplicada (promocion_id, venta_id, venta_linea_id, descuento_aplicado, descripcion, promocion_nombre, tipo, cantidad_gratis)
      VALUES (p.id, _venta_id, l.id, desc_monto, p.nombre, p.nombre, p.tipo::text,
              CASE WHEN p.tipo = 'producto_gratis' THEN ganado ELSE 0 END);
      total_reparado := total_reparado + desc_monto;

      IF NOT COALESCE(p.acumulable,false) THEN
        usados := usados || l.producto_id;
      END IF;
    END LOOP;
  END LOOP;

  RETURN ROUND(total_reparado, 2);
END;
$$;


--
-- Name: fn_refresh_logistica_pedido_resumen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_refresh_logistica_pedido_resumen(p_pedido_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.ventas v
    WHERE v.id = p_pedido_id
      AND v.tipo = 'pedido'
  ) THEN
    DELETE FROM public.logistica_pedido_resumen WHERE pedido_id = p_pedido_id;
    RETURN;
  END IF;

  WITH venta_base AS MATERIALIZED (
    SELECT
      v.id,
      v.empresa_id,
      v.status::text AS status,
      v.cerrado_at,
      v.fecha_entrega AS fecha_entrega_original
    FROM public.ventas v
    WHERE v.id = p_pedido_id
      AND v.tipo = 'pedido'
  ),
  venta_producto AS MATERIALIZED (
    SELECT
      vl.producto_id,
      SUM(COALESCE(vl.cantidad, 0))::numeric AS cantidad,
      SUM(COALESCE(vl.cantidad, 0) * COALESCE(vl.precio_unitario, 0))::numeric AS valor
    FROM public.venta_lineas vl
    WHERE vl.venta_id = p_pedido_id
    GROUP BY vl.producto_id
  ),
  entrega_producto AS MATERIALIZED (
    SELECT
      el.producto_id,
      SUM(CASE WHEN e.status::text = 'borrador' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS generada,
      SUM(CASE WHEN e.status::text IN ('surtido','asignado','cargado','en_ruta','hecho') THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS surtida,
      SUM(CASE WHEN e.status::text = 'hecho' THEN COALESCE(el.cantidad_entregada, 0) ELSE 0 END)::numeric AS entregada
    FROM public.entregas e
    INNER JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.pedido_id = p_pedido_id
      AND e.status::text <> 'cancelado'
    GROUP BY el.producto_id
  ),
  line_calc AS MATERIALIZED (
    SELECT
      vp.producto_id,
      vp.cantidad,
      vp.valor,
      COALESCE(ep.generada, 0)::numeric AS generada,
      COALESCE(ep.surtida, 0)::numeric AS surtida,
      COALESCE(ep.entregada, 0)::numeric AS entregada,
      GREATEST(0::numeric, vp.cantidad - COALESCE(ep.surtida, 0) - COALESCE(ep.generada, 0))::numeric AS pendiente,
      CASE
        WHEN vp.cantidad > 0 THEN
          GREATEST(0::numeric, vp.cantidad - COALESCE(ep.surtida, 0) - COALESCE(ep.generada, 0)) * (vp.valor / vp.cantidad)
        ELSE 0::numeric
      END AS valor_pendiente
    FROM venta_producto vp
    LEFT JOIN entrega_producto ep
      ON ep.producto_id IS NOT DISTINCT FROM vp.producto_id
  ),
  metrics AS (
    SELECT
      COALESCE(SUM(cantidad), 0)::numeric AS total_demanda,
      COALESCE(SUM(generada), 0)::numeric AS total_generada,
      COALESCE(SUM(surtida), 0)::numeric AS total_surtido,
      COALESCE(SUM(entregada), 0)::numeric AS total_entregado,
      COALESCE(SUM(pendiente), 0)::numeric AS total_pendiente,
      COALESCE(SUM(valor_pendiente), 0)::numeric AS total_valor_pendiente,
      COUNT(*) FILTER (WHERE pendiente > 0)::bigint AS lineas_pendientes
    FROM line_calc
  ),
  entrega_meta AS (
    SELECT
      MAX(e.fecha) FILTER (WHERE e.status::text <> 'cancelado') AS fecha_programada_actual,
      MAX(e.fecha_entrega) FILTER (WHERE e.status::text = 'hecho') AS fecha_entrega_real,
      COALESCE(BOOL_OR(e.status::text IN ('asignado','cargado','en_ruta')), false) AS tiene_en_ruta,
      (
        ARRAY_AGG(
          e.vendedor_ruta_id
          ORDER BY e.fecha DESC NULLS LAST, e.created_at DESC
        ) FILTER (
          WHERE e.status::text <> 'cancelado'
            AND e.vendedor_ruta_id IS NOT NULL
        )
      )[1] AS vendedor_ruta_id
    FROM public.entregas e
    WHERE e.pedido_id = p_pedido_id
  ),
  derived_1 AS (
    SELECT
      vb.*,
      m.*,
      COALESCE(em.fecha_programada_actual, vb.fecha_entrega_original) AS fecha_programada,
      em.fecha_entrega_real,
      em.tiene_en_ruta,
      em.vendedor_ruta_id,
      (m.total_demanda > 0 AND m.total_entregado >= m.total_demanda) AS fully_delivered,
      (m.total_demanda > 0 AND m.total_surtido >= m.total_demanda) AS fully_surtido
    FROM venta_base vb
    CROSS JOIN metrics m
    CROSS JOIN entrega_meta em
  ),
  derived_2 AS (
    SELECT
      d1.*,
      (
        NOT d1.fully_surtido
        AND d1.total_demanda > 0
        AND (d1.total_generada + d1.total_surtido) >= d1.total_demanda
      ) AS fully_generada,
      (NOT d1.fully_delivered AND d1.tiene_en_ruta) AS en_ruta
    FROM derived_1 d1
  ),
  final AS (
    SELECT
      d2.*,
      CASE
        WHEN d2.fully_delivered THEN 'entregado'
        WHEN d2.en_ruta THEN 'en_ruta'
        WHEN d2.fully_surtido THEN 'surtido_completo'
        WHEN d2.total_surtido > 0 THEN 'surtido_parcial'
        WHEN d2.total_generada > 0 AND d2.fully_generada THEN 'pendiente_surtir'
        WHEN d2.total_generada > 0 THEN 'en_surtido'
        ELSE NULL
      END AS estado_odoo,
      CASE
        WHEN d2.cerrado_at IS NOT NULL THEN 'cerrados'
        WHEN d2.status IN ('cancelado','facturado') THEN NULL
        WHEN d2.fully_delivered THEN 'entregados'
        WHEN d2.en_ruta THEN 'en_ruta'
        WHEN d2.fully_surtido THEN 'surtidos'
        WHEN d2.fully_generada THEN 'generadas'
        ELSE 'pendientes'
      END AS bucket
    FROM derived_2 d2
  )
  INSERT INTO public.logistica_pedido_resumen (
    pedido_id,
    empresa_id,
    total_demanda,
    total_generada,
    total_surtido,
    total_entregado,
    total_pendiente,
    total_valor_pendiente,
    lineas_pendientes,
    fully_generada,
    fully_surtido,
    fully_delivered,
    en_ruta,
    estado_odoo,
    bucket,
    fecha_programada,
    fecha_entrega_real,
    vendedor_ruta_id,
    updated_at
  )
  SELECT
    id,
    empresa_id,
    total_demanda,
    total_generada,
    total_surtido,
    total_entregado,
    total_pendiente,
    total_valor_pendiente,
    lineas_pendientes,
    fully_generada,
    fully_surtido,
    fully_delivered,
    en_ruta,
    estado_odoo,
    bucket,
    fecha_programada,
    fecha_entrega_real,
    vendedor_ruta_id,
    now()
  FROM final
  ON CONFLICT (pedido_id) DO UPDATE SET
    empresa_id = EXCLUDED.empresa_id,
    total_demanda = EXCLUDED.total_demanda,
    total_generada = EXCLUDED.total_generada,
    total_surtido = EXCLUDED.total_surtido,
    total_entregado = EXCLUDED.total_entregado,
    total_pendiente = EXCLUDED.total_pendiente,
    total_valor_pendiente = EXCLUDED.total_valor_pendiente,
    lineas_pendientes = EXCLUDED.lineas_pendientes,
    fully_generada = EXCLUDED.fully_generada,
    fully_surtido = EXCLUDED.fully_surtido,
    fully_delivered = EXCLUDED.fully_delivered,
    en_ruta = EXCLUDED.en_ruta,
    estado_odoo = EXCLUDED.estado_odoo,
    bucket = EXCLUDED.bucket,
    fecha_programada = EXCLUDED.fecha_programada,
    fecha_entrega_real = EXCLUDED.fecha_entrega_real,
    vendedor_ruta_id = EXCLUDED.vendedor_ruta_id,
    updated_at = now();
END;
$$;


--
-- Name: fn_revertir_surtido_al_cancelar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_revertir_surtido_al_cancelar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mov record;
  v_upd int;
BEGIN
  IF TG_OP <> 'UPDATE'
     OR OLD.status::text NOT IN ('borrador','surtido')
     OR NEW.status::text NOT IN ('cancelado','no_entregado') THEN
    RETURN NEW;
  END IF;

  FOR v_mov IN
    SELECT id, producto_id, cantidad, lote_id, almacen_origen_id
    FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo = 'entrega' AND tipo = 'salida'
    FOR UPDATE
  LOOP
    IF v_mov.almacen_origen_id IS NOT NULL AND COALESCE(v_mov.cantidad, 0) <> 0 THEN
      UPDATE public.stock_almacen
      SET cantidad = cantidad + v_mov.cantidad, updated_at = now()
      WHERE almacen_id = v_mov.almacen_origen_id AND producto_id = v_mov.producto_id;
      GET DIAGNOSTICS v_upd = ROW_COUNT;
      IF v_upd = 0 THEN
        INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
        VALUES (NEW.empresa_id, v_mov.almacen_origen_id, v_mov.producto_id, v_mov.cantidad);
      END IF;
      IF v_mov.lote_id IS NOT NULL THEN
        PERFORM public._aplica_stock_lote(NEW.empresa_id, v_mov.almacen_origen_id, v_mov.producto_id, v_mov.lote_id, v_mov.cantidad);
      END IF;
    END IF;
    DELETE FROM public.movimientos_inventario WHERE id = v_mov.id;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: fn_sugerencias_resurtido(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sugerencias_resurtido(p_almacen_id uuid) RETURNS TABLE(producto_id uuid, codigo text, nombre text, stock_actual numeric, stock_minimo numeric, stock_maximo numeric, cantidad_sugerida numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.codigo, p.nombre,
         COALESCE(sa.cantidad, 0) AS stock_actual,
         c.stock_minimo, c.stock_maximo,
         GREATEST(c.stock_maximo - COALESCE(sa.cantidad, 0), 0) AS cantidad_sugerida
  FROM public.producto_almacen_config c
  JOIN public.productos p ON p.id = c.producto_id
  JOIN public.almacenes a ON a.id = c.almacen_id
  LEFT JOIN public.stock_almacen sa
    ON sa.almacen_id = c.almacen_id AND sa.producto_id = c.producto_id
  WHERE c.almacen_id = p_almacen_id
    AND c.activo
    AND p.status = 'activo'
    AND (a.empresa_id = public.get_my_empresa_id() OR public.is_super_admin(auth.uid()))
    AND COALESCE(sa.cantidad, 0) <= c.stock_minimo
    AND GREATEST(c.stock_maximo - COALESCE(sa.cantidad, 0), 0) > 0
  ORDER BY p.nombre;
$$;


--
-- Name: fn_sync_apartado_linea(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_apartado_linea(p_linea_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_l public.venta_lineas%ROWTYPE;
  v_tipo text; v_status text; v_empresa_id uuid; v_flag boolean;
  v_cerrado timestamptz;
  v_detalle int;
BEGIN
  SELECT * INTO v_l FROM public.venta_lineas WHERE id = p_linea_id;
  IF NOT FOUND THEN
    DELETE FROM public.stock_apartado WHERE venta_linea_id = p_linea_id;
    RETURN;
  END IF;

  SELECT v.tipo, v.status, v.empresa_id, v.cerrado_at
    INTO v_tipo, v_status, v_empresa_id, v_cerrado
    FROM public.ventas v WHERE v.id = v_l.venta_id;

  IF v_tipo IS DISTINCT FROM 'pedido' THEN RETURN; END IF;

  SELECT apartar_stock_pedidos INTO v_flag FROM public.empresas WHERE id = v_empresa_id;
  IF NOT COALESCE(v_flag, false) THEN RETURN; END IF;

  IF v_status IN ('cancelado','entregado','facturado') OR v_cerrado IS NOT NULL
     OR v_l.almacen_id IS NULL OR v_l.producto_id IS NULL THEN
    DELETE FROM public.stock_apartado WHERE venta_linea_id = p_linea_id;
    RETURN;
  END IF;

  SELECT count(*) INTO v_detalle FROM public.venta_linea_lotes WHERE venta_linea_id = p_linea_id;

  IF v_detalle > 0 THEN
    DELETE FROM public.stock_apartado sa
     WHERE sa.venta_linea_id = p_linea_id
       AND (sa.lote_id IS NULL
            OR NOT EXISTS (SELECT 1 FROM public.venta_linea_lotes d
                            WHERE d.venta_linea_id = p_linea_id AND d.lote_id = sa.lote_id));

    INSERT INTO public.stock_apartado (empresa_id, venta_id, venta_linea_id, producto_id, almacen_id, cantidad, lote_id)
    SELECT v_empresa_id, v_l.venta_id, p_linea_id, v_l.producto_id,
           COALESCE(d.almacen_id, v_l.almacen_id), d.cantidad, d.lote_id
      FROM public.venta_linea_lotes d
     WHERE d.venta_linea_id = p_linea_id
    ON CONFLICT (venta_linea_id, COALESCE(lote_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO UPDATE SET cantidad = EXCLUDED.cantidad,
                  almacen_id = EXCLUDED.almacen_id,
                  producto_id = EXCLUDED.producto_id,
                  updated_at = now();
  ELSE
    DELETE FROM public.stock_apartado sa
     WHERE sa.venta_linea_id = p_linea_id
       AND sa.lote_id IS DISTINCT FROM v_l.lote_id;

    INSERT INTO public.stock_apartado (empresa_id, venta_id, venta_linea_id, producto_id, almacen_id, cantidad, lote_id)
    VALUES (v_empresa_id, v_l.venta_id, p_linea_id, v_l.producto_id, v_l.almacen_id, COALESCE(v_l.cantidad, 0), v_l.lote_id)
    ON CONFLICT (venta_linea_id, COALESCE(lote_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO UPDATE SET cantidad = EXCLUDED.cantidad,
                  almacen_id = EXCLUDED.almacen_id,
                  producto_id = EXCLUDED.producto_id,
                  updated_at = now();
  END IF;
END;
$$;


--
-- Name: fn_sync_venta_comision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_venta_comision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid;
  v_vendedor uuid;
  v_fecha date;
  v_status text;
BEGIN
  SELECT v.empresa_id, v.vendedor_id, v.fecha, v.status
    INTO v_empresa, v_vendedor, v_fecha, v_status
  FROM public.ventas v WHERE v.id = NEW.venta_id;

  IF v_empresa IS NULL OR v_vendedor IS NULL THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.comision_monto,0) <= 0 OR v_status = 'cancelado' THEN
    DELETE FROM public.venta_comisiones
     WHERE venta_linea_id = NEW.id AND pagada = false AND pago_comision_id IS NULL;
    RETURN NEW;
  END IF;

  INSERT INTO public.venta_comisiones (
    empresa_id, venta_id, venta_linea_id, vendedor_id, producto_id,
    monto_venta, comision_pct, comision_monto, fecha_venta
  ) VALUES (
    v_empresa, NEW.venta_id, NEW.id, v_vendedor, NEW.producto_id,
    COALESCE(NEW.total,0), COALESCE(NEW.comision_pct,0), COALESCE(NEW.comision_monto,0),
    COALESCE(v_fecha, CURRENT_DATE)
  )
  ON CONFLICT (venta_linea_id) DO UPDATE SET
    vendedor_id = EXCLUDED.vendedor_id,
    producto_id = EXCLUDED.producto_id,
    monto_venta = EXCLUDED.monto_venta,
    comision_pct = EXCLUDED.comision_pct,
    comision_monto = EXCLUDED.comision_monto,
    fecha_venta = EXCLUDED.fecha_venta
  WHERE public.venta_comisiones.pagada = false
    AND public.venta_comisiones.pago_comision_id IS NULL;

  RETURN NEW;
END;
$$;


--
-- Name: fn_sync_venta_inventario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_venta_inventario(p_venta_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta       public.ventas%ROWTYPE;
  v_almacen     uuid;
  v_aplica      boolean;
  v_ref_entrada text;
  p             RECORD;
  l             RECORD;
  v_lote        RECORD;
  v_diff        numeric;
  v_acc         numeric;
  v_res         numeric;
  v_take        numeric;
  v_maneja      boolean;
  v_stock_id    uuid;
  v_stock_act   numeric;
  v_user        uuid;
  v_nombre      text;
  v_log         jsonb := '[]'::jsonb;
BEGIN
  IF p_venta_id IS NULL THEN RETURN; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_venta_id::text, 0));

  SELECT * INTO v_venta FROM public.ventas WHERE id = p_venta_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_venta.tipo::text = 'saldo_inicial' OR COALESCE(v_venta.es_saldo_inicial, false) THEN RETURN; END IF;
  IF v_venta.tipo::text = 'pedido'
     AND EXISTS (SELECT 1 FROM public.entregas e WHERE e.pedido_id = p_venta_id) THEN
    RETURN;
  END IF;

  v_almacen := COALESCE(
    v_venta.almacen_id,
    (SELECT almacen_id FROM public.profiles WHERE id = v_venta.vendedor_id LIMIT 1)
  );

  v_aplica := CASE
    WHEN v_venta.status::text IN ('cancelado', 'borrador') THEN false
    WHEN v_venta.tipo::text = 'venta_directa'
      THEN COALESCE(v_venta.entrega_inmediata, false) OR v_venta.status::text IN ('entregado', 'facturado')
    WHEN v_venta.tipo::text = 'pedido'
      THEN v_venta.status::text IN ('entregado', 'facturado')
    ELSE false
  END;

  IF v_almacen IS NULL THEN
    IF v_aplica THEN
      RAISE EXCEPTION 'No se puede aplicar inventario de la venta % sin almacén asignado.',
        COALESCE(v_venta.folio, v_venta.id::text);
    END IF;
    RETURN;
  END IF;

  v_ref_entrada := CASE WHEN v_venta.status::text = 'cancelado'
                        THEN 'cancelacion_venta' ELSE 'reverso_borrador' END;
  v_user := COALESCE(auth.uid(), v_venta.vendedor_id, v_venta.creado_por);
  SELECT nombre INTO v_nombre FROM public.profiles WHERE id = v_user;

  CREATE TEMP TABLE IF NOT EXISTS _sync_des (producto_id uuid, lote_id uuid, cant numeric) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS _sync_apl (producto_id uuid, lote_id uuid, cant numeric) ON COMMIT DROP;
  DELETE FROM _sync_des WHERE true;
  DELETE FROM _sync_apl WHERE true;

  IF v_aplica THEN
    INSERT INTO _sync_des
    SELECT producto_id, lote_id, SUM(cant) FROM (
      SELECT vl.producto_id, d.lote_id, COALESCE(d.cantidad,0) AS cant
        FROM public.venta_lineas vl
        JOIN public.venta_linea_lotes d ON d.venta_linea_id = vl.id
       WHERE vl.venta_id = p_venta_id
      UNION ALL
      SELECT vl.producto_id, vl.lote_id, COALESCE(vl.cantidad,0)
        FROM public.venta_lineas vl
       WHERE vl.venta_id = p_venta_id
         AND NOT EXISTS (SELECT 1 FROM public.venta_linea_lotes d WHERE d.venta_linea_id = vl.id)
    ) x GROUP BY 1,2;
  END IF;

  INSERT INTO _sync_apl
  SELECT mi.producto_id, mi.lote_id,
         SUM(CASE WHEN mi.tipo::text = 'salida' THEN COALESCE(mi.cantidad,0) ELSE -COALESCE(mi.cantidad,0) END)
    FROM public.movimientos_inventario mi
   WHERE mi.referencia_id = p_venta_id
     AND mi.referencia_tipo IN ('venta','venta_lote','cancelacion_venta','reverso_borrador',
                                'cancelacion_venta_lote','reverso_borrador_lote')
   GROUP BY 1,2;

  FOR p IN
    SELECT producto_id,
           SUM(des) AS deseado_total,
           SUM(apl) AS aplicado_total
      FROM (
        SELECT producto_id, cant AS des, 0::numeric AS apl FROM _sync_des
        UNION ALL
        SELECT producto_id, 0::numeric, cant FROM _sync_apl
      ) z GROUP BY producto_id
      ORDER BY producto_id
  LOOP
    v_diff := ROUND(COALESCE(p.deseado_total,0) - COALESCE(p.aplicado_total,0), 6);
    SELECT COALESCE(maneja_lote,false) INTO v_maneja FROM public.productos WHERE id = p.producto_id;
    v_acc := 0;

    v_stock_id := NULL; v_stock_act := NULL;
    IF ABS(v_diff) > 0.000001 THEN
      SELECT id, cantidad INTO v_stock_id, v_stock_act
        FROM public.stock_almacen
       WHERE almacen_id = v_almacen AND producto_id = p.producto_id FOR UPDATE;
    END IF;

    FOR l IN
      SELECT d.lote_id,
             ROUND(SUM(d.cant) - COALESCE((SELECT a.cant FROM _sync_apl a
                                            WHERE a.producto_id = p.producto_id AND a.lote_id = d.lote_id), 0), 6) AS delta
        FROM _sync_des d
       WHERE d.producto_id = p.producto_id AND d.lote_id IS NOT NULL
       GROUP BY d.lote_id
       ORDER BY d.lote_id
    LOOP
      IF ABS(l.delta) < 0.000001 THEN CONTINUE; END IF;
      IF l.delta > 0 THEN
        INSERT INTO public.movimientos_inventario
          (empresa_id,tipo,producto_id,cantidad,almacen_origen_id,lote_id,referencia_tipo,referencia_id,user_id,fecha,notas)
        VALUES (v_venta.empresa_id,'salida',p.producto_id,l.delta,v_almacen,l.lote_id,'venta',p_venta_id,v_user,
                COALESCE(v_venta.fecha,CURRENT_DATE),'Venta '||COALESCE(v_venta.folio,'')||' · lote');
      ELSE
        INSERT INTO public.movimientos_inventario
          (empresa_id,tipo,producto_id,cantidad,almacen_destino_id,lote_id,referencia_tipo,referencia_id,user_id,fecha,notas)
        VALUES (v_venta.empresa_id,'entrada',p.producto_id,-l.delta,v_almacen,l.lote_id,v_ref_entrada,p_venta_id,v_user,
                COALESCE(v_venta.fecha,CURRENT_DATE),'Reverso venta '||COALESCE(v_venta.folio,'')||' · lote');
      END IF;
      v_acc := v_acc + l.delta;
    END LOOP;

    v_res := ROUND(v_diff - v_acc, 6);

    IF v_res > 0.000001 THEN
      IF v_maneja THEN
        FOR v_lote IN
          SELECT sl.lote_id, sl.cantidad AS existencia
            FROM public.stock_lotes sl JOIN public.lotes lo ON lo.id = sl.lote_id
           WHERE sl.almacen_id = v_almacen AND sl.producto_id = p.producto_id AND sl.cantidad > 0
           ORDER BY lo.fecha_caducidad ASC NULLS LAST, lo.created_at ASC, sl.lote_id ASC
           FOR UPDATE OF sl
        LOOP
          EXIT WHEN v_res <= 0.000001;
          v_take := LEAST(v_lote.existencia, v_res);
          INSERT INTO public.movimientos_inventario
            (empresa_id,tipo,producto_id,cantidad,almacen_origen_id,lote_id,referencia_tipo,referencia_id,user_id,fecha,notas)
          VALUES (v_venta.empresa_id,'salida',p.producto_id,v_take,v_almacen,v_lote.lote_id,'venta',p_venta_id,v_user,
                  COALESCE(v_venta.fecha,CURRENT_DATE),'Venta '||COALESCE(v_venta.folio,'')||' · lote FEFO');
          v_res := ROUND(v_res - v_take, 6);
        END LOOP;
      END IF;
      IF v_res > 0.000001 THEN
        INSERT INTO public.movimientos_inventario
          (empresa_id,tipo,producto_id,cantidad,almacen_origen_id,referencia_tipo,referencia_id,user_id,fecha,notas)
        VALUES (v_venta.empresa_id,'salida',p.producto_id,v_res,v_almacen,'venta',p_venta_id,v_user,
                COALESCE(v_venta.fecha,CURRENT_DATE),'Venta '||COALESCE(v_venta.folio,''));
      END IF;

    ELSIF v_res < -0.000001 THEN
      v_res := -v_res;
      FOR l IN
        SELECT a.lote_id, a.cant AS aplicado
          FROM _sync_apl a
         WHERE a.producto_id = p.producto_id AND a.lote_id IS NOT NULL AND a.cant > 0
           AND NOT EXISTS (SELECT 1 FROM _sync_des d
                            WHERE d.producto_id = p.producto_id AND d.lote_id = a.lote_id)
         ORDER BY a.lote_id
      LOOP
        EXIT WHEN v_res <= 0.000001;
        v_take := LEAST(l.aplicado, v_res);
        INSERT INTO public.movimientos_inventario
          (empresa_id,tipo,producto_id,cantidad,almacen_destino_id,lote_id,referencia_tipo,referencia_id,user_id,fecha,notas)
        VALUES (v_venta.empresa_id,'entrada',p.producto_id,v_take,v_almacen,l.lote_id,v_ref_entrada,p_venta_id,v_user,
                COALESCE(v_venta.fecha,CURRENT_DATE),'Reverso venta '||COALESCE(v_venta.folio,'')||' · lote');
        v_res := ROUND(v_res - v_take, 6);
      END LOOP;
      IF v_res > 0.000001 THEN
        INSERT INTO public.movimientos_inventario
          (empresa_id,tipo,producto_id,cantidad,almacen_destino_id,referencia_tipo,referencia_id,user_id,fecha,notas)
        VALUES (v_venta.empresa_id,'entrada',p.producto_id,v_res,v_almacen,v_ref_entrada,p_venta_id,v_user,
                COALESCE(v_venta.fecha,CURRENT_DATE),'Reverso venta '||COALESCE(v_venta.folio,''));
      END IF;
    END IF;

    IF ABS(v_diff) > 0.000001 THEN
      IF v_stock_id IS NOT NULL THEN
        UPDATE public.stock_almacen
           SET cantidad = COALESCE(v_stock_act,0) - v_diff, updated_at = now()
         WHERE id = v_stock_id;
      ELSE
        INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
        VALUES (v_venta.empresa_id, v_almacen, p.producto_id, -v_diff)
        ON CONFLICT (almacen_id, producto_id)
        DO UPDATE SET cantidad = public.stock_almacen.cantidad - v_diff, updated_at = now();
      END IF;
    END IF;

    IF ABS(v_diff) > 0.000001 OR ABS(v_acc) > 0.000001 THEN
      v_log := v_log || jsonb_build_object(
        'producto_id', p.producto_id, 'almacen_id', v_almacen,
        'deseado', p.deseado_total, 'aplicado_previo', p.aplicado_total, 'ajuste', v_diff);
    END IF;
  END LOOP;

  IF jsonb_array_length(v_log) > 0 THEN
    INSERT INTO public.venta_historial (venta_id, empresa_id, user_id, user_nombre, accion, detalles)
    VALUES (p_venta_id, v_venta.empresa_id, v_user, COALESCE(v_nombre,'sistema'),
            'inventario_ajustado',
            jsonb_build_object('status', v_venta.status, 'aplica', v_aplica, 'ajustes', v_log));
  END IF;

  DELETE FROM _sync_des WHERE true;
  DELETE FROM _sync_apl WHERE true;
END;
$$;


--
-- Name: fn_team_crm_assert_lead(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_assert_lead(p_empresa_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.is_platform_team_member(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.admin_trial_crm_leads lead
    WHERE lead.empresa_id = p_empresa_id
      AND lead.assigned_to IN (SELECT public.get_team_visible_people(auth.uid()))
  ) THEN
    RAISE EXCEPTION 'Este prospecto no pertenece a tu cartera' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: fn_team_crm_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_detail(p_empresa_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_visible boolean;
  v_result jsonb;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.admin_trial_crm_leads lead
    WHERE lead.empresa_id = p_empresa_id
      AND lead.assigned_to IN (SELECT public.get_team_visible_people(auth.uid()))
  ) INTO v_visible;

  IF NOT v_visible THEN
    RAISE EXCEPTION 'Este prospecto no pertenece a tu cartera' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'generated_at', now(),
    'company', COALESCE((
      SELECT to_jsonb(e)
      FROM public.empresas e
      WHERE e.id = p_empresa_id
    ), '{}'::jsonb),

    'lead', COALESCE((
      SELECT to_jsonb(l) || jsonb_build_object(
        'assigned_name', assigned.name,
        'lost_by_name', lost_person.name
      )
      FROM public.admin_trial_crm_leads l
      LEFT JOIN public.commission_people assigned
        ON assigned.id = l.assigned_to
      LEFT JOIN public.platform_team_members lost_tm
        ON lost_tm.user_id = l.lost_by
      LEFT JOIN public.commission_people lost_person
        ON lost_person.id = lost_tm.person_id
      WHERE l.empresa_id = p_empresa_id
    ), '{}'::jsonb),

    'summary', jsonb_build_object(
      'products', (
        SELECT count(*)
        FROM public.productos p
        WHERE p.empresa_id = p_empresa_id
      ),
      'clients', (
        SELECT count(*)
        FROM public.clientes c
        WHERE c.empresa_id = p_empresa_id
      ),
      'users', (
        SELECT count(*)
        FROM public.profiles p
        WHERE p.empresa_id = p_empresa_id
      ),
      'sales', (
        SELECT count(*)
        FROM public.ventas v
        WHERE v.empresa_id = p_empresa_id
      ),
      'invoices', (
        SELECT count(*)
        FROM public.facturas f
        WHERE f.empresa_id = p_empresa_id
      ),
      'paid_invoices', (
        SELECT count(*)
        FROM public.facturas f
        WHERE f.empresa_id = p_empresa_id
          AND f.estado = 'pagada'
      ),
      'paid_total', (
        SELECT COALESCE(sum(f.total), 0)
        FROM public.facturas f
        WHERE f.empresa_id = p_empresa_id
          AND f.estado = 'pagada'
      ),
      'activities', (
        SELECT count(*)
        FROM public.admin_trial_crm_activities a
        WHERE a.empresa_id = p_empresa_id
      )
    ),

    'subscriptions', COALESCE((
      SELECT jsonb_agg(to_jsonb(s) ORDER BY s.created_at DESC)
      FROM public.subscriptions s
      WHERE s.empresa_id = p_empresa_id
    ), '[]'::jsonb),

    'invoices', COALESCE((
      SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC)
      FROM (
        SELECT f.*
        FROM public.facturas f
        WHERE f.empresa_id = p_empresa_id
        ORDER BY f.created_at DESC
        LIMIT 100
      ) x
    ), '[]'::jsonb),

    'activities', COALESCE((
      SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC)
      FROM (
        SELECT
          a.id,
          a.empresa_id,
          a.activity_type,
          a.outcome,
          a.note,
          a.previous_stage,
          a.new_stage,
          a.created_at,
          a.created_by,
          COALESCE(
            person.name,
            CASE
              WHEN a.created_by IS NULL THEN 'Sistema'
              ELSE 'Usuario'
            END
          ) AS actor_name
        FROM public.admin_trial_crm_activities a
        LEFT JOIN public.platform_team_members tm
          ON tm.user_id = a.created_by
        LEFT JOIN public.commission_people person
          ON person.id = tm.person_id
        WHERE a.empresa_id = p_empresa_id
        ORDER BY a.created_at DESC
        LIMIT 1000
      ) x
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_team_crm_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_history(p_empresa_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM public.fn_team_crm_assert_lead(p_empresa_id);
  PERFORM set_config('app.crm_internal_team', 'on', true);
  v_result := public.fn_admin_trial_crm_history(p_empresa_id);
  PERFORM set_config('app.crm_internal_team', 'off', true);
  RETURN v_result;
END;
$$;


--
-- Name: fn_team_crm_log_contact(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_log_contact(p_empresa_id uuid, p_channel text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_stage text;
  v_assigned_to uuid;
  v_new_stage text;
BEGIN
  IF p_channel NOT IN (
    'call',
    'whatsapp',
    'email'
  ) THEN
    RAISE EXCEPTION
      'Canal inválido';
  END IF;

  SELECT
    lead.stage,
    lead.assigned_to
  INTO
    v_stage,
    v_assigned_to
  FROM public.admin_trial_crm_leads lead
  WHERE lead.empresa_id = p_empresa_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_assigned_to NOT IN (
       SELECT public.get_team_visible_people(auth.uid())
     ) THEN
    RAISE EXCEPTION
      'Este prospecto no pertenece a tu cartera'
      USING ERRCODE = '42501';
  END IF;

  v_new_stage := CASE
    WHEN v_stage = 'sin_contactar'
    THEN 'por_contactar'
    ELSE v_stage
  END;

  UPDATE public.admin_trial_crm_leads lead
  SET
    stage = v_new_stage,
    last_contact_at = now(),
    contact_attempts = lead.contact_attempts + 1,
    updated_by = auth.uid()
  WHERE lead.empresa_id = p_empresa_id;

  INSERT INTO public.admin_trial_crm_activities(
    empresa_id,
    activity_type,
    outcome,
    previous_stage,
    new_stage,
    created_by
  )
  VALUES (
    p_empresa_id,
    p_channel,
    'Contacto iniciado desde Mi equipo',
    v_stage,
    v_new_stage,
    auth.uid()
  );

  RETURN jsonb_build_object(
    'ok', true
  );
END;
$$;


