--
-- Name: fn_team_crm_save(uuid, text, uuid, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_save(p_empresa_id uuid, p_stage text, p_assigned_to uuid, p_next_follow_up_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text, p_activity_type text DEFAULT 'note'::text, p_outcome text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM public.fn_team_crm_assert_lead(p_empresa_id);

  IF p_assigned_to IS NOT NULL
     AND p_assigned_to NOT IN (SELECT public.get_team_visible_people(auth.uid())) THEN
    RAISE EXCEPTION 'Solo puedes asignar prospectos a tu equipo visible' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('app.crm_internal_team', 'on', true);
  v_result := public.fn_admin_trial_crm_save(
    p_empresa_id, p_stage, p_assigned_to, p_next_follow_up_at, p_note, p_activity_type, p_outcome
  );
  PERFORM set_config('app.crm_internal_team', 'off', true);
  RETURN v_result;
END;
$$;


--
-- Name: fn_team_crm_workspace(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_crm_workspace(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_people uuid[];
  v_users uuid[];
  v_snapshot jsonb;
  v_leads jsonb;
  v_ops jsonb;
BEGIN
  IF NOT public.is_platform_team_member(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_people
  FROM public.get_team_visible_people(auth.uid()) AS id;

  SELECT COALESCE(array_agg(tm.user_id), ARRAY[]::uuid[]) INTO v_users
  FROM public.platform_team_members tm
  WHERE tm.person_id = ANY (v_people) AND tm.user_id IS NOT NULL;

  PERFORM set_config('app.crm_internal_team', 'on', true);
  v_snapshot := public.fn_admin_trial_crm_workspace(p_days);
  PERFORM set_config('app.crm_internal_team', 'off', true);

  SELECT COALESCE(jsonb_agg(lead), '[]'::jsonb) INTO v_leads
  FROM jsonb_array_elements(COALESCE(v_snapshot->'leads', '[]'::jsonb)) AS lead
  WHERE (lead->>'assigned_to') IS NOT NULL
    AND (lead->>'assigned_to')::uuid = ANY (v_people);

  v_ops := COALESCE(v_snapshot->'operations', '{}'::jsonb);
  IF jsonb_typeof(v_ops) = 'object' THEN
    v_ops := v_ops || jsonb_build_object(
      'team', COALESCE((
        SELECT jsonb_agg(item)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_ops->'team') = 'array' THEN v_ops->'team' ELSE '[]'::jsonb END) AS item
        WHERE (item->>'user_id') IS NOT NULL AND (item->>'user_id')::uuid = ANY (v_users)
      ), '[]'::jsonb),
      'recent', COALESCE((
        SELECT jsonb_agg(item)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_ops->'recent') = 'array' THEN v_ops->'recent' ELSE '[]'::jsonb END) AS item
        WHERE (item->>'created_by') IS NULL OR (item->>'created_by')::uuid = ANY (v_users)
      ), '[]'::jsonb)
    );
  ELSE
    v_ops := '{}'::jsonb;
  END IF;

  RETURN v_snapshot
    || jsonb_build_object(
      'scope', 'team',
      'leads', v_leads,
      'operations', v_ops,
      'assignees', COALESCE((
        SELECT jsonb_agg(person)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_snapshot->'assignees') = 'array' THEN v_snapshot->'assignees' ELSE '[]'::jsonb END) AS person
        WHERE (person->>'id') IS NOT NULL AND (person->>'id')::uuid = ANY (v_people)
      ), '[]'::jsonb)
    );
END;
$$;


--
-- Name: fn_team_portal_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_team_portal_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_me uuid;
  v_result jsonb;
BEGIN
  SELECT tm.person_id
  INTO v_me
  FROM public.platform_team_members tm
  JOIN public.commission_people cp
    ON cp.id = tm.person_id
  WHERE tm.user_id = auth.uid()
    AND tm.status IN ('invited','active')
    AND cp.is_active = true;

  IF v_me IS NULL THEN
    RAISE EXCEPTION 'Acceso de equipo no disponible'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.platform_team_members tm
  SET
    last_access_at = now(),
    status = 'active'
  WHERE tm.person_id = v_me;

  WITH visible AS MATERIALIZED (
    SELECT public.get_team_visible_people(auth.uid()) AS id
  ),

  member_rows AS MATERIALIZED (
    SELECT
      cp.id,
      cp.name,
      cp.email,
      cp.phone,
      cp.manager_id,
      manager.name AS manager_name,
      tm.job_title,
      tm.access_level,
      tm.access_scope,
      tm.commission_mode,
      tm.commission_pct,
      tm.commission_payment_limit,
      tm.commission_fixed_amount
    FROM visible v
    JOIN public.commission_people cp
      ON cp.id = v.id
    JOIN public.platform_team_members tm
      ON tm.person_id = cp.id
    LEFT JOIN public.commission_people manager
      ON manager.id = cp.manager_id
  ),

  lead_base AS MATERIALIZED (
    SELECT
      e.id AS empresa_id,
      e.nombre,
      e.licencia,
      e.email,
      e.telefono,

      lead.stage,
      lead.assigned_to,
      cp.name AS assigned_name,
      lead.next_follow_up_at,
      lead.last_contact_at,
      lead.contact_attempts,
      lead.notes,
      lead.lost_at,
      lead.lost_reason,

      NULLIF(
        to_jsonb(e)->>'created_at',
        ''
      )::timestamptz AS created_at,

      GREATEST(
        0,
        floor(
          EXTRACT(
            EPOCH FROM (
              now() -
              COALESCE(
                NULLIF(
                  to_jsonb(e)->>'created_at',
                  ''
                )::timestamptz,
                now()
              )
            )
          ) / 86400
        )
      )::integer AS age_days,

      (
        SELECT count(*)::integer
        FROM public.productos p
        WHERE p.empresa_id = e.id
      ) AS products,

      (
        SELECT count(*)::integer
        FROM public.clientes c
        WHERE c.empresa_id = e.id
      ) AS clients,

      (
        SELECT count(*)::integer
        FROM public.ventas s
        WHERE s.empresa_id = e.id
      ) AS sales,

      (
        SELECT count(*)::integer
        FROM public.ventas s
        WHERE s.empresa_id = e.id
          AND COALESCE(
            to_jsonb(s)->>'estado',
            ''
          ) IN ('borrador','draft')
      ) AS draft_sales,

      (
        SELECT count(*)::integer
        FROM public.profiles pr
        WHERE pr.empresa_id = e.id
      ) AS users,

      COALESCE(
        (
          SELECT COALESCE(
            to_jsonb(s)->>'status',
            to_jsonb(s)->>'estado'
          )
          FROM public.subscriptions s
          WHERE s.empresa_id = e.id
          ORDER BY
            NULLIF(
              to_jsonb(s)->>'created_at',
              ''
            )::timestamptz DESC NULLS LAST
          LIMIT 1
        ),
        'sin_suscripcion'
      ) AS subscription_status,

      (
        NULLIF(
          to_jsonb(lead)->>'coupon_id',
          ''
        ) IS NOT NULL
      ) AS coupon_active,

      COALESCE(
        NULLIF(
          to_jsonb(lead)->>'activation_score',
          ''
        )::integer,

        LEAST(
          100,

          CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.productos p
              WHERE p.empresa_id = e.id
            )
            THEN 25
            ELSE 0
          END

          +

          CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.clientes c
              WHERE c.empresa_id = e.id
            )
            THEN 20
            ELSE 0
          END

          +

          CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.ventas s
              WHERE s.empresa_id = e.id
            )
            THEN 35
            ELSE 0
          END

          +

          CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.profiles pr
              WHERE pr.empresa_id = e.id
            )
            THEN 20
            ELSE 0
          END
        )
      ) AS activation_score

    FROM public.admin_trial_crm_leads lead
    JOIN visible v
      ON v.id = lead.assigned_to
    JOIN public.empresas e
      ON e.id = lead.empresa_id
    LEFT JOIN public.commission_people cp
      ON cp.id = lead.assigned_to
  ),

  lead_rows AS MATERIALIZED (
    SELECT
      lb.*,

      COALESCE(
        NULLIF(
          to_jsonb(l)->>'setup_level',
          ''
        ),

        CASE
          WHEN lb.activation_score >= 70
            THEN 'casi_listo'
          WHEN lb.activation_score > 0
            THEN 'exploro'
          ELSE 'sin_configurar'
        END
      ) AS setup_level

    FROM lead_base lb
    JOIN public.admin_trial_crm_leads l
      ON l.empresa_id = lb.empresa_id
  ),

  company_rows AS MATERIALIZED (
    SELECT
      e.id AS empresa_id,
      e.nombre,
      e.licencia,
      e.email,
      e.telefono,

      cca.managed_by_id,
      managed.name AS managed_by_name,

      cca.commissioned_by_id,
      commissioned.name AS commissioned_by_name,

      (pa.id IS NOT NULL) AS has_partner,

      COALESCE(
        (
          SELECT sum(f.total)
          FROM public.facturas f
          WHERE f.empresa_id = e.id
            AND f.estado = 'pagada'
        ),
        0
      ) AS paid_total

    FROM public.commission_client_attributions cca
    JOIN public.empresas e
      ON e.id = cca.empresa_id

    LEFT JOIN public.commission_people managed
      ON managed.id = cca.managed_by_id

    LEFT JOIN public.commission_people commissioned
      ON commissioned.id = cca.commissioned_by_id

    LEFT JOIN public.partner_atribuciones pa
      ON pa.empresa_id = e.id

    WHERE cca.managed_by_id IN (
      SELECT id
      FROM visible
    )
    OR cca.commissioned_by_id IN (
      SELECT id
      FROM visible
    )
  ),

  commission_rows AS MATERIALIZED (
    SELECT
      ice.*,
      cp.name AS person_name,
      e.nombre AS empresa_nombre

    FROM public.internal_commission_entries ice

    JOIN visible v
      ON v.id = ice.person_id

    JOIN public.commission_people cp
      ON cp.id = ice.person_id

    JOIN public.empresas e
      ON e.id = ice.empresa_id
  )

  SELECT jsonb_build_object(

    'generated_at',
    now(),

    'me_id',
    v_me,

    'me',
    (
      SELECT to_jsonb(m)
      FROM member_rows m
      WHERE m.id = v_me
    ),

    'metrics',
    jsonb_build_object(

      'active_leads',
      (
        SELECT count(*)
        FROM lead_rows
        WHERE stage NOT IN (
          'no_interesado',
          'descartado',
          'convertido'
        )
      ),

      'followups_due',
      (
        SELECT count(*)
        FROM lead_rows
        WHERE next_follow_up_at < now()
          AND stage NOT IN (
            'no_interesado',
            'descartado',
            'convertido'
          )
      ),

      'companies',
      (
        SELECT count(*)
        FROM company_rows
      ),

      'contacts_30d',
      (
        SELECT count(*)
        FROM public.admin_trial_crm_activities a
        WHERE a.created_by = auth.uid()
          AND a.activity_type IN (
            'call',
            'whatsapp',
            'email'
          )
          AND a.created_at >= now() - interval '30 days'
      ),

      'commission_pending',
      (
        SELECT COALESCE(
          sum(commission_amount),
          0
        )
        FROM commission_rows
        WHERE status IN (
          'pending',
          'approved'
        )
      ),

      'commission_paid',
      (
        SELECT COALESCE(
          sum(commission_amount),
          0
        )
        FROM commission_rows
        WHERE status = 'paid'
      )
    ),

    'members',
    COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(m)
          ORDER BY m.name
        )
        FROM member_rows m
      ),
      '[]'::jsonb
    ),

    'leads',
    COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(l)
          ORDER BY
            l.next_follow_up_at NULLS LAST,
            l.nombre
        )
        FROM lead_rows l
      ),
      '[]'::jsonb
    ),

    'companies',
    COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(c)
          ORDER BY c.nombre
        )
        FROM company_rows c
      ),
      '[]'::jsonb
    ),

    'commissions',
    COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(c)
          ORDER BY c.created_at DESC
        )
        FROM commission_rows c
      ),
      '[]'::jsonb
    ),

    'activities',
    COALESCE(
      (
        SELECT jsonb_agg(
          to_jsonb(x)
          ORDER BY x.created_at DESC
        )
        FROM (
          SELECT
            a.id,
            a.empresa_id,
            e.nombre AS empresa_nombre,
            a.activity_type,
            a.outcome,
            a.note,
            a.new_stage,
            a.created_at,
            cp.name AS person_name

          FROM public.admin_trial_crm_activities a

          JOIN public.empresas e
            ON e.id = a.empresa_id

          LEFT JOIN public.platform_team_members tm
            ON tm.user_id = a.created_by

          LEFT JOIN public.commission_people cp
            ON cp.id = tm.person_id

          WHERE a.created_by IN (
            SELECT tm2.user_id
            FROM public.platform_team_members tm2
            WHERE tm2.person_id IN (
              SELECT id
              FROM visible
            )
          )

          ORDER BY a.created_at DESC
          LIMIT 300
        ) x
      ),
      '[]'::jsonb
    )

  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: fn_total_efectivo_cerrado(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_total_efectivo_cerrado(p_venta_id uuid, p_total numeric) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_orig_base  numeric;
  v_deliv_base numeric;
BEGIN
  SELECT COALESCE(SUM(base), 0), COALESCE(SUM(base * ratio), 0)
    INTO v_orig_base, v_deliv_base
  FROM (
    SELECT
      (COALESCE(vl.subtotal,0) + COALESCE(vl.iva_monto,0) + COALESCE(vl.ieps_monto,0)) AS base,
      CASE WHEN vl.cantidad > 0
           THEN LEAST(COALESCE(ent.entregado, 0), vl.cantidad) / vl.cantidad
           ELSE 0 END AS ratio
    FROM public.venta_lineas vl
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(el.cantidad_entregada), 0) AS entregado
      FROM public.entrega_lineas el
      JOIN public.entregas e ON e.id = el.entrega_id
      WHERE e.pedido_id = p_venta_id
        AND e.status::text NOT IN ('cancelado','no_entregado')
        AND el.producto_id = vl.producto_id
    ) ent ON true
    WHERE vl.venta_id = p_venta_id
  ) q;

  IF COALESCE(v_orig_base, 0) <= 0 THEN RETURN 0; END IF;
  RETURN ROUND(COALESCE(p_total, 0) * (v_deliv_base / v_orig_base), 2);
END;
$$;


--
-- Name: fn_validate_cobro_aplicacion_no_excede_saldo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_cobro_aplicacion_no_excede_saldo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric;
  v_aplicado numeric;
  v_folio text;
BEGIN
  SELECT total, folio INTO v_total, v_folio FROM public.ventas WHERE id = NEW.venta_id;
  IF v_total IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_aplicado
  FROM public.cobro_aplicaciones ca
  JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = NEW.venta_id
    AND COALESCE(c.status, 'activo') <> 'cancelado'
    AND (TG_OP = 'INSERT' OR ca.id <> NEW.id);

  IF (v_aplicado + COALESCE(NEW.monto_aplicado, 0)) > v_total + 0.01 THEN
    RAISE EXCEPTION 'El monto aplicado (%) excede el saldo pendiente de la venta % (total: %, ya aplicado: %)',
      NEW.monto_aplicado, COALESCE(v_folio, NEW.venta_id::text), v_total, v_aplicado
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_validate_cobro_no_sobreaplicado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_cobro_no_sobreaplicado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_monto_cobro numeric;
  v_aplicado numeric;
BEGIN
  SELECT monto INTO v_monto_cobro FROM public.cobros WHERE id = NEW.cobro_id;
  IF v_monto_cobro IS NULL THEN RETURN NEW; END IF;

  SELECT COALESCE(SUM(monto_aplicado),0) INTO v_aplicado
  FROM public.cobro_aplicaciones
  WHERE cobro_id = NEW.cobro_id
    AND (TG_OP = 'INSERT' OR id <> NEW.id);

  IF (v_aplicado + COALESCE(NEW.monto_aplicado,0)) > v_monto_cobro + 0.01 THEN
    RAISE EXCEPTION 'El monto aplicado (% + %) excede el monto del cobro (%)',
      v_aplicado, NEW.monto_aplicado, v_monto_cobro
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ventas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ventas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    empresa_id uuid NOT NULL,
    folio text,
    tipo public.tipo_venta DEFAULT 'pedido'::public.tipo_venta NOT NULL,
    status public.status_venta DEFAULT 'borrador'::public.status_venta NOT NULL,
    cliente_id uuid NOT NULL,
    vendedor_id uuid,
    condicion_pago public.condicion_pago DEFAULT 'contado'::public.condicion_pago NOT NULL,
    tarifa_id uuid,
    almacen_id uuid,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    fecha_entrega date,
    entrega_inmediata boolean DEFAULT false,
    notas text,
    subtotal numeric DEFAULT 0,
    descuento_total numeric DEFAULT 0,
    iva_total numeric DEFAULT 0,
    ieps_total numeric DEFAULT 0,
    total numeric DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    saldo_pendiente numeric DEFAULT 0,
    pedido_origen_id uuid,
    requiere_factura boolean DEFAULT false,
    descuento_extra numeric DEFAULT 0 NOT NULL,
    descuento_extra_tipo text DEFAULT 'porcentaje'::text NOT NULL,
    es_saldo_inicial boolean DEFAULT false NOT NULL,
    concepto text,
    fecha_vencimiento date,
    descuento_extra_motivo text,
    origen text,
    turno_id uuid,
    comision_volumen_pago_id uuid,
    politica_cobro text,
    cerrado_at timestamp with time zone,
    cerrado_por uuid,
    total_efectivo numeric,
    cerrado_snapshot jsonb,
    updated_at timestamp with time zone DEFAULT now(),
    creado_por uuid,
    CONSTRAINT ventas_politica_cobro_chk CHECK (((politica_cobro IS NULL) OR (politica_cobro = ANY (ARRAY['pedido'::text, 'entregado'::text]))))
);
