--
-- Name: fn_venta_cobrable(public.ventas); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_venta_cobrable(v_venta public.ventas) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  p_venta_id     uuid := v_venta.id;
  v_cobrable     numeric;
  v_orig_base    numeric;
  v_deliv_base   numeric;
  v_es_entregado boolean;
BEGIN
  IF v_venta.cerrado_at IS NOT NULL THEN
    v_cobrable := COALESCE(v_venta.total_efectivo, 0);
  ELSE
    v_es_entregado :=
          v_venta.tipo::text = 'pedido'
      AND v_venta.politica_cobro IS NOT DISTINCT FROM 'entregado'
      -- Un pedido de CONTADO adeuda el total: no se reduce por lo entregado.
      AND COALESCE(v_venta.condicion_pago::text, '') <> 'contado'
      AND COALESCE(v_venta.es_saldo_inicial, false) = false
      AND NOT EXISTS (
        SELECT 1 FROM public.venta_lineas
        WHERE venta_id = p_venta_id
          AND (COALESCE(facturado, false) = true OR factura_cfdi_id IS NOT NULL)
      );

    IF v_es_entregado THEN
      SELECT COALESCE(SUM(base), 0), COALESCE(SUM(base * ratio), 0)
        INTO v_orig_base, v_deliv_base
      FROM (
        SELECT
          (COALESCE(vl.subtotal,0) + COALESCE(vl.iva_monto,0) + COALESCE(vl.ieps_monto,0)) AS base,
          CASE WHEN vl.cantidad > 0
               THEN LEAST(COALESCE(ent.entregado, 0), vl.cantidad) / vl.cantidad
               ELSE 0 END AS ratio
        FROM public.venta_lineas vl
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(el.cantidad_entregada), 0) AS entregado
          FROM public.entrega_lineas el
          JOIN public.entregas e ON e.id = el.entrega_id
          WHERE e.pedido_id = p_venta_id
            AND e.status::text NOT IN ('cancelado','no_entregado')
            AND el.producto_id = vl.producto_id
        ) ent ON true
        WHERE vl.venta_id = p_venta_id
      ) q;

      IF COALESCE(v_orig_base, 0) > 0 THEN
        v_cobrable := ROUND(COALESCE(v_venta.total, 0) * (v_deliv_base / v_orig_base), 2);
      ELSE
        v_cobrable := 0;
      END IF;
    ELSE
      v_cobrable := COALESCE(v_venta.total, 0);
    END IF;
  END IF;

  RETURN v_cobrable;
END;
$$;


--
-- Name: fn_venta_lineas_resumen(uuid, uuid, public.status_venta[], public.tipo_venta[], public.condicion_pago[], uuid[], uuid[], date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_venta_lineas_resumen(p_empresa_id uuid, p_vendedor_scope uuid DEFAULT NULL::uuid, p_statuses public.status_venta[] DEFAULT NULL::public.status_venta[], p_tipos public.tipo_venta[] DEFAULT NULL::public.tipo_venta[], p_condiciones public.condicion_pago[] DEFAULT NULL::public.condicion_pago[], p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_cliente_ids uuid[] DEFAULT NULL::uuid[], p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_promocion text DEFAULT NULL::text, p_search text DEFAULT NULL::text) RETURNS TABLE(lineas_count bigint, cantidad numeric, total numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_service_role boolean := COALESCE(auth.role(), '') = 'service_role';
  v_database_admin boolean := session_user IN ('postgres', 'supabase_admin');
  v_search text := NULLIF(lower(btrim(p_search)), '');
BEGIN
  IF p_empresa_id IS NULL THEN
    RAISE EXCEPTION 'La empresa es obligatoria' USING ERRCODE = '22023';
  END IF;

  IF NOT v_service_role AND NOT v_database_admin AND v_uid IS NULL THEN
    RAISE EXCEPTION 'Sesión no autenticada' USING ERRCODE = '42501';
  END IF;

  IF NOT v_service_role AND NOT v_database_admin
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(v_uid) THEN
    RAISE EXCEPTION 'No tienes acceso a esta empresa' USING ERRCODE = '42501';
  END IF;

  IF p_promocion IS NOT NULL AND p_promocion NOT IN ('si', 'no') THEN
    RAISE EXCEPTION 'Filtro de promoción inválido' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH filtered_sales AS MATERIALIZED (
    SELECT v.id
    FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND (p_vendedor_scope IS NULL OR v.vendedor_id = p_vendedor_scope)
      AND (p_statuses IS NULL OR v.status = ANY(p_statuses))
      AND (p_tipos IS NULL OR v.tipo = ANY(p_tipos))
      AND (p_condiciones IS NULL OR v.condicion_pago = ANY(p_condiciones))
      AND (p_vendedor_ids IS NULL OR v.vendedor_id = ANY(p_vendedor_ids))
      AND (p_cliente_ids IS NULL OR v.cliente_id = ANY(p_cliente_ids))
      AND (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
      AND (
        p_promocion IS NULL
        OR (
          p_promocion = 'si'
          AND (
            EXISTS (SELECT 1 FROM public.promocion_aplicada pa WHERE pa.venta_id = v.id)
            OR EXISTS (
              SELECT 1 FROM public.venta_lineas vlp
              WHERE vlp.venta_id = v.id
                AND vlp.precio_unitario = 0
                AND vlp.cantidad > 0
            )
          )
        )
        OR (
          p_promocion = 'no'
          AND NOT EXISTS (SELECT 1 FROM public.promocion_aplicada pa WHERE pa.venta_id = v.id)
          AND NOT EXISTS (
            SELECT 1 FROM public.venta_lineas vlp
            WHERE vlp.venta_id = v.id
              AND vlp.precio_unitario = 0
              AND vlp.cantidad > 0
          )
        )
      )
  )
  SELECT
    count(*)::bigint AS lineas_count,
    COALESCE(sum(COALESCE(vl.cantidad, 0)), 0)::numeric AS cantidad,
    COALESCE(sum(COALESCE(vl.total, 0)), 0)::numeric AS total
  FROM public.venta_lineas vl
  JOIN filtered_sales fs ON fs.id = vl.venta_id
  WHERE v_search IS NULL
     OR EXISTS (
       SELECT 1 FROM public.productos p
       WHERE p.id = vl.producto_id
         AND (
           strpos(lower(COALESCE(p.nombre, '')), v_search) > 0
           OR strpos(lower(COALESCE(p.codigo, '')), v_search) > 0
         )
     )
     OR EXISTS (
       SELECT 1 FROM public.ventas vs
       WHERE vs.id = vl.venta_id
         AND strpos(lower(COALESCE(vs.folio, '')), v_search) > 0
     );
END;
$$;


--
-- Name: FUNCTION fn_venta_lineas_resumen(p_empresa_id uuid, p_vendedor_scope uuid, p_statuses public.status_venta[], p_tipos public.tipo_venta[], p_condiciones public.condicion_pago[], p_vendedor_ids uuid[], p_cliente_ids uuid[], p_fecha_desde date, p_fecha_hasta date, p_promocion text, p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_venta_lineas_resumen(p_empresa_id uuid, p_vendedor_scope uuid, p_statuses public.status_venta[], p_tipos public.tipo_venta[], p_condiciones public.condicion_pago[], p_vendedor_ids uuid[], p_cliente_ids uuid[], p_fecha_desde date, p_fecha_hasta date, p_promocion text, p_search text) IS 'Totales de la vista Productos vendidos sin descargar todos los renglones.';


--
-- Name: fn_ventas_resumen(uuid, uuid, public.status_venta[], public.tipo_venta[], public.condicion_pago[], uuid[], uuid[], date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_ventas_resumen(p_empresa_id uuid, p_vendedor_scope uuid DEFAULT NULL::uuid, p_statuses public.status_venta[] DEFAULT NULL::public.status_venta[], p_tipos public.tipo_venta[] DEFAULT NULL::public.tipo_venta[], p_condiciones public.condicion_pago[] DEFAULT NULL::public.condicion_pago[], p_vendedor_ids uuid[] DEFAULT NULL::uuid[], p_cliente_ids uuid[] DEFAULT NULL::uuid[], p_fecha_desde date DEFAULT NULL::date, p_fecha_hasta date DEFAULT NULL::date, p_promocion text DEFAULT NULL::text, p_search text DEFAULT NULL::text) RETURNS TABLE(ventas_count bigint, subtotal_sin_impuestos numeric, descuento numeric, impuestos numeric, total_efectivo numeric, pagado numeric, saldo numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_service_role boolean := COALESCE(auth.role(), '') = 'service_role';
  v_database_admin boolean := session_user IN ('postgres', 'supabase_admin');
  v_search text := NULLIF(lower(btrim(p_search)), '');
BEGIN
  IF p_empresa_id IS NULL THEN
    RAISE EXCEPTION 'La empresa es obligatoria' USING ERRCODE = '22023';
  END IF;

  IF NOT v_service_role AND NOT v_database_admin AND v_uid IS NULL THEN
    RAISE EXCEPTION 'Sesión no autenticada' USING ERRCODE = '42501';
  END IF;

  -- Una sola comprobación de tenant. La función no confía solamente en el
  -- empresa_id recibido y nunca devuelve información de otra empresa.
  IF NOT v_service_role AND NOT v_database_admin
     AND p_empresa_id IS DISTINCT FROM public.get_my_empresa_id()
     AND NOT public.is_super_admin(v_uid) THEN
    RAISE EXCEPTION 'No tienes acceso a esta empresa' USING ERRCODE = '42501';
  END IF;

  IF p_promocion IS NOT NULL AND p_promocion NOT IN ('si', 'no') THEN
    RAISE EXCEPTION 'Filtro de promoción inválido' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH filtered AS MATERIALIZED (
    SELECT
      v.id,
      v.total,
      v.iva_total,
      v.ieps_total,
      v.descuento_total,
      v.status,
      v.total_efectivo,
      v.cerrado_at,
      v.cerrado_snapshot
    FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id
      AND v.es_saldo_inicial = false
      AND (p_vendedor_scope IS NULL OR v.vendedor_id = p_vendedor_scope)
      AND (p_statuses IS NULL OR v.status = ANY(p_statuses))
      AND (p_tipos IS NULL OR v.tipo = ANY(p_tipos))
      AND (p_condiciones IS NULL OR v.condicion_pago = ANY(p_condiciones))
      AND (p_vendedor_ids IS NULL OR v.vendedor_id = ANY(p_vendedor_ids))
      AND (p_cliente_ids IS NULL OR v.cliente_id = ANY(p_cliente_ids))
      AND (p_fecha_desde IS NULL OR v.fecha >= p_fecha_desde)
      AND (p_fecha_hasta IS NULL OR v.fecha <= p_fecha_hasta)
      AND (
        v_search IS NULL
        OR strpos(lower(COALESCE(v.folio, '')), v_search) > 0
        OR EXISTS (
          SELECT 1 FROM public.clientes c
          WHERE c.id = v.cliente_id
            AND strpos(lower(COALESCE(c.nombre, '')), v_search) > 0
        )
        OR EXISTS (
          SELECT 1 FROM public.profiles pr
          WHERE pr.id = v.vendedor_id
            AND strpos(lower(COALESCE(pr.nombre, '')), v_search) > 0
        )
        OR EXISTS (
          SELECT 1 FROM public.almacenes a
          WHERE a.id = v.almacen_id
            AND strpos(lower(COALESCE(a.nombre, '')), v_search) > 0
        )
      )
      AND (
        p_promocion IS NULL
        OR (
          p_promocion = 'si'
          AND (
            EXISTS (SELECT 1 FROM public.promocion_aplicada pa WHERE pa.venta_id = v.id)
            OR EXISTS (
              SELECT 1 FROM public.venta_lineas vlp
              WHERE vlp.venta_id = v.id
                AND vlp.precio_unitario = 0
                AND vlp.cantidad > 0
            )
          )
        )
        OR (
          p_promocion = 'no'
          AND NOT EXISTS (SELECT 1 FROM public.promocion_aplicada pa WHERE pa.venta_id = v.id)
          AND NOT EXISTS (
            SELECT 1 FROM public.venta_lineas vlp
            WHERE vlp.venta_id = v.id
              AND vlp.precio_unitario = 0
              AND vlp.cantidad > 0
          )
        )
      )
  ),
  line_discounts AS (
    SELECT
      vl.venta_id,
      round(sum(
        CASE
          WHEN COALESCE(vl.subtotal, 0) * (COALESCE(vl.descuento_pct, 0) / 100) < 0.005
               AND COALESCE(vl.total, 0) < 0.005
               AND CASE
                     WHEN COALESCE(vl.subtotal, 0) > 0.005 THEN COALESCE(vl.subtotal, 0)
                     ELSE COALESCE(vl.precio_unitario, 0) * COALESCE(vl.cantidad, 0)
                   END > 0.005
            THEN CASE
                   WHEN COALESCE(vl.subtotal, 0) > 0.005 THEN COALESCE(vl.subtotal, 0)
                   ELSE COALESCE(vl.precio_unitario, 0) * COALESCE(vl.cantidad, 0)
                 END
          ELSE COALESCE(vl.subtotal, 0) * (COALESCE(vl.descuento_pct, 0) / 100)
        END
      ), 2) AS descuento_lineas
    FROM public.venta_lineas vl
    JOIN filtered f ON f.id = vl.venta_id
    GROUP BY vl.venta_id
  ),
  promo_discounts AS (
    SELECT pa.venta_id, sum(COALESCE(pa.descuento_aplicado, 0)) AS descuento_promos
    FROM public.promocion_aplicada pa
    JOIN filtered f ON f.id = pa.venta_id
    GROUP BY pa.venta_id
  ),
  active_payments AS (
    SELECT ca.venta_id, sum(COALESCE(ca.monto_aplicado, 0)) AS cobrado
    FROM public.cobro_aplicaciones ca
    JOIN public.cobros c ON c.id = ca.cobro_id AND c.status = 'activo'
    JOIN filtered f ON f.id = ca.venta_id
    GROUP BY ca.venta_id
  ),
  calculated AS (
    SELECT
      f.id,
      f.status,
      COALESCE(f.iva_total, 0) + COALESCE(f.ieps_total, 0) AS impuestos_venta,
      greatest(
        COALESCE(ld.descuento_lineas, 0),
        COALESCE(pd.descuento_promos, 0),
        COALESCE(f.descuento_total, 0)
      ) AS descuento_venta,
      greatest(
        0::numeric,
        COALESCE(f.total, 0) - COALESCE(f.iva_total, 0) - COALESCE(f.ieps_total, 0)
      ) AS gravable,
      CASE
        WHEN f.cerrado_at IS NOT NULL THEN COALESCE(
          f.total_efectivo,
          NULLIF(f.cerrado_snapshot ->> 'total_efectivo', '')::numeric,
          f.total,
          0
        )
        ELSE COALESCE(f.total, 0)
      END AS total_real,
      COALESCE(ap.cobrado, 0) AS cobrado
    FROM filtered f
    LEFT JOIN line_discounts ld ON ld.venta_id = f.id
    LEFT JOIN promo_discounts pd ON pd.venta_id = f.id
    LEFT JOIN active_payments ap ON ap.venta_id = f.id
  ),
  with_balance AS (
    SELECT
      c.*,
      CASE
        WHEN c.status = 'cancelado' THEN 0::numeric
        ELSE greatest(0::numeric, c.total_real - c.cobrado)
      END AS saldo_real
    FROM calculated c
  )
  SELECT
    count(*)::bigint AS ventas_count,
    COALESCE(sum(wb.gravable + wb.descuento_venta), 0)::numeric AS subtotal_sin_impuestos,
    COALESCE(sum(wb.descuento_venta), 0)::numeric AS descuento,
    COALESCE(sum(wb.impuestos_venta), 0)::numeric AS impuestos,
    COALESCE(sum(wb.total_real), 0)::numeric AS total_efectivo,
    COALESCE(sum(greatest(0::numeric, wb.total_real - wb.saldo_real)), 0)::numeric AS pagado,
    COALESCE(sum(wb.saldo_real), 0)::numeric AS saldo
  FROM with_balance wb;
END;
$$;


--
-- Name: FUNCTION fn_ventas_resumen(p_empresa_id uuid, p_vendedor_scope uuid, p_statuses public.status_venta[], p_tipos public.tipo_venta[], p_condiciones public.condicion_pago[], p_vendedor_ids uuid[], p_cliente_ids uuid[], p_fecha_desde date, p_fecha_hasta date, p_promocion text, p_search text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_ventas_resumen(p_empresa_id uuid, p_vendedor_scope uuid, p_statuses public.status_venta[], p_tipos public.tipo_venta[], p_condiciones public.condicion_pago[], p_vendedor_ids uuid[], p_cliente_ids uuid[], p_fecha_desde date, p_fecha_hasta date, p_promocion text, p_search text) IS 'Resumen de Ventas de solo lectura; reemplaza la descarga completa usada por el listado.';


--
-- Name: folio_lpad(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.folio_lpad(p_texto text, p_largo integer, p_relleno text DEFAULT ' '::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN length(p_texto) >= p_largo THEN p_texto ELSE lpad(p_texto, p_largo, p_relleno) END
$$;


--
-- Name: folio_num(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.folio_num(n bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN length(n::text) >= 4 THEN n::text ELSE lpad(n::text, 4, '0') END
$$;


--
-- Name: folio_orden(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.folio_orden(p_folio text) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT NULLIF(substring(p_folio FROM '([0-9]+)$'), '')::bigint
$_$;


--
-- Name: generar_bonos_partner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_bonos_partner(_partner_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_nivel record;
  v_insertados integer := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.partners
    WHERE id = _partner_id
      AND estado = 'activo'
  ) THEN
    RETURN 0;
  END IF;

  SELECT *
  INTO v_nivel
  FROM public.get_partner_nivel(_partner_id)
  LIMIT 1;

  IF v_nivel.nivel_id IS NULL THEN
    RETURN 0;
  END IF;

  INSERT INTO public.partner_comisiones (
    partner_id,
    empresa_id,
    factura_id,
    periodo,
    monto_factura,
    partner_pct,
    cupon_pct,
    monto_comision,
    status,
    notas,
    tipo,
    nivel_id,
    empresas_activas_snapshot,
    regla_version
  )
  SELECT
    _partner_id,
    NULL,
    NULL,
    to_char(CURRENT_DATE, 'YYYY-MM'),
    0,
    n.comision_pct,
    0,
    n.bono_mxn,
    'pendiente',
    'Bono único por alcanzar el nivel ' || n.nombre,
    'bono_nivel',
    n.id,
    v_nivel.empresas_actuales,
    'partner-v2-2026-09-07'
  FROM public.partner_niveles n
  WHERE n.orden <= v_nivel.orden
    AND COALESCE(n.bono_mxn, 0) > 0
  ON CONFLICT (partner_id, nivel_id)
    WHERE tipo = 'bono_nivel'
    DO NOTHING;

  GET DIAGNOSTICS v_insertados = ROW_COUNT;

  RETURN v_insertados;
END;
$$;


--
-- Name: generar_comision_partner_factura(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_comision_partner_factura() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_atrib record;
  v_partner record;
  v_cupon_pct numeric := 0;
  v_nivel record;
  v_partner_pct numeric;
  v_pct_neto numeric;
  v_comision numeric;
  v_periodo text;
BEGIN
  IF NEW.estado <> 'pagada' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.estado = 'pagada' THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_atrib
  FROM public.partner_atribuciones
  WHERE empresa_id = NEW.empresa_id;

  IF v_atrib IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_partner
  FROM public.partners
  WHERE id = v_atrib.partner_id;

  IF v_partner IS NULL OR v_partner.estado <> 'activo' THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO v_nivel
  FROM public.get_partner_nivel(v_partner.id)
  LIMIT 1;

  v_partner_pct := COALESCE(
    v_nivel.comision_pct,
    v_partner.comision_pct,
    10
  );

  IF v_atrib.cupon_id IS NOT NULL THEN
    SELECT COALESCE(descuento_pct, 0)
    INTO v_cupon_pct
    FROM public.cupones
    WHERE id = v_atrib.cupon_id;
  END IF;

  v_cupon_pct := LEAST(
    COALESCE(v_cupon_pct, 0),
    v_partner_pct
  );

  v_pct_neto := v_partner_pct - v_cupon_pct;

  v_comision := ROUND(
    COALESCE(NEW.total, 0) * v_pct_neto / 100,
    2
  );

  v_periodo := to_char(
    COALESCE(NEW.periodo_inicio, CURRENT_DATE),
    'YYYY-MM'
  );

  INSERT INTO public.partner_comisiones (
    partner_id,
    empresa_id,
    factura_id,
    periodo,
    monto_factura,
    partner_pct,
    cupon_pct,
    monto_comision,
    status,
    tipo,
    nivel_id,
    empresas_activas_snapshot,
    regla_version
  )
  VALUES (
    v_partner.id,
    NEW.empresa_id,
    NEW.id,
    v_periodo,
    COALESCE(NEW.total, 0),
    v_partner_pct,
    v_cupon_pct,
    v_comision,
    'pendiente',
    'recurrente',
    v_nivel.nivel_id,
    v_nivel.empresas_actuales,
    'partner-v2-2026-09-07'
  )
  ON CONFLICT (factura_id) DO NOTHING;

  PERFORM public.generar_bonos_partner(v_partner.id);

  RETURN NEW;
END;
$$;


--
-- Name: generar_recibo_volumen(uuid, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_recibo_volumen(p_vendedor_id uuid, p_desde date, p_hasta date, p_fecha_corte date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_calc jsonb;
  v_empresa uuid;
  v_pago_id uuid;
  v_ids uuid[];
  v_caller uuid;
BEGIN
  SELECT empresa_id INTO v_caller FROM public.profiles WHERE user_id = auth.uid();
  SELECT empresa_id INTO v_empresa FROM public.profiles WHERE id = p_vendedor_id;
  IF v_caller IS NULL OR v_empresa IS NULL OR v_caller <> v_empresa THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  v_calc := public.calcular_comision_volumen(p_vendedor_id, p_desde, p_hasta);
  IF v_calc ? 'error' THEN
    RAISE EXCEPTION 'No se pudo calcular: %', v_calc->>'error';
  END IF;
  IF COALESCE((v_calc->>'comision')::numeric,0) <= 0 THEN
    RAISE EXCEPTION 'La comisión calculada es 0';
  END IF;

  INSERT INTO public.pago_comisiones (
    empresa_id, vendedor_id, fecha_corte, total_comisiones, user_id, estado,
    tipo_calculo, periodo_desde, periodo_hasta, detalle_calculo
  ) VALUES (
    v_empresa, p_vendedor_id, p_fecha_corte, (v_calc->>'comision')::numeric, auth.uid(), 'pendiente',
    'volumen', p_desde, p_hasta, v_calc
  ) RETURNING id INTO v_pago_id;

  -- Marcar ventas como ya contadas
  SELECT array_agg((value)::uuid) INTO v_ids
  FROM jsonb_array_elements_text(v_calc->'ventas_ids');
  IF v_ids IS NOT NULL AND array_length(v_ids,1) > 0 THEN
    UPDATE public.ventas SET comision_volumen_pago_id = v_pago_id WHERE id = ANY(v_ids);
  END IF;

  RETURN v_pago_id;
END;
$$;


--
-- Name: generate_empresa_licencia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_empresa_licencia() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  candidate TEXT;
  exists_flag BOOLEAN;
BEGIN
  LOOP
    candidate := lpad((floor(random() * 90000000) + 10000000)::bigint::text, 8, '0');
    SELECT EXISTS(SELECT 1 FROM public.empresas WHERE licencia = candidate) INTO exists_flag;
    IF NOT exists_flag THEN
      RETURN candidate;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: generate_folio(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_folio(p_empresa_id uuid, p_tipo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_max int;
  v_folio text;
BEGIN
  SELECT COALESCE(MAX(
    CAST(SUBSTRING(folio FROM LENGTH(p_tipo) + 2) AS integer)
  ), 0)
  INTO v_max
  FROM ventas
  WHERE empresa_id = p_empresa_id
    AND folio ~ ('^' || p_tipo || '-\d+$');

  v_folio := p_tipo || '-' || public.folio_lpad((v_max + 1)::text, 4, '0');
  RETURN v_folio;
END;
$_$;


--
-- Name: generate_internal_commission_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_internal_commission_from_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_assignment record;
  v_member record;
  v_payment_number integer;
  v_amount numeric(12,2);
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.estado = 'pagada'
       AND NEW.estado <> 'pagada' THEN
      UPDATE public.internal_commission_entries ice
      SET
        status = 'reversed',
        reversed_at = now(),
        reversal_reason = 'La factura dejó de estar pagada'
      WHERE ice.factura_id = NEW.id
        AND ice.status <> 'void';

      RETURN NEW;
    END IF;
  END IF;

  IF NEW.estado <> 'pagada'
     OR COALESCE(
       NEW.tipo,
       'subscription_renewal'
     ) <> 'subscription_renewal' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.partner_atribuciones pa
    WHERE pa.empresa_id = NEW.empresa_id
  ) THEN
    RETURN NEW;
  END IF;

  SELECT
    cca.commissioned_by_id,
    cca.commission_starts_at,
    captured.person_type AS captured_type
  INTO v_assignment
  FROM public.commission_client_attributions cca
  LEFT JOIN public.commission_people captured
    ON captured.id = cca.captured_by_id
  WHERE cca.empresa_id = NEW.empresa_id;

  IF v_assignment.commissioned_by_id IS NULL
     OR v_assignment.captured_type = 'partner'
     OR COALESCE(NEW.fecha_pago, now())
        < COALESCE(
          v_assignment.commission_starts_at,
          '-infinity'::timestamptz
        ) THEN
    RETURN NEW;
  END IF;

  SELECT
    tm.*,
    cp.is_active,
    cp.person_type
  INTO v_member
  FROM public.platform_team_members tm
  JOIN public.commission_people cp
    ON cp.id = tm.person_id
  WHERE tm.person_id = v_assignment.commissioned_by_id;

  IF NOT FOUND
     OR v_member.status NOT IN ('invited', 'active')
     OR NOT v_member.is_active
     OR v_member.person_type <> 'internal'
     OR v_member.commission_mode = 'none' THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_payment_number
  FROM public.facturas f
  WHERE f.empresa_id = NEW.empresa_id
    AND f.estado = 'pagada'
    AND COALESCE(
      f.tipo,
      'subscription_renewal'
    ) = 'subscription_renewal'
    AND (
      f.periodo_inicio < NEW.periodo_inicio
      OR (
        f.periodo_inicio = NEW.periodo_inicio
        AND f.id::text <= NEW.id::text
      )
    );

  v_payment_number := GREATEST(
    1,
    v_payment_number
  );

  v_amount := CASE v_member.commission_mode
    WHEN 'first_payment' THEN
      CASE
        WHEN v_payment_number = 1
        THEN round(
          COALESCE(NEW.total, 0)
          * v_member.commission_pct / 100,
          2
        )
        ELSE 0
      END

    WHEN 'first_n_payments' THEN
      CASE
        WHEN v_payment_number <= v_member.commission_payment_limit
        THEN round(
          COALESCE(NEW.total, 0)
          * v_member.commission_pct / 100,
          2
        )
        ELSE 0
      END

    WHEN 'recurring' THEN
      round(
        COALESCE(NEW.total, 0)
        * v_member.commission_pct / 100,
        2
      )

    WHEN 'fixed_activation' THEN
      CASE
        WHEN v_payment_number = 1
        THEN v_member.commission_fixed_amount
        ELSE 0
      END

    ELSE 0
  END;

  IF v_amount <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.internal_commission_entries(
    person_id,
    empresa_id,
    factura_id,
    invoice_number,
    payment_number,
    period,
    base_amount,
    commission_mode,
    commission_pct,
    commission_fixed_amount,
    commission_amount,
    rule_snapshot
  )
  VALUES (
    v_assignment.commissioned_by_id,
    NEW.empresa_id,
    NEW.id,
    NEW.numero_factura,
    v_payment_number,
    to_char(NEW.periodo_inicio, 'YYYY-MM'),
    COALESCE(NEW.total, 0),
    v_member.commission_mode,
    v_member.commission_pct,
    v_member.commission_fixed_amount,
    v_amount,
    jsonb_build_object(
      'version', 'internal-v1-2026-09-09',
      'mode', v_member.commission_mode,
      'percent', v_member.commission_pct,
      'payment_limit', v_member.commission_payment_limit,
      'fixed_amount', v_member.commission_fixed_amount,
      'payment_number', v_payment_number,
      'commission_starts_at', v_assignment.commission_starts_at
    )
  )
  ON CONFLICT (factura_id)
  DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: get_audit_users(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_audit_users(p_auditoria_id uuid) RETURNS TABLE(user_id uuid, nombre text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.user_id, p.nombre
  FROM profiles p
  WHERE p.empresa_id = (
    SELECT a.empresa_id FROM auditorias a WHERE a.id = p_auditoria_id LIMIT 1
  )
  AND p.estado = 'activo'
  ORDER BY p.nombre;
$$;


--
-- Name: get_database_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_database_health() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_result jsonb;
  v_db_size text;
  v_db_size_bytes bigint;
  v_top_tables jsonb;
  v_bloat_tables jsonb;
  v_storage_buckets jsonb;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de super administrador';
  END IF;

  SELECT pg_size_pretty(pg_database_size(current_database())),
         pg_database_size(current_database())
  INTO v_db_size, v_db_size_bytes;

  SELECT jsonb_agg(t) INTO v_top_tables
  FROM (
    SELECT
      schemaname || '.' || relname AS tabla,
      pg_size_pretty(pg_total_relation_size(schemaname || '.' || relname)) AS tamano,
      pg_total_relation_size(schemaname || '.' || relname) AS bytes,
      n_live_tup AS filas_vivas,
      n_dead_tup AS dead_tuples,
      CASE WHEN n_live_tup > 0
        THEN ROUND((n_dead_tup::numeric / n_live_tup::numeric) * 100, 2)
        ELSE 0 END AS bloat_pct,
      last_vacuum,
      last_autovacuum,
      last_analyze
    FROM pg_stat_user_tables
    WHERE schemaname = 'public'
    ORDER BY pg_total_relation_size(schemaname || '.' || relname) DESC
    LIMIT 10
  ) t;

  SELECT jsonb_agg(t) INTO v_bloat_tables
  FROM (
    SELECT
      schemaname || '.' || relname AS tabla,
      n_live_tup AS filas_vivas,
      n_dead_tup AS dead_tuples,
      CASE WHEN n_live_tup > 0
        THEN ROUND((n_dead_tup::numeric / n_live_tup::numeric) * 100, 2)
        ELSE 0 END AS bloat_pct,
      last_vacuum,
      last_autovacuum
    FROM pg_stat_user_tables
    WHERE schemaname = 'public' AND n_dead_tup > 100
    ORDER BY n_dead_tup DESC
    LIMIT 10
  ) t;

  BEGIN
    SELECT jsonb_agg(b) INTO v_storage_buckets
    FROM (
      SELECT
        bucket_id AS bucket,
        COUNT(*) AS num_archivos,
        pg_size_pretty(COALESCE(SUM((metadata->>'size')::bigint), 0)) AS tamano,
        COALESCE(SUM((metadata->>'size')::bigint), 0) AS bytes
      FROM storage.objects
      GROUP BY bucket_id
      ORDER BY COALESCE(SUM((metadata->>'size')::bigint), 0) DESC
    ) b;
  EXCEPTION WHEN OTHERS THEN
    v_storage_buckets := '[]'::jsonb;
  END;

  v_result := jsonb_build_object(
    'db_total_size', v_db_size,
    'db_total_bytes', v_db_size_bytes,
    'top_tables', COALESCE(v_top_tables, '[]'::jsonb),
    'bloat_tables', COALESCE(v_bloat_tables, '[]'::jsonb),
    'storage_buckets', COALESCE(v_storage_buckets, '[]'::jsonb),
    'generated_at', now()
  );

  RETURN v_result;
END;
$$;


--
-- Name: get_empresa_user_emails(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_empresa_user_emails(p_empresa_id uuid) RETURNS TABLE(user_id uuid, email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT u.id::uuid AS user_id, u.email::text
  FROM auth.users u
  JOIN public.profiles p ON p.user_id = u.id
  WHERE p.empresa_id = p_empresa_id
    AND (
      EXISTS (
        SELECT 1 FROM public.profiles me
        WHERE me.user_id = auth.uid() AND me.empresa_id = p_empresa_id
      )
      -- Super admin siempre puede ver los correos, incluso cuando está
      -- impersonando otra empresa (is_super_admin devuelve false en ese caso).
      OR EXISTS (
        SELECT 1 FROM public.super_admins sa WHERE sa.user_id = auth.uid()
      )
    );
$$;


--
-- Name: get_entregas_bulk_preview(uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_entregas_bulk_preview(p_entrega_ids uuid[], p_target_vendedor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_almacen uuid;
  v_target_nombre text;
  v_resultado jsonb;
BEGIN
  IF p_target_vendedor_id IS NOT NULL THEN
    SELECT almacen_id, nombre INTO v_target_almacen, v_target_nombre
    FROM profiles WHERE id = p_target_vendedor_id;
  END IF;

  SELECT jsonb_build_object(
    'target_vendedor_id', p_target_vendedor_id,
    'target_vendedor_nombre', v_target_nombre,
    'target_almacen_id', v_target_almacen,
    'entregas', COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb),
    'totales', jsonb_build_object(
      'total', COUNT(*),
      'con_movimiento', COUNT(*) FILTER (WHERE (t.status IN ('cargado','en_ruta'))),
      'sin_movimiento', COUNT(*) FILTER (WHERE (t.status NOT IN ('cargado','en_ruta','hecho','cancelado'))),
      'bloqueadas', COUNT(*) FILTER (WHERE (t.status IN ('hecho','cancelado'))),
      'unidades_a_mover', COALESCE(SUM(t.unidades_total) FILTER (WHERE t.status IN ('cargado','en_ruta')), 0)
    )
  )
  INTO v_resultado
  FROM (
    SELECT
      e.id,
      e.folio,
      e.status::text AS status,
      e.fecha,
      c.nombre AS cliente_nombre,
      vp.nombre AS vendedor_actual_nombre,
      vp.almacen_id AS vendedor_actual_almacen_id,
      al.nombre AS vendedor_actual_almacen_nombre,
      COALESCE((
        SELECT SUM(el.cantidad_entregada)
        FROM entrega_lineas el
        WHERE el.entrega_id = e.id AND el.hecho = true
      ), 0) AS unidades_total,
      (e.status IN ('cargado','en_ruta')) AS requiere_movimiento,
      (e.status IN ('hecho','cancelado')) AS bloqueada
    FROM entregas e
    LEFT JOIN clientes c ON c.id = e.cliente_id
    LEFT JOIN profiles vp ON vp.id = COALESCE(e.vendedor_ruta_id, e.vendedor_id)
    LEFT JOIN almacenes al ON al.id = vp.almacen_id
    WHERE e.id = ANY(p_entrega_ids)
      AND e.empresa_id = get_my_empresa_id()
  ) t;

  RETURN v_resultado;
END;
$$;


--
-- Name: get_inactive_empresas(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inactive_empresas(p_dias_inactivo integer DEFAULT 30, p_dias_vencido integer DEFAULT 30) RETURNS TABLE(empresa_id uuid, nombre text, email text, telefono text, owner_email text, empresa_created_at timestamp with time zone, status text, trial_ends_at timestamp with time zone, fecha_vencimiento date, current_period_end timestamp with time zone, last_sign_in_at timestamp with time zone, last_venta_at timestamp with time zone, dias_sin_actividad integer, dias_vencido integer, motivo text, total_ventas bigint, total_clientes bigint, total_usuarios bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de super administrador';
  END IF;

  RETURN QUERY
  WITH last_act AS (
    SELECT p.empresa_id AS emp_id, MAX(u.last_sign_in_at) AS last_sign_in_at
    FROM profiles p JOIN auth.users u ON u.id = p.user_id
    GROUP BY p.empresa_id
  ),
  ventas_act AS (
    SELECT v.empresa_id AS emp_id, MAX(v.created_at) AS last_venta_at, COUNT(*)::bigint AS total_ventas
    FROM ventas v GROUP BY v.empresa_id
  ),
  clientes_count AS (
    SELECT c.empresa_id AS emp_id, COUNT(*)::bigint AS total_clientes FROM clientes c GROUP BY c.empresa_id
  ),
  usuarios_count AS (
    SELECT pr.empresa_id AS emp_id, COUNT(*)::bigint AS total_usuarios FROM profiles pr GROUP BY pr.empresa_id
  ),
  base AS (
    SELECT
      e.id AS emp_id, e.nombre, e.email, e.telefono, e.owner_user_id,
      e.created_at AS empresa_created_at,
      s.status, s.trial_ends_at, s.fecha_vencimiento, s.current_period_end,
      COALESCE(s.es_manual, false) AS es_manual,
      la.last_sign_in_at, va.last_venta_at,
      va.total_ventas, cc.total_clientes, uc.total_usuarios,
      GREATEST(la.last_sign_in_at, va.last_venta_at) AS ultima_actividad_real,
      -- VIGENCIA REAL: considera current_period_end primero, luego fecha_vencimiento, luego trial (solo si trial)
      CASE
        WHEN s.status = 'active' AND s.current_period_end IS NOT NULL AND s.current_period_end >= now()
          THEN 0  -- vigente
        WHEN s.status = 'active' AND s.current_period_end IS NOT NULL AND s.current_period_end < now()
          THEN FLOOR(EXTRACT(EPOCH FROM (now() - s.current_period_end)) / 86400)::int
        WHEN s.fecha_vencimiento IS NOT NULL AND s.fecha_vencimiento < CURRENT_DATE
          THEN (CURRENT_DATE - s.fecha_vencimiento)::int
        WHEN s.status = 'trial' AND s.trial_ends_at IS NOT NULL AND s.trial_ends_at < now()
          THEN FLOOR(EXTRACT(EPOCH FROM (now() - s.trial_ends_at)) / 86400)::int
        ELSE 0
      END AS dias_venc_calc,
      -- ¿está vigente?
      (s.status = 'active' AND COALESCE(s.current_period_end >= now(), false))
       OR (s.fecha_vencimiento IS NOT NULL AND s.fecha_vencimiento >= CURRENT_DATE)
       OR (s.status = 'trial' AND COALESCE(s.trial_ends_at >= now(), false))
       AS suscripcion_vigente
    FROM empresas e
    LEFT JOIN subscriptions s ON s.empresa_id = e.id
    LEFT JOIN last_act la ON la.emp_id = e.id
    LEFT JOIN ventas_act va ON va.emp_id = e.id
    LEFT JOIN clientes_count cc ON cc.emp_id = e.id
    LEFT JOIN usuarios_count uc ON uc.emp_id = e.id
  ),
  enriched AS (
    SELECT b.*,
      CASE
        WHEN b.ultima_actividad_real IS NOT NULL
          THEN FLOOR(EXTRACT(EPOCH FROM (now() - b.ultima_actividad_real)) / 86400)::int
        ELSE FLOOR(EXTRACT(EPOCH FROM (now() - b.empresa_created_at)) / 86400)::int
      END AS dias_inact_calc
    FROM base b
  )
  SELECT
    e2.emp_id::uuid, e2.nombre::text, e2.email::text, e2.telefono::text,
    (SELECT u.email::text FROM auth.users u WHERE u.id = e2.owner_user_id) AS owner_email,
    e2.empresa_created_at::timestamptz, e2.status::text,
    e2.trial_ends_at::timestamptz, e2.fecha_vencimiento::date, e2.current_period_end::timestamptz,
    e2.last_sign_in_at::timestamptz, e2.last_venta_at::timestamptz,
    GREATEST(0, e2.dias_inact_calc)::int AS dias_sin_actividad,
    e2.dias_venc_calc::int AS dias_vencido,
    (CASE
      WHEN e2.dias_inact_calc >= p_dias_inactivo AND e2.dias_venc_calc >= p_dias_vencido
        THEN 'Inactiva ' || e2.dias_inact_calc || 'd y vencida ' || e2.dias_venc_calc || 'd'
      WHEN e2.dias_inact_calc >= p_dias_inactivo AND e2.status IS NULL
        THEN 'Inactiva ' || e2.dias_inact_calc || 'd, sin suscripción'
      WHEN e2.dias_inact_calc >= p_dias_inactivo AND e2.status IN ('suspended','cancelada')
        THEN 'Inactiva ' || e2.dias_inact_calc || 'd, suscripción ' || e2.status
      ELSE 'N/A'
    END)::text AS motivo,
    COALESCE(e2.total_ventas, 0)::bigint,
    COALESCE(e2.total_clientes, 0)::bigint,
    COALESCE(e2.total_usuarios, 0)::bigint
  FROM enriched e2
  WHERE
    e2.es_manual = false
    AND COALESCE(e2.suscripcion_vigente, false) = false  -- excluir empresas con suscripción vigente
    AND e2.dias_inact_calc >= p_dias_inactivo
    AND (
      e2.dias_venc_calc >= p_dias_vencido
      OR e2.status IS NULL
      OR e2.status IN ('suspended','cancelada')
    )
  ORDER BY e2.dias_inact_calc DESC;
END;
$$;


--
-- Name: get_my_empresa_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_empresa_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    CASE WHEN EXISTS (SELECT 1 FROM public.super_admins sa WHERE sa.user_id = auth.uid())
      THEN (SELECT super_admin_override_empresa_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)
    END,
    (SELECT empresa_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)
  );
$$;


--
-- Name: get_my_partner_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_partner_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT id FROM public.partners WHERE user_id = auth.uid() LIMIT 1; $$;


--
-- Name: get_optimization_quota(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_optimization_quota(_empresa_id uuid) RETURNS TABLE(usuarios_activos integer, cuota_base integer, recargas_disponibles integer, cuota_total integer, usadas_mes_actual integer, disponibles integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_usuarios INTEGER;
  v_base INTEGER;
  v_recargas INTEGER;
  v_usadas INTEGER;
  v_first_of_month TIMESTAMPTZ;
BEGIN
  v_first_of_month := date_trunc('month', now());

  SELECT COUNT(*)::INTEGER INTO v_usuarios
  FROM public.profiles
  WHERE empresa_id = _empresa_id AND estado = 'activo';

  v_base := COALESCE(v_usuarios, 0) * 30;

  SELECT COALESCE(SUM(cantidad_creditos - creditos_consumidos), 0)::INTEGER INTO v_recargas
  FROM public.optimizacion_recargas
  WHERE empresa_id = _empresa_id
    AND status = 'paid'
    AND cantidad_creditos > creditos_consumidos;

  SELECT COUNT(*)::INTEGER INTO v_usadas
  FROM public.optimizacion_rutas_log
  WHERE empresa_id = _empresa_id
    AND created_at >= v_first_of_month;

  RETURN QUERY SELECT
    v_usuarios,
    v_base,
    v_recargas,
    v_base + v_recargas,
    v_usadas,
    GREATEST(0, (v_base + v_recargas) - v_usadas);
END;
$$;


--
-- Name: get_partner_active_empresas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_partner_active_empresas(_partner_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(DISTINCT pa.empresa_id)::int
  FROM public.partner_atribuciones pa
  WHERE pa.partner_id = _partner_id
    AND EXISTS (
      SELECT 1
      FROM public.subscriptions s
      WHERE s.empresa_id = pa.empresa_id
        AND s.status = 'active'
        AND COALESCE(s.acceso_bloqueado, false) = false
    );
$$;


--
-- Name: get_partner_coupon_cap(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_partner_coupon_cap(_partner_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (
      SELECT n.comision_pct
      FROM public.get_partner_nivel(_partner_id) n
      LIMIT 1
    ),
    (
      SELECT p.comision_pct
      FROM public.partners p
      WHERE p.id = _partner_id
    ),
    0
  );
$$;


--
-- Name: get_partner_nivel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_partner_nivel(_partner_id uuid) RETURNS TABLE(nivel_id uuid, nombre text, orden integer, comision_pct numeric, empresas_min integer, empresas_max integer, emoji text, color text, empresas_actuales integer, empresas_para_siguiente integer, siguiente_nombre text, siguiente_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int;
  v_partner record;
  v_nivel record;
  v_pct_efectivo numeric;
  v_siguiente record;
BEGIN
  v_count := public.get_partner_active_empresas(_partner_id);

  SELECT p.*
  INTO v_partner
  FROM public.partners p
  WHERE p.id = _partner_id;

  SELECT pn.*
  INTO v_nivel
  FROM public.partner_niveles pn
  WHERE pn.empresas_min <= v_count
    AND (
      pn.empresas_max IS NULL
      OR pn.empresas_max >= v_count
    )
  ORDER BY pn.orden DESC
  LIMIT 1;

  IF v_nivel.id IS NULL THEN
    RETURN;
  END IF;

  v_pct_efectivo := v_nivel.comision_pct;

  IF v_partner.peor_nivel_pct_60d IS NOT NULL
     AND v_partner.peor_nivel_fecha > now() - interval '60 days'
     AND v_partner.peor_nivel_pct_60d > v_pct_efectivo THEN
    v_pct_efectivo := v_partner.peor_nivel_pct_60d;
  END IF;

  SELECT pn.*
  INTO v_siguiente
  FROM public.partner_niveles pn
  WHERE pn.orden > v_nivel.orden
  ORDER BY pn.orden ASC
  LIMIT 1;

  RETURN QUERY
  SELECT
    v_nivel.id,
    v_nivel.nombre,
    v_nivel.orden,
    v_pct_efectivo,
    v_nivel.empresas_min,
    v_nivel.empresas_max,
    v_nivel.emoji,
    v_nivel.color,
    v_count,
    CASE
      WHEN v_siguiente.empresas_min IS NULL THEN 0
      ELSE GREATEST(v_siguiente.empresas_min - v_count, 0)
    END,
    v_siguiente.nombre,
    v_siguiente.comision_pct;
END;
$$;


--
-- Name: get_sandbox_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sandbox_usage(p_empresa_id uuid) RETURNS TABLE(clientes_count integer, clientes_max integer, productos_count integer, productos_max integer, ventas_count integer, ventas_max integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    (SELECT count(*)::int FROM clientes WHERE empresa_id = p_empresa_id), 10,
    (SELECT count(*)::int FROM productos WHERE empresa_id = p_empresa_id), 20,
    (SELECT count(*)::int FROM ventas WHERE empresa_id = p_empresa_id), 50;
$$;


--
-- Name: get_team_visible_people(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_visible_people(p_user_id uuid DEFAULT auth.uid()) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH RECURSIVE mine AS (
    SELECT tm.person_id, tm.access_scope
    FROM public.platform_team_members tm
    JOIN public.commission_people cp
      ON cp.id = tm.person_id
    WHERE tm.user_id = p_user_id
      AND tm.status IN ('invited', 'active')
      AND cp.is_active = true
      AND (
        p_user_id = auth.uid()
        OR public.is_super_admin(auth.uid())
      )
  ),
  descendants(id) AS (
    SELECT mine.person_id
    FROM mine

    UNION

    SELECT cp.id
    FROM public.commission_people cp
    JOIN descendants d
      ON cp.manager_id = d.id
    CROSS JOIN mine
    WHERE mine.access_scope IN ('team', 'all')
      AND cp.person_type = 'internal'
      AND cp.is_active = true
  )

  SELECT descendants.id
  FROM descendants

  UNION

  SELECT cp.id
  FROM public.commission_people cp
  CROSS JOIN mine
  WHERE mine.access_scope = 'all'
    AND cp.person_type = 'internal'
    AND cp.is_active = true;
$$;


--
-- Name: get_user_archive_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_archive_summary(p_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa_id uuid;
  v_user_id uuid;
  v_almacen_id uuid;

  v_entregas_pendientes int;
  v_rutas_activas int;
  v_ventas_borrador int;

  v_stock_items int;
  v_stock_total numeric;

BEGIN

  SELECT
    empresa_id,
    user_id,
    almacen_id
  INTO
    v_empresa_id,
    v_user_id,
    v_almacen_id
  FROM public.profiles
  WHERE id = p_profile_id;


  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no encontrado';
  END IF;


  IF NOT public.is_empresa_admin(auth.uid(), v_empresa_id) THEN
    RAISE EXCEPTION
      'Acceso denegado: requiere permisos de administrador';
  END IF;


  -- ----------------------------------------------------------
  -- Entregas pendientes
  -- ----------------------------------------------------------

  SELECT COUNT(*)
  INTO v_entregas_pendientes
  FROM public.entregas
  WHERE empresa_id = v_empresa_id
    AND status NOT IN ('hecho', 'cancelado')
    AND (
      vendedor_id = p_profile_id
      OR vendedor_ruta_id = p_profile_id
    );


  -- ----------------------------------------------------------
  -- Rutas abiertas
  -- ----------------------------------------------------------

  SELECT COUNT(*)
  INTO v_rutas_activas
  FROM public.ruta_sesiones
  WHERE vendedor_id = p_profile_id
    AND status = 'abierta';


  -- ----------------------------------------------------------
  -- Ventas / pedidos todavía pendientes
  -- ----------------------------------------------------------

  SELECT COUNT(*)
  INTO v_ventas_borrador
  FROM public.ventas
  WHERE empresa_id = v_empresa_id
    AND vendedor_id = p_profile_id
    AND status IN ('borrador', 'confirmado')
    AND tipo IN ('pedido', 'venta_directa')
    AND COALESCE(saldo_pendiente, 0) > 0;


  -- ----------------------------------------------------------
  -- Inventario del almacén asignado
  -- ----------------------------------------------------------

  IF v_almacen_id IS NOT NULL THEN

    SELECT
      COUNT(*),
      COALESCE(SUM(cantidad), 0)
    INTO
      v_stock_items,
      v_stock_total
    FROM public.stock_almacen
    WHERE almacen_id = v_almacen_id
      AND cantidad <> 0;

  ELSE

    v_stock_items := 0;
    v_stock_total := 0;

  END IF;


  RETURN jsonb_build_object(

    'profile_id',
    p_profile_id,

    'empresa_id',
    v_empresa_id,

    'almacen_id',
    v_almacen_id,

    'entregas_pendientes',
    v_entregas_pendientes,

    'rutas_activas',
    v_rutas_activas,

    'ventas_borrador_con_saldo',
    v_ventas_borrador,

    'stock_items',
    v_stock_items,

    'stock_total',
    v_stock_total,

    'puede_archivar',
    (
      v_entregas_pendientes = 0
      AND v_rutas_activas = 0
      AND v_ventas_borrador = 0
      AND COALESCE(v_stock_total, 0) = 0
    )

  );

END;
$$;


--
-- Name: guardar_aprobacion_solicitud(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guardar_aprobacion_solicitud(p_solicitud_id uuid, p_almacen_origen_id uuid, p_observaciones text DEFAULT NULL::text, p_lineas jsonb DEFAULT '[]'::jsonb, p_excluidas jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sol public.solicitudes_traspaso%ROWTYPE;
  v_item jsonb;
  v_linea_id uuid;
  v_producto_id uuid;
  v_cantidad numeric;
  v_excluida_id uuid;
  v_existente public.solicitud_traspaso_lineas%ROWTYPE;
BEGIN
  SELECT * INTO v_sol
    FROM public.solicitudes_traspaso
   WHERE id = p_solicitud_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF NOT (
    v_sol.empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF v_sol.status <> 'solicitada' THEN
    RAISE EXCEPTION 'Solo se puede editar una solicitud pendiente de aprobación';
  END IF;

  IF p_almacen_origen_id IS NULL
     OR p_almacen_origen_id = v_sol.almacen_destino_id THEN
    RAISE EXCEPTION 'Elige un almacén origen diferente al destino';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.almacenes
     WHERE id = p_almacen_origen_id
       AND empresa_id = v_sol.empresa_id
  ) THEN
    RAISE EXCEPTION 'El almacén origen no pertenece a la empresa';
  END IF;

  -- Excluir partidas sin eliminar el historial.
  FOR v_excluida_id IN
    SELECT value::uuid
      FROM jsonb_array_elements_text(
        COALESCE(p_excluidas, '[]'::jsonb)
      )
  LOOP
    UPDATE public.solicitud_traspaso_lineas
       SET excluida = true,
           excluida_por = auth.uid(),
           excluida_at = now()
     WHERE id = v_excluida_id
       AND solicitud_id = p_solicitud_id
       AND excluida = false;
  END LOOP;

  FOR v_item IN
    SELECT *
      FROM jsonb_array_elements(
        COALESCE(p_lineas, '[]'::jsonb)
      )
  LOOP
    v_linea_id := NULLIF(v_item->>'linea_id', '')::uuid;
    v_producto_id := NULLIF(v_item->>'producto_id', '')::uuid;
    v_cantidad := GREATEST(
      COALESCE((v_item->>'cantidad_aprobada')::numeric, 0),
      0
    );

    IF v_linea_id IS NULL OR v_producto_id IS NULL THEN
      RAISE EXCEPTION 'Hay una partida incompleta en la aprobación';
    END IF;

    IF NOT EXISTS (
      SELECT 1
        FROM public.productos
       WHERE id = v_producto_id
         AND empresa_id = v_sol.empresa_id
    ) THEN
      RAISE EXCEPTION 'Uno de los productos no pertenece a la empresa';
    END IF;

    SELECT * INTO v_existente
      FROM public.solicitud_traspaso_lineas
     WHERE id = v_linea_id
     FOR UPDATE;

    IF FOUND THEN
      IF v_existente.solicitud_id <> p_solicitud_id
         OR v_existente.producto_id <> v_producto_id THEN
        RAISE EXCEPTION 'La partida no pertenece a esta solicitud';
      END IF;

      UPDATE public.solicitud_traspaso_lineas
         SET cantidad_aprobada = v_cantidad,
             excluida = false,
             excluida_por = NULL,
             excluida_at = NULL
       WHERE id = v_linea_id;
    ELSE
      IF EXISTS (
        SELECT 1
          FROM public.solicitud_traspaso_lineas
         WHERE solicitud_id = p_solicitud_id
           AND producto_id = v_producto_id
           AND excluida = false
      ) THEN
        RAISE EXCEPTION 'El producto agregado ya existe en la solicitud';
      END IF;

      INSERT INTO public.solicitud_traspaso_lineas (
        id,
        solicitud_id,
        producto_id,
        stock_actual_snapshot,
        stock_minimo_snapshot,
        stock_maximo_snapshot,
        cantidad_sugerida,
        cantidad_solicitada,
        cantidad_aprobada,
        cantidad_surtida,
        agregada_por_admin,
        agregada_por,
        agregada_at
      )
      VALUES (
        v_linea_id,
        p_solicitud_id,
        v_producto_id,
        0,
        0,
        0,
        0,
        0,
        v_cantidad,
        0,
        true,
        auth.uid(),
        now()
      );
    END IF;
  END LOOP;

  UPDATE public.solicitudes_traspaso
     SET almacen_origen_id = p_almacen_origen_id,
         observaciones = p_observaciones
   WHERE id = p_solicitud_id;

  PERFORM public.fn_log_solicitud_traspaso(
    p_solicitud_id,
    v_sol.empresa_id,
    'aprobacion_guardada',
    jsonb_build_object(
      'lineas',
      jsonb_array_length(COALESCE(p_lineas, '[]'::jsonb)),
      'excluidas',
      jsonb_array_length(COALESCE(p_excluidas, '[]'::jsonb))
    )
  );
END;
$$;


--
-- Name: guardar_compra_segura(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guardar_compra_segura(p_compra_id uuid, p_compra jsonb, p_lineas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_compra public.compras%ROWTYPE;
  v_linea public.compra_lineas%ROWTYPE;
  v_input record;
  v_producto record;
  v_empresa_id uuid;
  v_almacen_id uuid;
  v_proveedor_id uuid;
  v_actor uuid := auth.uid();
  v_folio text;
  v_status_original text;
  v_status_final text;
  v_condicion text;
  v_descuento_tipo text;
  v_total numeric;
  v_total_pagado numeric := 0;
  v_total_anterior numeric;
  v_total_nuevo numeric;
  v_recibido_anterior numeric;
  v_recibido_deseado numeric;
  v_delta numeric;
  v_loteado numeric;
  v_stock_disponible numeric;
  v_pendiente_inventario numeric;
  v_maneja_lotes_empresa boolean := false;
  v_requiere_lote boolean;
  v_era_completa boolean;
  v_recalc_producto_id uuid;
  v_productos_recalcular uuid[] := ARRAY[]::uuid[];
  v_es_nueva boolean := p_compra_id IS NULL;
  v_creadas integer := 0;
  v_actualizadas integer := 0;
  v_eliminadas integer := 0;
  v_entradas numeric := 0;
  v_salidas numeric := 0;
  v_epsilon constant numeric := 0.0001;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Debes iniciar sesión para guardar la compra';
  END IF;
  IF jsonb_typeof(p_compra) <> 'object' THEN
    RAISE EXCEPTION 'Los datos de la compra no son válidos';
  END IF;
  IF jsonb_typeof(p_lineas) <> 'array' OR jsonb_array_length(p_lineas) = 0 THEN
    RAISE EXCEPTION 'Agrega al menos un producto a la compra';
  END IF;

  IF v_es_nueva THEN
    v_empresa_id := NULLIF(p_compra->>'empresa_id', '')::uuid;
    IF v_empresa_id IS NULL THEN
      RAISE EXCEPTION 'La empresa de la compra es obligatoria';
    END IF;
    IF NOT (v_empresa_id = public.get_my_empresa_id() OR public.is_super_admin(v_actor)) THEN
      RAISE EXCEPTION 'No tienes permiso para crear compras en esta empresa';
    END IF;
    v_status_original := 'borrador';
  ELSE
    SELECT * INTO v_compra
    FROM public.compras
    WHERE id = p_compra_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Compra no encontrada';
    END IF;
    v_empresa_id := v_compra.empresa_id;
    IF NOT (v_empresa_id = public.get_my_empresa_id() OR public.is_super_admin(v_actor)) THEN
      RAISE EXCEPTION 'No tienes permiso para editar esta compra';
    END IF;
    IF v_compra.status = 'cancelada' THEN
      RAISE EXCEPTION 'Una compra cancelada no se puede editar';
    END IF;
    v_status_original := v_compra.status;
    v_folio := v_compra.folio;

    PERFORM 1 FROM public.compra_lineas WHERE compra_id = p_compra_id FOR UPDATE;
    PERFORM 1 FROM public.pago_compras WHERE compra_id = p_compra_id FOR UPDATE;
  END IF;

  SELECT COALESCE(maneja_lotes, false)
    INTO v_maneja_lotes_empresa
  FROM public.empresas
  WHERE id = v_empresa_id;

  v_almacen_id := NULLIF(p_compra->>'almacen_id', '')::uuid;
  v_proveedor_id := NULLIF(p_compra->>'proveedor_id', '')::uuid;
  IF v_almacen_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.almacenes a
    WHERE a.id = v_almacen_id AND a.empresa_id = v_empresa_id
  ) THEN
    RAISE EXCEPTION 'Selecciona un almacén destino válido';
  END IF;
  IF v_proveedor_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.proveedores p
    WHERE p.id = v_proveedor_id AND p.empresa_id = v_empresa_id
  ) THEN
    RAISE EXCEPTION 'El proveedor no pertenece a la empresa';
  END IF;

  v_condicion := COALESCE(NULLIF(p_compra->>'condicion_pago', ''), 'contado');
  IF v_condicion NOT IN ('contado', 'credito') THEN
    RAISE EXCEPTION 'La condición de pago no es válida';
  END IF;
  v_descuento_tipo := COALESCE(NULLIF(p_compra->>'descuento_extra_tipo', ''), 'monto');
  IF v_descuento_tipo NOT IN ('monto', 'porcentaje') THEN
    RAISE EXCEPTION 'El tipo de descuento no es válido';
  END IF;
  v_total := GREATEST(0, COALESCE(NULLIF(p_compra->>'total', '')::numeric, 0));

  IF NOT v_es_nueva THEN
    SELECT COALESCE(SUM(pc.monto), 0)
      INTO v_total_pagado
    FROM public.pago_compras pc
    WHERE pc.compra_id = p_compra_id;
    IF v_total + 0.01 < v_total_pagado THEN
      RAISE EXCEPTION
        'El nuevo total (%) no puede ser menor que lo ya pagado (%). Ajusta primero los pagos de la compra.',
        v_total, v_total_pagado;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_lineas) AS x(id uuid)
    WHERE x.id IS NOT NULL
    GROUP BY x.id
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'La factura contiene un renglón duplicado';
  END IF;

  IF v_es_nueva THEN
    INSERT INTO public.compras (
      empresa_id, proveedor_id, almacen_id, fecha, condicion_pago, dias_credito,
      status, subtotal, iva_total, total, saldo_pendiente, descuento_extra,
      descuento_extra_tipo, descuento_extra_motivo, descuento_total, ajuste_total,
      notas, notas_pago, numero_factura, fecha_vencimiento, created_by
    ) VALUES (
      v_empresa_id, v_proveedor_id, v_almacen_id,
      COALESCE(NULLIF(p_compra->>'fecha', '')::date, current_date),
      v_condicion,
      CASE WHEN v_condicion = 'credito' THEN GREATEST(0, COALESCE(NULLIF(p_compra->>'dias_credito', '')::integer, 0)) ELSE 0 END,
      'borrador',
      GREATEST(0, COALESCE(NULLIF(p_compra->>'subtotal', '')::numeric, 0)),
      GREATEST(0, COALESCE(NULLIF(p_compra->>'iva_total', '')::numeric, 0)),
      v_total, v_total, GREATEST(0, COALESCE(NULLIF(p_compra->>'descuento_extra', '')::numeric, 0)),
      v_descuento_tipo, NULLIF(p_compra->>'descuento_extra_motivo', ''),
      GREATEST(0, COALESCE(NULLIF(p_compra->>'descuento_total', '')::numeric, 0)),
      COALESCE(NULLIF(p_compra->>'ajuste_total', '')::numeric, 0),
      NULLIF(p_compra->>'notas', ''), NULLIF(p_compra->>'notas_pago', ''),
      NULLIF(p_compra->>'numero_factura', ''),
      CASE WHEN v_condicion = 'credito' THEN NULLIF(p_compra->>'fecha_vencimiento', '')::date ELSE NULL END,
      v_actor
    )
    RETURNING * INTO v_compra;
    p_compra_id := v_compra.id;
    v_folio := v_compra.folio;
  END IF;

  IF NOT v_es_nueva THEN
    FOR v_linea IN
      SELECT cl.*
      FROM public.compra_lineas cl
      WHERE cl.compra_id = p_compra_id
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_to_recordset(p_lineas) AS x(id uuid)
          WHERE x.id = cl.id
        )
      ORDER BY cl.id
      FOR UPDATE
    LOOP
      v_productos_recalcular := array_append(v_productos_recalcular, v_linea.producto_id);
      v_recibido_anterior := GREATEST(0, COALESCE(v_linea.cantidad_recibida, 0));
      SELECT COALESCE(SUM(cll.piezas), 0)
        INTO v_loteado
      FROM public.compra_linea_lotes cll
      WHERE cll.compra_linea_id = v_linea.id;

      IF v_loteado > 0 THEN
        SELECT sa.cantidad
          INTO v_stock_disponible
        FROM public.stock_almacen sa
        WHERE sa.almacen_id = v_compra.almacen_id
          AND sa.producto_id = v_linea.producto_id
        FOR UPDATE;
        IF COALESCE(v_stock_disponible, 0) + v_epsilon < v_recibido_anterior THEN
          RAISE EXCEPTION
            'No se puede eliminar el renglón: parte de la mercancía ya fue utilizada o vendida';
        END IF;
        IF EXISTS (
          SELECT 1
          FROM (
            SELECT cll.almacen_id, cll.lote_id, SUM(cll.piezas) AS piezas
            FROM public.compra_linea_lotes cll
            WHERE cll.compra_linea_id = v_linea.id
            GROUP BY cll.almacen_id, cll.lote_id
          ) d
          LEFT JOIN public.stock_lotes sl
            ON sl.almacen_id = d.almacen_id AND sl.lote_id = d.lote_id
          WHERE COALESCE(sl.cantidad, 0) + v_epsilon < d.piezas
        ) THEN
          RAISE EXCEPTION 'No se puede eliminar el renglón: parte de sus lotes ya fue utilizada o vendida';
        END IF;
        DELETE FROM public.compra_linea_lotes WHERE compra_linea_id = v_linea.id;
        v_salidas := v_salidas + v_loteado;
      END IF;

      v_delta := GREATEST(0, v_recibido_anterior - v_loteado);
      IF v_delta > v_epsilon THEN
        PERFORM public._aplicar_delta_compra_edicion(
          v_empresa_id, p_compra_id, v_linea.producto_id, v_compra.almacen_id,
          -v_delta, v_actor, v_folio, 'renglón eliminado'
        );
        v_salidas := v_salidas + v_delta;
      END IF;

      DELETE FROM public.compra_lineas WHERE id = v_linea.id;
      v_eliminadas := v_eliminadas + 1;
    END LOOP;
  END IF;

  FOR v_input IN
    SELECT *
    FROM jsonb_to_recordset(p_lineas) AS x(
      id uuid,
      producto_id uuid,
      cantidad numeric,
      precio_unitario numeric,
      subtotal numeric,
      total numeric,
      factor_conversion numeric,
      piezas_total numeric,
      lote_id uuid
    )
  LOOP
    IF v_input.producto_id IS NULL THEN
      RAISE EXCEPTION 'Todos los renglones deben tener un producto';
    END IF;
    IF COALESCE(v_input.cantidad, 0) <= 0 THEN
      RAISE EXCEPTION 'La cantidad de cada producto debe ser mayor que cero';
    END IF;
    IF COALESCE(v_input.factor_conversion, 0) <= 0 THEN
      RAISE EXCEPTION 'El factor de conversión debe ser mayor que cero';
    END IF;
    IF COALESCE(v_input.precio_unitario, 0) < 0 THEN
      RAISE EXCEPTION 'El costo unitario no puede ser negativo';
    END IF;

    SELECT p.id, p.nombre, COALESCE(p.maneja_lote, false) AS maneja_lote
      INTO v_producto
    FROM public.productos p
    WHERE p.id = v_input.producto_id
      AND p.empresa_id = v_empresa_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Uno de los productos no pertenece a la empresa';
    END IF;
    v_productos_recalcular := array_append(v_productos_recalcular, v_input.producto_id);

    v_requiere_lote := v_maneja_lotes_empresa AND v_producto.maneja_lote;
    v_total_nuevo := v_input.cantidad * v_input.factor_conversion;

    IF v_input.id IS NULL THEN
      v_recibido_deseado := CASE
        WHEN v_status_original IN ('recibida', 'pagada') AND NOT v_requiere_lote
          THEN v_total_nuevo
        ELSE 0
      END;

      INSERT INTO public.compra_lineas (
        compra_id, producto_id, cantidad, precio_unitario, subtotal, total,
        factor_conversion, piezas_total, cantidad_recibida, piezas_loteadas, lote_id
      ) VALUES (
        p_compra_id, v_input.producto_id, v_input.cantidad,
        COALESCE(v_input.precio_unitario, 0), COALESCE(v_input.subtotal, 0),
        COALESCE(v_input.total, 0), v_input.factor_conversion, v_total_nuevo,
        v_recibido_deseado, 0, v_input.lote_id
      );

      IF v_recibido_deseado > v_epsilon THEN
        PERFORM public._aplicar_delta_compra_edicion(
          v_empresa_id, p_compra_id, v_input.producto_id, v_almacen_id,
          v_recibido_deseado, v_actor, v_folio, 'renglón agregado'
        );
        v_entradas := v_entradas + v_recibido_deseado;
      END IF;
      v_creadas := v_creadas + 1;
      CONTINUE;
    END IF;

    SELECT * INTO v_linea
    FROM public.compra_lineas
    WHERE id = v_input.id
      AND compra_id = p_compra_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Uno de los renglones fue modificado por otro usuario. Recarga la compra e inténtalo de nuevo.';
    END IF;
    v_productos_recalcular := array_append(v_productos_recalcular, v_linea.producto_id);

    v_recibido_anterior := GREATEST(0, COALESCE(v_linea.cantidad_recibida, 0));
    v_total_anterior := v_linea.cantidad * COALESCE(NULLIF(v_linea.factor_conversion, 0), 1);
    v_era_completa := v_recibido_anterior + v_epsilon >= v_total_anterior;

    SELECT COALESCE(SUM(cll.piezas), 0)
      INTO v_loteado
    FROM public.compra_linea_lotes cll
    WHERE cll.compra_linea_id = v_linea.id;

    IF v_linea.producto_id IS DISTINCT FROM v_input.producto_id AND v_recibido_anterior > v_epsilon THEN
      RAISE EXCEPTION
        'No se puede cambiar el producto "%" porque ya tiene mercancía recibida. Elimina el renglón y agrega el producto correcto.',
        v_producto.nombre;
    END IF;
    IF v_compra.almacen_id IS DISTINCT FROM v_almacen_id AND v_recibido_anterior > v_epsilon THEN
      RAISE EXCEPTION 'No se puede cambiar el almacén de una compra con mercancía recibida';
    END IF;
    IF v_loteado > v_total_nuevo + v_epsilon THEN
      RAISE EXCEPTION
        'No se puede bajar "%" a % pieza(s): ya tiene % pieza(s) asignadas a lotes. Quita primero el loteo excedente.',
        v_producto.nombre, v_total_nuevo, v_loteado;
    END IF;

    v_recibido_deseado := CASE
      WHEN v_status_original IN ('recibida', 'pagada') AND v_era_completa AND NOT v_requiere_lote
        THEN v_total_nuevo
      ELSE LEAST(v_recibido_anterior, v_total_nuevo)
    END;
    v_delta := v_recibido_deseado - v_recibido_anterior;

    IF ABS(v_delta) > v_epsilon THEN
      PERFORM public._aplicar_delta_compra_edicion(
        v_empresa_id, p_compra_id, v_input.producto_id, v_almacen_id,
        v_delta, v_actor, v_folio, 'cantidad corregida'
      );
      IF v_delta > 0 THEN v_entradas := v_entradas + v_delta;
      ELSE v_salidas := v_salidas + ABS(v_delta);
      END IF;
    END IF;

    UPDATE public.compra_lineas
       SET producto_id = v_input.producto_id,
           cantidad = v_input.cantidad,
           precio_unitario = COALESCE(v_input.precio_unitario, 0),
           subtotal = COALESCE(v_input.subtotal, 0),
           total = COALESCE(v_input.total, 0),
           factor_conversion = v_input.factor_conversion,
           piezas_total = v_total_nuevo,
           cantidad_recibida = v_recibido_deseado,
           lote_id = v_input.lote_id
     WHERE id = v_linea.id;
    v_actualizadas := v_actualizadas + 1;
  END LOOP;

  SELECT COALESCE(SUM(GREATEST(
           0,
           cl.cantidad * COALESCE(NULLIF(cl.factor_conversion, 0), 1)
             - COALESCE(cl.cantidad_recibida, 0)
         )), 0)
    INTO v_pendiente_inventario
  FROM public.compra_lineas cl
  WHERE cl.compra_id = p_compra_id;

  v_status_final := CASE
    WHEN v_status_original = 'borrador' THEN 'borrador'
    WHEN v_pendiente_inventario > v_epsilon THEN 'confirmada'
    WHEN v_status_original = 'pagada' AND v_total_pagado + 0.01 >= v_total THEN 'pagada'
    ELSE 'recibida'
  END;

  UPDATE public.compras
     SET proveedor_id = v_proveedor_id,
         almacen_id = v_almacen_id,
         fecha = COALESCE(NULLIF(p_compra->>'fecha', '')::date, current_date),
         condicion_pago = v_condicion,
         dias_credito = CASE WHEN v_condicion = 'credito' THEN GREATEST(0, COALESCE(NULLIF(p_compra->>'dias_credito', '')::integer, 0)) ELSE 0 END,
         status = v_status_final,
         subtotal = GREATEST(0, COALESCE(NULLIF(p_compra->>'subtotal', '')::numeric, 0)),
         iva_total = GREATEST(0, COALESCE(NULLIF(p_compra->>'iva_total', '')::numeric, 0)),
         total = v_total,
         saldo_pendiente = GREATEST(0, v_total - v_total_pagado),
         descuento_extra = GREATEST(0, COALESCE(NULLIF(p_compra->>'descuento_extra', '')::numeric, 0)),
         descuento_extra_tipo = v_descuento_tipo,
         descuento_extra_motivo = NULLIF(p_compra->>'descuento_extra_motivo', ''),
         descuento_total = GREATEST(0, COALESCE(NULLIF(p_compra->>'descuento_total', '')::numeric, 0)),
         ajuste_total = COALESCE(NULLIF(p_compra->>'ajuste_total', '')::numeric, 0),
         notas = NULLIF(p_compra->>'notas', ''),
         notas_pago = NULLIF(p_compra->>'notas_pago', ''),
         numero_factura = NULLIF(p_compra->>'numero_factura', ''),
         fecha_vencimiento = CASE WHEN v_condicion = 'credito' THEN NULLIF(p_compra->>'fecha_vencimiento', '')::date ELSE NULL END
   WHERE id = p_compra_id;

  FOREACH v_recalc_producto_id IN ARRAY v_productos_recalcular
  LOOP
    PERFORM public.recalc_producto_costo(v_recalc_producto_id);
  END LOOP;

  RETURN jsonb_build_object(
    'compra_id', p_compra_id,
    'status', v_status_final,
    'lineas_creadas', v_creadas,
    'lineas_actualizadas', v_actualizadas,
    'lineas_eliminadas', v_eliminadas,
    'piezas_entrada', v_entradas,
    'piezas_salida', v_salidas
  );
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_empresa_id uuid;
  v_empresa_nombre text;
  v_ref_slug text;
  v_cupon_codigo text;
  v_is_partner boolean;
  v_role_id uuid;
  v_almacen_id uuid;
BEGIN
  IF NEW.raw_user_meta_data ->> 'account_type' = 'rutapp_team' THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS(
    SELECT 1
    FROM public.partners partner
    WHERE lower(partner.email) = lower(NEW.email)
  )
  INTO v_is_partner;

  IF v_is_partner THEN
    UPDATE public.partners partner
    SET user_id = NEW.id
    WHERE lower(partner.email) = lower(NEW.email)
      AND partner.user_id IS NULL;

    RETURN NEW;
  END IF;

  v_empresa_nombre := COALESCE(NEW.raw_user_meta_data ->> 'empresa_nombre', '');
  v_ref_slug := NULLIF(NEW.raw_user_meta_data ->> 'partner_ref', '');
  v_cupon_codigo := NULLIF(NEW.raw_user_meta_data ->> 'cupon_codigo', '');

  IF v_empresa_nombre <> '' THEN
    INSERT INTO public.empresas(nombre, telefono, email, owner_user_id)
    VALUES (
      v_empresa_nombre,
      COALESCE(NEW.raw_user_meta_data ->> 'phone', NEW.phone, ''),
      COALESCE(NEW.email, ''),
      NEW.id
    )
    RETURNING id INTO v_empresa_id;
  ELSE
    SELECT empresa.id
    INTO v_empresa_id
    FROM public.empresas empresa
    LIMIT 1;
  END IF;

  SELECT almacen.id
  INTO v_almacen_id
  FROM public.almacenes almacen
  WHERE almacen.empresa_id = v_empresa_id
    AND almacen.nombre = 'Almacén General'
  LIMIT 1;

  INSERT INTO public.profiles(
    user_id,
    nombre,
    empresa_id,
    telefono,
    almacen_id
  )
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.email),
    v_empresa_id,
    NEW.raw_user_meta_data ->> 'phone',
    v_almacen_id
  );

  SELECT role.id
  INTO v_role_id
  FROM public.roles role
  WHERE role.empresa_id = v_empresa_id
    AND role.nombre = 'Administrador'
  LIMIT 1;

  IF v_role_id IS NOT NULL THEN
    INSERT INTO public.user_roles(user_id, role_id)
    VALUES (NEW.id, v_role_id)
    ON CONFLICT DO NOTHING;
  END IF;

  IF v_empresa_nombre <> ''
     AND (v_ref_slug IS NOT NULL OR v_cupon_codigo IS NOT NULL) THEN
    BEGIN
      PERFORM public.aplicar_partner_referido(
        v_empresa_id,
        v_ref_slug,
        v_cupon_codigo
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: has_admin_pin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_admin_pin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = p_user_id
      AND pin_code IS NOT NULL
      AND length(btrim(pin_code)) > 0
  );
$$;


--
-- Name: has_billing_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_billing_access(p_empresa_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sub record;
  v_today date := (now() AT TIME ZONE 'America/Mexico_City')::date;
  v_day_of_month int := EXTRACT(DAY FROM v_today)::int;
BEGIN
  -- Super admin always has access
  IF public.is_super_admin(auth.uid()) THEN
    RETURN true;
  END IF;

  SELECT status, trial_ends_at, fecha_vencimiento, acceso_bloqueado, es_manual
  INTO v_sub
  FROM public.subscriptions
  WHERE empresa_id = p_empresa_id;

  IF NOT FOUND THEN RETURN false; END IF;

  -- Manual subscriptions skip billing checks
  IF v_sub.es_manual = true THEN RETURN true; END IF;

  -- Hard block (set by cron on day 4+)
  IF v_sub.acceso_bloqueado = true THEN RETURN false; END IF;

  -- Active trial
  IF v_sub.status = 'trial' AND v_sub.trial_ends_at IS NOT NULL AND v_sub.trial_ends_at >= now() THEN
    RETURN true;
  END IF;

  -- Within paid period
  IF v_sub.fecha_vencimiento IS NOT NULL AND v_sub.fecha_vencimiento >= v_today THEN
    RETURN true;
  END IF;

  -- Grace period: days 1-3 of any month always allowed if vencimiento was last month or earlier
  IF v_day_of_month <= 3 THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$$;


--
-- Name: inherit_entrega_orden_from_cliente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inherit_entrega_orden_from_cliente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_dia text;
  v_orden integer;
BEGIN
  -- Skip if orden_entrega already set manually
  IF NEW.orden_entrega IS NOT NULL AND NEW.orden_entrega > 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.cliente_id IS NULL THEN RETURN NEW; END IF;

  -- Day of week from fecha_entrega (or fecha) in Spanish
  v_dia := CASE EXTRACT(DOW FROM COALESCE(NEW.fecha_entrega, NEW.fecha))
    WHEN 0 THEN 'Domingo'
    WHEN 1 THEN 'Lunes'
    WHEN 2 THEN 'Martes'
    WHEN 3 THEN 'Miércoles'
    WHEN 4 THEN 'Jueves'
    WHEN 5 THEN 'Viernes'
    WHEN 6 THEN 'Sábado'
  END;

  -- 1) Try exact match: día + vendedor
  SELECT orden INTO v_orden
  FROM public.cliente_orden_ruta
  WHERE cliente_id = NEW.cliente_id
    AND dia = v_dia
    AND vendedor_id = NEW.vendedor_id
  LIMIT 1;

  -- 2) Fallback: día sin vendedor específico
  IF v_orden IS NULL THEN
    SELECT orden INTO v_orden
    FROM public.cliente_orden_ruta
    WHERE cliente_id = NEW.cliente_id
      AND dia = v_dia
      AND vendedor_id IS NULL
    LIMIT 1;
  END IF;

  -- 3) Fallback: vendedor sin día
  IF v_orden IS NULL AND NEW.vendedor_id IS NOT NULL THEN
    SELECT orden INTO v_orden
    FROM public.cliente_orden_ruta
    WHERE cliente_id = NEW.cliente_id
      AND vendedor_id = NEW.vendedor_id
      AND dia IS NULL
    LIMIT 1;
  END IF;

  -- 4) Fallback: cualquier orden del cliente
  IF v_orden IS NULL THEN
    SELECT orden INTO v_orden
    FROM public.cliente_orden_ruta
    WHERE cliente_id = NEW.cliente_id
    ORDER BY orden ASC
    LIMIT 1;
  END IF;

  IF v_orden IS NOT NULL THEN
    NEW.orden_entrega := v_orden;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: is_active_app_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_app_user(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = p_user_id
      AND p.estado = 'activo'
      AND p.archivado_en IS NULL
  );
$$;


--
-- Name: is_diego_super_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_diego_super_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.super_admins
    WHERE user_id = p_user_id
      AND lower(email) = 'diego.leon@uniline.mx'
  );
$$;


--
-- Name: is_email_blacklisted(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_email_blacklisted(p_email text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.trial_blacklist WHERE lower(email) = lower(p_email)
  );
$$;


--
-- Name: is_empresa_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_empresa_admin(p_user_id uuid, p_empresa_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    public.is_super_admin(p_user_id)
    OR (
      public.is_active_app_user(p_user_id)
      AND EXISTS (
        SELECT 1
        FROM public.profiles pr
        JOIN public.user_roles ur
          ON ur.user_id = pr.user_id
        JOIN public.roles r
          ON r.id = ur.role_id
        WHERE pr.user_id = p_user_id
          AND pr.empresa_id = p_empresa_id
          AND r.nombre = 'Administrador'
      )
    );
$$;


--
-- Name: is_platform_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_platform_team_member(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.platform_team_members tm
    JOIN public.commission_people cp
      ON cp.id = tm.person_id
    WHERE tm.user_id = p_user_id
      AND tm.status IN ('invited', 'active')
      AND cp.is_active = true
      AND cp.person_type = 'internal'
      AND (
        p_user_id = auth.uid()
        OR public.is_super_admin(auth.uid())
      )
  );
$$;


--
-- Name: is_sandbox_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_sandbox_empresa(p_empresa_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE((SELECT is_partner_sandbox FROM empresas WHERE id = p_empresa_id), false);
$$;


--
-- Name: is_super_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_super_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.super_admins WHERE user_id = p_user_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.profiles
      WHERE user_id = p_user_id AND super_admin_override_empresa_id IS NOT NULL
    );
$$;


--
-- Name: liberar_ventas_recibo_volumen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.liberar_ventas_recibo_volumen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.tipo_calculo = 'volumen' THEN
    UPDATE public.ventas SET comision_volumen_pago_id = NULL WHERE comision_volumen_pago_id = OLD.id;
  END IF;
  RETURN OLD;
END $$;


--
-- Name: limpiar_consumo_datos_antiguo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.limpiar_consumo_datos_antiguo() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
