--
-- Name: listar_planes_cupon_partner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_planes_cupon_partner() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ctx record;
  v_result json;
begin
  select * into v_ctx from public.contexto_partner();

  if v_ctx.partner_id is null or v_ctx.estado <> 'activo' then
    raise exception 'Sesion de partner invalida';
  end if;

  select coalesce(
    json_agg(row_to_json(t) order by t.orden, t.nombre),
    '[]'::json
  )
  into v_result
  from (
    select
      p.id,
      p.codigo,
      p.nombre,
      p.orden
    from public.planes_servicios p
    where p.activo = true
      and p.tipo = 'plan'
    order by p.orden, p.nombre
  ) t;

  return v_result;
end;
$$;


