-- Name: mirror_profile_to_vendedor_cobrador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_profile_to_vendedor_cobrador() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.vendedores
    SET nombre = COALESCE(NEW.nombre, nombre),
        telefono = NEW.telefono
  WHERE id = NEW.id;

  UPDATE public.cobradores
    SET nombre = COALESCE(NEW.nombre, nombre),
