END;
$$;


--
-- Name: mis_cupones_partner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mis_cupones_partner() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ctx record;
  v_result json;
begin
  select * into v_ctx from public.contexto_partner();

  if v_ctx.partner_id is null or v_ctx.estado <> 'activo' then
    raise exception 'Sesion de partner invalida';
  end if;

  select coalesce(
    json_agg(row_to_json(t) order by t.created_at desc),
    '[]'::json
  )
  into v_result
  from (
    select
      c.id,
      c.codigo,
      c.nombre,
      c.valor as porcentaje,
      c.activo,
      c.usos_totales as usos_actuales,
      c.un_uso_por_empresa,
      c.aplica_a,
      c.planes_aplicables,

      case
        when c.aplica_a = 'planes_seleccionados'
          and cardinality(c.planes_aplicables) = 1
        then c.planes_aplicables[1]
        else null
      end as plan_id,

      case
        when c.aplica_a = 'planes_seleccionados'
          and cardinality(c.planes_aplicables) = 1
        then (
          select ps.nombre
          from public.planes_servicios ps
          where ps.id = c.planes_aplicables[1]
        )
        else null
      end as plan_nombre,

      c.vigente_desde,
      c.vigente_hasta,
      c.created_at

    from public.partner_cupones pc
    join public.cupones c
      on c.id = pc.cupon_id

    where pc.partner_id = v_ctx.partner_id
  ) t;

  return v_result;
end;
$$;


--
-- Name: next_folio(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_folio(prefix text, p_empresa_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  next_num BIGINT;
  pattern TEXT := '^' || prefix || '-[0-9]+$';
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('folio:' || prefix), hashtext(p_empresa_id::text));
  IF prefix IN ('VTA', 'PED') THEN
    SELECT COALESCE(MAX(CASE WHEN folio ~ pattern THEN CAST(SUBSTRING(folio FROM LENGTH(prefix) + 2) AS BIGINT) ELSE 0 END), 0) + 1
    INTO next_num FROM public.ventas WHERE empresa_id = p_empresa_id AND folio ~ pattern;
  ELSIF prefix = 'CLI' THEN
    SELECT COALESCE(MAX(CASE WHEN codigo ~ pattern THEN CAST(SUBSTRING(codigo FROM LENGTH(prefix) + 2) AS BIGINT) ELSE 0 END), 0) + 1
    INTO next_num FROM public.clientes WHERE empresa_id = p_empresa_id;
  ELSIF prefix = 'PROD' THEN
    SELECT COALESCE(MAX(CASE WHEN codigo ~ pattern THEN CAST(SUBSTRING(codigo FROM LENGTH(prefix) + 2) AS BIGINT) ELSE 0 END), 0) + 1
    INTO next_num FROM public.productos WHERE empresa_id = p_empresa_id;
  ELSE
    next_num := 1;
  END IF;
  RETURN prefix || '-' || public.folio_num(next_num);
END;
$_$;


