--
-- Name: normalize_devolucion_tipo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_devolucion_tipo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.tipo::text NOT IN ('almacen', 'tienda') THEN
    NEW.tipo := CASE WHEN NEW.cliente_id IS NOT NULL THEN 'tienda'::public.tipo_devolucion
                     ELSE 'almacen'::public.tipo_devolucion END;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: normalize_venta_total_descuento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_venta_total_descuento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_gross numeric;
  v_correct_total numeric;
BEGIN
  v_gross := ROUND((COALESCE(NEW.subtotal, 0) + COALESCE(NEW.iva_total, 0) + COALESCE(NEW.ieps_total, 0))::numeric, 2);
  v_correct_total := ROUND(GREATEST(0, v_gross - COALESCE(NEW.descuento_total, 0))::numeric, 2);

  IF COALESCE(NEW.descuento_total, 0) > 0
     AND COALESCE(NEW.total, 0) > v_correct_total + 0.009 THEN
    NEW.total := v_correct_total;
  END IF;

  IF COALESCE(NEW.saldo_pendiente, 0) > COALESCE(NEW.total, 0) + 0.009 THEN
    NEW.saldo_pendiente := NEW.total;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: notify_on_cobro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_cobro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  cli_nombre TEXT;
  v_venta_id UUID;
  v_link TEXT;
BEGIN
  SELECT nombre INTO cli_nombre FROM public.clientes WHERE id = NEW.cliente_id;
  SELECT venta_id INTO v_venta_id FROM public.cobro_aplicaciones WHERE cobro_id = NEW.id LIMIT 1;
  v_link := COALESCE('/ventas/' || v_venta_id, '/clientes/' || NEW.cliente_id, '/ventas/cobranza');
  INSERT INTO public.internal_notifications (empresa_id, tipo, title, body, link, entity_type, entity_id)
  VALUES (
    NEW.empresa_id,
    'cobro',
    'Cobro recibido · $' || to_char(COALESCE(NEW.monto,0), 'FM999,999,990.00'),
    COALESCE(cli_nombre, 'Cliente') || ' · ' || COALESCE(NEW.metodo_pago, ''),
    v_link,
    'cobro',
    NEW.id
  );
  RETURN NEW;
END $_$;


