--
-- Name: pagar_comisiones_partner(uuid, numeric, text, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pagar_comisiones_partner(p_partner_id uuid, p_monto numeric, p_metodo text DEFAULT NULL::text, p_referencia text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_comision_ids uuid[] DEFAULT NULL::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_pago_id uuid;
  v_total numeric;
  v_count integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Solo super admin puede registrar pagos';
  END IF;

  IF p_monto IS NULL OR p_monto <= 0 THEN
    RAISE EXCEPTION 'El monto debe ser mayor a cero';
  END IF;

  IF p_monto < 500 AND EXISTS (
    SELECT 1
    FROM public.partners
    WHERE id = p_partner_id
      AND estado = 'activo'
  ) THEN
    RAISE EXCEPTION
      'El pago mínimo para un partner activo es $500 MXN';
  END IF;

  IF lower(COALESCE(p_metodo, '')) LIKE '%transfer%'
     AND NULLIF(trim(COALESCE(p_referencia, '')), '') IS NULL THEN
    RAISE EXCEPTION
      'La referencia bancaria es obligatoria para una transferencia';
  END IF;

  IF p_comision_ids IS NULL
     OR COALESCE(array_length(p_comision_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION
      'Selecciona al menos una comisión pendiente';
  END IF;

  PERFORM id
  FROM public.partner_comisiones
  WHERE id = ANY(p_comision_ids)
    AND partner_id = p_partner_id
    AND status = 'pendiente'
  FOR UPDATE;

  SELECT
    COUNT(*),
    COALESCE(SUM(monto_comision), 0)
  INTO
    v_count,
    v_total
  FROM public.partner_comisiones
  WHERE id = ANY(p_comision_ids)
    AND partner_id = p_partner_id
    AND status = 'pendiente';

  IF v_count <> array_length(p_comision_ids, 1) THEN
    RAISE EXCEPTION
      'Una o más comisiones ya no están pendientes';
  END IF;

  IF abs(v_total - p_monto) > 0.01 THEN
    RAISE EXCEPTION
      'El monto (%) debe coincidir con el total seleccionado (%)',
      p_monto,
      v_total;
  END IF;

  INSERT INTO public.partner_pagos (
    partner_id,
    monto,
    metodo,
    referencia,
    notas,
    pagado_por
  )
  VALUES (
    p_partner_id,
    v_total,
    p_metodo,
    p_referencia,
    p_notas,
    auth.uid()
  )
  RETURNING id INTO v_pago_id;

  UPDATE public.partner_comisiones
  SET
    status = 'pagada',
    pagado_en = now(),
    pago_id = v_pago_id
  WHERE id = ANY(p_comision_ids)
    AND partner_id = p_partner_id
    AND status = 'pendiente';

  RETURN v_pago_id;
END;
$_$;


