--
-- Name: reactivar_usuario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivar_usuario(p_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE

  v_empresa_id uuid;
  v_estado text;
  v_archivado_en timestamptz;

  v_max int;
  v_active int;

BEGIN

  SELECT
    empresa_id,
    estado,
    archivado_en

  INTO
    v_empresa_id,
    v_estado,
    v_archivado_en

  FROM public.profiles

  WHERE id = p_profile_id

  FOR UPDATE;


  IF v_empresa_id IS NULL THEN

    RAISE EXCEPTION
      'Usuario no encontrado';

  END IF;


  IF NOT public.is_empresa_admin(auth.uid(), v_empresa_id) THEN

    RAISE EXCEPTION
      'Acceso denegado: requiere permisos de administrador';

  END IF;


  -- ----------------------------------------------------------
  -- Idempotencia
  -- ----------------------------------------------------------

  IF v_estado = 'activo'
     AND v_archivado_en IS NULL THEN

    RETURN jsonb_build_object(

      'reactivado',
      true,

      'already_active',
      true,

      'profile_id',
      p_profile_id

    );

  END IF;


  -- ----------------------------------------------------------
  -- Límite de usuarios del plan
  -- ----------------------------------------------------------

  SELECT COALESCE(max_usuarios, 999)

  INTO v_max

  FROM public.subscriptions

  WHERE empresa_id = v_empresa_id;


  -- ----------------------------------------------------------
  -- Contar únicamente usuarios REALMENTE activos
  -- ----------------------------------------------------------

  SELECT COUNT(*)

  INTO v_active

  FROM public.profiles

  WHERE empresa_id = v_empresa_id

    AND estado = 'activo'

    AND archivado_en IS NULL;


  IF v_active >= COALESCE(v_max, 999) THEN

    RAISE EXCEPTION
      'Tu plan no tiene cupo disponible (% / %). Archiva otro usuario o actualiza tu plan.',
      v_active,
      COALESCE(v_max, 999);

  END IF;


  -- ----------------------------------------------------------
  -- Reactivar
  -- ----------------------------------------------------------

  UPDATE public.profiles

  SET

    estado = 'activo',

    archivado_en = NULL,

    archivado_por = NULL,

    archivado_motivo = NULL

  WHERE id = p_profile_id;


  RETURN jsonb_build_object(

    'reactivado',
    true,

    'already_active',
    false,

    'profile_id',
    p_profile_id,

    'cupo_usado',
    v_active + 1,

    'cupo_max',
    COALESCE(v_max, 999)

  );

END;
$$;


--
-- Name: reasignar_entregas_bulk(uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reasignar_entregas_bulk(p_entrega_ids uuid[], p_target_vendedor_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid := get_my_empresa_id();
  v_target_almacen uuid;
  v_target_estado text;
  v_target_empresa uuid;
  v_entrega RECORD;
  v_linea RECORD;
  v_origen_almacen uuid;
  v_reasignadas int := 0;
  v_con_movimiento int := 0;
  v_omitidas int := 0;
  v_today date := CURRENT_DATE;
BEGIN
  IF p_entrega_ids IS NULL OR array_length(p_entrega_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No hay entregas seleccionadas';
  END IF;
  IF p_target_vendedor_id IS NULL THEN
    RAISE EXCEPTION 'Debes seleccionar un vendedor destino';
  END IF;

  SELECT almacen_id, estado, empresa_id
  INTO v_target_almacen, v_target_estado, v_target_empresa
  FROM profiles WHERE id = p_target_vendedor_id;

  IF v_target_empresa IS NULL THEN RAISE EXCEPTION 'Vendedor destino no encontrado'; END IF;
  IF v_target_empresa <> v_empresa AND NOT is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'El vendedor destino no pertenece a tu empresa';
  END IF;
  IF v_target_estado <> 'activo' THEN
    RAISE EXCEPTION 'El vendedor destino no está activo';
  END IF;

  FOR v_entrega IN
    SELECT e.*, p.almacen_id AS actual_almacen_id
    FROM entregas e
    LEFT JOIN profiles p ON p.id = COALESCE(e.vendedor_ruta_id, e.vendedor_id)
    WHERE e.id = ANY(p_entrega_ids)
      AND (e.empresa_id = v_empresa OR is_super_admin(auth.uid()))
    FOR UPDATE OF e
  LOOP
    -- Bloqueadas: hecho/cancelado
    IF v_entrega.status::text IN ('hecho','cancelado') THEN
      v_omitidas := v_omitidas + 1;
      CONTINUE;
    END IF;

    -- ¿Mismo vendedor? saltar
    IF COALESCE(v_entrega.vendedor_ruta_id, v_entrega.vendedor_id) = p_target_vendedor_id THEN
      v_omitidas := v_omitidas + 1;
      CONTINUE;
    END IF;

    -- Si está cargado/en_ruta y hay almacén actual: mover stock
    IF v_entrega.status::text IN ('cargado','en_ruta') THEN
      IF v_entrega.actual_almacen_id IS NULL THEN
        RAISE EXCEPTION 'La entrega % está cargada pero el vendedor actual no tiene almacén asignado', COALESCE(v_entrega.folio, v_entrega.id::text);
      END IF;
      IF v_target_almacen IS NULL THEN
        RAISE EXCEPTION 'El vendedor destino no tiene almacén asignado, no se puede mover el stock cargado de la entrega %', COALESCE(v_entrega.folio, v_entrega.id::text);
      END IF;

      FOR v_linea IN
        SELECT producto_id, cantidad_entregada
        FROM entrega_lineas
        WHERE entrega_id = v_entrega.id AND hecho = true AND cantidad_entregada > 0
      LOOP
        PERFORM _mover_stock_entre_almacenes(
          v_empresa, v_linea.producto_id, v_linea.cantidad_entregada,
          v_entrega.actual_almacen_id, v_target_almacen,
          'entrega', v_entrega.id, p_user_id, v_today,
          concat('Reasignación entrega ', COALESCE(v_entrega.folio, v_entrega.id::text))
        );
      END LOOP;
      v_con_movimiento := v_con_movimiento + 1;
    END IF;

    UPDATE entregas
    SET vendedor_ruta_id = p_target_vendedor_id,
        fecha_asignacion = COALESCE(fecha_asignacion, now())
    WHERE id = v_entrega.id;

    v_reasignadas := v_reasignadas + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'reasignadas', v_reasignadas,
    'con_movimiento_stock', v_con_movimiento,
    'omitidas', v_omitidas
  );
END;
$$;


--
-- Name: reasignar_pendientes_usuario(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reasignar_pendientes_usuario(p_profile_id uuid, p_target_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE

  v_empresa_id uuid;

  v_target_empresa uuid;
  v_target_estado text;
  v_target_archivado_en timestamptz;

  v_entregas int := 0;
  v_ventas int := 0;

BEGIN

  SELECT empresa_id
  INTO v_empresa_id
  FROM public.profiles
  WHERE id = p_profile_id;


  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'Usuario origen no encontrado';
  END IF;


  SELECT
    empresa_id,
    estado,
    archivado_en
  INTO
    v_target_empresa,
    v_target_estado,
    v_target_archivado_en
  FROM public.profiles
  WHERE id = p_target_profile_id;


  IF v_target_empresa IS NULL THEN
    RAISE EXCEPTION 'Usuario destino no encontrado';
  END IF;


  IF v_target_empresa <> v_empresa_id THEN
    RAISE EXCEPTION
      'El usuario destino debe ser de la misma empresa';
  END IF;


  IF v_target_estado <> 'activo'
     OR v_target_archivado_en IS NOT NULL THEN

    RAISE EXCEPTION
      'El usuario destino debe estar activo';

  END IF;


  IF p_profile_id = p_target_profile_id THEN
    RAISE EXCEPTION
      'No se puede reasignar al mismo usuario';
  END IF;


  IF NOT public.is_empresa_admin(auth.uid(), v_empresa_id) THEN
    RAISE EXCEPTION
      'Acceso denegado: requiere permisos de administrador';
  END IF;


  -- ----------------------------------------------------------
  -- Reasignar entregas pendientes como vendedor de ruta
  -- ----------------------------------------------------------

  WITH upd AS (

    UPDATE public.entregas

    SET vendedor_ruta_id = p_target_profile_id

    WHERE empresa_id = v_empresa_id

      AND status NOT IN ('hecho', 'cancelado')

      AND vendedor_ruta_id = p_profile_id

    RETURNING 1

  )

  SELECT COUNT(*)
  INTO v_entregas
  FROM upd;


  -- ----------------------------------------------------------
  -- Reasignar vendedor general en entregas
  -- ----------------------------------------------------------

  UPDATE public.entregas

  SET vendedor_id = p_target_profile_id

  WHERE empresa_id = v_empresa_id

    AND status NOT IN ('hecho', 'cancelado')

    AND vendedor_id = p_profile_id;


  -- ----------------------------------------------------------
  -- Reasignar ventas/pedidos todavía pendientes
  -- ----------------------------------------------------------

  WITH upd2 AS (

    UPDATE public.ventas

    SET vendedor_id = p_target_profile_id

    WHERE empresa_id = v_empresa_id

      AND vendedor_id = p_profile_id

      AND status IN ('borrador', 'confirmado')

      AND tipo IN ('pedido', 'venta_directa')

      AND COALESCE(saldo_pendiente, 0) > 0

      AND COALESCE(entrega_inmediata, false) = false

    RETURNING 1

  )

  SELECT COUNT(*)
  INTO v_ventas
  FROM upd2;


  RETURN jsonb_build_object(

    'entregas_reasignadas',
    v_entregas,

    'ventas_reasignadas',
    v_ventas

  );

END;
$$;


--
-- Name: recalc_producto_costo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_producto_costo(p_producto_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_calculo calculo_costo;
  v_new_cost numeric;
  v_empresa_id uuid;
  v_proveedor_id uuid;
BEGIN
  SELECT calculo_costo, empresa_id
  INTO v_calculo, v_empresa_id
  FROM public.productos
  WHERE id = p_producto_id;

  IF v_calculo IS NULL OR v_calculo IN ('manual', 'estandar') THEN
    RETURN;
  END IF;

  IF v_calculo = 'ultimo' THEN
    SELECT
      cl.precio_unitario
      * public.fn_factor_neto_compra(c.id)
      / NULLIF(COALESCE(cl.factor_conversion, 1), 0)
    INTO v_new_cost
    FROM public.compra_lineas cl
    JOIN public.compras c ON c.id = cl.compra_id
    WHERE cl.producto_id = p_producto_id
      AND c.empresa_id = v_empresa_id
      AND c.status IN ('recibida', 'pagada')
    ORDER BY c.fecha DESC, c.created_at DESC
    LIMIT 1;

  ELSIF v_calculo = 'ultimo_compra' THEN
    SELECT
      cl.precio_unitario
      * public.fn_factor_neto_compra(c.id)
      / NULLIF(COALESCE(cl.factor_conversion, 1), 0)
    INTO v_new_cost
    FROM public.compra_lineas cl
    JOIN public.compras c ON c.id = cl.compra_id
    WHERE cl.producto_id = p_producto_id
      AND c.empresa_id = v_empresa_id
      AND c.status IN ('recibida', 'pagada')
      AND c.condicion_pago = 'contado'
    ORDER BY c.fecha DESC, c.created_at DESC
    LIMIT 1;

  ELSIF v_calculo = 'ultimo_proveedor' THEN
    SELECT pp.proveedor_id
    INTO v_proveedor_id
    FROM public.producto_proveedores pp
    WHERE pp.producto_id = p_producto_id
      AND pp.es_principal = true
    LIMIT 1;

    IF v_proveedor_id IS NOT NULL THEN
      SELECT
        cl.precio_unitario
        * public.fn_factor_neto_compra(c.id)
        / NULLIF(COALESCE(cl.factor_conversion, 1), 0)
      INTO v_new_cost
      FROM public.compra_lineas cl
      JOIN public.compras c ON c.id = cl.compra_id
      WHERE cl.producto_id = p_producto_id
        AND c.empresa_id = v_empresa_id
        AND c.proveedor_id = v_proveedor_id
        AND c.status IN ('recibida', 'pagada')
      ORDER BY c.fecha DESC, c.created_at DESC
      LIMIT 1;
    END IF;

  ELSIF v_calculo = 'promedio' THEN
    SELECT
      SUM(
        cl.precio_unitario
        * cl.cantidad
        * public.fn_factor_neto_compra(c.id)
      )
      / NULLIF(
          SUM(cl.cantidad * COALESCE(cl.factor_conversion, 1)),
          0
        )
    INTO v_new_cost
    FROM public.compra_lineas cl
    JOIN public.compras c ON c.id = cl.compra_id
    WHERE cl.producto_id = p_producto_id
      AND c.empresa_id = v_empresa_id
      AND c.status IN ('recibida', 'pagada');
  END IF;

  IF v_new_cost IS NOT NULL THEN
    UPDATE public.productos
    SET costo = ROUND(v_new_cost, 4)
    WHERE id = p_producto_id;
  END IF;
END;
$$;


--
-- Name: recalc_producto_stock_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_producto_stock_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_producto_id uuid;
  v_total numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_producto_id := OLD.producto_id;
  ELSE
    v_producto_id := NEW.producto_id;
  END IF;

  SELECT COALESCE(SUM(cantidad), 0)
  INTO v_total
  FROM stock_almacen
  WHERE producto_id = v_producto_id;

  UPDATE productos SET cantidad = v_total WHERE id = v_producto_id;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: recalc_saldos_on_cobro_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_saldos_on_cobro_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cobro_id uuid;
  v_venta_id uuid;
  v_total numeric;
  v_pagado numeric;
BEGIN
  v_cobro_id := COALESCE(NEW.id, OLD.id);
  FOR v_venta_id IN
    SELECT DISTINCT ca.venta_id FROM public.cobro_aplicaciones ca
    WHERE ca.cobro_id = v_cobro_id AND ca.venta_id IS NOT NULL
  LOOP
    SELECT CASE WHEN cerrado_at IS NOT NULL THEN COALESCE(total_efectivo, total) ELSE total END
      INTO v_total FROM public.ventas WHERE id = v_venta_id;
    SELECT COALESCE(SUM(ca2.monto_aplicado), 0) INTO v_pagado
    FROM public.cobro_aplicaciones ca2 JOIN public.cobros c ON c.id = ca2.cobro_id
    WHERE ca2.venta_id = v_venta_id AND c.status <> 'cancelado';
    UPDATE public.ventas SET saldo_pendiente = COALESCE(v_total, 0) - v_pagado WHERE id = v_venta_id;
  END LOOP;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: recalc_venta_saldo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_venta_saldo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta_id uuid;
  v_total numeric;
  v_pagado numeric;
BEGIN
  v_venta_id := COALESCE(NEW.venta_id, OLD.venta_id);
  SELECT CASE WHEN cerrado_at IS NOT NULL THEN COALESCE(total_efectivo, total) ELSE total END
    INTO v_total FROM public.ventas WHERE id = v_venta_id;
  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_pagado
  FROM public.cobro_aplicaciones ca JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = v_venta_id AND c.status <> 'cancelado';
  UPDATE public.ventas SET saldo_pendiente = COALESCE(v_total, 0) - v_pagado WHERE id = v_venta_id;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: recalc_venta_saldo_on_total_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_venta_saldo_on_total_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pagado numeric;
BEGIN
  IF NEW.cerrado_at IS NOT NULL AND NEW.total IS DISTINCT FROM OLD.total THEN
    NEW.total_efectivo := public.fn_total_efectivo_cerrado(NEW.id, NEW.total);
  END IF;

  SELECT COALESCE(SUM(ca.monto_aplicado), 0) INTO v_pagado
  FROM public.cobro_aplicaciones ca JOIN public.cobros c ON c.id = ca.cobro_id
  WHERE ca.venta_id = NEW.id AND c.status <> 'cancelado';
  NEW.saldo_pendiente := GREATEST(0, public.fn_venta_cobrable(NEW) - v_pagado);
  RETURN NEW;
END;
$$;


--
-- Name: recalc_venta_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_venta_total() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venta_id uuid;
  v_subtotal numeric;
  v_iva numeric;
  v_ieps numeric;
  v_total numeric;
BEGIN
  v_venta_id := COALESCE(NEW.venta_id, OLD.venta_id);
  IF v_venta_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT
    COALESCE(SUM(subtotal), 0),
    COALESCE(SUM(iva_monto), 0),
    COALESCE(SUM(ieps_monto), 0),
    COALESCE(SUM(total), 0)
  INTO v_subtotal, v_iva, v_ieps, v_total
  FROM public.venta_lineas
  WHERE venta_id = v_venta_id;

  UPDATE public.ventas
  SET
    subtotal = v_subtotal,
    iva_total = v_iva,
    ieps_total = v_ieps,
    total = v_total
  WHERE id = v_venta_id
    AND (
      total IS DISTINCT FROM v_total
      OR subtotal IS DISTINCT FROM v_subtotal
      OR iva_total IS DISTINCT FROM v_iva
      OR ieps_total IS DISTINCT FROM v_ieps
    );

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalc_venta_totales(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_venta_totales(p_venta_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_subtotal numeric := 0;
  v_iva numeric := 0;
  v_ieps numeric := 0;
  v_total_lineas numeric := 0;
  v_desc_extra numeric := 0;
  v_desc_extra_tipo text;
  v_total_final numeric := 0;
  v_es_saldo_inicial boolean;
BEGIN
  SELECT COALESCE(es_saldo_inicial,false),
         COALESCE(descuento_extra,0),
         COALESCE(descuento_extra_tipo,'monto')
    INTO v_es_saldo_inicial, v_desc_extra, v_desc_extra_tipo
  FROM public.ventas WHERE id = p_venta_id;

  -- Saldos iniciales: NO se recalculan desde líneas (no tienen)
  IF v_es_saldo_inicial THEN RETURN; END IF;

  SELECT COALESCE(SUM(subtotal),0),
         COALESCE(SUM(iva_monto),0),
         COALESCE(SUM(ieps_monto),0),
         COALESCE(SUM(total),0)
    INTO v_subtotal, v_iva, v_ieps, v_total_lineas
  FROM public.venta_lineas WHERE venta_id = p_venta_id;

  IF v_desc_extra_tipo = 'porcentaje' THEN
    v_total_final := ROUND((v_total_lineas * (1 - v_desc_extra/100.0))::numeric, 2);
  ELSE
    v_total_final := ROUND((v_total_lineas - v_desc_extra)::numeric, 2);
  END IF;

  UPDATE public.ventas
     SET subtotal = ROUND(v_subtotal::numeric,2),
         iva_total = ROUND(v_iva::numeric,2),
         ieps_total = ROUND(v_ieps::numeric,2),
         total = v_total_final
   WHERE id = p_venta_id;
END;
$$;


--
-- Name: recalc_ventas_on_cobro_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_ventas_on_cobro_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  UPDATE public.ventas v
  SET saldo_pendiente = GREATEST(0, COALESCE(v.total,0) - COALESCE((
    SELECT SUM(ca2.monto_aplicado)
    FROM public.cobro_aplicaciones ca2
    JOIN public.cobros c2 ON c2.id = ca2.cobro_id
    WHERE ca2.venta_id = v.id AND c2.status <> 'cancelado'
  ), 0))
  WHERE v.id IN (
    SELECT venta_id FROM public.cobro_aplicaciones
    WHERE cobro_id = COALESCE(NEW.id, OLD.id)
  );

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: recalcular_facturacion_cfdi(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_facturacion_cfdi(p_cfdi_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'No autorizado' USING ERRCODE = '42501';
  END IF;

  UPDATE venta_lineas vl SET
    facturado = x.qty_vigente > 0 AND x.qty_vigente >= COALESCE(vl.cantidad, 0) - 0.000001,
    factura_cfdi_id = x.ultimo_cfdi,
    facturado_global = COALESCE(x.global_vigente, false)
  FROM (
    SELECT l.id,
           COALESCE(sum(cl.cantidad) FILTER (WHERE public.cfdi_status_vigente(c.status)), 0) AS qty_vigente,
           (array_agg(c.id ORDER BY c.created_at DESC) FILTER (WHERE public.cfdi_status_ocupa(c.status)))[1] AS ultimo_cfdi,
           bool_or(c.es_global AND public.cfdi_status_vigente(c.status)) AS global_vigente
    FROM venta_lineas l
    JOIN cfdi_lineas cl ON cl.venta_linea_id = l.id
    JOIN cfdis c ON c.id = cl.cfdi_id
    WHERE l.id IN (SELECT venta_linea_id FROM cfdi_lineas WHERE cfdi_id = p_cfdi_id AND venta_linea_id IS NOT NULL)
    GROUP BY l.id
  ) x
  WHERE vl.id = x.id;
END;
$$;


--
-- Name: recalcular_nivel_partner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_nivel_partner(_partner_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_partner public.partners%ROWTYPE;
  v_level public.partner_niveles%ROWTYPE;
  v_count integer;
  v_protected_pct numeric;
BEGIN
  SELECT *
  INTO v_partner
  FROM public.partners
  WHERE id = _partner_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  v_count := public.get_partner_active_empresas(_partner_id);

  SELECT *
  INTO v_level
  FROM public.partner_niveles
  WHERE empresas_min <= v_count
    AND (
      empresas_max IS NULL
      OR empresas_max >= v_count
    )
  ORDER BY orden DESC
  LIMIT 1;

  v_protected_pct := CASE
    WHEN v_partner.peor_nivel_fecha > now() - interval '60 days'
      THEN v_partner.peor_nivel_pct_60d
    ELSE NULL
  END;

  IF v_partner.nivel_base_pct_snapshot IS NOT NULL
     AND v_level.comision_pct < v_partner.nivel_base_pct_snapshot THEN

    v_protected_pct := GREATEST(
      v_partner.nivel_base_pct_snapshot,
      COALESCE(v_protected_pct, 0)
    );

    UPDATE public.partners
    SET
      peor_nivel_pct_60d = v_protected_pct,
      peor_nivel_fecha = now()
    WHERE id = _partner_id;

  ELSIF v_protected_pct IS NOT NULL
        AND v_level.comision_pct >= v_protected_pct THEN

    UPDATE public.partners
    SET
      peor_nivel_pct_60d = NULL,
      peor_nivel_fecha = NULL
    WHERE id = _partner_id;
  END IF;

  UPDATE public.partners
  SET
    nivel_base_id_snapshot = v_level.id,
    nivel_base_pct_snapshot = v_level.comision_pct,
    nivel_revisado_at = now()
  WHERE id = _partner_id;

  RETURN GREATEST(
    v_level.comision_pct,
    COALESCE(v_protected_pct, 0)
  );
END;
$$;


--
-- Name: rechazar_solicitud_partner(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rechazar_solicitud_partner(_solicitud_id uuid, _motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.super_admins WHERE user_id = auth.uid()) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  UPDATE public.partner_solicitudes
  SET status = 'rejected', notas_admin = _motivo, processed_at = now(), processed_by = auth.uid()
  WHERE id = _solicitud_id AND status = 'pending';
END;
$$;


--
-- Name: rechazar_solicitud_traspaso(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rechazar_solicitud_traspaso(p_solicitud_id uuid, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_sol public.solicitudes_traspaso%ROWTYPE;
BEGIN
  SELECT * INTO v_sol FROM public.solicitudes_traspaso WHERE id = p_solicitud_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada'; END IF;
  IF NOT (v_sol.empresa_id = public.get_my_empresa_id() OR public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;
  IF v_sol.status NOT IN ('solicitada','aprobada') THEN RAISE EXCEPTION 'Esta solicitud no se puede rechazar'; END IF;
  UPDATE public.solicitudes_traspaso
     SET status = 'rechazada', rechazado_por = auth.uid(), rechazado_at = now(), motivo_rechazo = p_motivo
   WHERE id = p_solicitud_id;
  PERFORM public.fn_log_solicitud_traspaso(p_solicitud_id, v_sol.empresa_id, 'rechazada', jsonb_build_object('motivo', p_motivo));
END; $$;


--
-- Name: recibir_compra_linea_parcial(uuid, numeric, uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recibir_compra_linea_parcial(p_linea_id uuid, p_piezas numeric, p_almacen_id uuid, p_empresa_id uuid, p_compra_id uuid, p_folio text, p_user_id uuid, p_lote_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_producto_id uuid; v_cantidad numeric; v_factor numeric; v_recibido numeric;
  v_total_piezas numeric; v_pendiente numeric; v_a_recibir numeric;
  v_sa_id uuid; v_sa_qty numeric; v_today date := current_date;
  v_pendiente_compra numeric; v_sl_id uuid; v_sl_qty numeric;
BEGIN
  SELECT producto_id, cantidad, COALESCE(NULLIF(factor_conversion,0), 1), cantidad_recibida
    INTO v_producto_id, v_cantidad, v_factor, v_recibido
  FROM compra_lineas WHERE id = p_linea_id FOR UPDATE;

  IF v_producto_id IS NULL THEN RAISE EXCEPTION 'Línea de compra no encontrada'; END IF;

  v_total_piezas := v_cantidad * v_factor;
  v_pendiente := GREATEST(0, v_total_piezas - v_recibido);
  IF v_pendiente <= 0 THEN RETURN; END IF;

  v_a_recibir := LEAST(COALESCE(p_piezas, v_pendiente), v_pendiente);
  IF v_a_recibir <= 0 THEN RETURN; END IF;

  IF p_lote_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM lotes WHERE id = p_lote_id AND producto_id = v_producto_id) THEN
      RAISE EXCEPTION 'El lote no corresponde al producto de la línea';
    END IF;
  END IF;

  IF p_almacen_id IS NOT NULL THEN
    SELECT id, cantidad INTO v_sa_id, v_sa_qty
    FROM stock_almacen WHERE almacen_id = p_almacen_id AND producto_id = v_producto_id FOR UPDATE;
    IF v_sa_id IS NOT NULL THEN
      UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty,0) + v_a_recibir, updated_at = now() WHERE id = v_sa_id;
    ELSE
      INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
      VALUES (p_empresa_id, p_almacen_id, v_producto_id, v_a_recibir);
    END IF;

    IF p_lote_id IS NOT NULL THEN
      SELECT id, cantidad INTO v_sl_id, v_sl_qty
      FROM stock_lotes WHERE almacen_id = p_almacen_id AND lote_id = p_lote_id FOR UPDATE;
      IF v_sl_id IS NOT NULL THEN
        UPDATE stock_lotes SET cantidad = COALESCE(v_sl_qty,0) + v_a_recibir, updated_at = now() WHERE id = v_sl_id;
      ELSE
        INSERT INTO stock_lotes (empresa_id, almacen_id, producto_id, lote_id, cantidad)
        VALUES (p_empresa_id, p_almacen_id, v_producto_id, p_lote_id, v_a_recibir);
      END IF;
    END IF;
  END IF;

  INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas, lote_id)
  VALUES (p_empresa_id, 'entrada', v_producto_id, v_a_recibir, p_almacen_id, 'compra', p_compra_id, p_user_id, v_today,
          concat('Compra ', COALESCE(p_folio, p_compra_id::text), ' recepción parcial'), p_lote_id);

  UPDATE compra_lineas SET cantidad_recibida = v_recibido + v_a_recibir WHERE id = p_linea_id;

  SELECT COALESCE(SUM(GREATEST(0, cantidad * COALESCE(NULLIF(factor_conversion,0),1) - cantidad_recibida)), 0)
    INTO v_pendiente_compra
  FROM compra_lineas WHERE compra_id = p_compra_id;

  IF v_pendiente_compra = 0 THEN
    UPDATE compras SET status = 'recibida'
     WHERE id = p_compra_id AND status NOT IN ('recibida','pagada','cancelada');
  END IF;
END;
$$;


--
-- Name: recibir_linea_compra(uuid, numeric, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recibir_linea_compra(p_producto_id uuid, p_piezas numeric, p_almacen_id uuid, p_empresa_id uuid, p_compra_id uuid, p_folio text, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sa_id uuid;
  v_sa_qty numeric;
  v_today date := current_date;
BEGIN
  -- Upsert stock_almacen atomically
  IF p_almacen_id IS NOT NULL THEN
    SELECT id, cantidad INTO v_sa_id, v_sa_qty
    FROM stock_almacen WHERE almacen_id = p_almacen_id AND producto_id = p_producto_id FOR UPDATE;

    IF v_sa_id IS NOT NULL THEN
      UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty, 0) + p_piezas, updated_at = now() WHERE id = v_sa_id;
    ELSE
      INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad) VALUES (p_empresa_id, p_almacen_id, p_producto_id, p_piezas);
    END IF;
  END IF;

  -- productos.cantidad is now auto-recalculated by trigger

  INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, notas)
  VALUES (p_empresa_id, 'entrada', p_producto_id, p_piezas, p_almacen_id, 'compra', p_compra_id, p_user_id, v_today, concat('Compra ', COALESCE(p_folio, p_compra_id::text), ' recibida'));
END;
$$;


--
-- Name: reconciliar_saldos_cliente(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconciliar_saldos_cliente(p_cliente_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n int;
BEGIN
  WITH agg AS (
    SELECT v.id,
      GREATEST(0, COALESCE(v.total,0) - COALESCE(SUM(ca.monto_aplicado) FILTER (WHERE c.status <> 'cancelado'), 0)) AS nuevo
    FROM public.ventas v
    LEFT JOIN public.cobro_aplicaciones ca ON ca.venta_id = v.id
    LEFT JOIN public.cobros c ON c.id = ca.cobro_id
    WHERE v.cliente_id = p_cliente_id AND v.status <> 'cancelado'
    GROUP BY v.id
  )
  UPDATE public.ventas v SET saldo_pendiente = a.nuevo
  FROM agg a
  WHERE a.id = v.id AND v.saldo_pendiente IS DISTINCT FROM a.nuevo;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: reconciliar_saldos_empresa(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconciliar_saldos_empresa(p_empresa_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n int;
BEGIN
  WITH agg AS (
    SELECT v.id,
      GREATEST(0, COALESCE(v.total,0) - COALESCE(SUM(ca.monto_aplicado) FILTER (WHERE c.status <> 'cancelado'), 0)) AS nuevo
    FROM public.ventas v
    LEFT JOIN public.cobro_aplicaciones ca ON ca.venta_id = v.id
    LEFT JOIN public.cobros c ON c.id = ca.cobro_id
    WHERE v.empresa_id = p_empresa_id AND v.status <> 'cancelado'
    GROUP BY v.id
  )
  UPDATE public.ventas v SET saldo_pendiente = a.nuevo
  FROM agg a
  WHERE a.id = v.id AND v.saldo_pendiente IS DISTINCT FROM a.nuevo;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: registrar_cobro(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_cobro(p_cobro jsonb, p_aplicaciones jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa   uuid := COALESCE(get_my_empresa_id(), NULLIF(p_cobro->>'empresa_id','')::uuid);
  v_cobro_id  uuid := COALESCE(NULLIF(p_cobro->>'id','')::uuid, gen_random_uuid());
  v_cliente   uuid := NULLIF(p_cobro->>'cliente_id','')::uuid;
  v_user      uuid := COALESCE(NULLIF(p_cobro->>'user_id','')::uuid, auth.uid());
  v_ap        jsonb;
  v_venta     uuid;
  v_monto     numeric;
  v_ap_id     uuid;
  v_aplicadas int := 0;
BEGIN
  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'registrar_cobro: no se pudo determinar la empresa';
  END IF;
  IF v_cliente IS NULL THEN
    RAISE EXCEPTION 'registrar_cobro: cliente_id es obligatorio';
  END IF;

  -- 1) Cobro — idempotente por id. Si ya existe (reenvío/resync), no duplica.
  INSERT INTO public.cobros (
    id, empresa_id, cliente_id, user_id, monto, metodo_pago,
    referencia, notas, fecha, status, created_at
  ) VALUES (
    v_cobro_id, v_empresa, v_cliente, v_user,
    COALESCE(NULLIF(p_cobro->>'monto','')::numeric, 0),
    COALESCE(NULLIF(p_cobro->>'metodo_pago',''), 'efectivo'),
    NULLIF(p_cobro->>'referencia',''),
    NULLIF(p_cobro->>'notas',''),
    COALESCE(NULLIF(p_cobro->>'fecha','')::date, CURRENT_DATE),
    COALESCE(NULLIF(p_cobro->>'status',''), 'activo'),
    COALESCE(NULLIF(p_cobro->>'created_at','')::timestamptz, now())
  )
  ON CONFLICT (id) DO NOTHING;

  -- 2) Aplicaciones — atómicas con el cobro. Id estable por (cobro,venta) →
  --    reenviar deduplica; una FK a venta inexistente aborta TODA la función
  --    (rollback del cobro también) y se reintenta como una unidad: nunca
  --    queda un cobro sin su aplicación.
  FOR v_ap IN SELECT * FROM jsonb_array_elements(COALESCE(p_aplicaciones, '[]'::jsonb))
  LOOP
    v_venta := NULLIF(v_ap->>'venta_id','')::uuid;
    v_monto := COALESCE(NULLIF(v_ap->>'monto_aplicado','')::numeric, 0);
    IF v_venta IS NULL OR v_monto <= 0 THEN
      CONTINUE;
    END IF;

    v_ap_id := COALESCE(
      NULLIF(v_ap->>'id','')::uuid,
      (md5(v_cobro_id::text || '|' || v_venta::text))::uuid
    );

    INSERT INTO public.cobro_aplicaciones (id, cobro_id, venta_id, monto_aplicado, created_at)
    VALUES (
      v_ap_id, v_cobro_id, v_venta, v_monto,
      COALESCE(NULLIF(v_ap->>'created_at','')::timestamptz, now())
    )
    ON CONFLICT (id) DO NOTHING;

    v_aplicadas := v_aplicadas + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'cobro_id',   v_cobro_id,
    'aplicadas',  v_aplicadas
  );
END;
$$;


--
-- Name: registrar_merma(uuid, uuid, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_merma(_almacen_origen_id uuid, _ruta_id uuid, _motivo_id uuid, _observaciones text, _lineas jsonb, _devolucion_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _empresa_id uuid := public.get_my_empresa_id();
  _user_id uuid := auth.uid();
  _almacen_mermas uuid; _merma_id uuid; _folio text; _next int;
  _total_costo numeric := 0; _total_venta numeric := 0;
  _line jsonb; _producto_id uuid; _cantidad numeric; _costo numeric; _precio numeric;
  _linea_id uuid; _maneja boolean; _asig jsonb; _lote_id uuid; _qty numeric;
  _pending numeric; _disp numeric; _l RECORD; _take numeric;
BEGIN
  IF _empresa_id IS NULL THEN RAISE EXCEPTION 'No hay empresa activa'; END IF;
  _almacen_mermas := public.ensure_almacen_mermas(_empresa_id);
  SELECT COALESCE(MAX(NULLIF(regexp_replace(folio,'[^0-9]','','g'),'')::int),0)+1
    INTO _next FROM public.mermas WHERE empresa_id = _empresa_id;
  _folio := 'MER-' || public.folio_lpad(_next::text, 4, '0');

  INSERT INTO public.mermas(empresa_id, folio, almacen_origen_id, ruta_id, motivo_id, observaciones, devolucion_id, creado_por)
  VALUES (_empresa_id, _folio, _almacen_origen_id, _ruta_id, _motivo_id, _observaciones, _devolucion_id, _user_id)
  RETURNING id INTO _merma_id;

  FOR _line IN SELECT * FROM jsonb_array_elements(_lineas) LOOP
    _producto_id := (_line->>'producto_id')::uuid;
    _cantidad := (_line->>'cantidad')::numeric;
    _costo := COALESCE((_line->>'costo_unitario')::numeric, 0);
    _precio := COALESCE((_line->>'precio_venta_unitario')::numeric, 0);

    INSERT INTO public.merma_lineas(merma_id, empresa_id, producto_id, cantidad, costo_unitario, precio_venta_unitario, subtotal_costo, subtotal_venta)
    VALUES (_merma_id, _empresa_id, _producto_id, _cantidad, _costo, _precio, _costo*_cantidad, _precio*_cantidad)
    RETURNING id INTO _linea_id;

    _total_costo := _total_costo + _costo*_cantidad;
    _total_venta := _total_venta + _precio*_cantidad;

    UPDATE public.stock_almacen SET cantidad = cantidad - _cantidad, updated_at = now()
     WHERE empresa_id = _empresa_id AND almacen_id = _almacen_origen_id AND producto_id = _producto_id;
    IF NOT FOUND THEN
      INSERT INTO public.stock_almacen(empresa_id, almacen_id, producto_id, cantidad)
      VALUES (_empresa_id, _almacen_origen_id, _producto_id, -_cantidad);
    END IF;

    INSERT INTO public.stock_almacen(empresa_id, almacen_id, producto_id, cantidad)
    VALUES (_empresa_id, _almacen_mermas, _producto_id, _cantidad)
    ON CONFLICT (almacen_id, producto_id) DO UPDATE
       SET cantidad = public.stock_almacen.cantidad + EXCLUDED.cantidad, updated_at = now();

    INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, notas, user_id, fecha)
    VALUES (_empresa_id, 'salida', _producto_id, _cantidad, _almacen_origen_id, 'merma', _merma_id, _folio, _user_id, CURRENT_DATE);

    INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, notas, user_id, fecha)
    VALUES (_empresa_id, 'entrada', _producto_id, _cantidad, _almacen_mermas, 'merma', _merma_id, _folio, _user_id, CURRENT_DATE);

    SELECT COALESCE(maneja_lote, false) INTO _maneja FROM public.productos WHERE id = _producto_id;
    IF _maneja THEN
      IF jsonb_typeof(_line->'lotes') = 'array' AND jsonb_array_length(_line->'lotes') > 0 THEN
        FOR _asig IN SELECT * FROM jsonb_array_elements(_line->'lotes') LOOP
          _lote_id := (_asig->>'lote_id')::uuid;
          _qty := COALESCE((_asig->>'cantidad')::numeric, 0);
          IF _lote_id IS NULL OR _qty <= 0 THEN CONTINUE; END IF;

          SELECT sl.cantidad INTO _disp FROM public.stock_lotes sl
           WHERE sl.almacen_id = _almacen_origen_id AND sl.lote_id = _lote_id AND sl.producto_id = _producto_id
           FOR UPDATE;
          IF _disp IS NULL OR _disp < _qty THEN
            RAISE EXCEPTION 'El lote seleccionado no tiene existencia suficiente (disponible %, solicitado %)', COALESCE(_disp,0), _qty;
          END IF;

          INSERT INTO public.merma_linea_lotes(empresa_id, merma_id, merma_linea_id, producto_id, lote_id, cantidad)
          VALUES (_empresa_id, _merma_id, _linea_id, _producto_id, _lote_id, _qty);

          -- El stock por lote lo aplica el trigger trg_sync_stock_lote a partir de estos movimientos
          INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
          VALUES (_empresa_id, 'salida', _producto_id, _qty, _almacen_origen_id, _lote_id, 'merma_lote', _merma_id, _folio, _user_id, CURRENT_DATE);
          INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
          VALUES (_empresa_id, 'entrada', _producto_id, _qty, _almacen_mermas, _lote_id, 'merma_lote_entrada', _merma_id, _folio, _user_id, CURRENT_DATE);
        END LOOP;
      ELSE
        _pending := _cantidad;
        FOR _l IN
          SELECT sl.lote_id, sl.cantidad AS existencia
          FROM public.stock_lotes sl JOIN public.lotes lo ON lo.id = sl.lote_id
          WHERE sl.almacen_id = _almacen_origen_id AND sl.producto_id = _producto_id AND sl.cantidad > 0
          ORDER BY lo.fecha_caducidad ASC NULLS LAST, lo.created_at ASC
          FOR UPDATE OF sl
        LOOP
          EXIT WHEN _pending <= 0;
          _take := LEAST(_l.existencia, _pending);
          INSERT INTO public.merma_linea_lotes(empresa_id, merma_id, merma_linea_id, producto_id, lote_id, cantidad)
          VALUES (_empresa_id, _merma_id, _linea_id, _producto_id, _l.lote_id, _take);

          INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_origen_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
          VALUES (_empresa_id, 'salida', _producto_id, _take, _almacen_origen_id, _l.lote_id, 'merma_lote', _merma_id, _folio || ' (FEFO)', _user_id, CURRENT_DATE);
          INSERT INTO public.movimientos_inventario(empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, notas, user_id, fecha)
          VALUES (_empresa_id, 'entrada', _producto_id, _take, _almacen_mermas, _l.lote_id, 'merma_lote_entrada', _merma_id, _folio || ' (FEFO)', _user_id, CURRENT_DATE);
          _pending := _pending - _take;
        END LOOP;
      END IF;
    END IF;
  END LOOP;

  UPDATE public.mermas SET total_costo = _total_costo, total_venta = _total_venta WHERE id = _merma_id;
  RETURN _merma_id;
END;
$$;


--
-- Name: registrar_saldo_inicial(uuid, uuid, numeric, date, text, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_saldo_inicial(p_empresa_id uuid, p_cliente_id uuid, p_monto numeric, p_fecha date DEFAULT CURRENT_DATE, p_concepto text DEFAULT 'Saldo anterior'::text, p_user_id uuid DEFAULT NULL::uuid, p_fecha_vencimiento date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_venta_id uuid;
  v_folio text;
BEGIN
  SELECT 'SAL-' || public.folio_lpad((COALESCE(MAX(
    CASE WHEN folio ~ '^SAL-[0-9]+$'
      THEN CAST(SUBSTRING(folio FROM 5) AS INT)
      ELSE 0
    END
  ), 0) + 1)::TEXT, 4, '0')
  INTO v_folio
  FROM public.ventas
  WHERE empresa_id = p_empresa_id;

  INSERT INTO public.ventas (
    empresa_id, cliente_id, total, saldo_pendiente,
    subtotal, iva_total, ieps_total,
    tipo, es_saldo_inicial, fecha, concepto,
    status, condicion_pago, folio, vendedor_id, fecha_vencimiento
  ) VALUES (
    p_empresa_id, p_cliente_id, p_monto, p_monto,
    p_monto, 0, 0,
    'saldo_inicial', true, p_fecha, p_concepto,
    'confirmado', 'credito', v_folio, NULL, p_fecha_vencimiento
  ) RETURNING id INTO v_venta_id;

  RETURN v_venta_id;
END;
$_$;


--
-- Name: release_timbre(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_timbre(p_reservation_id uuid, p_motivo text DEFAULT 'Liberación de reserva'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa_id uuid;
  v_user_id uuid;
  v_saldo_actual integer;
  v_already_released boolean;
BEGIN
  -- Sólo procesar si aún es una reserva (no si ya fue confirmada como 'uso')
  SELECT empresa_id, user_id
  INTO v_empresa_id, v_user_id
  FROM timbres_movimientos
  WHERE id = p_reservation_id
    AND tipo = 'reserva'
  FOR UPDATE;

  IF v_empresa_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT saldo INTO v_saldo_actual
  FROM timbres_saldo
  WHERE empresa_id = v_empresa_id
  FOR UPDATE;

  UPDATE timbres_saldo
  SET saldo = saldo + 1, updated_at = now()
  WHERE empresa_id = v_empresa_id;

  -- Marca la reserva como liberada
  UPDATE timbres_movimientos
  SET tipo = 'reserva_liberada',
      notas = COALESCE(p_motivo, 'Liberación de reserva')
  WHERE id = p_reservation_id;

  -- Movimiento espejo (+1) para que la suma de saldos cuadre con el log
  INSERT INTO timbres_movimientos (empresa_id, tipo, cantidad, saldo_anterior, saldo_nuevo, referencia_id, user_id, notas)
  VALUES (v_empresa_id, 'liberacion', 1, COALESCE(v_saldo_actual, 0), COALESCE(v_saldo_actual, 0) + 1, p_reservation_id, v_user_id, p_motivo);

  RETURN true;
END;
$$;


--
-- Name: repair_missing_entrega_carga(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_missing_entrega_carga() RETURNS TABLE(out_entrega_id uuid, out_folio text, out_producto_id uuid, out_cantidad numeric, out_ruta_almacen uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rec record;
  v_ruta_almacen uuid;
  v_vendedor uuid;
BEGIN
  FOR v_rec IN
    SELECT e.id AS eid, e.folio, e.empresa_id, e.vendedor_ruta_id, e.vendedor_id,
           el.producto_id, el.cantidad_entregada
    FROM public.entregas e
    JOIN public.entrega_lineas el ON el.entrega_id = e.id
    WHERE e.status IN ('cargado','en_ruta','hecho')
      AND el.hecho = true
      AND COALESCE(el.cantidad_entregada,0) > 0
      AND EXISTS (
        SELECT 1 FROM public.movimientos_inventario m
        WHERE m.referencia_id = e.id AND m.referencia_tipo = 'entrega'
          AND m.tipo = 'salida' AND m.producto_id = el.producto_id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.movimientos_inventario m
        WHERE m.referencia_id = e.id AND m.referencia_tipo = 'entrega_cargado'
          AND m.producto_id = el.producto_id
      )
  LOOP
    v_vendedor := COALESCE(v_rec.vendedor_ruta_id, v_rec.vendedor_id);
    SELECT almacen_id INTO v_ruta_almacen FROM public.profiles WHERE id = v_vendedor;
    IF v_ruta_almacen IS NULL THEN CONTINUE; END IF;

    INSERT INTO public.movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, vendedor_destino_id,
       referencia_tipo, referencia_id, notas, fecha)
    VALUES
      (v_rec.empresa_id, 'entrada', v_rec.producto_id, v_rec.cantidad_entregada,
       v_ruta_almacen, v_vendedor, 'entrega_cargado', v_rec.eid,
       'Carga a camión (reparación automática)', CURRENT_DATE);

    INSERT INTO public.stock_almacen AS sa (empresa_id, almacen_id, producto_id, cantidad)
    VALUES (v_rec.empresa_id, v_ruta_almacen, v_rec.producto_id, v_rec.cantidad_entregada)
    ON CONFLICT (almacen_id, producto_id) DO UPDATE
      SET cantidad = sa.cantidad + EXCLUDED.cantidad, updated_at = now();

    out_entrega_id := v_rec.eid; out_folio := v_rec.folio;
    out_producto_id := v_rec.producto_id; out_cantidad := v_rec.cantidad_entregada;
    out_ruta_almacen := v_ruta_almacen;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: reprogramar_entregas_bulk(uuid[], date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprogramar_entregas_bulk(p_entrega_ids uuid[], p_nueva_fecha date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa uuid := get_my_empresa_id();
  v_actualizadas int := 0;
  v_omitidas int := 0;
BEGIN
  IF p_entrega_ids IS NULL OR array_length(p_entrega_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'No hay entregas seleccionadas';
  END IF;
  IF p_nueva_fecha IS NULL THEN RAISE EXCEPTION 'Debes seleccionar una fecha'; END IF;

  WITH actualizadas AS (
    UPDATE entregas
    SET fecha = p_nueva_fecha
    WHERE id = ANY(p_entrega_ids)
      AND (empresa_id = v_empresa OR is_super_admin(auth.uid()))
      AND status::text NOT IN ('hecho','cancelado')
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_actualizadas FROM actualizadas;

  v_omitidas := array_length(p_entrega_ids, 1) - v_actualizadas;

  RETURN jsonb_build_object(
    'reprogramadas', v_actualizadas,
    'omitidas', v_omitidas,
    'nueva_fecha', p_nueva_fecha
  );
END;
$$;


--
-- Name: reserve_timbre(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_timbre(p_empresa_id uuid, p_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo_actual integer;
  v_mov_id uuid;
BEGIN
  SELECT saldo INTO v_saldo_actual
  FROM timbres_saldo
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  IF v_saldo_actual IS NULL OR v_saldo_actual < 1 THEN
    RETURN NULL;
  END IF;

  UPDATE timbres_saldo
  SET saldo = saldo - 1, updated_at = now()
  WHERE empresa_id = p_empresa_id;

  INSERT INTO timbres_movimientos (empresa_id, tipo, cantidad, saldo_anterior, saldo_nuevo, referencia_id, user_id, notas)
  VALUES (p_empresa_id, 'reserva', -1, v_saldo_actual, v_saldo_actual - 1, NULL, p_user_id, 'Reserva previa a timbrado Facturama')
  RETURNING id INTO v_mov_id;

  RETURN v_mov_id;
END;
$$;


--
-- Name: resolver_comision_pct_linea(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolver_comision_pct_linea(p_empresa_id uuid, p_tarifa_id uuid, p_cliente_id uuid, p_producto_id uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tarifa uuid := p_tarifa_id;
  v_clas uuid;
  v_lista uuid;
  v_pct numeric;
BEGIN
  IF v_tarifa IS NULL AND p_cliente_id IS NOT NULL THEN
    SELECT c.tarifa_id INTO v_tarifa FROM clientes c WHERE c.id = p_cliente_id;
  END IF;
  IF v_tarifa IS NULL THEN
    SELECT t.id INTO v_tarifa FROM tarifas t
    WHERE t.empresa_id = p_empresa_id AND t.tipo = 'general'
    ORDER BY t.created_at LIMIT 1;
  END IF;
  IF v_tarifa IS NULL THEN RETURN NULL; END IF;

  SELECT p.clasificacion_id, p.lista_id INTO v_clas, v_lista FROM productos p WHERE p.id = p_producto_id;

  SELECT tl.comision_pct INTO v_pct
  FROM tarifa_lineas tl
  WHERE tl.tarifa_id = v_tarifa
    AND tl.comision_pct IS NOT NULL
    AND (
      (tl.aplica_a = 'producto' AND p_producto_id = ANY(COALESCE(tl.producto_ids, '{}')))
      OR (tl.aplica_a = 'grupo' AND v_lista IS NOT NULL AND v_lista::text = ANY(COALESCE(tl.grupos, '{}')))
      OR (tl.aplica_a = 'categoria' AND v_clas IS NOT NULL AND v_clas = ANY(COALESCE(tl.clasificacion_ids, '{}')))
      OR tl.aplica_a = 'todos'
    )
  ORDER BY CASE tl.aplica_a WHEN 'producto' THEN 1 WHEN 'grupo' THEN 2 WHEN 'categoria' THEN 3 ELSE 4 END
  LIMIT 1;

  RETURN v_pct;
END; $$;


--
-- Name: restore_cancelled_sale_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_cancelled_sale_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linea RECORD;
  v_stock_id uuid;
  v_stock_actual numeric;
  v_was_delivered boolean;
  v_neto_pendiente numeric;
  v_a_devolver numeric;
  v_ref_tipo text;
  v_nota text;
BEGIN
  IF NEW.tipo = 'saldo_inicial' THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('cancelado', 'borrador') THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF NEW.tipo <> 'venta_directa' THEN RETURN NEW; END IF;

  v_was_delivered := (COALESCE(OLD.entrega_inmediata, false) = true) OR (OLD.status = 'entregado');
  IF NOT v_was_delivered THEN RETURN NEW; END IF;
  IF NEW.almacen_id IS NULL THEN RETURN NEW; END IF;

  IF NEW.status = 'cancelado' THEN
    v_ref_tipo := 'cancelacion_venta';
    v_nota := 'Cancelación venta ' || COALESCE(NEW.folio, NEW.id::text);
  ELSE
    v_ref_tipo := 'reverso_borrador';
    v_nota := 'Reverso por vuelta a borrador ' || COALESCE(NEW.folio, NEW.id::text);
  END IF;

  FOR v_linea IN
    SELECT producto_id, SUM(cantidad) AS cantidad
    FROM public.venta_lineas WHERE venta_id = NEW.id
    GROUP BY producto_id
  LOOP
    SELECT COALESCE(SUM(CASE
              WHEN tipo = 'salida' AND referencia_tipo = 'venta' THEN cantidad
              WHEN tipo = 'entrada' AND referencia_tipo IN ('cancelacion_venta','reverso_borrador') THEN -cantidad
              ELSE 0
           END), 0)
    INTO v_neto_pendiente
    FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND producto_id = v_linea.producto_id;

    v_a_devolver := LEAST(GREATEST(v_neto_pendiente, 0), COALESCE(v_linea.cantidad, 0));
    IF v_a_devolver <= 0 THEN CONTINUE; END IF;

    SELECT id, cantidad INTO v_stock_id, v_stock_actual
      FROM public.stock_almacen
      WHERE almacen_id = NEW.almacen_id AND producto_id = v_linea.producto_id
      FOR UPDATE LIMIT 1;

    IF v_stock_id IS NOT NULL THEN
      UPDATE public.stock_almacen
        SET cantidad = COALESCE(v_stock_actual, 0) + v_a_devolver, updated_at = now()
        WHERE id = v_stock_id;
    ELSE
      INSERT INTO public.stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
        VALUES (NEW.empresa_id, NEW.almacen_id, v_linea.producto_id, v_a_devolver);
    END IF;

    INSERT INTO public.movimientos_inventario
      (id, empresa_id, tipo, producto_id, cantidad, almacen_destino_id, referencia_tipo, referencia_id, user_id, fecha, created_at, notas)
    VALUES
      (gen_random_uuid(), NEW.empresa_id, 'entrada', v_linea.producto_id, v_a_devolver,
       NEW.almacen_id, v_ref_tipo, NEW.id, COALESCE(NEW.vendedor_id, NEW.cliente_id),
       COALESCE(NEW.fecha, current_date), now(), v_nota);
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: reverse_devolucion_linea_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_devolucion_linea_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mov record;
BEGIN
  -- Renglón aplicado con etiqueta propia: se revierte solo lo suyo.
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario
             WHERE referencia_id = OLD.devolucion_id AND referencia_tipo = 'devolucion_aplicada'
               AND notas LIKE '%[linea:' || OLD.id::text || ']%') THEN
    FOR v_mov IN
      SELECT id, almacen_destino_id, producto_id, cantidad
      FROM public.movimientos_inventario
      WHERE referencia_id = OLD.devolucion_id AND referencia_tipo = 'devolucion_aplicada'
        AND tipo = 'entrada' AND cantidad > 0
        AND notas LIKE '%[linea:' || OLD.id::text || ']%'
    LOOP
      IF v_mov.almacen_destino_id IS NOT NULL THEN
        UPDATE public.stock_almacen
        SET cantidad = cantidad - v_mov.cantidad, updated_at = now()
        WHERE almacen_id = v_mov.almacen_destino_id AND producto_id = v_mov.producto_id;
      END IF;
    END LOOP;
    DELETE FROM public.movimientos_inventario
    WHERE referencia_id = OLD.devolucion_id AND referencia_tipo = 'devolucion_aplicada'
      AND notas LIKE '%[linea:' || OLD.id::text || ']%';
    RETURN OLD;
  END IF;

  FOR v_mov IN
    SELECT id, almacen_destino_id, producto_id, cantidad
    FROM public.movimientos_inventario
    WHERE referencia_id = OLD.devolucion_id
      AND producto_id = OLD.producto_id
      AND referencia_tipo IN ('devolucion_aplicada', 'devolucion')
      AND tipo = 'entrada'
      AND cantidad > 0
  LOOP
    IF v_mov.almacen_destino_id IS NOT NULL THEN
      UPDATE public.stock_almacen
      SET cantidad = cantidad - v_mov.cantidad, updated_at = now()
      WHERE almacen_id = v_mov.almacen_destino_id
        AND producto_id = v_mov.producto_id;
    END IF;
  END LOOP;

  DELETE FROM public.movimientos_inventario
  WHERE referencia_id = OLD.devolucion_id
    AND producto_id = OLD.producto_id
    AND referencia_tipo IN ('devolucion_aplicada', 'devolucion');

  RETURN OLD;
END;
$$;


--
-- Name: revertir_lote_compra_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revertir_lote_compra_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_mov record;
BEGIN
  IF NOT (
    COALESCE(OLD.status, '') <> 'cancelada'
    AND NEW.status = 'cancelada'
  ) THEN
    RETURN NEW;
  END IF;

  -- La función nueva ya descontó correctamente los lotes.
  IF EXISTS (
    SELECT 1
    FROM public.movimientos_inventario mi
    WHERE mi.empresa_id = NEW.empresa_id
      AND mi.referencia_id = NEW.id
      AND mi.referencia_tipo = 'compra'
      AND mi.tipo = 'salida'
      AND mi.notas LIKE 'Cancelación atómica compra %'
  ) THEN
    RETURN NEW;
  END IF;

  -- Compatibilidad con cancelaciones anteriores.
  IF EXISTS (
    SELECT 1
    FROM public.movimientos_inventario mi
    WHERE mi.referencia_id = NEW.id
      AND mi.referencia_tipo = 'compra_cancel_lote'
  ) THEN
    RETURN NEW;
  END IF;

  FOR v_mov IN
    SELECT
      producto_id,
      cantidad,
      lote_id,
      almacen_destino_id
    FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id
      AND referencia_tipo = 'compra'
      AND tipo = 'entrada'
      AND lote_id IS NOT NULL
  LOOP
    INSERT INTO public.movimientos_inventario (
      empresa_id,
      tipo,
      producto_id,
      cantidad,
      almacen_origen_id,
      lote_id,
      referencia_tipo,
      referencia_id,
      fecha,
      notas
    )
    VALUES (
      NEW.empresa_id,
      'salida',
      v_mov.producto_id,
      v_mov.cantidad,
      v_mov.almacen_destino_id,
      v_mov.lote_id,
      'compra_cancel_lote',
      NEW.id,
      CURRENT_DATE,
      'Reversa lote · cancelación compra'
    );
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: revertir_lote_traspaso_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revertir_lote_traspaso_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_mov RECORD;
BEGIN
  IF NOT (OLD.status = 'confirmado' AND NEW.status = 'cancelado') THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.movimientos_inventario
             WHERE referencia_id = NEW.id AND referencia_tipo = 'traspaso_cancel_lote') THEN RETURN NEW; END IF;
  FOR v_mov IN
    SELECT producto_id, cantidad, lote_id, almacen_origen_id, almacen_destino_id
    FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo = 'traspaso'
      AND tipo = 'transferencia'::public.tipo_movimiento AND lote_id IS NOT NULL
    ORDER BY producto_id, lote_id
  LOOP
    INSERT INTO public.movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, almacen_destino_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
    VALUES (NEW.empresa_id, 'transferencia'::public.tipo_movimiento, v_mov.producto_id, v_mov.cantidad,
       v_mov.almacen_destino_id, v_mov.almacen_origen_id, v_mov.lote_id,
       'traspaso_cancel_lote', NEW.id, CURRENT_DATE, 'Reversa lote · cancelación traspaso');
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: revertir_lote_venta_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revertir_lote_venta_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ref_tipo text; v_rec RECORD; v_net numeric;
BEGIN
  IF NEW.tipo <> 'venta_directa' THEN RETURN NEW; END IF;
  IF NEW.status NOT IN ('cancelado', 'borrador') THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF NOT ((COALESCE(OLD.entrega_inmediata, false) = true) OR (OLD.status = 'entregado')) THEN RETURN NEW; END IF;
  IF NEW.almacen_id IS NULL THEN RETURN NEW; END IF;
  v_ref_tipo := CASE WHEN NEW.status = 'cancelado' THEN 'cancelacion_venta_lote' ELSE 'reverso_borrador_lote' END;
  FOR v_rec IN
    SELECT producto_id, lote_id, (array_agg(almacen_origen_id))[1] AS almacen_id FROM public.movimientos_inventario
    WHERE referencia_id = NEW.id AND referencia_tipo IN ('venta','venta_lote') AND tipo = 'salida' AND lote_id IS NOT NULL
    GROUP BY producto_id, lote_id
  LOOP
    SELECT COALESCE(SUM(CASE
             WHEN tipo = 'salida' AND referencia_tipo IN ('venta','venta_lote') THEN cantidad
             WHEN tipo = 'entrada' AND referencia_tipo IN ('cancelacion_venta_lote', 'reverso_borrador_lote') THEN -cantidad
             ELSE 0 END), 0) INTO v_net
    FROM public.movimientos_inventario WHERE referencia_id = NEW.id AND producto_id = v_rec.producto_id AND lote_id = v_rec.lote_id;
    IF v_net > 0 THEN
      INSERT INTO public.movimientos_inventario
        (empresa_id, tipo, producto_id, cantidad, almacen_destino_id, lote_id, referencia_tipo, referencia_id, fecha, notas)
      VALUES (NEW.empresa_id, 'entrada', v_rec.producto_id, v_net, v_rec.almacen_id, v_rec.lote_id, v_ref_tipo, NEW.id, COALESCE(NEW.fecha, CURRENT_DATE),
              'Reversa lote · ' || (CASE WHEN NEW.status = 'cancelado' THEN 'cancelación' ELSE 'vuelta a borrador' END) || ' venta');
    END IF;
  END LOOP;
  RETURN NEW;
END; $$;


--
-- Name: revertir_surtido_linea(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revertir_surtido_linea(p_linea_id uuid, p_entrega_id uuid, p_empresa_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_producto uuid;
  v_hecho boolean;
  v_mov record;
  v_upd int;
BEGIN
  SELECT producto_id, hecho INTO v_producto, v_hecho
  FROM entrega_lineas WHERE id = p_linea_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Línea no encontrada'; END IF;

  FOR v_mov IN
    SELECT id, cantidad, lote_id, almacen_origen_id
    FROM movimientos_inventario
    WHERE empresa_id = p_empresa_id
      AND referencia_tipo = 'entrega'
      AND referencia_id = p_entrega_id
      AND producto_id = v_producto
      AND tipo = 'salida'
    FOR UPDATE
  LOOP
    IF v_mov.almacen_origen_id IS NOT NULL THEN
      UPDATE stock_almacen
      SET cantidad = cantidad + v_mov.cantidad, updated_at = now()
      WHERE almacen_id = v_mov.almacen_origen_id AND producto_id = v_producto;
      GET DIAGNOSTICS v_upd = ROW_COUNT;
      IF v_upd = 0 THEN
        INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
        VALUES (p_empresa_id, v_mov.almacen_origen_id, v_producto, v_mov.cantidad);
      END IF;
    END IF;

    IF v_mov.lote_id IS NOT NULL AND v_mov.almacen_origen_id IS NOT NULL THEN
      PERFORM public._aplica_stock_lote(p_empresa_id, v_mov.almacen_origen_id, v_producto, v_mov.lote_id, v_mov.cantidad);
    END IF;

    DELETE FROM movimientos_inventario WHERE id = v_mov.id;
  END LOOP;

  UPDATE entrega_lineas
  SET hecho = false, cantidad_entregada = 0
  WHERE id = p_linea_id;
END;
$$;


--
-- Name: run_maintenance_vacuum(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_maintenance_vacuum(p_tables text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_duration_ms integer;
  v_tables text[];
  v_table text;
  v_log_id uuid;
  v_processed text[] := ARRAY[]::text[];
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Acceso denegado: se requieren permisos de super administrador';
  END IF;

  IF p_tables IS NULL OR array_length(p_tables, 1) IS NULL THEN
    v_tables := ARRAY[
      'public.role_permisos',
      'public.movimientos_inventario',
      'public.ventas',
      'public.venta_lineas',
      'public.cobros',
      'public.cobro_aplicaciones',
      'public.stock_almacen',
      'public.productos',
      'public.clientes'
    ];
  ELSE
    v_tables := p_tables;
  END IF;

  -- ANALYZE is allowed inside a transaction (VACUUM is not).
  -- This refreshes planner statistics and helps autovacuum prioritize bloated tables.
  FOREACH v_table IN ARRAY v_tables LOOP
    IF v_table ~ '^public\.[a-z_][a-z0-9_]*$' AND EXISTS (
      SELECT 1 FROM pg_tables WHERE schemaname = 'public'
        AND tablename = split_part(v_table, '.', 2)
    ) THEN
      EXECUTE 'ANALYZE ' || v_table;
      v_processed := array_append(v_processed, v_table);
    END IF;
  END LOOP;

  v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_start)) * 1000;

  INSERT INTO public.maintenance_log (ejecutado_por, tablas_procesadas, duracion_ms, notas)
  VALUES (auth.uid(), v_processed, v_duration_ms,
          'ANALYZE manual (VACUUM no puede ejecutarse dentro de una transacción; autovacuum agresivo configurado)')
  RETURNING id INTO v_log_id;

  RETURN jsonb_build_object(
    'success', true,
    'log_id', v_log_id,
    'duracion_ms', v_duration_ms,
    'tablas_procesadas', v_processed,
    'nota', 'Se ejecutó ANALYZE. El VACUUM real lo ejecuta automáticamente autovacuum (configurado de forma agresiva en tablas de alta rotación).'
  );
END;
$_$;


--
-- Name: ruta_sesion_validate_and_sync_km(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ruta_sesion_validate_and_sync_km() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_km_actual NUMERIC;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.vehiculo_id IS NOT NULL THEN
      SELECT km_actual INTO v_km_actual FROM public.vehiculos WHERE id = NEW.vehiculo_id;
      IF v_km_actual IS NOT NULL AND NEW.km_inicio IS NOT NULL AND NEW.km_inicio < v_km_actual THEN
        RAISE EXCEPTION 'KM inicial (%) no puede ser menor al último KM registrado del vehículo (%)', NEW.km_inicio, v_km_actual;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'cerrada' AND OLD.status <> 'cerrada' THEN
      IF NEW.vehiculo_id IS NOT NULL THEN
        IF NEW.km_fin IS NULL THEN
          RAISE EXCEPTION 'Para cerrar la jornada se requiere KM final';
        END IF;
        IF NEW.km_inicio IS NOT NULL AND NEW.km_fin < NEW.km_inicio THEN
          RAISE EXCEPTION 'KM final (%) no puede ser menor al KM inicial (%)', NEW.km_fin, NEW.km_inicio;
        END IF;
        UPDATE public.vehiculos SET km_actual = NEW.km_fin, updated_at = now() WHERE id = NEW.vehiculo_id;
      END IF;
      IF NEW.fin_at IS NULL THEN
        NEW.fin_at := now();
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: saldo_clientes_a_la_fecha(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saldo_clientes_a_la_fecha(p_empresa_id uuid, p_fecha date) RETURNS TABLE(cliente_id uuid, cliente text, cargos numeric, abonos numeric, saldo numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH cargos AS (
    SELECT v.cliente_id, COALESCE(SUM(v.total),0) AS monto
    FROM public.ventas v
    WHERE v.empresa_id = p_empresa_id AND v.fecha <= p_fecha
      AND v.status::text <> 'cancelado' AND v.cliente_id IS NOT NULL
    GROUP BY v.cliente_id
  ),
  abonos AS (
    SELECT c.cliente_id, COALESCE(SUM(c.monto),0) AS monto
    FROM public.cobros c
    WHERE c.empresa_id = p_empresa_id AND c.fecha <= p_fecha
      AND COALESCE(c.status,'activo') <> 'cancelado' AND c.cliente_id IS NOT NULL
    GROUP BY c.cliente_id
  ),
  ids AS (SELECT cliente_id FROM cargos UNION SELECT cliente_id FROM abonos)
  SELECT i.cliente_id, cl.nombre, COALESCE(ca.monto,0), COALESCE(ab.monto,0),
         COALESCE(ca.monto,0) - COALESCE(ab.monto,0)
  FROM ids i
  JOIN public.clientes cl ON cl.id = i.cliente_id
  LEFT JOIN cargos ca ON ca.cliente_id = i.cliente_id
  LEFT JOIN abonos ab ON ab.cliente_id = i.cliente_id
  WHERE cl.empresa_id = p_empresa_id
  ORDER BY (COALESCE(ca.monto,0) - COALESCE(ab.monto,0)) DESC, cl.nombre;
$$;


