--
-- Name: set_cliente_lada_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_cliente_lada_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.lada IS NULL OR NEW.lada = '' THEN
    SELECT lada INTO NEW.lada FROM public.empresas WHERE id = NEW.empresa_id;
    IF NEW.lada IS NULL OR NEW.lada = '' THEN
      NEW.lada := '52';
    END IF;
  END IF;
  -- Limpiar: solo dígitos
  NEW.lada := regexp_replace(NEW.lada, '\D', '', 'g');
  RETURN NEW;
END;
$$;


