-- Name: solicitud_compra_sync_proveedor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.solicitud_compra_sync_proveedor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_nombre text;
  v_email text;
  v_empresa_id uuid;
begin
  -- New requests must always point to a real supplier. Legacy rows that were already
  -- created without proveedor_id remain editable so they can be repaired manually.
  if new.proveedor_id is null then
    if tg_op = 'INSERT' or old.proveedor_id is distinct from new.proveedor_id then
      raise exception 'Selecciona un proveedor registrado en el catálogo de proveedores.'
        using errcode = '23502';
    end if;
    return new;
  end if;

  select p.nombre, p.email, p.empresa_id
    into v_nombre, v_email, v_empresa_id
  from public.proveedores p
  where p.id = new.proveedor_id;

  if not found then
    raise exception 'El proveedor seleccionado no existe.'
      using errcode = '23503';
  end if;

  if v_empresa_id is distinct from new.empresa_id then
    raise exception 'El proveedor seleccionado no pertenece a esta empresa.'
      using errcode = '23514';
  end if;

  -- These fields are snapshots only. They cannot diverge from the supplier master.
  new.proveedor_nombre := coalesce(v_nombre, '');
  new.proveedor_email := nullif(btrim(coalesce(v_email, '')), '');

  return new;
end;
$$;


--
-- Name: stock_a_la_fecha(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_a_la_fecha(p_empresa_id uuid, p_fecha date) RETURNS TABLE(producto_id uuid, producto text, almacen_id uuid, almacen text, cantidad numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT x.producto_id, x.producto, x.almacen_id, x.almacen, x.cantidad
  FROM jsonb_to_recordset(
    public.fn_inventory_stock_at_date(p_empresa_id, p_fecha)->'rows'
  ) AS x(
    producto_id uuid,
    producto text,
    almacen_id uuid,
    almacen text,
    cantidad numeric
  )
  WHERE x.cantidad <> 0
  ORDER BY x.producto, x.almacen;
$$;


--
-- Name: stock_almacen_at_eod(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_almacen_at_eod(p_almacen_id uuid, p_fecha date) RETURNS TABLE(producto_id uuid, cantidad numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH tz AS (
    SELECT COALESCE(NULLIF(e.zona_horaria, ''), 'America/Mexico_City') AS zh
    FROM public.almacenes a
    LEFT JOIN public.empresas e ON e.id = a.empresa_id
    WHERE a.id = p_almacen_id
    LIMIT 1
  ),
  cutoff AS (
    SELECT (((p_fecha + INTERVAL '1 day')::timestamp) AT TIME ZONE (SELECT zh FROM tz)) AS ts
  ),
  actual AS (
    SELECT sa.producto_id, sa.cantidad
    FROM public.stock_almacen sa
    WHERE sa.almacen_id = p_almacen_id
  ),
  movs_post AS (
    SELECT
      mi.producto_id,
      SUM(
        CASE WHEN mi.almacen_destino_id = p_almacen_id THEN mi.cantidad ELSE 0 END
        - CASE WHEN mi.almacen_origen_id  = p_almacen_id THEN mi.cantidad ELSE 0 END
      ) AS delta
    FROM public.movimientos_inventario mi, cutoff c
    WHERE (mi.almacen_destino_id = p_almacen_id OR mi.almacen_origen_id = p_almacen_id)
      AND mi.created_at > c.ts
    GROUP BY mi.producto_id
  )
  SELECT
    COALESCE(a.producto_id, m.producto_id) AS producto_id,
    COALESCE(a.cantidad, 0) - COALESCE(m.delta, 0) AS cantidad
  FROM actual a
  FULL OUTER JOIN movs_post m ON m.producto_id = a.producto_id
  WHERE COALESCE(a.cantidad, 0) - COALESCE(m.delta, 0) <> 0;
$$;


--
-- Name: stock_almacen_at_eod_v2(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_almacen_at_eod_v2(p_almacen_id uuid, p_fecha date) RETURNS TABLE(producto_id uuid, cantidad numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa_id uuid;
  v_tz text;
  v_cutoff timestamptz;
BEGIN
  SELECT a.empresa_id, COALESCE(e.zona_horaria, 'America/Mexico_City')
    INTO v_empresa_id, v_tz
  FROM public.almacenes a
  LEFT JOIN public.empresas e ON e.id = a.empresa_id
  WHERE a.id = p_almacen_id;

  IF v_empresa_id IS NULL THEN
    RETURN;
  END IF;

  v_cutoff := ((p_fecha + 1)::timestamp AT TIME ZONE v_tz);

  RETURN QUERY
  WITH live AS (
    SELECT s.producto_id, COALESCE(s.cantidad, 0)::numeric AS cantidad
    FROM public.stock_almacen s
    WHERE s.almacen_id = p_almacen_id
  ),
  posteriores AS (
    SELECT
      m.producto_id,
      SUM(
        CASE
          -- Entradas al almacén (sumaron stock → revertir restando)
          WHEN m.tipo = 'entrada' AND m.almacen_destino_id = p_almacen_id
            THEN COALESCE(m.cantidad,0)
          WHEN m.tipo = 'transferencia' AND m.almacen_destino_id = p_almacen_id
            THEN COALESCE(m.cantidad,0)
          -- Salidas del almacén (restaron stock → revertir sumando)
          WHEN m.tipo = 'salida' AND m.almacen_origen_id = p_almacen_id
            THEN -COALESCE(m.cantidad,0)
          WHEN m.tipo = 'transferencia' AND m.almacen_origen_id = p_almacen_id
            THEN -COALESCE(m.cantidad,0)
          ELSE 0
        END
      )::numeric AS delta
    FROM public.movimientos_inventario m
    WHERE m.empresa_id = v_empresa_id
      AND (m.almacen_origen_id = p_almacen_id OR m.almacen_destino_id = p_almacen_id)
      AND m.created_at >= v_cutoff
    GROUP BY m.producto_id
  )
  SELECT
    COALESCE(l.producto_id, p.producto_id) AS producto_id,
    (COALESCE(l.cantidad,0) - COALESCE(p.delta,0))::numeric AS cantidad
  FROM live l
  FULL OUTER JOIN posteriores p ON p.producto_id = l.producto_id;
END;
$$;


--
-- Name: super_admin_list_empresas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.super_admin_list_empresas() RETURNS TABLE(id uuid, nombre text, status text, current_period_end timestamp with time zone, trial_ends_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id, e.nombre, s.status, s.current_period_end, s.trial_ends_at
  FROM public.empresas e
  LEFT JOIN public.subscriptions s ON s.empresa_id = e.id
  WHERE public.is_super_admin(auth.uid())
  ORDER BY e.nombre;
$$;


--
-- Name: surtir_linea_entrega(uuid, uuid, uuid, numeric, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.surtir_linea_entrega(p_linea_id uuid, p_producto_id uuid, p_almacen_origen_id uuid, p_cantidad_surtida numeric, p_entrega_id uuid, p_empresa_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vender_sin_stock boolean;
  v_today date := current_date;
  v_sa_id uuid;
  v_sa_qty numeric;
  v_new_qty numeric;
  v_already boolean;
BEGIN
  -- IDEMPOTENCIA: bloquear la línea y salir si ya fue surtida.
  SELECT hecho INTO v_already
  FROM entrega_lineas
  WHERE id = p_linea_id
  FOR UPDATE;

  IF COALESCE(v_already, false) THEN
    RETURN; -- ya surtida: no-op
  END IF;

  SELECT vender_sin_stock INTO v_vender_sin_stock FROM productos WHERE id = p_producto_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Producto no encontrado'; END IF;

  SELECT id, cantidad INTO v_sa_id, v_sa_qty
  FROM stock_almacen WHERE almacen_id = p_almacen_origen_id AND producto_id = p_producto_id FOR UPDATE;

  v_new_qty := COALESCE(v_sa_qty, 0) - p_cantidad_surtida;

  IF NOT COALESCE(v_vender_sin_stock, false) THEN
    IF v_sa_id IS NULL OR v_new_qty < 0 THEN
      RAISE EXCEPTION 'Stock insuficiente en almacén. Disponible: %, solicitado: %', COALESCE(v_sa_qty, 0), p_cantidad_surtida;
    END IF;
  END IF;

  IF v_sa_id IS NOT NULL THEN
    UPDATE stock_almacen SET cantidad = v_new_qty, updated_at = now() WHERE id = v_sa_id;
  END IF;

  UPDATE entrega_lineas SET cantidad_entregada = p_cantidad_surtida, almacen_origen_id = p_almacen_origen_id, hecho = true WHERE id = p_linea_id;

  INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas)
  VALUES (p_empresa_id, 'salida', p_producto_id, p_cantidad_surtida, p_almacen_origen_id, 'entrega', p_entrega_id, p_user_id, v_today, 'Surtido de entrega');
END;
$$;


--
-- Name: surtir_linea_entrega_lotes(uuid, uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.surtir_linea_entrega_lotes(p_linea_id uuid, p_producto_id uuid, p_almacen_origen_id uuid, p_entrega_id uuid, p_empresa_id uuid, p_user_id uuid, p_asignacion jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric := 0;
  v_item jsonb;
  v_lote uuid;
  v_cant numeric;
  v_sa_id uuid;
  v_sa_qty numeric;
  v_vender_sin_stock boolean;
  v_today date := current_date;
BEGIN
  SELECT COALESCE(SUM((x->>'cantidad')::numeric), 0) INTO v_total
  FROM jsonb_array_elements(COALESCE(p_asignacion, '[]'::jsonb)) x;
  IF v_total <= 0 THEN RAISE EXCEPTION 'Asignación de lotes vacía'; END IF;

  SELECT vender_sin_stock INTO v_vender_sin_stock FROM productos WHERE id = p_producto_id;

  SELECT id, cantidad INTO v_sa_id, v_sa_qty
  FROM stock_almacen WHERE almacen_id = p_almacen_origen_id AND producto_id = p_producto_id FOR UPDATE;

  IF v_sa_id IS NULL THEN
    IF NOT COALESCE(v_vender_sin_stock, false) THEN
      RAISE EXCEPTION 'Sin stock en el almacén origen';
    END IF;
    INSERT INTO stock_almacen (empresa_id, almacen_id, producto_id, cantidad)
    VALUES (p_empresa_id, p_almacen_origen_id, p_producto_id, -v_total);
  ELSE
    IF NOT COALESCE(v_vender_sin_stock, false) AND COALESCE(v_sa_qty,0) - v_total < 0 THEN
      RAISE EXCEPTION 'Stock insuficiente en almacén. Disponible: %, solicitado: %', COALESCE(v_sa_qty,0), v_total;
    END IF;
    UPDATE stock_almacen SET cantidad = COALESCE(v_sa_qty,0) - v_total, updated_at = now() WHERE id = v_sa_id;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_asignacion, '[]'::jsonb))
  LOOP
    v_lote := (v_item->>'lote_id')::uuid;
    v_cant := COALESCE((v_item->>'cantidad')::numeric, 0);
    IF v_lote IS NULL OR v_cant <= 0 THEN CONTINUE; END IF;
    IF NOT EXISTS (SELECT 1 FROM lotes WHERE id = v_lote AND producto_id = p_producto_id) THEN
      RAISE EXCEPTION 'Un lote no corresponde al producto';
    END IF;
    INSERT INTO movimientos_inventario
      (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas, lote_id)
    VALUES
      (p_empresa_id, 'salida', p_producto_id, v_cant, p_almacen_origen_id, 'entrega', p_entrega_id, p_user_id, v_today, 'Surtido de entrega (lote)', v_lote);
  END LOOP;

  UPDATE entrega_lineas
  SET cantidad_entregada = v_total, almacen_origen_id = p_almacen_origen_id, hecho = true
  WHERE id = p_linea_id;
END;
$$;


--
-- Name: surtir_linea_entrega_parcial(uuid, uuid, uuid, numeric, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.surtir_linea_entrega_parcial(p_linea_id uuid, p_producto_id uuid, p_almacen_origen_id uuid, p_cantidad_pedida numeric, p_entrega_id uuid, p_empresa_id uuid, p_user_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_vender_sin_stock boolean;
  v_today date := current_date;
  v_sa_id uuid;
  v_sa_qty numeric;
  v_disponible numeric;
  v_surtir numeric;
  v_already boolean;
BEGIN
  -- IDEMPOTENCIA: bloquear la línea y salir si ya fue surtida.
  SELECT hecho INTO v_already
  FROM entrega_lineas
  WHERE id = p_linea_id
  FOR UPDATE;

  IF COALESCE(v_already, false) THEN
    RETURN 0; -- ya surtida: no-op
  END IF;

  SELECT vender_sin_stock INTO v_vender_sin_stock FROM productos WHERE id = p_producto_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Producto no encontrado'; END IF;

  SELECT id, cantidad INTO v_sa_id, v_sa_qty
  FROM stock_almacen WHERE almacen_id = p_almacen_origen_id AND producto_id = p_producto_id FOR UPDATE;

  v_disponible := COALESCE(v_sa_qty, 0);

  IF COALESCE(v_vender_sin_stock, false) THEN
    -- Puede ir a negativo: surtir lo pedido completo.
    v_surtir := p_cantidad_pedida;
  ELSE
    -- Clamp al disponible: surtir el máximo que alcance.
    v_surtir := LEAST(p_cantidad_pedida, v_disponible);
  END IF;

  -- Nada que surtir (0 disponible o pedido 0) → dejar la línea PENDIENTE.
  IF v_surtir <= 0 THEN
    RETURN 0;
  END IF;

  IF v_sa_id IS NOT NULL THEN
    UPDATE stock_almacen SET cantidad = v_disponible - v_surtir, updated_at = now() WHERE id = v_sa_id;
  END IF;

  UPDATE entrega_lineas
  SET cantidad_entregada = v_surtir, almacen_origen_id = p_almacen_origen_id, hecho = true
  WHERE id = p_linea_id;

  INSERT INTO movimientos_inventario (empresa_id, tipo, producto_id, cantidad, almacen_origen_id, referencia_tipo, referencia_id, user_id, fecha, notas)
  VALUES (p_empresa_id, 'salida', p_producto_id, v_surtir, p_almacen_origen_id, 'entrega', p_entrega_id, p_user_id, v_today, 'Surtido de entrega');

  RETURN v_surtir;
END;
$$;


--
-- Name: surtir_solicitud_traspaso(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.surtir_solicitud_traspaso(p_solicitud_id uuid, p_lineas jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sol public.solicitudes_traspaso%ROWTYPE;
  v_item jsonb;
  v_linea public.solicitud_traspaso_lineas%ROWTYPE;
  v_cant numeric;
  v_pend numeric;
  v_disp numeric;
  v_traspaso_id uuid;
  v_traspaso_linea_id uuid;
  v_maneja_lote boolean;
  v_restante numeric;
  v_lote RECORD;
  v_toma numeric;
  v_total_aprobado numeric;
  v_total_surtido numeric;
  v_algo boolean := false;
BEGIN
  SELECT * INTO v_sol
    FROM public.solicitudes_traspaso
   WHERE id = p_solicitud_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Solicitud no encontrada';
  END IF;

  IF NOT (
    v_sol.empresa_id = public.get_my_empresa_id()
    OR public.is_super_admin(auth.uid())
  ) THEN
    RAISE EXCEPTION 'No autorizado';
  END IF;

  IF v_sol.status NOT IN (
    'aprobada',
    'parcialmente_surtida'
  ) THEN
    RAISE EXCEPTION 'Esta solicitud ya no admite surtidos';
  END IF;

  IF v_sol.almacen_origen_id IS NULL
     OR v_sol.almacen_destino_id IS NULL THEN
    RAISE EXCEPTION 'La solicitud no tiene almacén origen o destino';
  END IF;

  v_traspaso_id := gen_random_uuid();

  INSERT INTO public.traspasos (
    id,
    empresa_id,
    tipo,
    status,
    almacen_origen_id,
    almacen_destino_id,
    fecha,
    notas,
    user_id
  )
  VALUES (
    v_traspaso_id,
    v_sol.empresa_id,
    'almacen_almacen'::public.tipo_traspaso,
    'borrador'::public.status_traspaso,
    v_sol.almacen_origen_id,
    v_sol.almacen_destino_id,
    CURRENT_DATE,
    'Surtido de solicitud ' || COALESCE(v_sol.folio, ''),
    COALESCE(auth.uid(), v_sol.solicitante_user_id)
  );

  FOR v_item IN
    SELECT *
      FROM jsonb_array_elements(
        COALESCE(p_lineas, '[]'::jsonb)
      )
  LOOP
    SELECT * INTO v_linea
      FROM public.solicitud_traspaso_lineas
     WHERE id = (v_item->>'linea_id')::uuid
       AND solicitud_id = p_solicitud_id
       AND excluida = false
     FOR UPDATE;

    CONTINUE WHEN NOT FOUND;

    PERFORM 1
      FROM public.stock_almacen
     WHERE empresa_id = v_sol.empresa_id
       AND almacen_id = v_sol.almacen_origen_id
       AND producto_id = v_linea.producto_id
     FOR UPDATE;

    v_pend := GREATEST(
      v_linea.cantidad_aprobada - v_linea.cantidad_surtida,
      0
    );

    v_disp := GREATEST(
      COALESCE(
        public.fn_disponible_almacen(
          v_linea.producto_id,
          v_sol.almacen_origen_id
        ),
        0
      ),
      0
    );

    v_cant := GREATEST(
      COALESCE((v_item->>'cantidad')::numeric, 0),
      0
    );

    v_cant := LEAST(v_cant, v_pend, v_disp);

    CONTINUE WHEN v_cant <= 0;

    v_traspaso_linea_id := gen_random_uuid();

    INSERT INTO public.traspaso_lineas (
      id,
      traspaso_id,
      producto_id,
      cantidad
    )
    VALUES (
      v_traspaso_linea_id,
      v_traspaso_id,
      v_linea.producto_id,
      v_cant
    );

    SELECT COALESCE(maneja_lote, false)
      INTO v_maneja_lote
      FROM public.productos
     WHERE id = v_linea.producto_id;

    IF v_maneja_lote THEN
      v_restante := v_cant;

      FOR v_lote IN
        SELECT
          sl.lote_id,
          sl.cantidad,
          l.fecha_caducidad
        FROM public.stock_lotes sl
        JOIN public.lotes l
          ON l.id = sl.lote_id
        WHERE sl.empresa_id = v_sol.empresa_id
          AND sl.almacen_id = v_sol.almacen_origen_id
          AND sl.producto_id = v_linea.producto_id
          AND sl.cantidad > 0
        ORDER BY
          l.fecha_caducidad NULLS LAST,
          l.created_at
        FOR UPDATE OF sl
      LOOP
        EXIT WHEN v_restante <= 0;

        v_toma := LEAST(v_restante, v_lote.cantidad);

        INSERT INTO public.traspaso_linea_lotes (
          empresa_id,
          traspaso_id,
          traspaso_linea_id,
          producto_id,
          lote_id,
          cantidad
        )
        VALUES (
          v_sol.empresa_id,
          v_traspaso_id,
          v_traspaso_linea_id,
          v_linea.producto_id,
          v_lote.lote_id,
          v_toma
        );

        v_restante := v_restante - v_toma;
      END LOOP;

      IF v_restante > 0 THEN
        v_cant := v_cant - v_restante;

        IF v_cant <= 0 THEN
          DELETE FROM public.traspaso_linea_lotes
           WHERE traspaso_linea_id = v_traspaso_linea_id;

          DELETE FROM public.traspaso_lineas
           WHERE id = v_traspaso_linea_id;

          CONTINUE;
        END IF;

        UPDATE public.traspaso_lineas
           SET cantidad = v_cant
         WHERE id = v_traspaso_linea_id;
      END IF;
    END IF;

    UPDATE public.solicitud_traspaso_lineas
       SET cantidad_surtida = cantidad_surtida + v_cant
     WHERE id = v_linea.id;

    v_algo := true;
  END LOOP;

  IF NOT v_algo THEN
    DELETE FROM public.traspasos
     WHERE id = v_traspaso_id;

    RAISE EXCEPTION
      'No hay existencia disponible en el almacén origen para surtir esta solicitud';
  END IF;

  PERFORM public.confirmar_traspaso(
    v_traspaso_id,
    COALESCE(auth.uid(), v_sol.solicitante_user_id)
  );

  INSERT INTO public.solicitud_traspaso_surtidos (
    empresa_id,
    solicitud_id,
    traspaso_id,
    surtido_por
  )
  VALUES (
    v_sol.empresa_id,
    p_solicitud_id,
    v_traspaso_id,
    auth.uid()
  );

  SELECT
    COALESCE(SUM(cantidad_aprobada), 0),
    COALESCE(SUM(cantidad_surtida), 0)
  INTO
    v_total_aprobado,
    v_total_surtido
  FROM public.solicitud_traspaso_lineas
  WHERE solicitud_id = p_solicitud_id
    AND excluida = false;

  UPDATE public.solicitudes_traspaso
     SET status = CASE
       WHEN v_total_surtido >= v_total_aprobado
         THEN 'surtida'::public.status_solicitud_traspaso
       ELSE 'parcialmente_surtida'::public.status_solicitud_traspaso
     END
   WHERE id = p_solicitud_id;

  PERFORM public.fn_log_solicitud_traspaso(
    p_solicitud_id,
    v_sol.empresa_id,
    'surtida',
    jsonb_build_object(
      'traspaso_id',
      v_traspaso_id,
      'lineas',
      p_lineas
    )
  );

  RETURN v_traspaso_id;
END;
$$;


--
-- Name: sync_crm_assignment_to_team_portfolio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_crm_assignment_to_team_portfolio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.assigned_to IS NOT DISTINCT FROM NEW.assigned_to THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.assigned_to IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.platform_team_members member
       JOIN public.commission_people person
         ON person.id = member.person_id
       WHERE member.person_id = NEW.assigned_to
         AND member.status IN ('invited', 'active')
         AND person.is_active = true
         AND person.person_type = 'internal'
     ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.commission_client_attributions(
    empresa_id,
    managed_by_id,
    channel,
    notes
  )
  VALUES (
    NEW.empresa_id,
    NEW.assigned_to,
    'manual',
    'Responsable sincronizado desde CRM'
  )
  ON CONFLICT (empresa_id)
  DO UPDATE SET
    managed_by_id = EXCLUDED.managed_by_id;

  RETURN NEW;
END;
$$;


--
-- Name: sync_max_usuarios(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_max_usuarios() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_empresa uuid; v_activos int;
begin
  v_empresa := coalesce(new.empresa_id, old.empresa_id);
  if v_empresa is null then return coalesce(new, old); end if;
  select count(*) into v_activos from public.profiles
    where empresa_id = v_empresa and estado = 'activo' and archivado_en is null;
  update public.subscriptions s
  set max_usuarios = greatest(
        v_activos,
        coalesce((select sp.usuarios_incluidos from public.subscription_plans sp where sp.id = s.plan_id), s.max_usuarios)
      ), updated_at = now()
  where s.empresa_id = v_empresa;
  return coalesce(new, old);
end $$;


--
-- Name: sync_partner_attribution_to_commissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_partner_attribution_to_commissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_person_id uuid;
BEGIN
  SELECT id
  INTO v_person_id
  FROM public.commission_people
  WHERE partner_id = NEW.partner_id;

  IF v_person_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.commission_client_attributions (
    empresa_id,
    captured_by_id,
    managed_by_id,
    channel,
    captured_at,
    notes
  )
  VALUES (
    NEW.empresa_id,
    v_person_id,
    v_person_id,
    CASE NEW.metodo
      WHEN 'link' THEN 'partner_link'
      WHEN 'cupon' THEN 'partner_coupon'
      ELSE 'manual'
    END,
    NEW.created_at,
    'Atribuido automáticamente desde el programa de partners'
  )
  ON CONFLICT (empresa_id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: sync_partner_reglas_por_suscripcion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_partner_reglas_por_suscripcion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresa_id uuid;
  v_partner_id uuid;
BEGIN
  v_empresa_id := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.empresa_id
    ELSE NEW.empresa_id
  END;

  SELECT partner_id
  INTO v_partner_id
  FROM public.partner_atribuciones
  WHERE empresa_id = v_empresa_id;

  IF v_partner_id IS NOT NULL THEN
    PERFORM public.recalcular_nivel_partner(v_partner_id);
    PERFORM public.desactivar_cupones_partner_fuera_limite(v_partner_id);
    PERFORM public.generar_bonos_partner(v_partner_id);
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: sync_partner_to_commission_people(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_partner_to_commission_people() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.commission_people (
    id,
    person_type,
    partner_id,
    name,
    email,
    phone,
    is_active,
    notes,
    created_at,
    updated_at
  )
  VALUES (
