  )
  ON CONFLICT (partner_id) DO UPDATE SET
    name = EXCLUDED.name,
    email = EXCLUDED.email,
    phone = EXCLUDED.phone,
    is_active = EXCLUDED.is_active,
    updated_at = EXCLUDED.updated_at;

  RETURN NEW;
END;
$$;


--
-- Name: sync_stock_lote_from_movimiento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_stock_lote_from_movimiento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.lote_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.almacen_destino_id IS NOT NULL THEN
    PERFORM public._aplica_stock_lote(NEW.empresa_id, NEW.almacen_destino_id, NEW.producto_id, NEW.lote_id,  COALESCE(NEW.cantidad,0));
  END IF;
  IF NEW.almacen_origen_id IS NOT NULL THEN
    PERFORM public._aplica_stock_lote(NEW.empresa_id, NEW.almacen_origen_id,  NEW.producto_id, NEW.lote_id, -COALESCE(NEW.cantidad,0));
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: sync_usa_presentaciones(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_usa_presentaciones() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_producto uuid;
  v_tiene boolean;
BEGIN
  v_producto := COALESCE(NEW.producto_id, OLD.producto_id);
  v_tiene := EXISTS (
    SELECT 1 FROM public.producto_presentaciones pp
    WHERE pp.producto_id = v_producto AND pp.activo = true
  );
  UPDATE public.productos p
  SET usa_presentaciones = v_tiene
  WHERE p.id = v_producto
    AND p.usa_presentaciones IS DISTINCT FROM v_tiene;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: team_has_master_permission(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_has_master_permission(p_module text, p_action text DEFAULT 'view'::text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE(
    CASE
      WHEN public.is_super_admin(p_user_id) THEN true
      ELSE (
        SELECT
          COALESCE((tm.permissions ->> 'master_access')::boolean, false)
          AND COALESCE((tm.permissions -> p_module ->> p_action)::boolean, false)
        FROM public.platform_team_members tm
        JOIN public.commission_people cp ON cp.id = tm.person_id
        WHERE tm.user_id = p_user_id
          AND tm.status IN ('invited','active')
          AND cp.is_active = true
          AND cp.person_type = 'internal'
        LIMIT 1
      )
    END,
    false
  );
$$;


--
-- Name: tg_cobro_aplicaciones_historial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cobro_aplicaciones_historial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _emp uuid; _metodo text; _ref text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT c.empresa_id, c.metodo_pago, c.referencia INTO _emp, _metodo, _ref
      FROM public.cobros c WHERE c.id = NEW.cobro_id;
    PERFORM public.log_venta_historial(NEW.venta_id, _emp, 'pago_agregado',
      jsonb_build_object('monto', NEW.monto_aplicado, 'metodo', COALESCE(_metodo,''), 'referencia', COALESCE(_ref,'')));
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT c.empresa_id, c.metodo_pago INTO _emp, _metodo FROM public.cobros c WHERE c.id = OLD.cobro_id;
    IF _emp IS NULL THEN SELECT empresa_id INTO _emp FROM public.ventas WHERE id = OLD.venta_id; END IF;
    IF _emp IS NOT NULL THEN
      PERFORM public.log_venta_historial(OLD.venta_id, _emp, 'pago_eliminado',
        jsonb_build_object('monto', OLD.monto_aplicado, 'metodo', COALESCE(_metodo,'')));
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: tg_cobro_aplicaciones_recalc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cobro_aplicaciones_recalc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_recalc_venta_saldo(OLD.venta_id);
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    PERFORM public.fn_recalc_venta_saldo(NEW.venta_id);
    IF OLD.venta_id IS DISTINCT FROM NEW.venta_id THEN
      PERFORM public.fn_recalc_venta_saldo(OLD.venta_id);
    END IF;
    RETURN NEW;
  ELSE
    PERFORM public.fn_recalc_venta_saldo(NEW.venta_id);
    RETURN NEW;
  END IF;
END;
$$;


--
-- Name: tg_cobros_status_recalc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cobros_status_recalc() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.status,'activo') IS DISTINCT FROM COALESCE(NEW.status,'activo') THEN
    FOR r IN SELECT DISTINCT venta_id FROM public.cobro_aplicaciones WHERE cobro_id = NEW.id LOOP
      PERFORM public.fn_recalc_venta_saldo(r.venta_id);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_entrega_lineas_historial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_entrega_lineas_historial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _vid uuid; _emp uuid; _folio text; _prod text;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.cantidad_entregada IS DISTINCT FROM OLD.cantidad_entregada
                       OR NEW.cantidad_pedida IS DISTINCT FROM OLD.cantidad_pedida) THEN
    SELECT e.pedido_id, e.empresa_id, e.folio INTO _vid, _emp, _folio
      FROM public.entregas e WHERE e.id = NEW.entrega_id;
    IF _vid IS NULL OR _emp IS NULL THEN RETURN NEW; END IF;
    SELECT COALESCE(nombre, codigo, '') INTO _prod FROM public.productos WHERE id = NEW.producto_id;
    PERFORM public.log_venta_historial(_vid, _emp, 'entrega_editada',
      jsonb_build_object('folio', COALESCE(_folio,''), 'producto', COALESCE(_prod,''),
        'cantidad_entregada', jsonb_build_object('anterior', OLD.cantidad_entregada, 'nuevo', NEW.cantidad_entregada)));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_entregas_historial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_entregas_historial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE _vid uuid;
BEGIN
  _vid := COALESCE(NEW.pedido_id, OLD.pedido_id);
  IF _vid IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  IF TG_OP = 'INSERT' THEN
    PERFORM public.log_venta_historial(_vid, NEW.empresa_id, 'entrega_creada',
      jsonb_build_object('folio', COALESCE(NEW.folio,''), 'status', NEW.status::text));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM public.log_venta_historial(_vid, NEW.empresa_id,
      public._map_entrega_status(NEW.status::text),
      jsonb_build_object('folio', COALESCE(NEW.folio,''),
        'status', jsonb_build_object('anterior', OLD.status::text, 'nuevo', NEW.status::text)));
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


