--
-- Name: trg_audit_venta_linea_precio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_venta_linea_precio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prod      public.productos%ROWTYPE;
  v_mult      numeric;
  v_esperado  numeric;
  v_guardado  numeric;
  v_empresa   uuid;
BEGIN
  IF NEW.producto_id IS NULL THEN RETURN NEW; END IF;
  IF COALESCE(NEW.precio_manual, false) THEN RETURN NEW; END IF;
  IF COALESCE(NEW.descuento_pct, 0) <> 0 THEN RETURN NEW; END IF;
  IF NEW.lista_precio_id IS NOT NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_prod FROM public.productos WHERE id = NEW.producto_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- Solo interesa cuando hay impuestos (la erosión venía de dividir de más).
  IF COALESCE(v_prod.tiene_iva, false) = false AND COALESCE(v_prod.tiene_ieps, false) = false THEN
    RETURN NEW;
  END IF;

  v_mult := (1 + CASE WHEN COALESCE(v_prod.tiene_ieps,false) THEN COALESCE(v_prod.ieps_pct,0)/100.0 ELSE 0 END)
          * (1 + CASE WHEN COALESCE(v_prod.tiene_iva,false)  THEN COALESCE(v_prod.iva_pct,0)/100.0  ELSE 0 END);
  IF v_mult <= 0 THEN RETURN NEW; END IF;

  v_esperado := ROUND(COALESCE(v_prod.precio_principal, 0) / v_mult, 4);
  v_guardado := ROUND(COALESCE(NEW.precio_unitario, 0), 4);

  IF v_esperado <= 0 OR v_guardado <= 0 THEN RETURN NEW; END IF;

  -- Tolerancia 1%: solo se registra lo que se ve como erosión (precio por debajo).
  IF v_guardado < v_esperado * 0.99 THEN
    SELECT empresa_id INTO v_empresa FROM public.ventas WHERE id = NEW.venta_id;
    INSERT INTO public.ventas_descuadre_auditoria
      (empresa_id, venta_id, venta_linea_id, producto_id, tipo,
       precio_guardado, precio_esperado, diferencia, detalle)
    VALUES
      (v_empresa, NEW.venta_id, NEW.id, NEW.producto_id, 'precio_erosionado',
       v_guardado, v_esperado, ROUND(v_esperado - v_guardado, 4),
       jsonb_build_object(
         'iva_pct', v_prod.iva_pct, 'ieps_pct', v_prod.ieps_pct,
         'precio_principal', v_prod.precio_principal,
         'precio_unitario_sin_redondeo', NEW.precio_unitario_sin_redondeo,
         'op', TG_OP));
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_cobro_aplicaciones_candado_rep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_cobro_aplicaciones_candado_rep() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (TG_OP <> 'INSERT' AND public.cobro_tiene_rep_vigente(OLD.cobro_id))
     OR (TG_OP <> 'DELETE' AND public.cobro_tiene_rep_vigente(NEW.cobro_id)) THEN
    RAISE EXCEPTION 'Este cobro tiene complemento de pago (REP) timbrado; cancela primero el complemento.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trg_cobros_candado_rep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_cobros_candado_rep() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.cobro_tiene_rep_vigente(OLD.id) AND (
       TG_OP = 'DELETE'
       OR NEW.monto IS DISTINCT FROM OLD.monto
       OR NEW.fecha IS DISTINCT FROM OLD.fecha
       OR NEW.status IS DISTINCT FROM OLD.status
       OR NEW.cliente_id IS DISTINCT FROM OLD.cliente_id
       OR NEW.metodo_pago IS DISTINCT FROM OLD.metodo_pago) THEN
    RAISE EXCEPTION 'Este cobro tiene complemento de pago (REP) timbrado; cancela primero el complemento.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trg_compra_lineas_recalc_costos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_compra_lineas_recalc_costos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_prod uuid;
BEGIN
  v_prod := COALESCE(NEW.producto_id, OLD.producto_id);
  SELECT status INTO v_status FROM compras WHERE id = COALESCE(NEW.compra_id, OLD.compra_id);
  IF v_status IN ('recibida','pagada') AND v_prod IS NOT NULL THEN
    PERFORM recalc_producto_costo(v_prod);
    -- si cambió el producto de la línea, recalcula también el anterior
    IF TG_OP = 'UPDATE' AND NEW.producto_id IS DISTINCT FROM OLD.producto_id AND OLD.producto_id IS NOT NULL THEN
      PERFORM recalc_producto_costo(OLD.producto_id);
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trg_compra_recalc_costos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_compra_recalc_costos() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
  v_should boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_should := NEW.status IN ('recibida', 'pagada');

  ELSIF TG_OP = 'UPDATE' THEN
    v_should := NEW.status IN ('recibida', 'pagada')
      AND (
        OLD.status IS DISTINCT FROM NEW.status
        OR OLD.fecha IS DISTINCT FROM NEW.fecha
        OR OLD.proveedor_id IS DISTINCT FROM NEW.proveedor_id
        OR OLD.condicion_pago IS DISTINCT FROM NEW.condicion_pago
        OR OLD.total IS DISTINCT FROM NEW.total
        OR OLD.descuento_total IS DISTINCT FROM NEW.descuento_total
        OR OLD.ajuste_total IS DISTINCT FROM NEW.ajuste_total
      );
  END IF;

  IF v_should THEN
    FOR r IN
      SELECT DISTINCT producto_id
      FROM public.compra_lineas
      WHERE compra_id = NEW.id
    LOOP
      PERFORM public.recalc_producto_costo(r.producto_id);
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_cotizacion_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_cotizacion_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE next_num int;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('folio:COT'), hashtext(NEW.empresa_id::text));
  SELECT COALESCE(MAX(NULLIF(regexp_replace(folio, '\D', '', 'g'), '')::int), 0) + 1
    INTO next_num FROM public.cotizaciones WHERE empresa_id = NEW.empresa_id;
  NEW.folio := 'COT-' || public.folio_lpad(next_num::text, 5, '0');
  IF NEW.vence_at IS NULL THEN
    NEW.vence_at := NEW.fecha + (NEW.vigencia_dias || ' days')::interval;
  END IF;
  RETURN NEW;
END; $$;


