--
-- Name: trg_recalc_venta_header(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_recalc_venta_header() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_recalc_venta_header(OLD.venta_id);
    RETURN OLD;
  END IF;

  PERFORM public.fn_recalc_venta_header(NEW.venta_id);
  IF TG_OP = 'UPDATE' AND NEW.venta_id IS DISTINCT FROM OLD.venta_id THEN
    PERFORM public.fn_recalc_venta_header(OLD.venta_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_refresh_logistica_pedido_from_entrega(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_logistica_pedido_from_entrega() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.pedido_id IS NOT NULL THEN
      PERFORM public.fn_refresh_logistica_pedido_resumen(OLD.pedido_id);
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.pedido_id IS NOT NULL THEN
    PERFORM public.fn_refresh_logistica_pedido_resumen(NEW.pedido_id);
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.pedido_id IS NOT NULL
     AND OLD.pedido_id IS DISTINCT FROM NEW.pedido_id THEN
    PERFORM public.fn_refresh_logistica_pedido_resumen(OLD.pedido_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_refresh_logistica_pedido_from_entrega_linea(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_logistica_pedido_from_entrega_linea() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_pedido_new uuid;
  v_pedido_old uuid;
BEGIN
  IF TG_OP <> 'DELETE' THEN
    SELECT e.pedido_id INTO v_pedido_new
    FROM public.entregas e
    WHERE e.id = NEW.entrega_id;

    IF v_pedido_new IS NOT NULL THEN
      PERFORM public.fn_refresh_logistica_pedido_resumen(v_pedido_new);
    END IF;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    SELECT e.pedido_id INTO v_pedido_old
    FROM public.entregas e
    WHERE e.id = OLD.entrega_id;

    IF v_pedido_old IS NOT NULL
       AND v_pedido_old IS DISTINCT FROM v_pedido_new THEN
      PERFORM public.fn_refresh_logistica_pedido_resumen(v_pedido_old);
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_refresh_logistica_pedido_from_venta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_logistica_pedido_from_venta() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
