--
-- Name: trg_refresh_logistica_pedido_from_venta_linea(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_logistica_pedido_from_venta_linea() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.fn_refresh_logistica_pedido_resumen(OLD.venta_id);
    RETURN OLD;
  END IF;

  PERFORM public.fn_refresh_logistica_pedido_resumen(NEW.venta_id);
  IF TG_OP = 'UPDATE' AND OLD.venta_id IS DISTINCT FROM NEW.venta_id THEN
    PERFORM public.fn_refresh_logistica_pedido_resumen(OLD.venta_id);
  END IF;
  RETURN NEW;
END;
$$;


