--
-- Name: trg_venta_linea_lotes_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_venta_linea_lotes_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linea uuid;
  v_principal uuid;
BEGIN
  v_linea := COALESCE(NEW.venta_linea_id, OLD.venta_linea_id);

  SELECT d.lote_id INTO v_principal
    FROM public.venta_linea_lotes d
   WHERE d.venta_linea_id = v_linea
   ORDER BY d.cantidad DESC, d.created_at ASC
   LIMIT 1;

  UPDATE public.venta_lineas
     SET lote_id = v_principal
   WHERE id = v_linea
     AND lote_id IS DISTINCT FROM v_principal;

  PERFORM public.fn_sync_apartado_linea(v_linea);
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: trg_venta_lineas_apartado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_venta_lineas_apartado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.stock_apartado WHERE venta_linea_id = OLD.id;
    RETURN OLD;
  END IF;
  PERFORM public.fn_sync_apartado_linea(NEW.id);
  RETURN NEW;
END;
$$;


--
-- Name: trg_venta_sync_inventario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_venta_sync_inventario() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'ventas' THEN
    PERFORM public.fn_sync_venta_inventario(COALESCE(NEW.id, OLD.id));
  ELSE
    v_id := COALESCE(NEW.venta_id, OLD.venta_id);
    PERFORM public.fn_sync_venta_inventario(v_id);
    IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'venta_lineas'
       AND NEW.venta_id IS DISTINCT FROM OLD.venta_id THEN
      PERFORM public.fn_sync_venta_inventario(OLD.venta_id);
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


