     AND OLD.status IS DISTINCT FROM NEW.status THEN
    DELETE FROM public.stock_apartado WHERE venta_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: ultima_visita_por_cliente(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ultima_visita_por_cliente(p_empresa_id uuid, p_desde timestamp with time zone, p_hasta timestamp with time zone) RETURNS TABLE(cliente_id uuid, fecha timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT v.cliente_id, max(v.fecha)
  FROM public.visitas v
  WHERE v.empresa_id = p_empresa_id
    AND v.fecha >= p_desde AND v.fecha < p_hasta
    AND v.cliente_id IS NOT NULL
  GROUP BY v.cliente_id
$$;


