--
-- Name: validar_cobro_pos_turno(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_cobro_pos_turno() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_origen text;
BEGIN
  v_origen := NULLIF(lower(btrim(NEW.origen)), '');
  NEW.origen := v_origen;

  -- Cancelar/reactivar o editar datos ajenos a la trazabilidad debe seguir
  -- funcionando aunque el turno ya esté cerrado.
  IF TG_OP = 'UPDATE'
     AND NEW.turno_id IS NOT DISTINCT FROM OLD.turno_id
     AND NEW.origen IS NOT DISTINCT FROM OLD.origen
     AND NEW.empresa_id IS NOT DISTINCT FROM OLD.empresa_id
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id THEN
    RETURN NEW;
  END IF;

  IF v_origen = 'pos' THEN
    IF NEW.turno_id IS NULL THEN
      RAISE EXCEPTION 'Un cobro POS requiere un turno activo';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.caja_turnos t
      WHERE t.id = NEW.turno_id
        AND t.empresa_id = NEW.empresa_id
        AND t.cajero_id = NEW.user_id
        AND t.status = 'abierto'
    ) THEN
      RAISE EXCEPTION 'El turno POS no está abierto o no corresponde a la empresa y cajero';
    END IF;
  ELSIF NEW.turno_id IS NOT NULL THEN
    RAISE EXCEPTION 'Sólo los cobros con origen POS pueden asociarse a un turno';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validar_cupon_partner_pct(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_cupon_partner_pct() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max numeric;
BEGIN
  IF NEW.partner_id IS NULL
     OR COALESCE(NEW.activo, true) = false THEN
    RETURN NEW;
  END IF;

  v_max := public.get_partner_coupon_cap(NEW.partner_id);

  IF COALESCE(NEW.descuento_pct, 0) > v_max THEN
    RAISE EXCEPTION
      'El descuento del cupón (%) no puede superar la comisión vigente del partner (%)',
      NEW.descuento_pct,
      v_max
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validar_stock_cotizacion(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_stock_cotizacion(p_cotizacion_id uuid, p_almacen_id uuid) RETURNS TABLE(producto_id uuid, descripcion text, cantidad_solicitada numeric, stock_disponible numeric, faltante numeric, ok boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    cl.producto_id,
    COALESCE(cl.descripcion, p.nombre) AS descripcion,
    cl.cantidad AS cantidad_solicitada,
    COALESCE(sa.cantidad, 0) AS stock_disponible,
    GREATEST(cl.cantidad - COALESCE(sa.cantidad, 0), 0) AS faltante,
    (COALESCE(sa.cantidad, 0) >= cl.cantidad OR COALESCE(p.vender_sin_stock, false)) AS ok
  FROM public.cotizacion_lineas cl
  LEFT JOIN public.productos p ON p.id = cl.producto_id
  LEFT JOIN public.stock_almacen sa ON sa.producto_id = cl.producto_id AND sa.almacen_id = p_almacen_id
  WHERE cl.cotizacion_id = p_cotizacion_id AND cl.producto_id IS NOT NULL;
$$;


--
-- Name: validate_commission_manager(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_commission_manager() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.manager_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.commission_people
    WHERE id = NEW.manager_id
      AND is_active = true
  ) THEN
    RAISE EXCEPTION
      'El encargado seleccionado no existe o está inactivo';
  END IF;

  IF EXISTS (
    WITH RECURSIVE managers(id) AS (
      SELECT NEW.manager_id

      UNION

      SELECT person.manager_id
      FROM public.commission_people person
      JOIN managers current_manager
        ON person.id = current_manager.id
      WHERE person.manager_id IS NOT NULL
    )
    SELECT 1
    FROM managers
    WHERE id = NEW.id
  ) THEN
    RAISE EXCEPTION 'La jerarquía no puede formar un ciclo';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_entrega_linea_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_entrega_linea_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_folio text;
BEGIN
  -- "Ajustar entrega" (ajustar_entrega) agrega el producto realmente entregado.
  IF current_setting('rutapp.ajuste_entrega', true) = 'on' THEN RETURN NEW; END IF;

  SELECT status::text, folio INTO v_status, v_folio
  FROM public.entregas WHERE id = NEW.entrega_id;

  IF v_status IN ('surtido', 'asignado', 'cargado', 'en_ruta', 'hecho', 'cancelado') THEN
    RAISE EXCEPTION 'No se pueden agregar líneas a la entrega %: ya está en estado "%".',
      COALESCE(v_folio, NEW.entrega_id::text), v_status;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_entrega_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_entrega_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lineas_sin_origen int;
  v_lineas_hechas int;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'cargado' THEN
    IF NEW.vendedor_ruta_id IS NULL AND NEW.vendedor_id IS NULL THEN
      RAISE EXCEPTION 'No se puede cargar la entrega %: falta asignar vendedor de ruta.',
        COALESCE(NEW.folio, NEW.id::text);
    END IF;

    -- Solo contar líneas realmente surtidas (cantidad_entregada > 0)
    SELECT COUNT(*) FILTER (WHERE hecho AND cantidad_entregada > 0 AND almacen_origen_id IS NULL),
           COUNT(*) FILTER (WHERE hecho AND cantidad_entregada > 0)
    INTO v_lineas_sin_origen, v_lineas_hechas
    FROM public.entrega_lineas
    WHERE entrega_id = NEW.id;

    IF v_lineas_hechas = 0 THEN
      RAISE EXCEPTION 'No se puede cargar la entrega %: no hay líneas surtidas.',
        COALESCE(NEW.folio, NEW.id::text);
    END IF;

    IF v_lineas_sin_origen > 0 THEN
      RAISE EXCEPTION 'No se puede cargar la entrega %: hay % línea(s) surtida(s) sin almacén origen.',
        COALESCE(NEW.folio, NEW.id::text), v_lineas_sin_origen;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = COALESCE(NEW.vendedor_ruta_id, NEW.vendedor_id)
        AND almacen_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'No se puede cargar la entrega %: el vendedor de ruta no tiene almacén asignado en su perfil.',
        COALESCE(NEW.folio, NEW.id::text);
    END IF;
  END IF;

  IF NEW.status = 'hecho' AND OLD.status NOT IN ('cargado', 'en_ruta') THEN
    RAISE EXCEPTION 'No se puede validar la entrega %: primero debe estar cargada (estado actual: %).',
      COALESCE(NEW.folio, NEW.id::text), OLD.status;
  END IF;

  RETURN NEW;
END;
$$;


