--
-- Name: partner_resumen; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.partner_resumen WITH (security_invoker='true') AS
 SELECT p.id AS partner_id,
    p.nombre,
    p.comision_pct,
    p.estado,
    p.ref_slug,
    ( SELECT count(*) AS count
           FROM public.partner_atribuciones a
          WHERE (a.partner_id = p.id)) AS empresas_referidas,
    ( SELECT COALESCE(sum(c.monto_comision), (0)::numeric) AS "coalesce"
           FROM public.partner_comisiones c
          WHERE ((c.partner_id = p.id) AND (c.status <> 'anulada'::text))) AS total_generado,
    ( SELECT COALESCE(sum(c.monto_comision), (0)::numeric) AS "coalesce"
           FROM public.partner_comisiones c
          WHERE ((c.partner_id = p.id) AND (c.status = 'pagada'::text))) AS total_pagado,
    ( SELECT COALESCE(sum(c.monto_comision), (0)::numeric) AS "coalesce"
           FROM public.partner_comisiones c
          WHERE ((c.partner_id = p.id) AND (c.status = 'pendiente'::text))) AS saldo_pendiente,
    p.email,
    p.telefono,
    p.created_at,
    n.nombre AS nivel_nombre,
    n.emoji AS nivel_emoji,
    n.comision_pct AS comision_actual_pct,
    n.empresas_actuales AS empresas_activas,
    ( SELECT count(*) AS count
           FROM public.cupones c
          WHERE ((c.partner_id = p.id) AND c.activo)) AS cupones_activos,
    p.terms_accepted_at,
    p.terms_version
   FROM (public.partners p
     LEFT JOIN LATERAL public.get_partner_nivel(p.id) n(nivel_id, nombre, orden, comision_pct, empresas_min, empresas_max, emoji, color, empresas_actuales, empresas_para_siguiente, siguiente_nombre, siguiente_pct) ON (true));


