--
-- Name: platform_team_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_team_members (
    person_id uuid NOT NULL,
    user_id uuid,
    job_title text,
    access_level text DEFAULT 'executive'::text NOT NULL,
    access_scope text DEFAULT 'own'::text NOT NULL,
    status text DEFAULT 'invited'::text NOT NULL,
    commission_mode text DEFAULT 'none'::text NOT NULL,
    commission_pct numeric(5,2) DEFAULT 0 NOT NULL,
    commission_payment_limit integer,
    commission_fixed_amount numeric(12,2) DEFAULT 0 NOT NULL,
    permissions jsonb DEFAULT '{"crm": true, "portfolio": true, "commissions": true, "billing_audit": false, "company_admin": false}'::jsonb NOT NULL,
    invited_at timestamp with time zone,
    last_access_at timestamp with time zone,
    created_by uuid DEFAULT auth.uid(),
    updated_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email_is_fictitious boolean DEFAULT false NOT NULL,
    CONSTRAINT platform_team_commission_configuration CHECK (((commission_mode = 'none'::text) OR ((commission_mode = ANY (ARRAY['first_payment'::text, 'first_n_payments'::text, 'recurring'::text])) AND (commission_pct > (0)::numeric)) OR ((commission_mode = 'fixed_activation'::text) AND (commission_fixed_amount > (0)::numeric)))),
    CONSTRAINT platform_team_members_access_level_check CHECK ((access_level = ANY (ARRAY['executive'::text, 'supervisor'::text, 'manager'::text]))),
    CONSTRAINT platform_team_members_access_scope_check CHECK ((access_scope = ANY (ARRAY['own'::text, 'team'::text, 'all'::text]))),
    CONSTRAINT platform_team_members_commission_fixed_amount_check CHECK ((commission_fixed_amount >= (0)::numeric)),
    CONSTRAINT platform_team_members_commission_mode_check CHECK ((commission_mode = ANY (ARRAY['none'::text, 'first_payment'::text, 'first_n_payments'::text, 'recurring'::text, 'fixed_activation'::text]))),
    CONSTRAINT platform_team_members_commission_payment_limit_check CHECK (((commission_payment_limit >= 1) AND (commission_payment_limit <= 60))),
    CONSTRAINT platform_team_members_commission_pct_check CHECK (((commission_pct >= (0)::numeric) AND (commission_pct <= (100)::numeric))),
    CONSTRAINT platform_team_members_status_check CHECK ((status = ANY (ARRAY['invited'::text, 'active'::text, 'suspended'::text]))),
    CONSTRAINT platform_team_payment_limit CHECK (((commission_mode <> 'first_n_payments'::text) OR (commission_payment_limit IS NOT NULL)))
);
